se. presença ativa de múltiplos elementos da comunicação,","utilização de um verbo de ação. entre os quais se destacam as funções da linguagem.","apagamento de uma preposição."]'::jsonb, correct_answer = '"organização interrogativa da frase. presença ativa de múltiplos elementos da comunicação,"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"31c6fa0e7a1de00698372a7404678d4fcf93cb20dec4ec814c8a6c59ea3f2aa7","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"133fa780ead4b0e76950b075b9f935166a92ee2b3dd6a73fb3502c7e487a43bf","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":6,"language":null,"page":6,"storagePath":"2020-D1-CD1/question-6-COMMON/statement-page-6.png","sha256":"2576934290f8083b1eda3e919875fe06e7b02c65a97efb21ac0be380e76b82f3","crop":{"left":0,"bottom":288.78170000000034,"width":302.958525,"height":396.9301999999997}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":6,"language":null,"source_page":6,"source_sha256":"ab25200a67d34c0c0be86316572d5ca5a93d7836f005fc1a90b1f195f7e5fdd2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
