idência da memória sobre as imagens narradas.","alternância entre impressões subjetivas e relatos"]'::jsonb, correct_answer = '"perspectiva infantil assumida pela voz narrativa."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"e87b50f9f4d2362a494a7042c79292193b85bfc462830d9b08d9a12fe163b37f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"8286775859cd83efa79e97f60a05c54d66b683c6082d6090adaf5ae435226d07","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":34,"language":null,"source_page":15,"source_sha256":"ab25200a67d34c0c0be86316572d5ca5a93d7836f005fc1a90b1f195f7e5fdd2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
