  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'ba90b2ac85f94e8b1905f248e449a950b9536558dd7a059bcbc75a4803d03b77', 'STATEMENT_CROP', 20, '2020-D1-CD4/question-46-COMMON/statement-page-20.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"ba90b2ac85f94e8b1905f248e449a950b9536558dd7a059bcbc75a4803d03b77","crop":{"left":0,"bottom":589.9359,"width":260.3993249999999,"height":90.11599999999999},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0ea6dc2a544c442c67a095c93f2878439573ac12c7bce7dd0858a62315b6d27d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D1', 53, 'CIENCIAS_HUMANAS', 'apenas um sonho ou alucinação gigante, de que você “Devo estar chegando perto do centro da Terra. Deixe jamais fosse despertar? Se assim fosse, então é claro ver: deve ter sido mais de seis mil quilômetros, por aí...” que você nunca poderia despertar, como faz quando (como se vê, Alice tinha aprendido uma porção de coisas sonha, pois significaria que não há mundo “real” no qual desse tipo na escola, e embora essa não fosse uma despertar. Logo, não seria exatamente igual a um sonho oportunidade lá muito boa de demonstrar conhecimentos, ou alucinação normal. NAGEL, T. Uma breve introdução à filosofia . São Paulo: Martins Fontes, 2011. já que não havia ninguém por perto para escutá-la, em todo caso era bom praticar um pouco) “... sim, deve ser O texto confere visibilidade a uma doutrina filosófica mais ou menos essa a distância... mas então qual seria contemporânea conhecida como: a latitude ou longitude em que estou?” (Alice não tinha A Personalismo, que vincula a realidade circundante a menor ideia do que fosse latitude ou longitude, mas aos domínios do pessoal. achou que eram palavras muito imponentes). B Falsificacionismo, que estabelece ciclos de problemas CARROLL, L. Aventuras de Alice : no País das Maravilhas, Através do espelho e outros textos. São Paulo: Summus, 1980. para refutar uma conjectura. O texto descreve uma confusão da personagem em C Falibilismo, que rejeita mecanismos mentais para relação sustentar uma crença inequívoca.', '["ao tipo de projeção cartográfica. D Idealismo, que nega a existência de objetos","aos contornos dos fusos horários. independentemente do trabalho cognoscente.","à localização do norte magnético. E Solipsismo, que reconhece limitações cognitivas para","aos referenciais de posição relativa. compreender uma experiência compartilhada.","às distorções das formas continentais."]'::jsonb, '"aos referenciais de posição relativa. compreender uma experiência compartilhada."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"0ea6dc2a544c442c67a095c93f2878439573ac12c7bce7dd0858a62315b6d27d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FILOSOFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FILOSOFIA","classification_source_fingerprint":"718397af9b19a67adcc4afc10af40004a5bd5f1f4d319bfb454f3afdff0555aa","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":53,"language":null,"page":22,"storagePath":"2020-D1-CD1/question-53-COMMON/statement-page-22.png","sha256":"d2448e5eecd4e72c72c2041bc39cc06789d7855a675110b4ac42e27bc4778e70","crop":{"left":0,"bottom":123.1651,"width":254.38266249999998,"height":256.2043}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":53,"language":null,"source_page":22,"source_sha256":"ab25200a67d34c0c0be86316572d5ca5a93d7836f005fc1a90b1f195f7e5fdd2"}}'::jsonb, true) returning id into v_question_id; end if;
