  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e29da56d3204cd671d10a30c0c2c0ed8eea5a3e8e1cbd759523cd60f6f1570e8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D1', 66, 'CIENCIAS_HUMANAS', 'Um dos resquícios franceses na dança são os comandos proferidos pelo marcador da quadrilha. Seu papel é anunciar os próximos passos da coreografia. O abrasileiramento de termos franceses deu origem, por exemplo, ao saruê ( soirée — reunião social noturna, ordem para todos se juntarem no centro do salão), anarriê ( en arrière — para trás) e anavã ( en avant — para frente). Disponível em: www.ebc.com.br. Acesso em: 6 jul. 2015. A característica apresentada dessa manifestação popular resulta do seguinte processo socio-histórico:', '["Massificação da arte erudita.","Rejeição de hábitos elitistas.","Laicização dos rituais religiosos.","Restauração dos costumes antigos.","Apropriação de práticas estrangeiras."]'::jsonb, '"Apropriação de práticas estrangeiras."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"e29da56d3204cd671d10a30c0c2c0ed8eea5a3e8e1cbd759523cd60f6f1570e8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"45054ae36f066f16e4718355f71c31dc52812b1b7720138baa89943030bc4db2","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":66,"language":null,"page":25,"storagePath":"2020-D1-CD1/question-66-COMMON/statement-page-25.png","sha256":"8fd560872a7211884bf2333648fa42e6c28575d4822a0301b882c295b17509af","crop":{"left":0,"bottom":100.1611,"width":316.0338562499999,"height":113.80679999999998}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":66,"language":null,"source_page":25,"source_sha256":"ab25200a67d34c0c0be86316572d5ca5a93d7836f005fc1a90b1f195f7e5fdd2"}}'::jsonb, true) returning id into v_question_id; end if;
