  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '3c8a6b722d79cf5e4d789f02cfd8b19da7303ce2369e652308d56cdfac6b7ab9' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D1', 80, 'CIENCIAS_HUMANAS', 'A característica física que justifica a fixação do homem Os seringueiros amazônicos eram invisíveis no nos locais apresentados no texto é a ocorrência de cenário nacional nos anos 1970. Começaram a se articular como um movimento agrário no início dos anos A solo fértil. 1980, e na década seguinte conseguiram reconhecimento B encosta íngreme. nacional, obtendo a implantação das primeiras reservas C vegetação diversificada. extrativas após o assassinato de Chico Mendes. Assim, D drenagem eficiente. em vinte anos, os camponeses da floresta passaram da invisibilidade à posição de paradigma de desenvolvimento E clima ameno. sustentável com participação popular.', '["se","encosta íngreme.","vegetação diversificada.","drenagem eficiente.","clima ameno."]'::jsonb, '"vegetação diversificada."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"3c8a6b722d79cf5e4d789f02cfd8b19da7303ce2369e652308d56cdfac6b7ab9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"2a12653e3762b90480aa03f93d5d9b7e24f4b717623a11749572ff6b2a37205f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":80,"language":null,"page":29,"storagePath":"2020-D1-CD1/question-80-COMMON/statement-page-29.png","sha256":"af28766809d6be066af631a0d933560d7134caf6fceb435559af6f6ca5a2f8aa","crop":{"left":0,"bottom":655.8743999999999,"width":283.39175,"height":53.83750000000009}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":80,"language":null,"source_page":29,"source_sha256":"ab25200a67d34c0c0be86316572d5ca5a93d7836f005fc1a90b1f195f7e5fdd2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2020, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 80, subject_area = 'CIENCIAS_HUMANAS', statement = 'A característica física que justifica a fixação do homem Os seringueiros amazônicos eram invisíveis no nos locais apresentados no texto é a ocorrência de cenário nacional nos anos 1970. Começaram a se articular como um movimento agrário no início dos anos A solo fértil. 1980, e na década seguinte conseguiram reconhecimento B encosta íngreme. nacional, obtendo a implantação das primeiras reservas C vegetação diversificada. extrativas após o assassinato de Chico Mendes. Assim, D drenagem eficiente. em vinte anos, os camponeses da floresta passaram da invisibilidade à posição de paradigma de desenvolvimento E clima ameno. sustentável com participação popular.', options = '["se","encosta íngreme.","vegetação diversificada.","drenagem eficiente.","clima ameno."]'::jsonb, correct_answer = '"vegetação diversificada."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"3c8a6b722d79cf5e4d789f02cfd8b19da7303ce2369e652308d56cdfac6b7ab9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"2a12653e3762b90480aa03f93d5d9b7e24f4b717623a11749572ff6b2a37205f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":80,"language":null,"page":29,"storagePath":"2020-D1-CD1/question-80-COMMON/statement-page-29.png","sha256":"af28766809d6be066af631a0d933560d7134caf6fceb435559af6f6ca5a2f8aa","crop":{"left":0,"bottom":655.8743999999999,"width":283.39175,"height":53.83750000000009}}],"enem_are