  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'bc07d3eb1ddbcac020ac0f4485df9315028132d07abc0742bf640576fc283372' limit 1;
