  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0731ebe2422c4f9e27829a8be43c1e0ebd2bf47dc1fbc6a81843bd76c59af8ea' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D1', 73, 'CIENCIAS_HUMANAS', 'Um motivo que explica a ambientação da prática descrita Porque todos confessamos não se poder viver sem no texto encontra-se no(a) alguns escravos, que busquem a lenha e a água, e A regra judaica, que pregava a superioridade espiritual façam cada dia o pão que se come, e outros serviços que não são possíveis poderem-se fazer pelos dos cultos das sinagogas. Irmãos Jesuítas, máxime sendo tão poucos, que seria B moralismo da legislação, que dificultava as reuniões necessário deixar as confissões e tudo mais. Parece- abertas da juventude livre. me que a Companhia de Jesus deve ter e adquirir C adesão do patriciado, que subvertia o conceito escravos, justamente, por meios que as Constituições permitem, quando puder para nossos colégios e casas original dos valores estrangeiros. de meninos. D decisão política, que censurava as manifestações LEITE, S. História da Companhia de Jesus no Brasil . Rio de Janeiro: Civilização Brasileira, 1938 (adaptado). públicas da doutrina dissidente. O texto explicita premissas da expansão ultramarina E violência senhorial, que impunha a desestruturação portuguesa ao buscar justificar a forçada das famílias escravas. A propagação do ideário cristão.', '["regra judaica, que pregava a superioridade espiritual","moralismo da legislação, que dificultava as reuniões","adesão do patriciado, que subvertia o conceito","decisão política, que censurava as manifestações","violência senhorial, que impunha a desestruturação"]'::jsonb, '"adesão do patriciado, que subvertia o conceito"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"0731ebe2422c4f9e27829a8be43c1e0ebd2bf47dc1fbc6a81843bd76c59af8ea","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"HISTORIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_HISTORIA","classification_source_fingerprint":"b84670925ec8d9dbfa87b61e7c75a5a9266234283187f14f1799f1690cbdf0f6","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":73,"language":null,"page":27,"storagePath":"2020-D1-CD4/question-73-COMMON/statement-page-27.png","sha256":"624751ab263e2c9561b26336a84ae450cabb6c340043d330a97bf4bea9fccf4a","crop":{"left":0,"bottom":411.01460000000003,"width":283.39175,"height":56.67209999999994}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD4","question_number":73,"language":null,"source_page":27,"source_sha256":"7800498710b4fadf9ff2809e9de4e08c3082f31edac619b3d5e4a1403a19f7c7"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2020, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 73, subject_area = 'CIENCIAS_HUMANAS', statement = 'Um motivo que explica a ambientação da prática descrita Porque todos confessamos não se poder viver sem no texto encontra-se no(a) alguns escravos, que busquem a lenha e a água, e A regra judaica, que pregava a superioridade espiritual façam cada dia o pão que se come, e outros serviços que não são possíveis poderem-se fazer pelos dos cultos das sinagogas. Irmãos Jesuítas, máxime sendo tão poucos, que seria B moralismo da legislação, que dificultava as reuniões necessário deixar as confissões e tudo mais. Parece- abertas da juventude livre. me que a Companhia de Jesus deve ter e adquirir C adesão do patriciado, que subvertia o conceito escravos, justamente, por meios que as Constituições permitem, quando puder para nossos colégios e casas original dos valores estrangeiros. de meninos. D decisão política, que censurava as manifestações LEITE, S. História da Companhia de Jesus no Brasil . Rio de Janeiro: Civilização Brasileira, 1938 (adaptado). públicas da doutrina dissidente. O texto explicita premissas da expansão ultramarina E violência senhorial, que impunha a desestruturação portuguesa ao buscar justificar a forçada das famílias escravas. A propagação do ideário cristão.', options = '["regra judaica, que pregava a superioridade espiritual","moralismo da legislação, que dificultava as reuniões","adesão do patriciado, que subvertia o conceito","decisão política, que censurava as manifestações","violência senhorial, que impunha a desestruturação"]'::jsonb, correct_answer = '"adesão do patriciado, que subvertia o conceito"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"0731e