ções gástricas. D Permitir a liberação do princípio ativo pela ação das A Absorção. amilases salivares. B Interferência. E Facilitar a liberação do fármaco pela ação dos sais C Polarização. biliares sobre o revestimento. D Reflexão.', options = '["supressão do ronco das turbinas do avião","Impedir que o fármaco seja solubilizado no intestino.","Garantir que o fármaco não seja afetado pelas","Permitir a liberação do princípio ativo pela ação das A Absorção.","Facilitar a liberação do fármaco pela ação dos sais"]'::jsonb, correct_answer = '"Garantir que o fármaco não seja afetado pelas"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"2fc2121daf966d0870a8d7d993e2fb4d8faffec36c0d97ea740dd7979ea4bf0a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"9c9e4aa4d136463ba56a749d94b9037bbb74413f4018b64dcdd723faf22439d1","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":91,"language":null,"page":2,"storagePath":"2020-D2-CD5/question-91-COMMON/statement-page-2.png","sha256":"fc21bfd692ed15b2d56ff8c07f84db2bb12c04b6b266e279262745b3039d201c","crop":{"left":0,"bottom":496.47029999999995,"width":283.254375,"height":183.58159999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":91,"language":null,"source_page":2,"source_sha256":"854495fd40b9bd61b7280f7df87b7154dadb4e2ab705f12a3c757579f369c12b"}}'::jsonb, active = true, updated_at = now() where id = v_question