  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '50fd9ee5af0f569e246e6c94d87ac319cc882cfdb20b72b1a853891484558aa8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D2', 105, 'CIENCIAS_NATUREZA', 'Grupos de proteção ao meio ambiente conseguem resgatar muitas aves aquáticas vítimas de vazamentos de petróleo. Essas aves são lavadas com água e detergente neutro para a retirada completa do óleo de seu corpo e, posteriormente, são aquecidas, medicadas, desintoxicadas e alimentadas. Mesmo após esses cuidados, o retorno ao ambiente não pode ser imediato, pois elas precisam recuperar a capacidade de flutuação. Para flutuar, essas aves precisam', '["recuperar o tônus muscular.","restaurar a massa corporal.","substituir as penas danificadas.","restabelecer a capacidade de homeotermia.","refazer a camada de cera impermeabilizante das penas."]'::jsonb, '"refazer a camada de cera impermeabilizante das penas."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"50fd9ee5af0f569e246e6c94d87ac319cc882cfdb20b72b1a853891484558aa8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"4d0f6072aa45049541b74f2e9b09f3a151106142a360797f7043fc398ed102ee","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":105,"language":null,"page":5,"storagePath":"2020-D2-CD5/question-105-COMMON/statement-page-5.png","sha256":"d8fc402ff873ffbd39b25185c18c88b40afc2bdba03ae5be21f8565758895aed","crop":{"left":0,"bottom":107.33605000000004,"width":342.92028749999986,"height":109.44044999999996}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":105,"language":null,"source_page":5,"source_sha256":"854495fd40b9bd61b7280f7df87b7154dadb4e2ab705f12a3c757579f369c12b"}}'::jsonb, true) returning id into v_question_id; end if;
