  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'b050b09e6e96338da4eb882b2d462eb9cac53dda64cb3fb833834155d47b4b05' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D2', 132, 'CIENCIAS_NATUREZA', 'A Química Verde é um ramo da química que prega o desenvolvimento de processos eficientes, que transformem a maior parte do reagente em produto, de forma mais rápida e seletiva, que utilizem poucos reagentes, que produzam somente o produto desejado, evitando a formação de coprodutos, e que utilizem solventes não agressivos ao meio ambiente. Assim, as indústrias contornariam problemas relacionados à poluição ambiental e ao desperdício de água e energia. O perfil de um processo que segue todos os princípios desse ramo da química pode ser representado por:', '["A + B + C → D (a reação ocorre a altas pressões).","A + B → C + D (a reação é fortemente endotérmica).","A + 3B → C (a reação ocorre com uso de solvente orgânico).","3A + 2B → 2C → 3D + 2E (a reação ocorrre sob pressão atmosférica). 1","A + − B → C (a reação ocorre com o uso de um catalisador contendo um metal não tóxico)."]'::jsonb, '"A + − B → C (a reação ocorre com o uso de um catalisador contendo um metal não tóxico)."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"b050b09e6e96338da4eb882b2d462eb9cac53dda64cb3fb833834155d47b4b05","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"c1ce5d669002984e44350e7c6f8d7aedbd2587872ca253c9c4f320fbcfde00f8","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":132,"language":null,"source_page":14,"source_sha256":"854495fd40b9bd61b7280f7df87b7154dadb4e2ab705f12a3c757579f369c12b"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2020, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 132, subject_area = 'CIENCIAS_NATUREZA', statement = 'A Química Verde é um ramo da química que prega o desenvolvimento de processos eficientes, que transformem a maior parte do reagente em produto, de forma mais rápida e seletiva, que utilizem poucos reagentes, que produzam somente o produto desejado, evitando a formação de coprodutos, e que utilizem solventes não agressivos ao meio ambiente. Assim, as indústrias contornariam problemas relacionados à poluição ambiental e ao desperdício de água e energia. O perfil de um processo que segue todos os princípios desse ramo da química pode ser representado por:', options = '["A + B + C → D (a reação ocorre a altas pressões).","A + B → C + D (a reação é fortemente endotérmica).","A + 3B → C (a reação ocorre com uso de solvente orgânico).","3A + 2B → 2C → 3D + 2E (a reação ocorrre sob pressão atmosférica). 1","A + − B → C (a reação ocorre com o uso de um catalisador contendo um metal não tóxico)."]'::jsonb, correct_answer = '"A + − B → C (a reação ocorre com o uso de um catalisador contendo um metal não tóxico)."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"b050b09e6e96338da4eb882b2d462eb9cac53dda64cb3fb833834155d47b4b05","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"c1ce5d669002984e44350e7c6f8d7aedbd2587872ca253c9c4f320fbcfde00f8","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","of