  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2020, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 152, subject_area = 'MATEMATICA', statement = 'A caixa-d’água de um edifício terá a forma de um O proprietário de um apartamento decidiu instalar paralelepípedo retângulo reto com volume igual a porcelanato no piso da sala. Essa sala tem formato 28 080 litros. Em uma maquete que representa o edifício, retangular com 3,2 m de largura e 3,6 m de comprimento. a caixa-d’água tem dimensões 2 cm × 3,51 cm × 4 cm. As peças do porcelanato têm formato de um quadrado Dado: 1 dm³ = 1 L. com lado medindo 80 cm. Esse porcelanato é vendido em A escala usada pelo arquiteto foi dois tipos de caixas, com os preços indicados a seguir.', options = '["1 : 10 • Caixas do tipo A: 4 unidades de piso, R$ 35,00;","1 : 100","1 : 1 000 • Caixas do tipo B: 3 unidades de piso, R$ 27,00.","1 : 10 000 Na instalação do porcelanato, as peças podem ser","1 : 100 000"]'::jsonb, correct_answer = '"1 : 1 000 • Caixas do tipo B: 3 unidades de piso, R$ 27,00."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"ff278a261313d116f30dcb0d08432a4e6c424fa35c763fc09be4affa57c017c5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"4b12431082aa7c58d47f2ff96ed78d10698a968a16edf0b0b851684d57cb88ec","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","q