  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D2', 153, 'MATEMATICA', 'Um hotel de 3 andares está sendo construído. Cada andar terá 100 quartos. Os quartos serão numerados de 100 a 399 e cada um terá seu número afixado à porta. Cada número será composto por peças individuais, cada uma simbolizando um único algarismo. Qual a quantidade mínima de peças, simbolizando o algarismo 2, necessárias para identificar o número de todos os quartos?', '["160","157","130","120 Em qual dia foi aplicada a metodologia mais eficiente?","60"]'::jsonb, '"160"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"18c72cbd3a182f24979bdc6ce917f09d5985e569d4d954a31c7b4aff292b03a9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"9b65cf13cb6cdc8d56d7fefac08d6e30376f5c016b24fb18925ed9d7fac9c2df","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":153,"language":null,"page":22,"storagePath":"2020-D2-CD5/question-153-COMMON/statement-page-22.png","sha256":"a8c47647fcbad616bf0df12073bf2c0611d0274e2c4d8395191a4ca708a84ad9","crop":{"left":252.4436999999997,"bottom":227.8222999999999,"width":314.4853000000003,"height":142.86600000000013}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"