  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2020, 'ENEM', 'REGULAR', 'D2', 174, 'MATEMATICA', 'O quadro representa os gastos mensais, em real, de uma família com internet, mensalidade escolar e Nível de envasamento mesada do filho. da garrafa Internet Mensalidade escolar Mesada do filho 120 700 400 No início do ano, a internet e a mensalidade escolar tiveram acréscimos, respectivamente, de 20% e 10%. Necessitando manter o valor da despesa mensal total com os itens citados, a família reduzirá a mesada do fi lho. Qual será a porcentagem da redução da mesada?', '["15,0","23,5","30,0","70,0","76,5"]'::jsonb, '"23,5"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', '{"canonical_id":"53b7788239fc71c83bd7be5eef020e6556b49931c524e42d644d3a4497d18cdb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"530b6e556b469b47c4b85366bcfe9d177a8200d287efafcfe0ab71d6ba580822","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":174,"language":null,"page":29,"storagePath":"2020-D2-CD5/question-174-COMMON/statement-page-29.png","sha256":"5a2cc158a2c66138a0c6a5d1df0ec8518a2dbb1f55961d9618546ba342ab51f9","crop":{"left":253.6288124999997,"bottom":93.26335000000002,"width":313.3001875000003,"height":163.74065000000002}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":174,"language":null,"source_page":29,"source_sha256":"854495fd40b9bd61b7280f7df87b7154dadb4e2ab705f12a3c757579f369c12b"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2020, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 174, subject_area = 'MATEMATICA', statement = 'O quadro representa os gastos mensais, em real, de uma família com internet, mensalidade escolar e Nível de envasamento mesada do filho. da garrafa Internet Mensalidade escolar Mesada do filho 120 700 400 No início do ano, a internet e a mensalidade escolar tiveram acréscimos, respectivamente, de 20% e 10%. Necessitando manter o valor da despesa mensal total com os itens citados, a família reduzirá a mesada do fi lho. Qual será a porcentagem da redução da mesada?', options = '["15,0","23,5","30,0","70,0","76,5"]'::jsonb, correct_answer = '"23,5"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2020', metadata = '{"canonical_id":"53b7788239fc71c83bd7be5eef020e6556b49931c524e42d644d3a4497d18cdb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"530b6e556b469b47c4b85366bcfe9d177a8200d287efafcfe0ab71d6ba580822","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":174,"language":null,"page":29,"storagePath":"2020-D2-CD5/question-174-COMMON/statement-page-29.png","sha256":"5a2cc158a2c66138a0c6a5d1df0ec8518a2dbb1f55961d9618546ba342ab51f9","crop":{"left":253.6288124999997,"bottom":93.26335000000002,"width":313.3001875000003,"height":163.74065000000002}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2020,"exam":"ENEM","application":"REGULAR","day"