  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '69e1aa3737f8c243f89f6184f96880880d941ff9d3af1c3c2923c20a3ec9aa90' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D1', 33, 'LINGUAGENS', 'Notas Soluços, lágrimas, casa armada, veludo preto nos portais, um homem que veio vestir o cadáver, outro que tomou a medida do caixão, caixão, essa, tocheiros, convites, convidados que entravam, lentamente, a passo surdo, e apertavam a mão à família, alguns tristes, todos sérios e calados, padre e sacristão, rezas, aspersões d’água benta, o fechar do caixão, a prego e martelo, seis pessoas que o tomam da essa, e o levantam, e o descem a custo pela escada, não obstante os gritos, soluços e novas lágrimas da família, e vão até o coche fúnebre, e o colocam em cima e traspassam e apertam as correias, o rodar do coche, o rodar dos carros, um a um... Isto que parece um simples inventário eram notas que eu havia tomado para um capítulo triste e vulgar que não escrevo. ASSIS, M. Memórias póstumas de Brás Cubas . Disponível em: www.dominiopublico.gov.br. Acesso em: 25 jul. 2022. O recurso linguístico que permite a Machado de Assis considerar um capítulo de Memórias póstumas de Brás Cubas como inventário é a', '["A enumeração de objetos e fatos.","B predominância de linguagem objetiva.","C ocorrência de período longo no trecho.","D combinação de verbos no presente e no pretérito.","E presença de léxico do campo semântico de funerais."]'::jsonb, '"A enumeração de objetos e fatos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"69e1aa3737f8c243f89f6184f96880880d941ff9d3af1c3c2923c20a3ec9aa90","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":fa