  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c062db9acc99a183bb221dc5a86a92ce6f8a5928a6e8d733964b5303fc52095d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D1', 44, 'LINGUAGENS', 'de “mangue”, vegetação típica da região, e “beat”, para TEXTO I representar as batidas e as influências musicais que o movimento abraçaria a partir dali. Era a hora e a vez de os caranguejos — aos quais os músicos recifenses gostavam de se comparar — mostrarem as caras: o maracatu e suas alfaias se misturaram com as batidas do hip-hop, as guitarras do rock, elementos eletrônicos e o sotaque recifense de Chico Science. A busca pelo novo rendeu uma perspectiva diferente do Brasil ao olhar para o Recife. A cidade deixou de ser o lugar apenas do frevo e do carnaval, transformando-se na ebulição musical que continua a acontecer mesmo após os 25 anos do lançamento do primeiro disco da Nação Zumbi, Da lama ao caos . FORCIONI, G. et al. O mangue está de volta. Revista Esquinas , n. 87, set. 2019 (adaptado). Chico Science foi fundamental para a renovação da música pernambucana, fato que se deu pela', '["A utilização de aparelhos musicais eletrônicos em lugar dos instrumentos tradicionais.","B ocupação de espaços da natureza local para a produção de eventos musicais memoráveis.","C substituição de antigas práticas musicais, como o frevo, por melodias e harmonias inovadoras.","D recuperação de composições tradicionais folclóricas","sua apresentação em grandes festivais."]'::jsonb, '"C substituição de antigas práticas musicais, como o frevo, por melodias e harmonias inovadoras."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"c062db9acc99a183bb221dc5a86a92ce6f8a5928a6e8d733964b5303fc52095d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"7ebd5c0b3bc00330493e23a1044b6367c91f8bc364a1621de8f7e7632d366c00","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":44,"language":null,"source_page":19,"source_sha256":"4aafd3567873578507f2bd47970c71d701c3db776654188b7d597e7284303adc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2022, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 44, subject_area = 'LINGUAGENS', statement = 'de “mangue”, vegetação típica da região, e “beat”, para TEXTO I representar as batidas e as influências musicais que o movimento abraçaria a partir dali. Era a hora e a vez de os caranguejos — aos quais os músicos recifenses gostavam de se comparar — mostrarem as caras: o maracatu e suas alfaias se misturaram com as batidas do hip-hop, as guitarras do rock, elementos eletrônicos e o sotaque recifense de Chico Science. A busca pelo novo rendeu uma perspectiva diferente do Brasil ao olhar para o Recife. A cidade deixou de ser o lugar apenas do frevo e do carnaval, transformando-se na ebulição musical que continua a acontecer mesmo após os 25 anos do lançamento do primeiro disco da Nação Zumbi, Da lama ao caos . FORCIONI, G. et al. O mangue está de volta. Revista Esquinas , n. 87, set. 2019 (adaptado). Chico Science foi fundamental para a renovação da música pernambucana, fato que se deu pela', options = '["A utilização de aparelhos musicais eletrônicos em lugar dos instrumentos tradicionais.","B ocupação de espaços da natureza local para a produção de eventos musicais memoráveis.","C substituição de antigas práticas musicais, como o frevo, por melodias e harmonias inovadoras.","D recuperação de composições tradicionais folclóricas","sua apresentação em grandes festivais."]'::jsonb, correct_answer = '"C substituição de antigas práticas musicais, como o frevo, por melodias e harmonias inovadoras."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', metadata = '{"canonical_id":"c062db9acc99a183bb221dc5a86a92ce6f8a5928a6e8d733964b5303fc52095d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"a