  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2022 and exam = 'ENEM' and application = 'REGULAR' and day = 'D1' and booklet = 'CD1' and question_number = 47 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '21ba218eecba4db8460f5221a7d99f18fe9dc540492592df3d89ca9b28b78c75' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D1', 56, 'CIENCIAS_HUMANAS', 'Os caixeiros do comércio a retalho do Rio de Janeiro TEXTO I estiveram entre as primeiras categorias de trabalhadores a se organizar em associações e a exigir a intervenção TÁ dos poderes públicos na mediação de suas lutas por ESTUDANDO, direitos. Na década de 1880, os caixeiros participaram JÚNIOR? da arena política e ganharam as ruas com vários outros, como os republicanos e os abolicionistas. POPINIGIS, F. “Todas as liberdades são irmãs”: os caixeiros e as lutas dos trabalhadores por direitos entre o Império e a República. Estudos Históricos , n. 59, set.-dez. 2016 (adaptado). A atuação dos trabalhadores mencionados no texto representou, na capital do Império, um momento de CALMA,', '["A manutenção das regras patronais. TÔ TENTANDO","B desprendimento das ideias liberais. ACHAR UM SINAL","C fortalecimento dos contratos laborais. DE WI-FI!","D consolidação das estruturas sindicais.","E contestação dos princípios monárquicos."]'::jsonb, '"A manutenção das regras patronais. TÔ TENTANDO"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"21ba218eecba4db8460f5221a7d99f18fe9dc540492592df3d89ca9b28b78c75","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"HISTORIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_HISTORIA","classification_source_fingerprint":"056f14a534a8b35f768e3cd4198e248afa1fabe729ba9479a2f1e49bb7814e2a","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":56,"language":null,"source_page":23,"source_sha256":"4aafd3567873578507f2bd47970c71d701c3db776654188b7d597e7284303adc"}}'::jsonb, true) returning id into v_question_id; end if;
