  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '11875db7e29e5c6969c61a3e05f394209a10ba7855085d29558c3b6c89c5a127' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D1', 76, 'CIENCIAS_HUMANAS', 'Lá embaixo está o Açude Itans, com seu formigueiro RADIAÇÃO SOLAR a cavar a terra. É mesmo impressionante o esforço GLOBAL HORIZONTAL daquele formigar de homens ao sol, lavados em suor, que MÉDIA ANUAL não param, em longas filas pacientes acompanhando centenas de burricos que sobem e descem, numa ciranda comovente e silenciosa, cada burrico com duas caixas de terra no lombo. É o labor organizado para a salvação da terra e do homem. Depois do semideserto que tanto nos acabrunhou o espírito por falta de chuvas, o esforço destes milhares de sertanejos, todos vestidos de brim mescla e calçando alpercatas, no combate consciente à esterilidade da natureza, com as famílias alojadas em pequeninas casas de taipa e telha — embrião de futura cidade — impressionava-nos profundamente. VALLE, F. M. História do Açude Itans, município de Caicó (RN) . Brasília, 1994 (adaptado). Na construção do empreendimento descrito, destaca-se a presença de', '["A engenheiros na execução de canais fluviais.","B coronéis na ampliação de antigas fazendas. 3,15 3,50 3,85 4,20 4,55 4,90 5,25 5,60 5,95 6,30 6,65 kWh/m²","C operários na distribuição dos recursos hídricos. 0 200 400 600 800 1000 km","D trabalhadores na formação de novos espaços. PEREIRA, E. B. et al. Atlas brasileiro de energia solar . São José dos Campos: Inpe, 2006.","E negociantes na organização de redes comerciais."]'::jsonb, '"D trabalhadores na formação de novos espaços. PEREIRA, E. B. et al. Atlas brasileiro de energia solar . São José dos Campos: Inpe, 2006."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"11875db7e29e5c6969c61a3e05f394209a10ba7855085d29558c3b6c89c5a127","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"4961924ce3c5f08913fc67dfb8c74ac16a41b0954efc06bd4067f4d64e00e600","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":76,"language":null,"source_page":28,"source_sha256":"4aafd3567873578507f2bd47970c71d701c3db776654188b7d597e7284303adc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2022, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 76, subject_area = 'CIENCIAS_HUMANAS', statement = 'Lá embaixo está o Açude Itans, com seu formigueiro RADIAÇÃO SOLAR a cavar a terra. É mesmo impressionante o esforço GLOBAL HORIZONTAL daquele formigar de homens ao sol, lavados em suor, que MÉDIA ANUAL não param, em longas filas pacientes acompanhando centenas de burricos que sobem e descem, numa ciranda comovente e silenciosa, cada burrico com duas caixas de terra no lombo. É o labor organizado para a salvação da terra e do homem. Depois do semideserto que tanto nos acabrunhou o espírito por falta de chuvas, o esforço destes milhares de sertanejos, todos vestidos de brim mescla e calçando alpercatas, no combate consciente à esterilidade da natureza, com as famílias alojadas em pequeninas casas de taipa e telha — embrião de futura cidade — impressionava-nos profundamente. VALLE, F. M. História do Açude Itans, município de Caicó (RN) . Brasília, 1994 (adaptado). Na construção do empreendimento descrito, destaca-se a presença de', options = '["A engenheiros na execução de canais fluviais.","B coronéis na ampliação de antigas fazendas. 3,15 3,50 3,85 4,20 4,55 4,90 5,25 5,60 5,95 6,30 6,65 kWh/m²","C operários na distribuição dos recursos hídricos. 0 200 400 600 800 1000 km","D trabalhadores na formação de novos espaços. PEREIRA, E. B. et al. Atlas brasileiro de energia solar . São José dos Campos: Inpe, 2006.","E negociantes na organização de redes comerciais."]'::jsonb, correct_answer = '"D trabalhadores na formação de novos espaços. PEREIRA, E. B. et al. Atlas brasileiro de energia solar . São José dos Campos: Inpe, 2006."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', metadata = '{"canonical_id":"1187