 povo Kambeba tem o rio como um(a) D D tradicionalistas dos nativos. E E emancipadores das metrópoles.', '["A objeto tombado e museográfico.","B herança religiosa e sacralizada.","C cenário bucólico e paisagístico.","D riqueza individual e efêmera.","E patrimônio cultural e afetivo."]'::jsonb, '"E patrimônio cultural e afetivo."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"aae5a28c1ef5715b1b6baacf5ed2a6e50846d72d184625a851cb21ee0c34930a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"f5b5848471757d6cb89977219638988ce507a4c6695d7b4de6092b2141be8a49","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":75,"language":null,"source_page":28,"source_sha256":"4aafd3567873578507f2bd47970c71d701c3db776654188b7d597e7284303adc"}}'::jsonb, true) returning id into v_question_id; end if;
