  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2022 and exam = 'ENEM' and application = 'REGULAR' and day = 'D2' and booklet = 'CD5' and question_number = 106 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e4e1f2f97788c508b9cee1dfab353bd487315d974d422a0231b00d187f75d1ff' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D2', 109, 'CIENCIAS_NATUREZA', 'A biomassa celulósica pode ser utilizada para a produção de etanol de segunda geração. Entretanto, é necessário que os polissacarídeos sejam convertidos em mono e dissacarídeos, processo que pode ser conduzido em meio ácido, conforme mostra o esquema: + H OH OH O H O O O O O H OH OH OH OH O H H O + O + O O O H OH OH OH OH O H O O O H O + O H OH OH O H H OH OH + O O H O H O + O OH O H O H OH H OH OGEDA, T. L.; PETRI, D. F. S. [...] Química Nova , n. 7, 2010 (adaptado). + Nessa conversão de polissacarídeos, a função do íon H é', '["A dissolver os reagentes.","B deslocar o equilíbrio químico.","C aumentar a velocidade da reação.","D mudar a constante de equilíbrio da reação.","E formar ligações de hidrogênio com o polissacarídeo."]'::jsonb, '"C aumentar a velocidade da reação."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"e4e1f2f97788c508b9cee1dfab353bd487315d974d422a0231b00d187f75d1ff","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"911d3d95778725b5cc108520e560b613843b2fed9463bd4a1306253aa7be4a66","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":109,"language":null,"source_page":8,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2022, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 109, subject_area = 'CIENCIAS_NATUREZA', statement = 'A biomassa celulósica pode ser utilizada para a produção de etanol de segunda geração. Entretanto, é necessário que os polissacarídeos sejam convertidos em mono e dissacarídeos, processo que pode ser conduzido em meio ácido, conforme mostra o esquema: + H OH OH O H O O O O O H OH OH OH OH O H H O + O + O O O H OH OH OH OH O H O O O H O + O H OH OH O H H OH OH + O O H O H O + O OH O H O H OH H OH OGEDA, T. L.; PETRI, D. F. S. [...] Química Nova , n. 7, 2010 (adaptado). + Nessa conversão de polissacarídeos, a função do íon H é', options = '["A dissolver os reagentes.","B deslocar o equilíbrio químico.","C aumentar a velocidade da reação.","D mudar a constante de equilíbrio da reação.","E formar ligações de hidrogênio com o polissacarídeo."]'::jsonb, correct_answer = '"C aumentar a velocidade da reação."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', metadata = '{"canonical_id":"e4e1f2f97788c508b9cee1dfab353bd487315d974d422a0231b00d187f75d1ff","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"911d3d95778725b5cc108520e560b613843b2fed9463bd4a1306253aa7be4a66","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":109,"language":null,"source_page":8,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
