  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8c7efda78cc2a64d8e32d23b61b627eba103a0861dd6926cf6eb735b4330da95' limit 1;
