  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2022 and exam = 'ENEM' and application = 'REGULAR' and day = 'D2' and booklet = 'CD5' and question_number = 132 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '6d8c66299b776eae4ed57b76af7c31f9a004d88e44933772254278a04bd8bc26' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D2', 133, 'CIENCIAS_NATUREZA', 'Uma lanterna funciona com três pilhas de resistência interna igual a 0,5 Ω cada, ligadas em série. Quando posicionadas corretamente, devem acender a lâmpada incandescente de especificações 4,5 W e 4,5 V. Cada pilha na posição correta gera uma f.e.m. (força eletromotriz) de 1,5 V. Uma pessoa, ao trocar as pilhas da lanterna, comete o equívoco de inverter a posição de uma das pilhas. Considere que as pilhas mantêm contato independentemente da posição. Com esse equívoco, qual é a intensidade de corrente que passa pela lâmpada ao se ligar a lanterna?', '["A 0,25 A","B 0,33 A","C 0,75 A","D 1,00 A","E 1,33 A"]'::jsonb, '"A 0,25 A"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"6d8c66299b776eae4ed57b76af7c31f9a004d88e44933772254278a04bd8bc26","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"d66bc36612997a7826d1530e14719588943091c93fe54467c46afe698b8fc6c1","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":133,"language":null,"source_page":16,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2022, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 133, subject_area = 'CIENCIAS_NATUREZA', statement = 'Uma lanterna funciona com três pilhas de resistência interna igual a 0,5 Ω cada, ligadas em série. Quando posicionadas corretamente, devem acender a lâmpada incandescente de especificações 4,5 W e 4,5 V. Cada pilha na posição correta gera uma f.e.m. (força eletromotriz) de 1,5 V. Uma pessoa, ao trocar as pilhas da lanterna, comete o equívoco de inverter a posição de uma das pilhas. Considere que as pilhas mantêm contato independentemente da posição. Com esse equívoco, qual é a intensidade de corrente que passa pela lâmpada ao se ligar a lanterna?', options = '["A 0,25 A","B 0,33 A","C 0,75 A","D 1,00 A","E 1,33 A"]'::jsonb, correct_answer = '"A 0,25 A"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', metadata = '{"canonical_id":"6d8c66299b776eae4ed57b76af7c31f9a004d88e44933772254278a04bd8bc26","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"d66bc36612997a7826d1530e14719588943091c93fe54467c46afe698b8fc6c1","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":133,"language":null,"source_page":16,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
