0. O investimento feito para a publicação do anúncio","C 200 000. nessa rede foi de R$ 200,00.","D 300 000. Por experiência, o pessoal da equipe de marketing considera que a quantidade de novas pessoas que verão","E 400 000."]'::jsonb, '"C 200 000. nessa rede foi de R$ 200,00."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"efcc693f3fac08851814846f78a5bdd6cc4f11f01fd55223233d5d66420f707d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"2d9d5d2227478b027fbd7e42de4cb951bc441934d99538d0e13f1aba97a52e5c","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":156,"language":null,"source_page":22,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, true) returning id into v_question_id; end if;
