  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e56b6791fc33fcc33400c51eb4a10eb3a25cec5013f723ca0984d0b915416639' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2022, 'ENEM', 'REGULAR', 'D2', 177, 'MATEMATICA', 'Um atleta iniciou seu treinamento visando as competições de fim de ano. Seu treinamento consiste em cinco tipos diferentes de treinos: treino T , treino T , treino T , treino T e treino T . A sequência dos treinamentos deve seguir esta ordem: 1 2 3 4 5 A letra R significa repouso. Após completar a sequência de treinamentos, o atleta começa novamente a sequência a partir do treino T e segue a ordem descrita. Após 24 semanas completas de treinamento, se dará o início das competições. 1 A sequência de treinamentos que o atleta realizará na 24ª semana de treinos é', '["A T R T R R T R. 3 4 5","B R T R T R R T . 3 4 5","C R T R R T R T . 4 5 1","D R R T R T R R. 5 1","E R T R T R R T ."]'::jsonb, '"B R T R T R R T . 3 4 5"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', '{"canonical_id":"e56b6791fc33fcc33400c51eb4a10eb3a25cec5013f723ca0984d0b915416639","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"95b6e65245f39ed3a8ff9d506541df901af57b649f20e40c9ac482281d0165f9","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":177,"language":null,"source_page":30,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2022, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 177, subject_area = 'MATEMATICA', statement = 'Um atleta iniciou seu treinamento visando as competições de fim de ano. Seu treinamento consiste em cinco tipos diferentes de treinos: treino T , treino T , treino T , treino T e treino T . A sequência dos treinamentos deve seguir esta ordem: 1 2 3 4 5 A letra R significa repouso. Após completar a sequência de treinamentos, o atleta começa novamente a sequência a partir do treino T e segue a ordem descrita. Após 24 semanas completas de treinamento, se dará o início das competições. 1 A sequência de treinamentos que o atleta realizará na 24ª semana de treinos é', options = '["A T R T R R T R. 3 4 5","B R T R T R R T . 3 4 5","C R T R R T R T . 4 5 1","D R R T R T R R. 5 1","E R T R T R R T ."]'::jsonb, correct_answer = '"B R T R T R R T . 3 4 5"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2022', metadata = '{"canonical_id":"e56b6791fc33fcc33400c51eb4a10eb3a25cec5013f723ca0984d0b915416639","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"95b6e65245f39ed3a8ff9d506541df901af57b649f20e40c9ac482281d0165f9","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2022,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":177,"language":null,"source_page":30,"source_sha256":"068a960ff3fde64d89484995f1a323676c354ad1efa27c109f09a4bb90619756