  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5abd6c4e1f282beeff9bfe3f7a51209c2c8050ab806c181a2b84f14681c62cd5' limit 1;
