to de Agualusa tematiza o preconceito em relação","D associação entre o lema olímpico e a cooperatividade. ao português brasileiro. Com base no trecho citado pelo","E vinculação entre o lema olímpico e os eventos atléticos."]'::jsonb, '"D associação entre o lema olímpico e a cooperatividade. ao português brasileiro. Com base no trecho citado pelo"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"6fcd0e4e454057b1f7140fcd94d5aca60dcc28e640894be4ff935c9b9aec2915","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"109be284ba6bc5246e78d24b23ad6d8461c42eed30fbe1b8d32b2208661e84a9","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":6,"language":null,"source_page":6,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
