  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D1', 16, 'LINGUAGENS', 'O uso não padrão dos colchetes para nomear a revista atribui-lhes uma nova função e está correlacionado ao(à) Mandioca, macaxeira, aipim e castelinha são nomes A A perfil de público-alvo, constituído por leitores exigentes diferentes da mesma planta. Semáforo, sinaleiro e farol e especializados em leitura acadêmica. também significam a mesma coisa. O que muda é só o hábito cultural de cada região. A mesma coisa acontece B B propósito do editor, chamando a atenção para o rigor com a Língua Brasileira de Sinais (Libras). Embora ela normativo nos textos da revista. seja a comunicação oficial da comunidade surda no Brasil, C C exclusividade na seleção temática, direcionada para existem sinais que variam em relação à região, à idade e até a área das ciências humanas. ao gênero de quem se comunica. A cor verde, por exemplo, D D identidade da revista, voltada para a recepção e a possui sinais diferentes no Rio de Janeiro, Paraná e São promoção de ideias circulantes em livros. Paulo. São os regionalismos na língua de sinais. E E padrão editorial dos artigos, organizados em torno de Essas variações são um dos temas da disciplina uma proposta de design inovador. Linguística na língua de sinais, oferecida pela Universidade Estadual Paulista (Unesp) ao longo do segundo semestre.', '["A perfil de público-alvo, constituído por leitores exigentes","B propósito do editor, chamando a atenção para o rigor","C exclusividade na seleção temática, direcionada para","D identidade da revista, voltada para a recepção e a","está correlacionado ao(à)"]'::jsonb, '"A perfil de público-alvo, constituído por leitores exigentes"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"f14327d3890173b5701bf6818a20e64719459054c94d068fdb15394d213e0ee4","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"6aeb9d14ea0a2c74d7f42896866e1709a86788888e05d87ce509b62f773ad169","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":16,"language":null,"source_page":10,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 16, subject_area = 'LINGUAGENS', statement = 'O uso não padrão dos colchetes para nomear a revista atribui-lhes uma nova função e está correlacionado ao(à) Mandioca, macaxeira, aipim e castelinha são nomes A A perfil de público-alvo, constituído por leitores exigentes diferentes da mesma planta. Semáforo, sinaleiro e farol e especializados em leitura acadêmica. também significam a mesma coisa. O que muda é só o hábito cultural de cada região. A mesma coisa acontece B B propósito do editor, chamando a atenção para o rigor com a Língua Brasileira de Sinais (Libras). Embora ela normativo nos textos da revista. seja a comunicação oficial da comunidade surda no Brasil, C C exclusividade na seleção temática, direcionada para existem sinais que variam em relação à região, à idade e até a área das ciências humanas. ao gênero de quem se comunica. A cor verde, por exemplo, D D identidade da revista, voltada para a recepção e a possui sinais diferentes no Rio de Janeiro, Paraná e São promoção de ideias circulantes em livros. Paulo. São os regionalismos na língua de sinais. E E padrão editorial dos artigos, organizados em torno de Essas variações são um dos temas da disciplina uma proposta de design inovador. Linguística na língua de sinais, oferecida pela Universidade Estadual Paulista (Unesp) ao longo do segundo semestre.', options = '["A perfil de público-alvo, constituído por leitores exigentes","B propósito do editor, chamando a atenção para o rigor","C exclusividade na seleção temática, direcionada para","D identidade da revista, voltada para a recepção e a","está correlacionado ao(à)"]'::jsonb, correct_answer = '"A perfil de público-alvo, constituído por leitores exigentes"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"f14327d3890173b5701bf6818a20e64719459054c94d068fdb15394d213e0ee4","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"6aeb9d14ea0a2c74d7f42896866e1709a86788888e05d87ce509b62f773ad169","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":16,"language":null,"source_page":10,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
