  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2023 and exam = 'ENEM' and application = 'REGULAR' and day = 'D1' and booklet = 'CD1' and question_number = 54 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'b9e6f41bd7cd595988792cef9ec0ccfa26c8548f77a2cae44f26dcf0d3982825' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D1', 55, 'CIENCIAS_HUMANAS', 'A diversão é o prolongamento do trabalho sob o capitalismo tardio. Ela é procurada por quem quer escapar ao processo de trabalho mecanizado para se pôr de novo em condições de enfrentá-lo. Mas, ao mesmo tempo, a mecanização atingiu um tal poderio sobre a pessoa em seu lazer e sobre a sua felicidade, ela determina tão profundamente a fabricação das mercadorias destinadas à diversão que essa pessoa não pode mais perceber outra coisa senão as cópias que reproduzem o próprio processo de trabalho. ADORNO, T.; HORKHEIMER, M. Dialética do esclarecimento . Rio de Janeiro: Zahar, 1997. No texto, o tempo livre é concebido como', '["A consumo de produtos culturais elaborados no mesmo sistema produtivo do capitalismo.","B forma de realizar as diversas potencialidades da natureza humana.","C alternativa para equilibrar tensões psicológicas do dia a dia.","D promoção da satisfação de necessidades artificiais.","E mecanismo de organização do ócio e do prazer."]'::jsonb, '"A consumo de produtos culturais elaborados no mesmo sistema produtivo do capitalismo."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"b9e6f41bd7cd595988792cef9ec0ccfa26c8548f77a2cae44f26dcf0d3982825","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"49e078474d6ae929bb9444f419da98dd097aaf06f6e2bb5271cba1874765319c","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":55,"language":null,"source_page":22,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 55, subject_area = 'CIENCIAS_HUMANAS', statement = 'A diversão é o prolongamento do trabalho sob o capitalismo tardio. Ela é procurada por quem quer escapar ao processo de trabalho mecanizado para se pôr de novo em condições de enfrentá-lo. Mas, ao mesmo tempo, a mecanização atingiu um tal poderio sobre a pessoa em seu lazer e sobre a sua felicidade, ela determina tão profundamente a fabricação das mercadorias destinadas à diversão que essa pessoa não pode mais perceber outra coisa senão as cópias que reproduzem o próprio processo de trabalho. ADORNO, T.; HORKHEIMER, M. Dialética do esclarecimento . Rio de Janeiro: Zahar, 1997. No texto, o tempo livre é concebido como', options = '["A consumo de produtos culturais elaborados no mesmo sistema produtivo do capitalismo.","B forma de realizar as diversas potencialidades da natureza humana.","C alternativa para equilibrar tensões psicológicas do dia a dia.","D promoção da satisfação de necessidades artificiais.","E mecanismo de organização do ócio e do prazer."]'::jsonb, correct_answer = '"A consumo de produtos culturais elaborados no mesmo sistema produtivo do capitalismo."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"b9e6f41bd7cd595988792cef9ec0ccfa26c8548f77a2cae44f26dcf0d3982825","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"49e078474d6ae929bb9444f419da98dd097aaf06f6e2bb5271cba1874765319c","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evi