  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '93252de9ea0f5bf986bc5e406ccec42aaa7e155ff5bf464507393d8de47b11d0' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D1', 58, 'CIENCIAS_HUMANAS', 'O processo social relatado indica a formação de uma etiqueta que tem como princípio a A Cavalgada de Sant’Ana é uma expressão da devoção A A distinção das classes sociais. dos vaqueiros à padroeira de Caicó (RN). Nas décadas de 1950 a 1970, esse evento, então denominado Cavalaria, B B valorização de hábitos de higiene. era celebrado pelas pessoas que residiam na zona rural C C exaltação da cultura mediterrânea. do município de Caicó. Essas pessoas usavam os animais D D consagração de tradições medievais. (jegues, mulas e cavalos) como único meio de transporte, E E disseminação de produtos manufaturados. sobretudo para se dirigirem à cidade nos dias de feiras, trazendo seus produtos para comercializarem. Estando em', '["Cavalgada de Sant’Ana é uma expressão da devoção","B valorização de hábitos de higiene.","C exaltação da cultura mediterrânea.","D consagração de tradições medievais.","E disseminação de produtos manufaturados."]'::jsonb, '"Cavalgada de Sant’Ana é uma expressão da devoção"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"93252de9ea0f5bf986bc5e406ccec42aaa7e155ff5bf464507393d8de47b11d0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"SOCIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_SOCIOLOGIA","classification_source_fingerprint":"d292286043aa5e4cc5c30bbd1434d34febb016e5c6ccc9bb2850dc7a181e8ae3","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":58,"language":null,"source_page":23,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
