  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D1', 67, 'CIENCIAS_HUMANAS', 'depois que o Talibã assumiu o controle de sua cidade e milhares de criminosos condenados foram libertados No sul da Bahia, desde o século XVIII, tem-se da prisão, as ameaças de morte começaram. O país registros de um tipo de sistema agroflorestal. Até hoje, sempre foi considerado um dos lugares mais difíceis e esse sistema é característica marcante da paisagem perigosos do mundo para as mulheres. De acordo com da região, conhecido como cabruca, que consiste no estudos de organizações não governamentais, cerca de cultivo do cacau à sombra do dossel da floresta nativa. 87% das mulheres e meninas serão vítimas de abuso Esse sistema de cultivo do cacau (graças à tolerância durante a vida. da espécie à sombra) é considerado amigável para a Disponível em: https://g1.globo.com. Acesso em: 12 out. 2021 (adaptado). vida silvestre, pois apresenta superioridade em termos O texto evidencia situação representativa de de conservação da biodiversidade quando comparado A A afronta às estruturas sociais. com outras plantações tropicais (monoculturas de dendê, seringa ou café), agricultura ou pastagens. B B desprezo aos valores religiosos. SOLLBERG, I.; SCHIAVETTI, A.; MORAES, M. E. B. Manejo agrícola no C C transgressão às normas morais. Refúgio de Vida Silvestre de Una: agroflorestas como uma perspectiva de conservação. Revista Árvore , n. 2, 2014 (adaptado). D D desrespeito à dignidade humana. A prática produtiva apresentada é um exemplo de E E oposição aos princípios hierárquicos.', '["A difusão comercial de lavouras temporárias.","B utilização sustentável dos recursos naturais.","C ampliação tecnológica da pecuária intensiva.","D padronização alimentar dos povos tradicionais.","E modernização logística de plantios convencionais."]'::jsonb, '"B utilização sustentável dos recursos naturais."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"2ea44294b25fe8b3ed5299c90d553140dc30ce7a0d0be00f30fa1b08699e8755","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"abfdf37f2d69fb8a5b7404fe465c4d7054c9d13bd3599eaffb1e96a63733721d","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":67,"language":null,"source_page":25,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 67, subject_area = 'CIENCIAS_HUMANAS', statement = 'depois que o Talibã assumiu o controle de sua cidade e milhares de criminosos condenados foram libertados No sul da Bahia, desde o século XVIII, tem-se da prisão, as ameaças de morte começaram. O país registros de um tipo de sistema agroflorestal. Até hoje, sempre foi considerado um dos lugares mais difíceis e esse sistema é característica marcante da paisagem perigosos do mundo para as mulheres. De acordo com da região, conhecido como cabruca, que consiste no estudos de organizações não governamentais, cerca de cultivo do cacau à sombra do dossel da floresta nativa. 87% das mulheres e meninas serão vítimas de abuso Esse sistema de cultivo do cacau (graças à tolerância durante a vida. da espécie à sombra) é considerado amigável para a Disponível em: https://g1.globo.com. Acesso em: 12 out. 2021 (adaptado). vida silvestre, pois apresenta superioridade em termos O texto evidencia situação representativa de de conservação da biodiversidade quando comparado A A afronta às estruturas sociais. com outras plantações tropicais (monoculturas de dendê, seringa ou café), agricultura ou pastagens. B B desprezo aos valores religiosos. SOLLBERG, I.; SCHIAVETTI, A.; MORAES, M. E. B. Manejo agrícola no C C transgressão às normas morais. Refúgio de Vida Silvestre de Una: agroflorestas como uma perspectiva de conservação. Revista Árvore , n. 2, 2014 (adaptado). D D desrespeito à dignidade humana. A prática produtiva apresentada é um exemplo de E E oposição aos princípios hierárquicos.', options = '["A difusão comercial de lavouras temporárias.","B utilização sustentável dos recursos naturais.","C ampliação tecnológica da pecuária intensiva.","D padronização alimentar dos povos tradicionais.","E modernização logística de plantios convencionais."]'::jsonb, correct_answer = '"B utilização sustentável dos recursos naturais."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"2ea44294b25fe8b3ed5299c90d553140dc30ce7a0d0be00f30fa1b08699e8755","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"abfdf37f2d69fb8a5b7404fe465c4d7054c9d13bd3599eaffb1e96a63733721d","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":67,"language":null,"source_page":25,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
