  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2023 and exam = 'ENEM' and application = 'REGULAR' and day = 'D1' and booklet = 'CD4' and question_number = 66 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'df0bf2ed16777985880be0bffdb82a4d25d73a774a8f2509fda215c24fd9cf24' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D1', 90, 'CIENCIAS_HUMANAS', 'Não tinha outra filosofia. Nem eu. Não digo que a Universidade me não tivesse ensinado alguma; mas eu decorei-lhe só as fórmulas, o vocabulário, o esqueleto. Tratei-a como tratei o latim; embolsei três versos de Virgílio, dois de Horácio, uma dúzia de locuções morais e políticas, para as despesas da conversação. Tratei-os como tratei a história e a jurisprudência. Colhi de todas as cousas a fraseologia, a casca, a ornamentação. ASSIS, M. Memórias póstumas de Brás Cubas . Belo Horizonte: Autêntica, 1999. A descrição crítica do personagem de Machado de Assis assemelha-se às características dos sofistas, contestados pelos filósofos gregos da Antiguidade, porque se mostra alinhada à', '["A elaboração conceitual de entendimentos.","B utilização persuasiva do discurso.","C narração alegórica dos rapsodos.","D investigação empírica da physis.","E expressão pictográfica da pólis."]'::jsonb, '"B utilização persuasiva do discurso."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"df0bf2ed16777985880be0bffdb82a4d25d73a774a8f2509fda215c24fd9cf24","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"HISTORIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_HISTORIA","classification_source_fingerprint":"45d46874d8f1c0e3314a872166e232427f775b7f38080e08cd8e2f654181e85d","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":90,"language":null,"source_page":31,"source_sha256":"8f0f7ff3ae3bdf64754fdc48d7c79bad696b053f80d3083373580dc48b484fc8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 90, subject_area = 'CIENCIAS_HUMANAS', statement = 'Não tinha outra filosofia. Nem eu. Não digo que a Universidade me não tivesse ensinado alguma; mas eu decorei-lhe só as fórmulas, o vocabulário, o esqueleto. Tratei-a como tratei o latim; embolsei três versos de Virgílio, dois de Horácio, uma dúzia de locuções morais e políticas, para as despesas da conversação. Tratei-os como tratei a história e a jurisprudência. Colhi de todas as cousas a fraseologia, a casca, a ornamentação. ASSIS, M. Memórias póstumas de Brás Cubas . Belo Horizonte: Autêntica, 1999. A descrição crítica do personagem de Machado de Assis assemelha-se às características dos sofistas, contestados pelos filósofos gregos da Antiguidade, porque se mostra alinhada à', options = '["A elaboração conceitual de entendimentos.","B utilização persuasiva do discurso.","C narração alegórica dos rapsodos.","D investigação empírica da physis.","E expressão pictográfica da pólis."]'::jsonb, correct_answer = '"B utilização persuasiva do discurso."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"df0bf2ed16777985880be0bffdb82a4d25d73a774a8f2509fda215c24fd9cf24","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"HISTORIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_HISTORIA","classification_source_fingerprint":"45d46874d8f1c0e3314a872166e232427f775b7f38080e08cd8e2f654181e85d","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_prov