  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2023 and exam = 'ENEM' and application = 'REGULAR' and day = 'D1' and booklet = 'CD4' and question_number = 87 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '3f1e867ac07f2be1cfc6abf2612a7f437018cc65656784878925f86f10e331cd' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 92, 'CIENCIAS_NATUREZA', 'Informações digitais — dados — são gravadas em discos ópticos, como CD e DVD, na forma de cavidades microscópicas. A gravação e a leitura óptica dessas informações são realizadas por um laser (fonte de luz monocromática). Quanto menores as dimensões dessas cavidades, mais dados são armazenados na mesma área do disco. O fator limitante para a leitura de dados é o espalhamento da luz pelo efeito de difração, fenômeno que ocorre quando a luz atravessa um obstáculo com dimensões da ordem de seu comprimento de onda. Essa limitação motivou o desenvolvimento de lasers com emissão em menores comprimentos de onda, possibilitando armazenar e ler dados em cavidades cada vez menores. Em qual região espectral se situa o comprimento de onda do laser que otimiza o armazenamento e a leitura de dados em discos de uma mesma área?', '["A Violeta.","B Azul.","C Verde.","D Vermelho.","E Infravermelho."]'::jsonb, '"A Violeta."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"3f1e867ac07f2be1cfc6abf2612a7f437018cc65656784878925f86f10e331cd","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"bfcaa64c08016ffdaa4844f967c23afc870744be37ffdb4879bdce8d9924cf53","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":92,"language":null,"source_page":2,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 92, subject_area = 'CIENCIAS_NATUREZA', statement = 'Informações digitais — dados — são gravadas em discos ópticos, como CD e DVD, na forma de cavidades microscópicas. A gravação e a leitura óptica dessas informações são realizadas por um laser (fonte de luz monocromática). Quanto menores as dimensões dessas cavidades, mais dados são armazenados na mesma área do disco. O fator limitante para a leitura de dados é o espalhamento da luz pelo efeito de difração, fenômeno que ocorre quando a luz atravessa um obstáculo com dimensões da ordem de seu comprimento de onda. Essa limitação motivou o desenvolvimento de lasers com emissão em menores comprimentos de onda, possibilitando armazenar e ler dados em cavidades cada vez menores. Em qual região espectral se situa o comprimento de onda do laser que otimiza o armazenamento e a leitura de dados em discos de uma mesma área?', options = '["A Violeta.","B Azul.","C Verde.","D Vermelho.","E Infravermelho."]'::jsonb, correct_answer = '"A Violeta."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"3f1e867ac07f2be1cfc6abf2612a7f437018cc65656784878925f86f10e331cd","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"bfcaa64c08016ffdaa4844f967c23afc870744be37ffdb4879bdce8d9924cf53","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"