  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '18bcc2f66d10d4e6db89ea0ef81c5e524d315b489250127cecb7f0bd8b9683ec' limit 1;
