  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '130e3abe23b05fdec4202dcf65e7bb504b7ad552645ccb6e9d2932888c13ac61' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 100, 'CIENCIAS_NATUREZA', 'Aparelho do tipo 2 Aparelho do tipo 1 Na fertilização in vitro, espermatozoides são adicionados aos gametas femininos retirados de uma mulher. Após o período de incubação, a fecundação é favorecida pela ação de enzimas. Em um procedimento realizado, observou-se que nenhum dos gametas femininos foi fertilizado e, posteriormente, verificou-se que havia sido adicionado, equivocadamente, um coquetel de inibidores das enzimas do acrossomo, no lugar de um dos nutrientes constituintes do meio de cultura. F F O coquetel de inibidores impediu o(a)', '["A formação do pronúcleo masculino.","B início da divisão mitótica do zigoto. M M 1 2","C término da segunda divisão meiótica do ovócito.","D passagem do espermatozoide pela corona radiata e zona pelúcida. M 2 Para essa academia, qual deve ser a razão informada M","E fusão das membranas plasmáticas do ovócito e do 1 aos usuários?"]'::jsonb, '"D passagem do espermatozoide pela corona radiata e zona pelúcida. M 2 Para essa academia, qual deve ser a razão informada M"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"130e3abe23b05fdec4202dcf65e7bb504b7ad552645ccb6e9d2932888c13ac61","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"a95691f520668c02c93d725cddb62b0b29ebc457210f512d03f9229e6e8d0cd2","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":100,"language":null,"source_page":5,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 100, subject_area = 'CIENCIAS_NATUREZA', statement = 'Aparelho do tipo 2 Aparelho do tipo 1 Na fertilização in vitro, espermatozoides são adicionados aos gametas femininos retirados de uma mulher. Após o período de incubação, a fecundação é favorecida pela ação de enzimas. Em um procedimento realizado, observou-se que nenhum dos gametas femininos foi fertilizado e, posteriormente, verificou-se que havia sido adicionado, equivocadamente, um coquetel de inibidores das enzimas do acrossomo, no lugar de um dos nutrientes constituintes do meio de cultura. F F O coquetel de inibidores impediu o(a)', options = '["A formação do pronúcleo masculino.","B início da divisão mitótica do zigoto. M M 1 2","C término da segunda divisão meiótica do ovócito.","D passagem do espermatozoide pela corona radiata e zona pelúcida. M 2 Para essa academia, qual deve ser a razão informada M","E fusão das membranas plasmáticas do ovócito e do 1 aos usuários?"]'::jsonb, correct_answer = '"D passagem do espermatozoide pela corona radiata e zona pelúcida. M 2 Para essa academia, qual deve ser a razão informada M"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"130e3abe23b05fdec4202dcf65e7bb504b7ad552645ccb6e9d2932888c13ac61","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"a95691f520668c02c93d725cddb62b0b29ebc457210f512d03f9229e6e8d0cd2","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":100,"language":null,"source_page":5,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
