  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '510f5f2ee2dbce422f7c4ea64eb0c394a65a066279ebbc506677e3df657639b4' limit 1;
