  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0b4516ee299fc7eea98bdc11eb1d6b86740e62e3eab13f97d0d7d9268da9fa1d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 139, 'MATEMATICA', 'Uma pessoa pratica quatro atividades físicas — caminhar, correr, andar de bicicleta e jogar futebol — como parte de seu programa de emagrecimento. Essas atividades são praticadas semanalmente de acordo com o quadro, que apresenta o número de horas diárias por atividade. Dias da semana Caminhar Correr Andar de bicicleta Jogar futebol Segunda-feira 1,0 0,5 0,0 2,0 Terça-feira 0,5 1,0 0,5 1,0 Quarta-feira 0,0 1,5 1,0 0,5 Quinta-feira 0,0 2,0 0,0 0,0 Sexta-feira 0,0 0,5 0,0 2,5 Ela deseja comemorar seu aniversário e escolhe o dia da semana em que o gasto calórico com as atividades físicas praticadas for o maior. Para tanto, considera que os valores dos gastos calóricos das atividades por hora (cal/h) são os seguintes: Atividade física Caminhar Correr Andar de bicicleta Jogar futebol Gasto calórico (cal/h) 248 764 356 492 O dia da semana em que será comemorado o aniversário é', '["A segunda-feira.","B terça-feira.","C quarta-feira.","D quinta-feira.","E sexta-feira."]'::jsonb, '"C quarta-feira."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"0b4516ee299fc7eea98bdc11eb1d6b86740e62e3eab13f97d0d7d9268da9fa1d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"ed3f2c1b95563062a27b606c9b2cc8d4876e44c4705d29caa651d6fc140b048c","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":139,"language":null,"source_page":17,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, true) returning id into v_question_id; end if;
