  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'bd8100cd5b3467b995522ec6d0601e6eeee19d9c81c3a3e4e6e36e3d5bd8bb99' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 152, 'MATEMATICA', 'em função do tempo, contado a partir do instante em que Os números figurados pentagonais provavelmente a cadeira da pessoa P se encontra na posição mais alta foram introduzidos pelos pitagóricos por volta do da roda-gigante, é século V a.C. As figuras ilustram como obter os seis primeiros deles, sendo os demais obtidos seguindo o mesmo padrão geométrico. A A Altura em relação ao solo Tempo 0 22 12 5 1 B B Altura em relação ao solo Tempo 0 35 51 O oitavo número pentagonal é C C A A 59. Altura em B B 83. relação ao solo C C 86. Tempo 0 D D 89. E E 92.', '["partir do instante em que","B","C 86.","D 89.","E 92."]'::jsonb, '"E 92."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"bd8100cd5b3467b995522ec6d0601e6eeee19d9c81c3a3e4e6e36e3d5bd8bb99","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"9dc750204cd6872bc234a2a7074c125949f3f0d598c4bb2c103f3827a5780b6b","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":152,"language":null,"source_page":22,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137b