  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 152, subject_area = 'MATEMATICA', statement = 'em função do tempo, contado a partir do instante em que Os números figurados pentagonais provavelmente a cadeira da pessoa P se encontra na posição mais alta foram introduzidos pelos pitagóricos por volta do da roda-gigante, é século V a.C. As figuras ilustram como obter os seis primeiros deles, sendo os demais obtidos seguindo o mesmo padrão geométrico. A A Altura em relação ao solo Tempo 0 22 12 5 1 B B Altura em relação ao solo Tempo 0 35 51 O oitavo número pentagonal é C C A A 59. Altura em B B 83. relação ao solo C C 86. Tempo 0 D D 89. E E 92.', options = '["partir do instante em que","B","C 86.","D 89.","E 92."]'::jsonb, correct_answer = '"E 92."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"bd8100cd5b3467b995522ec6d0601e6eeee19d9c81c3a3e4e6e36e3d5bd8bb99","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"9dc750204cd6872bc234a2a7074c125949f3f0d598c4bb2c103f3827a5780b6b","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":152,"language":null,"source_page":22,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
