  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 175, 'MATEMATICA', 'Um supermercado conta com cinco caixas disponíveis Na planta baixa de um clube, a piscina é representada para pagamento. Foram instaladas telas que apresentam por um quadrado cuja área real mede 400 m². Ao redor o tempo médio gasto por cada caixa para iniciar e finalizar o dessa piscina, será construída uma calçada, de largura atendimento de cada cliente, e o número de pessoas constante igual a 5 m. presentes na fila de cada caixa em tempo real. Um cliente, na hora de passar sua compra, sabendo que cada um 5 m Calçada dos cinco caixas iniciará um novo atendimento naquele momento, pretende gastar o menor tempo possível de espera na fila. Ele observa que as telas apresentavam as informações a seguir. 5 m • Caixa I: atendimento 12 minutos, 5 pessoas na fila. Piscina • Caixa II: atendimento 6 minutos, 9 pessoas na fila. • Caixa III: atendimento 5 minutos, 6 pessoas na fila. • Caixa IV: atendimento 15 minutos, 2 pessoas na fila. 5 m • Caixa V: atendimento 9 minutos, 3 pessoas na fila. Para alcançar seu objetivo, o cliente deverá escolher o caixa 5 m', '["A I.","B II. Qual é a medida da área, em metro quadrado, ocupada","C III. pela calçada?","D IV. A A 1 000","E V. B B 900"]'::jsonb, '"D IV. A A 1 000"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"320a6a678d845482800ba2afda4f568d9686c9f7243984c457717578dd6080c1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"900dab3a689314455a78727bef6cfb9f9c8be34b7d849baa254917ed6bb0f554","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":175,"language":null,"source_page":29,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2023, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 175, subject_area = 'MATEMATICA', statement = 'Um supermercado conta com cinco caixas disponíveis Na planta baixa de um clube, a piscina é representada para pagamento. Foram instaladas telas que apresentam por um quadrado cuja área real mede 400 m². Ao redor o tempo médio gasto por cada caixa para iniciar e finalizar o dessa piscina, será construída uma calçada, de largura atendimento de cada cliente, e o número de pessoas constante igual a 5 m. presentes na fila de cada caixa em tempo real. Um cliente, na hora de passar sua compra, sabendo que cada um 5 m Calçada dos cinco caixas iniciará um novo atendimento naquele momento, pretende gastar o menor tempo possível de espera na fila. Ele observa que as telas apresentavam as informações a seguir. 5 m • Caixa I: atendimento 12 minutos, 5 pessoas na fila. Piscina • Caixa II: atendimento 6 minutos, 9 pessoas na fila. • Caixa III: atendimento 5 minutos, 6 pessoas na fila. • Caixa IV: atendimento 15 minutos, 2 pessoas na fila. 5 m • Caixa V: atendimento 9 minutos, 3 pessoas na fila. Para alcançar seu objetivo, o cliente deverá escolher o caixa 5 m', options = '["A I.","B II. Qual é a medida da área, em metro quadrado, ocupada","C III. pela calçada?","D IV. A A 1 000","E V. B B 900"]'::jsonb, correct_answer = '"D IV. A A 1 000"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', metadata = '{"canonical_id":"320a6a678d845482800ba2afda4f568d9686c9f7243984c457717578dd6080c1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"900dab3a689314455a78727bef6cfb9f9c8be34b7d849baa254917ed6bb0f554","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":175,"language":null,"source_page":29,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
