  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5ec7374f77b87f8851a8c677cf042971fa5e4c858e3ddc8a9c708cd355a0eff2' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2023, 'ENEM', 'REGULAR', 'D2', 180, 'MATEMATICA', 'O metrô de um município oferece dois tipos de tíquetes com colorações diferentes, azul e vermelha, sendo vendidos em cartelas, cada qual com nove tíquetes da mesma cor e mesmo valor unitário. Duas cartelas de tíquetes azuis e uma cartela de tíquetes vermelhos são vendidas por R$ 32,40. Sabe-se que o preço de um tíquete azul menos o preço de um tíquete vermelho é igual ao preço de um tíquete vermelho mais cinco centavos. Qual o preço, em real, de uma cartela de tíquetes vermelhos?', '["A 4,68","B 6,30","C 9,30","D 10,50","E 10,65"]'::jsonb, '"B 6,30"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2023', '{"canonical_id":"5ec7374f77b87f8851a8c677cf042971fa5e4c858e3ddc8a9c708cd355a0eff2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"f446bf5feb2c12880069929afcbc8eb97fce6a2f8c31a95ea54a656031b4398d","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2023,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":180,"language":null,"source_page":31,"source_sha256":"818b89dec87eb0b77bf77f96d3e744502c7bdffb57166d2b5137beb3a6b9ac59"}}'::jsonb, true) returning id into v_question_id; end if;
