  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0ddba43b7fb137356218de14447625d1e4407705f8104495ccd705a893d02da1' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 18, 'LINGUAGENS', 'Nesse fragmento do romance de Júlia Lopes de Almeida, escrito no cenário brasileiro pós-abolição, a narradora Um estudo norte-americano analisou os efeitos exprime um olhar crítico sobre a da pandemia da covid-19 sobre a saúde mental e a manutenção da atividade física, revelando que um fator A desvalorização da arte produzida por mulheres. está diretamente ligado ao outro. De acordo com os dados, B mudança das condições de moradia do povo negro. famílias de baixa renda foram mais impactadas pelo C ruptura do projeto político de emancipação feminina. ciclo vicioso de falta de motivação e pelo sedentarismo. D exploração da força de trabalho da população negra. Diante da necessidade de distanciamento social e do E disputa de poder entre brancos e negros no século XIX. início da quarentena, as opções de espaços seguros para exercícios físicos diminuíram, o que dificultou que as', '["desvalorização da arte produzida por mulheres.","mudança das condições de moradia do povo negro.","ruptura do projeto político de emancipação feminina.","exploração da força de trabalho da população negra.","disputa de poder entre brancos e negros no século XIX."]'::jsonb, '"exploração da força de trabalho da população negra."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"0ddba43b7fb137356218de14447625d1e4407705f8104495ccd705a893d02da1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"c99a0bcc45e52b5606d18014d113eaeeb6be268bd03a09f93847b8526d44379c","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":18,"language":null,"page":9,"storagePath":"2024-D1-CD1/question-18-COMMON/statement-page-9.png","sha256":"8b22118a0e61219bd73b607f3118f0334cfe7a6282575a3d6bb6ba7d72198675","crop":{"left":0,"bottom":694.3709,"width":293.51627000000195,"height":58.891399999999976}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":18,"language":null,"source_page":9,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
