  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'b0539c079a5322669542c07fc7572daf8a89d39f155b3b441c6b0cefd9e4bd55' limit 1;
