 linguístico a situações de coloquialidade.","associa o uso da norma culta à ocorrência de"]'::jsonb, '"contrapõe o preciosismo linguístico a situações de coloquialidade."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"b0539c079a5322669542c07fc7572daf8a89d39f155b3b441c6b0cefd9e4bd55","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"4306331b0473288c4e48dbf4ec11006835cc09ac9f28bf27f4ee5d47f26b9b90","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":24,"language":null,"page":11,"storagePath":"2024-D1-CD1/question-24-COMMON/statement-page-11.png","sha256":"46137b01559eaa689c8d4a008373d4d64019d4952ccb1a8e43b8688b1d80edb7","crop":{"left":0,"bottom":296.6069,"width":287.574220000002,"height":85.63029999999998}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":24,"language":null,"source_page":11,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
