  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2024 and exam = 'ENEM' and application = 'REGULAR' and day = 'D1' and booklet = 'CD4' and question_number = 19 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '71b0fd61df5eeb0e52622bf45d9726569b2725baa446bdd08407736a88af79fa' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 35, 'LINGUAGENS', '— Eu lhe juro, Aurélia. Estes lábios nunca tocaram a face de outra mulher, que não fosse minha mãe. Meu primeiro beijo de amor, guardei-o para minha esposa, para ti... [...] — Ou de outra mais rica! — disse ela, retraindo-se para fugir ao beijo do marido, e afastando-o com a ponta dos dedos. A voz da moça tomara o timbre cristalino, eco da rispidez e aspereza do sentimento que lhe sublevava o seio, e que parecia ringir-lhe nos lábios como aço. — Aurélia! Que significa isto? — Representamos uma comédia, na qual ambos desempenhamos o nosso papel com perícia consumada. Podemos ter este orgulho, que os melhores atores não nos excederiam. Mas é tempo de pôr termo a esta cruel mistificação, com que nos estamos escarnecendo mutuamente, senhor. Entremos na realidade por mais triste que ela seja; e resigne-se cada um ao que é, eu, uma mulher traída; o senhor, um homem vendido. — Vendido! — exclamou Seixas ferido dentro d’alma. — Vendido, sim: não tem outro nome. Sou rica, muito rica; sou milionária; precisava de um marido, traste indispensável às mulheres honestas. O senhor estava no mercado; comprei-o. Custou-me cem contos de réis, foi barato; não se fez valer. Eu daria o dobro, o triplo, toda a minha riqueza por este momento. ALENCAR, J. Senhora . Rio de Janeiro: Tecnoprint, 2003. Ao tematizar o casamento, esse fragmento reproduz uma concepção de literatura romântica evidenciada na', '["defesa da igualdade de gêneros.","importância atribuída à castidade.","indignação com as injustiças sociais.","interferência da riqueza sobre o amor.","valorização das relações interpessoais."]'::jsonb, '"interferência da riqueza sobre o amor."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"71b0fd61df5eeb0e52622bf45d9726569b2725baa446bdd08407736a88af79fa","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"89ed9099ed90e6c964abeeca0fd5a27d25553f3ad84a3cb13f383d5685f8d3f2","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":35,"language":null,"page":15,"storagePath":"2024-D1-CD1/question-35-COMMON/statement-page-15.png","sha256":"7443f77260cedf53e32a39789673aa9f60e12dc8dc678a38403c8f1dfbbe2834","crop":{"left":0,"bottom":494.8635,"width":308.7223694899999,"height":258.3988}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":35,"language":null,"source_page":15,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
