/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"71b0fd61df5eeb0e52622bf45d9726569b2725baa446bdd08407736a88af79fa","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"89ed9099ed90e6c964abeeca0fd5a27d25553f3ad84a3cb13f383d5685f8d3f2","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":35,"language":null,"page":15,"storagePath":"2024-D1-CD1/question-35-COMMON/statement-page-15.png","sha256":"7443f77260cedf53e32a39789673aa9f60e12dc8dc678a38403c8f1dfbbe2834","crop":{"left":0,"bottom":494.8635,"width":308.7223694899999,"height":258.3988}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":35,"language":null,"source_page":15,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
