te. [...]","composição de enredos musicais pelos “garanchosos”."]'::jsonb, '"aproximação da manifestação folclórica com o esporte. [...]"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"8bb168c1ad6bb85814156f7309e37563c376435afd9893c5c463d457163be060","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"b2b40d93f7dc3a693a30656a208d4d71b3151958a643e682ff2c218e7c23e5a5","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":42,"language":null,"source_page":17,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
