  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '56a4d9ba84d057b58f90e4020fe845664fcf0b3b8a7bef718a8903a39b4c783f' limit 1;
