  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '1014adb491432a695fcbded48b11f187ed5705274d4f4ed84a746e5a73ad4ba2' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 78, 'CIENCIAS_HUMANAS', 'A regra de ouro, popularmente conhecida pelo provérbio “Trate os outros como gostaria de ser tratado”, é um dos princípios morais mais onipresentes. A noção subjacente, que apela para o senso ético mais básico, se expressa de uma forma ou de outra em praticamente todas as tradições religiosas, e poucos filósofos morais deixaram de invocar a regra ou pelo menos de tecer comentários a respeito da relação com seus próprios princípios. DUPRÉ, B. 50 grandes ideias da humanidade . São Paulo: Planeta do Brasil, 2016. O princípio ético apresentado no texto, como elemento estruturante da vida em sociedade, se traduz pela seguinte formulação teórica:', '["Doutrina teleológica.","Imperativo categórico.","Pensamento utilitarista.","Secularização inautêntica.","Raciocínio consequencialista."]'::jsonb, '"Imperativo categórico."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"1014adb491432a695fcbded48b11f187ed5705274d4f4ed84a746e5a73ad4ba2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FILOSOFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FILOSOFIA","classification_source_fingerprint":"5e0304b6502174ee745ef336e04a6b195b05894582a4f5fe5663b20274c3d876","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":78,"language":null,"page":28,"storagePath":"2024-D1-CD1/question-78-COMMON/statement-page-28.png","sha256":"c00efd4d04b64ffb9927eb35afc26e12b96806aaa6d197b68ba30bd0a542ff5b","crop":{"left":0,"bottom":297.6685,"width":237.67586250000005,"height":129.83320000000003}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":78,"language":null,"source_page":28,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
