  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5af8f6a4228e23adcee8a1120ddbb26dc41e0edbb5e8fbddef4cb57e6380b8bf' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 79, 'CIENCIAS_HUMANAS', 'O que alicerça, portanto, o acolhimento de refugiados pelos Estados gira em torno da fronteira erguida entre inclusão e exclusão, admissão e rejeição, desejáveis e indesejáveis; ao mesmo tempo, enseja vulnerabilidade, indefinição e incerteza a esses migrantes internacionais forçados. MOREIRA, J. B. Refugiados no Brasil. REMHU , n. 43, jul.-dez. 2014. A eliminação, para os refugiados, do tipo de fronteira descrita no texto necessita de políticas públicas de', '["planejamento familiar.","segregação territorial.","homogeneização cultural.","diferenciação étnico-racial.","integração socioeconômica."]'::jsonb, '"integração socioeconômica."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"5af8f6a4228e23adcee8a1120ddbb26dc41e0edbb5e8fbddef4cb57e6380b8bf","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"a29d7de03e869b726dc1b29c3d7d98cbf251d8c337d60253254ace08ce01e488","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":79,"language":null,"page":28,"storagePath":"2024-D1-CD1/question-79-COMMON/statement-page-28.png","sha256":"cb404201fe2edcbe5fdf679a108446ec5b692876f77f2c3b79fb6df12fedd0f2","crop":{"left":0,"bottom":130.6375,"width":237.67586250000005,"height":106.62140000000002}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":79,"language":null,"source_page":28,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
