  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '20a59ad5f802236e7bb131e27aab7d49e8212eaba63eb3a817ce6097ff79cf6b', 'STATEMENT_CROP', 28, '2024-D1-CD4/question-77-COMMON/statement-page-28.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"20a59ad5f802236e7bb131e27aab7d49e8212eaba63eb3a817ce6097ff79cf6b","crop":{"left":0,"bottom":646.6409,"width":237.67586250000005,"height":106.6214},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'aedd25c690b7d6bb9c65909c95d740eacd4e246d55b8877fe53aae6116396bf6' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 81, 'CIENCIAS_HUMANAS', 'No texto, a cartografia é apresentada como um instrumento No Brasil, os remanescentes de antigos quilombos, usado essencialmente para a “mocambos”, “comunidades negras rurais”, “quilombos A preservação de espaços naturais. contemporâneos”, “comunidades quilombolas” ou “terras B emancipação de sujeitos marginais. de preto” referem-se a um mesmo patrimônio territorial e cultural inestimável, que só recentemente passaram C revalorização de culturas reprimidas. a ter atenção do Estado e ser do interesse de algumas D inversão de hierarquias estabelecidas. autoridades e organismos oficiais. E sustentação de hegemonias territoriais. ANJOS, R. S. A. Cartografia e quilombos: territórios étnicos africanos no Brasil. Africana Studia , n. 9, 2007. Na esfera de ação do Estado, com a Constituição de 1988, os espaços mencionados tornaram-se objeto de', '["iniciativas de planejamento familiar.","projetos de reorientação religiosa.","programas de moradias sustentáveis.","políticas de inserção social.","medidas de homogeneização educacional. "]'::jsonb, '"políticas de inserção social."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"aedd25c690b7d6bb9c65909c95d740eacd4e246d55b8877fe53aae6116396bf6","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"3c5ee10aba2c373f5e75934e48638434e282be