  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'f3494ebf56045e7d19d3490723c14add1c69e01c123d984eddc932bd89d7c6e3', 'STATEMENT_CROP', 29, '2024-D1-CD1/question-81-COMMON/statement-page-29.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"f3494ebf56045e7d19d3490723c14add1c69e01c123d984eddc932bd89d7c6e3","crop":{"left":0,"bottom":254.377,"width":268.8348,"height":62.37059999999997},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'a0d8a4207e8ad3d65ea614eda2f7643894eac4acf8a23b0542e6f11a6cc51932' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 86, 'CIENCIAS_HUMANAS', 'TEXTO I TEXTO I O bufarinheiro, conhecido nas cidades por teque-teque, chama-se, nos recônditos da Amazônia, “regatão”. Em lugar de transportar nas costas o mundo de miudezas, transporta-o no bojo de uma gaiola que desloca duas, três, quatro toneladas, divididas em seções de secos e molhados e é movido por remo de faia. Cortando comunidades e matas da Amazônia por rios, dentro dessas gaiolas, riscadas de prateleiras, encontram-se os artigos mais díspares, que vão da agulha à espingarda, do lenço ao cobertor, da chita à escova de dentes. MORAES, R. Na Planície Amazônica . São Paulo: Editora Nacional, 1936 (adaptado). TEXTO II No século XIX, o comércio dos regatões era feito, então, Disponível em: https://earth.google.com. Acesso em: 13 out. 2023. com base em relações tecidas com quilombolas, pequenos TEXTO II produtores, comerciantes locais e indígenas, constituindo relação comercial alternativa ao abastecimento da população. HENRIQUE, M. C.; MORAIS, L. T. Estradas líquidas, comércio sólido: índios e regatões na Amazônia (século XIX). Rev. Hist. , n. 171, jul.-dez. 2014 (adaptado). Como parte do patrimônio cultural da Amazônia, o regatão foi fundamental, no século XIX, para a', '["organização de rotas de fuga na floresta tropical.","criação de postos de trabalho nos seringais nortistas.","divulgação de receitas de fármacos nas zonas ribeirinhas.","construção de redes de sociabilidade no interior brasileiro.","ampliação de ambientes de lazer nos territórios autóctones."]'::jsonb, '"construção de redes de sociabilidade no interior brasileiro."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"a0d8a4207e8ad3d65ea614eda2f7643894eac4acf8a23b0542e6f11a6cc51932","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"3167d2c8a2387bead3fcb49b5b6046791991b9bdc663b706405213a003efe7f8","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":86,"language":null,"source_page":30,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2024, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 86, subject_area = 'CIENCIAS_HUMANAS', statement = 'TEXTO I TEXTO I O bufarinheiro, conhecido nas cidades por teque-teque, chama-se, nos recônditos da Amazônia, “regatão”. Em lugar de transportar nas costas o mundo de miudezas, transporta-o no bojo de uma gaiola que desloca duas, três, quatro toneladas, divididas em seções de secos e molhados e é movido por remo de faia. Cortando comunidades e matas da Amazônia por rios, dentro dessas gaiolas, riscadas de prateleiras, encontram-se os artigos mais díspares, que vão da agulha à espingarda, do lenço ao cobertor, da chita à escova de dentes. MORAES, R. Na Planície Amazônica . São Paulo: Editora Nacional, 1936 (adaptado). TEXTO II No século XIX, o comércio dos regatões era feito, então, Disponível em: https://earth.google.com. Acesso em: 13 out. 2023. com base em relações tecidas com quilombolas, pequenos TEXTO II produtores, comerciantes locais e indígenas, constituindo relação comercial alternativa ao abastecimento da população. HENRIQUE, M. C.; MORAIS, L. T. Estradas líquidas, comércio sólido: índios e regatões na Amazônia (século XIX). Rev. Hist. , n. 171, jul.-dez. 2014 (adaptado). Como parte do patrimônio cultural da Amazônia, o regatão foi fundamental, no século XIX, para a', options = '["organização de rotas de fuga na floresta tropical.","criação de postos de trabalho nos seringais nortistas.","divulgação de receitas de fármacos nas zonas ribeirinhas.","construção de redes de sociabilidade no interior brasileiro.","ampliação de ambientes de lazer nos territórios autóctones."]'::jsonb, correct_answer = '"construção de redes de sociabilidade no interior brasileiro."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"a0d8a4207e8ad3d65ea614eda2f7643894eac4acf8a23b0542e6f11a6cc51932","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"3167d2c8a2387bead3fcb49b5b6046791991b9bdc663b706405213a003efe7f8","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":86,"language":null,"source_page":30,"source_sha256":"b0adc1dc79a002aba36f725f1ef792cf53e47ff75ee012638ef34a4e6fbb18f5"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
