  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '868ca64f24ddf091ff1cfd6ebfe73c7d9d663ae31b2c72e185a1d9dc28ea8d8e', 'STATEMENT_CROP', 2, '2024-D1-CD4/question-1-SPANISH/statement-page-2.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"868ca64f24ddf091ff1cfd6ebfe73c7d9d663ae31b2c72e185a1d9dc28ea8d8e","crop":{"left":0,"bottom":488.71880000000004,"width":299.4447200000021,"height":219.81929999999994},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '821b87fa7700fa43d763e765bd84151b72ea48ce82eaaaef8bf9fbabe8ce6dab' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D1', 29, 'LINGUAGENS', 'o que tem de pior na sociedade brasileira, uma sequência tristemente hilária de ações moralmente condenáveis, atitudes Meu irmão é filho adotivo. Há uma tecnicidade no termo, pusilânimes, cálculos mesquinhos e maus passos cretinos. filho adotivo, que contribui para sua aceitação social. Há uma novidade que por um átimo o absolve das mazelas do passado, A literatura, o cinema e o teatro vêm se transformando que parece limpá-lo de seus sentidos indesejáveis. Digo que num exercício de lacração: o mal está sempre no outro, os meu irmão é filho adotivo e as pessoas tendem a assentir com protagonistas são ironmen / women da virtude. A pessoa solenidade, disfarçando qualquer pesar, baixando os olhos sai da leitura ou da sessão não com a guarda abaixada, como se não sentissem nenhuma ânsia de perguntar mais as certezas abaladas, mais próxima da verdade (ou, à falta nada. Talvez compartilhem da minha inquietude, talvez de de uma palavra melhor, da sinceridade): sai com suas certezas reforçadas. fato se esqueçam do assunto no próximo gole ou na próxima garfada. Se a inquietude continua a reverberar em mim, A realidade é confusa. Contraditória. Muitas vezes é porque ouço a frase também de maneira parcial — meu irmão incompreensível. A arte é onde tentamos nos mostrar nus, é filho — e é difícil aceitar que ela não termine com a verdade com todos os nossos defeitos. tautológica habitual: meu irmão é filho dos meus pais. Estou PRATA, A. Disponível em: www1.folha.uol.com.br. entoando que meu irmão é filho e uma interrogação sempre Acesso em: 12 jan. 2024 (adaptado). me salta aos lábios: filho de quem? No que diz respeito à arte, o posicionamento de Antônio FUCKS, J. A resistência . São Paulo: Cia. das Letras, 2015. Prata, no Texto II, aproxima-se da tese de Graciliano Ramos, Das reflexões do narrador, apreende-se uma perspectiva no Texto I, uma vez que ambos que associa a adoção A defendem a dignidade do ofício dos artistas.', '["a representações sociais estigmatizadas da parentalidade. B concluem que a arte reforça crenças pessoais.","à necessidade de aprovação por parte de desconhecidos. C apresentam a pobreza como inspiração para a arte.","ao julgamento velado de membros do núcleo familiar. D afirmam o necessário caráter desestabilizador da arte.","ao conflito entre o termo técnico e o vínculo afetivo. E atestam que há mudanças significativas na produção","a inquietações próprias das relações entre irmãos. artística. "]'::jsonb, '"a representações sociais estigmatizadas da parentalidade. B concluem que a arte reforça crenças pessoais."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"821b87fa7700fa43d763e765bd84151b72ea48ce82eaaaef8bf9fbabe8ce6dab","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"1ceb78419ce212859f254678619400bf894d3bc5e1c24293f20613d941033ba9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":29,"language":null,"page":13,"storagePath":"2024-D1-CD4/question-29-COMMON/statement-page-13.png","sha256":"30c12d908bb4be1414e14137d433362dd69c7d437f450bf2c3a66d7cc6a42c47","crop":{"left":0,"bottom":129.68325000000002,"width":284.236020000002,"height":250.24735}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD4","question_number":29,"language":null,"source_page":13,"source_sha256":"e8d4283f2162d9e28f41530ea5eebb925c5029842d2e5e39422bbb0d7a6699fb"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2024, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 29, subject_area = 'LINGUAGENS', statement = 'o que tem de pior na sociedade brasileira, uma sequência tristemente hilária de ações moralmente condenáveis, atitudes Meu irmão é filho adotivo. Há uma tecnicidade no termo, pusilânimes, cálculos mesquinhos e maus passos cretinos. filho adotivo, que contribui para sua aceitação social. Há uma novidade que por um átimo o absolve das mazelas do passado, A literatura, o cinema e o teatro vêm se transformando que parece limpá-lo de seus sentidos indesejáveis. Digo que num exercício de lacração: o mal está sempre no outro, os meu irmão é filho adotivo e as pessoas tendem a assentir com protagonistas são ironmen / women da virtude. A pessoa solenidade, disfarçando qualquer pesar, baixando os olhos sai da leitura ou da sessão não com a guarda abaixada, como se não sentissem nenhuma ânsia de perguntar mais as certezas abaladas, mais próxima da verdade (ou, à falta nada. Talvez compartilhem da minha inquietude, talvez de de uma palavra melhor, da sinceridade): sai com suas certezas reforçadas. fato se esqueçam do assunto no próximo gole ou na próxima garfada. Se a inquietude continua a reverberar em mim, A realidade é confusa. Contraditória. Muitas vezes é porque ouço a frase também de maneira parcial — meu irmão incompreensível. A arte é onde tentamos nos mostrar nus, é filho — e é difícil aceitar que ela não termine com a verdade com todos os nossos defeitos. tautológica habitual: meu irmão é filho dos meus pais. Estou PRATA, A. Disponível em: www1.folha.uol.com.br. entoando que meu irmão é filho e uma interrogação sempre Acesso em: 12 jan. 2024 (adaptado). me salta aos lábios: filho de quem? No que diz respeito à arte, o posicionamento de Antônio FUCKS, J. A resistência . São Paulo: Cia. das Letras, 2015. Prata, no Texto II, aproxima-se da tese de Graciliano Ramos, Das reflexões do narrador, apreende-se uma perspectiva no Texto I, uma vez que ambos que associa a adoção A defendem a dignidade do ofício dos artistas.', options = '["a representações sociais estigmatizadas da parentalidade. B concluem que a arte reforça crenças pessoais.","à necessidade de aprovação por parte de desconhecidos. C apresentam a pobreza como inspiração para a arte.","ao julgamento velado de membros do núcleo familiar. D afirmam o necessário caráter desestabilizador da arte.","ao conflito entre o termo técnico e o vínculo afetivo. E atestam que há mudanças significativas na produção","a inquietações próprias das relações entre irmãos. artística. "]'::jsonb, correct_answer = '"a representações sociais estigmatizadas da parentalidade. B concluem que a arte reforça crenças pessoais."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"821b87fa7700fa43d763e765bd84151b72ea48ce82eaaaef8bf9fbabe8ce6dab","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"1ceb78419ce212859f254678619400bf894d3bc5e1c24293f20613d941033ba9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":29,"language":null,"page":13,"storagePath":"2024-D1-CD4/question-29-COMMON/statement-page-13.png","sha256":"30c12d908bb4be1414e14137d433362dd69c7d437f450bf2c3a66d7cc6a42c47","crop":{"left":0,"bottom":129.68325000000002,"width":284.236020000002,"height":250.24735}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam