  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '0537abefe5f7c4cf55ea04e9c14a5c19bfc6da46f89c0d1cd6873a701a45c975', 'STATEMENT_CROP', 4, '2024-D2-CD5/question-99-COMMON/statement-page-4.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"0537abefe5f7c4cf55ea04e9c14a5c19bfc6da46f89c0d1cd6873a701a45c975","crop":{"left":0,"bottom":164.7308,"width":266.846,"height":192.3929},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '7546476c995cd109cd9460b6dc7cbd6db8133c0792c77149a15915e6dfee8eba' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D2', 103, 'CIENCIAS_NATUREZA', 'Placas solares comuns dependem de dias ensolarados O diagrama P-V a seguir representa o ciclo de Otto para gerar energia. Mas podemos gerar eletricidade com para um motor de combustão interna, como os motores a a ajuda de gotas de chuva, revestindo placas solares gasolina ou a etanol, utilizados nos automóveis. com uma fina camada de grafeno. Os íons dissociados a m + n − partir da água da chuva (A e B ) tornam a combinação grafeno e água da chuva um par perfeito para geração de energia. O processo requer apenas uma camada de − grafeno para que grande quantidade de elétrons (e ) se movimente ao longo da superfície. As etapas representadas no diagrama estão descritas no quadro. Etapa Processo Descrição Admissão isobárica da mistura I 0 a 1 ar-combustível no cilindro do motor. II 1 a 2 Compressão adiabática da mistura. TANG, Q. et al. A Solar Cell that is Triggered by Sun and Rain. Angewandte Chemie International Edition , n. 55, 2016 (adaptado). Introdução de energia na forma III 2 a 3 de calor da combustão. Ao produzir eletricidade em dias chuvosos, o grafeno IV 3 a 4 Expansão adiabática.', '["oxida os cátions dissolvidos na água da chuva.","impede a difusão da água através das placas solares. Liberação de energia","diminui a energia de ativação da reação no pseudocapacitor. V 4 a 1 na forma de calor.","forma um compósito não metálico com os íons na água Liberação dos gases da chuva. VI 1 a 0 resultantes da combustão.","gera uma diferença de potencial pela interação dos"]'::jsonb, '"diminui a energia de ativação da reação no pseudocapacitor. V 4 a 1 na forma de calor."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"7546476c995cd109cd9460b6dc7cbd6db8133c0792c77149a15915e6dfee8eba","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"71aad9768256190b25ef25c16f281ab177c65672522777bf85d4c9a15a3b6dfc","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":103,"language":null,"source_page":5,"source_sha256":"ec4e704ab4017762ffb1eba84c55285a429d3d02ed0e58258c1171315cb34937"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2024, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 103, subject_area = 'CIENCIAS_NATUREZA', statement = 'Placas solares comuns dependem de dias ensolarados O diagrama P-V a seguir representa o ciclo de Otto para gerar energia. Mas podemos gerar eletricidade com para um motor de combustão interna, como os motores a a ajuda de gotas de chuva, revestindo placas solares gasolina ou a etanol, utilizados nos automóveis. com uma fina camada de grafeno. Os íons dissociados a m + n − partir da água da chuva (A e B ) tornam a combinação grafeno e água da chuva um par perfeito para geração de energia. O processo requer apenas uma camada de − grafeno para que grande quantidade de elétrons (e ) se movimente ao longo da superfície. As etapas representadas no diagrama estão descritas no quadro. Etapa Processo Descrição Admissão isobárica da mistura I 0 a 1 ar-combustível no cilindro do motor. II 1 a 2 Compressão adiabática da mistura. TANG, Q. et al. A Solar Cell that is Triggered by Sun and Rain. Angewandte Chemie International Edition , n. 55, 2016 (adaptado). Introdução de energia na forma III 2 a 3 de calor da combustão. Ao produzir eletricidade em dias chuvosos, o grafeno IV 3 a 4 Expansão adiabática.', options = '["oxida os cátions dissolvidos na água da chuva.","impede a difusão da água através das placas solares. Liberação de energia","diminui a energia de ativação da reação no pseudocapacitor. V 4 a 1 na forma de calor.","forma um compósito não metálico com os íons na água Liberação dos gases da chuva. VI 1 a 0 resultantes da combustão.","gera uma diferença de potencial pela interação dos"]'::jsonb, correct_answer = '"diminui a energia de ativação da reação no pseudocapacitor. V 4 a 1 na forma de calor."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"7546476c995cd109cd9460b6dc7cbd6db8133c0792c77149a15915e6dfee8eba","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"71aad9768256190b25ef25c16f281ab177c65672522777bf85d4c9a15a3b6dfc","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":103,"language":null,"source_page":5,"source_sha256":"ec4e704ab4017762ffb1eba84c55285a429d3d02ed0e58258c1171315cb34937"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
