  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '0b575d4b0ae2b9459175bb883c07323d4f55c7ca3ff83c6bd445fe1db842bab4', 'STATEMENT_CROP', 7, '2024-D2-CD5/question-108-COMMON/statement-page-7.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"0b575d4b0ae2b9459175bb883c07323d4f55c7ca3ff83c6bd445fe1db842bab4","crop":{"left":0,"bottom":117.80690000000001,"width":246.40680530000003,"height":164.415},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd8e849b558bd9a1511967733d31c0fae95be8c54b806b4faea0389453a2c5014' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D2', 111, 'CIENCIAS_NATUREZA', 'C O biogás é uma alternativa energética muito importante, pois, além de reduzir a dependência por combustíveis fósseis, sua obtenção pode ser realizada a partir de resíduos da produção agroindustrial. Considere que o biogás produzido em um empreendimento de suinocultura contém 70% em volume de metano (massa molar 16 g/mol; volume molar 22 L/mol). Ele será utilizado para geração de energia em substituição ao etanol (massa molar 46 g/mol) 3 em um gerador no qual 1 m de biogás de origem suína D substitui 0,59 L de etanol anidro (densidade 0,78 g/mL). Nessas condições, a massa de metano necessária para substituir 10 mol de etanol na produção de energia é mais próxima de', '["300 g.","400 g. E","510 g.","590 g.","720 g. "]'::jsonb, '"510 g."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"d8e849b558bd9a1511967733d31c0fae95be8c54b806b4faea0389453a2c5014","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"3df2944bc9cd2f0dc63fb4a3f29bd0389e9a4c4c9476e5cebf89496878c1f4d3","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":111,"language":null,"page":8,"storagePath":"2024-D2-CD5/question-111-COMMON/statement-page-8.png","sha256":"4a15278605b3794fa47b6699e073c177e81dd3d836be4a8d023795a36f85ed15","crop":{"left":251.76609028000004,"bottom":