  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '11e675935c4d4e1f7d91ec364074747b7f6a1d82f8f228173259688e51e62c5b' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D2', 121, 'CIENCIAS_NATUREZA', 'No senso comum, considera-se, ainda hoje, que compostos orgânicos são substâncias presentes nos seres vivos. Na Química, a expressão “compostos orgânicos” tem um uso histórico de mais de 200 anos, adquirindo diferentes conotações ao longo do desenvolvimento dessa ciência. Atualmente, atribui-se a essa expressão outro significado. A concepção científica atual define esses compostos como substâncias', '["benéficas à saúde humana.","capazes de serem biodegradadas.","formadas a partir de gás carbônico.","produzidas sem o uso de agrotóxicos.","contendo carbono como elemento principal. "]'::jsonb, '"contendo carbono como elemento principal. "'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"11e675935c4d4e1f7d91ec364074747b7f6a1d82f8f228173259688e51e62c5b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"4eac1b2189028b62e64ee1131552bd0d61b9a541b82620f165f32ca6248a4878","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":11,"storagePath":"2024-D2-CD5/question-121-COMMON/statement-page-11.png","sha256":"2203dbcb67b6b38a516a0bded7ad7a612b9944d682b769c545351f64c6f0968f","crop":{"left":307.1924150000018,"bottom":129.4316,"width":261.3898849999981,"height":134.90279999999996}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":121,"language":null,"source_page":11,"source_sha256":"ec4e704ab4017762ffb1eba84c55285a429d3d02ed0e58258c1171315cb34937"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2024, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 121, subject_area = 'CIENCIAS_NATUREZA', statement = 'No senso comum, considera-se, ainda hoje, que compostos orgânicos são substâncias presentes nos seres vivos. Na Química, a expressão “compostos orgânicos” tem um uso histórico de mais de 200 anos, adquirindo diferentes conotações ao longo do desenvolvimento dessa ciência. Atualmente, atribui-se a essa expressão outro significado. A concepção científica atual define esses compostos como substâncias', options = '["benéficas à saúde humana.","capazes de serem biodegradadas.","formadas a partir de gás carbônico.","produzidas sem o uso de agrotóxicos.","contendo carbono como elemento principal. "]'::jsonb, correct_answer = '"contendo carbono como elemento principal. "'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"11e675935c4d4e1f7d91ec364074747b7f6a1d82f8f228173259688e51e62c5b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"4eac1b2189028b62e64ee1131552bd0d61b9a541b82620f165f32ca6248a4878","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":11,"storagePath":"2024-D2-CD5/question-121-COMMON/statement-page-11.png","sha256":"2203dbcb67b6b38a516a0bded7ad7a612b9944d682b769c545351f64c6f0968f","crop":{"left":307.1924150000018,"bottom":129.4316,"width":261.3898849999981,"height":134.90279999999996}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"