ions = '["Facilita a captura de presas.","Diminui a competição por recursos.","Possibilita a geração de indivíduos híbridos.","Reduz a possibilidade de sofrerem predação.","Otimiza o encontro de parceiros reprodutivos."]'::jsonb, correct_answer = '"Diminui a competição por recursos."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', metadata = '{"canonical_id":"73b637ecc700e5c667c062472aa4111740689e114cab199472e0b9a1d0829587","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"72d96aff65610b8b499271f20dbb7165ceab2e07d694d5ada07a834821424557","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":135,"language":null,"source_page":15,"source_sha256":"ec4e704ab4017762ffb1eba84c55285a429d3d02ed0e58258c1171315cb34937"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
