  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '7831f50deb94c44798e145b46812d1598df596bb7c53c41db9e5367aa0ddbbcb' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2024, 'ENEM', 'REGULAR', 'D2', 159, 'MATEMATICA', 'Uma piscina tem capacidade de 2 500 000 litros. Em uma loja de defensivos agrícolas, os preços de Seu sistema de abastecimento foi regulado para ter alguns produtos foram divulgados em um cartaz. uma vazão constante de 6 000 litros de água por minuto. O mesmo sistema foi instalado em uma segunda piscina, com capacidade de 2 750 000 litros, e regulado para ter uma vazão, também constante, capaz de enchê-la em um tempo 20% maior que o gasto para encher a primeira piscina. A vazão do sistema de abastecimento da segunda piscina, em litro por minuto, é', '["8 250.","7 920.","6 545.","5 500.","5 280."]'::jsonb, '"6 545."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2024', '{"canonical_id":"7831f50deb94c44798e145b46812d1598df596bb7c53c41db9e5367aa0ddbbcb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"4f07d6de2d04fd68e56521f1c1dc1ebb4ebacfcb1b0ec73d35f50b0f502da4de","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2024,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":159,"language":null,"source_page":25,"source_sha256":"ec4e704ab4017762ffb1eba84c55285a429d3d02ed0e58258c1171315cb34937"}}'::jsonb, true) returning id into v_question_id; end if;
