  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8674ad52cfb3eefe6f75b2d62bfe2822bce81a597fa75d081c4c3930c4378c37' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 1, 'LINGUAGENS', 'Glory Ames, from the White Earth reservation, is frustrated that despite the presence of several indigenous reservations near Moorhead, local Halloween stores still feature a western section with costumes such as “pow wow princess”. Even worse, despite a long-running debate about racism and cultural appropriation, often prompted by backlash against celebrities and politicians for donning offensive costumes, people continue to wear such costumes. Last Halloween, Ames spotted a photo on Instagram of a girl dressed as a Native American with a bullet in her forehead. She immediately reported it to the social media platform and had it removed. “They blatantly take certain aspects of our culture, race, religion, and use it for their advantage and ignore the people living it”, said Ames. LIU, M. C. M. Disponível em: www.washingtonpost.com. Acesso em: 12 maio 2024 (adaptado). Ao abordar um aspecto da celebração do Halloween, esse texto tem por objetivo', '["denunciar a violência contra crianças indígenas.","descrever costumes tradicionais em celebrações indígenas.","valorizar as vestimentas características dos povos originários.","criticar a exploração indevida de elementos da identidade indígena.","sugerir ações de combate ao preconceito contra os povos originários."]'::jsonb, '"criticar a exploração indevida de elementos da identidade indígena."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"8674ad52cfb3eefe6f75b2d62bfe2822bce81a597fa75d081c4c3930c4378c37","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"e4bb59b94b85a186e72ff9db9c352160ce1d03a13733f372eb4275bdbb2823ca","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":1,"language":"ENGLISH","page":2,"storagePath":"2025-D1-CD1/question-1-ENGLISH/statement-page-2.png","sha256":"b0b15d03c17904cbd39af4843e67e6370dd9698c0b89a6fcef3438f85590d48b","crop":{"left":0,"bottom":550.244,"width":278.19109999999995,"height":143.27099999999996}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":1,"language":"ENGLISH","source_page":2,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 1, subject_area = 'LINGUAGENS', statement = 'Glory Ames, from the White Earth reservation, is frustrated that despite the presence of several indigenous reservations near Moorhead, local Halloween stores still feature a western section with costumes such as “pow wow princess”. Even worse, despite a long-running debate about racism and cultural appropriation, often prompted by backlash against celebrities and politicians for donning offensive costumes, people continue to wear such costumes. Last Halloween, Ames spotted a photo on Instagram of a girl dressed as a Native American with a bullet in her forehead. She immediately reported it to the social media platform and had it removed. “They blatantly take certain aspects of our culture, race, religion, and use it for their advantage and ignore the people living it”, said Ames. LIU, M. C. M. Disponível em: www.washingtonpost.com. Acesso em: 12 maio 2024 (adaptado). Ao abordar um aspecto da celebração do Halloween, esse texto tem por objetivo', options = '["denunciar a violência contra crianças indígenas.","descrever costumes tradicionais em celebrações indígenas.","valorizar as vestimentas características dos povos originários.","criticar a exploração indevida de elementos da identidade indígena.","sugerir ações de combate ao preconceito contra os povos originários."]'::jsonb, correct_answer = '"criticar a exploração indevida de elementos da identidade indígena."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"8674ad52cfb3eefe6f75b2d62bfe2822bce81a597fa75d081c4c3930c4378c37","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"e4bb59b94b85a186e72ff9db9c352160ce1d03a13733f372eb4275bdbb2823ca","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":1,"language":"ENGLISH","page":2,"storagePath":"2025-D1-CD1/question-1-ENGLISH/statement-page-2.png","sha256":"b0b15d03c17904cbd39af4843e67e6370dd9698c0b89a6fcef3438f85590d48b","crop":{"left":0,"bottom":550.244,"width":278.19109999999995,"height":143.27099999999996}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":1,"language":"ENGLISH","source_page":2,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
