  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'c616d08b1b98608516d0ae00a5e400f83db44adc08488fb9820ce5dafae6e8ef', 'STATEMENT_CROP', 3, '2025-D1-CD4/question-4-ENGLISH/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"c616d08b1b98608516d0ae00a5e400f83db44adc08488fb9820ce5dafae6e8ef","crop":{"left":0,"bottom":574.2248,"width":302.40139123999995,"height":167.52520000000004},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'be6f98675a4ea30d75283aa63ed3e8e335eb01b1126ef74621e9447c6274bce8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 2, 'LINGUAGENS', 'My idea of philosophy is that if it is not relevant to human problems, if it does not tell us how we can go about eradicating some of the misery in this world, then it is not worth the name of philosophy. I think Socrates made a very profound statement when he asserted that philosophy is to teach us proper living. In this day and age “proper living” means liberation from the urgent problems of poverty, economic necessity and indoctrination, mental oppression. DAVIS, A. Lectures on Liberation . Washington: Smithsonian Libraries, 1971 (adaptado). Nesse texto, ao discorrer sobre a relevância da filosofia, a escritora Angela Davis tem por objetivo', '["criticá-la pela restrição temática.","vinculá-la ao universo acadêmico.","afastá-la da abordagem socrática.","aproximá-la dos problemas sociais.","responsabilizá-la pela pobreza humana."]'::jsonb, '"aproximá-la dos problemas sociais."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"be6f98675a4ea30d75283aa63ed3e8e335eb01b1126ef74621e9447c6274bce8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"8d656682641e75075f29975839ba274798f90872063263d8350517658445b4ae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":2,"language":"ENGLISH","page":2,"storagePath":"2025-D1-CD1/question-2-ENGLISH/statement-page-2.png","sha256":"94905a686fb6c96cb6d8320153c257ac9ebb00d8c0840b15832a3e9dd4a91216","crop":{"left":0,"bottom":393.3427,"width":278.19109999999995,"height":105.9334}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":2,"language":"ENGLISH","source_page":2,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 2, subject_area = 'LINGUAGENS', statement = 'My idea of philosophy is that if it is not relevant to human problems, if it does not tell us how we can go about eradicating some of the misery in this world, then it is not worth the name of philosophy. I think Socrates made a very profound statement when he asserted that philosophy is to teach us proper living. In this day and age “proper living” means liberation from the urgent problems of poverty, economic necessity and indoctrination, mental oppression. DAVIS, A. Lectures on Liberation . Washington: Smithsonian Libraries, 1971 (adaptado). Nesse texto, ao discorrer sobre a relevância da filosofia, a escritora Angela Davis tem por objetivo', options = '["criticá-la pela restrição temática.","vinculá-la ao universo acadêmico.","afastá-la da abordagem socrática.","aproximá-la dos problemas sociais.","responsabilizá-la pela pobreza humana."]'::jsonb, correct_answer = '"aproximá-la dos problemas sociais."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"be6f98675a4ea30d75283aa63ed3e8e335eb01b1126ef74621e9447c6274bce8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"8d656682641e75075f29975839ba274798f90872063263d8350517658445b4ae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":2,"language":"ENGLISH","page":2,"storagePath":"2025-D1-CD1/question-2-ENGLISH/statement-page-2.png","sha256":"94905a686fb6c96cb6d8320153c257ac9ebb00d8c0840b15832a3e9dd4a91216","crop"