  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '2ff7da2609ac186a0eb5ff2cf9da4f26802bbb0d6e93e07310c50c99fb4142fd', 'STATEMENT_CROP', 2, '2025-D1-CD4/question-1-ENGLISH/statement-page-2.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"2ff7da2609ac186a0eb5ff2cf9da4f26802bbb0d6e93e07310c50c99fb4142fd","crop":{"left":0,"bottom":508.77279999999996,"width":315.4359,"height":184.8742000000001},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8613764ed4d833225dc8dcfc61e1030eeb045347d040e508214f692d05adacc2' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 3, 'LINGUAGENS', 'Remember the sky that you were born under, know each of the star’s stories. Remember the moon, know who she is. Remember the sun’s birth at dawn. [...] Remember your birth, how your mother struggled to give you form and breath [...] Remember the earth whose skin you are: red earth, black earth, yellow earth, white earth brown earth, we are earth. Remember the plants, trees, animal life who all have their tribes, their families, their histories, too [...] Remember you are all people and all people are you. Remember you are this universe and this universe is you. Remember all is in motion, is growing, is you. HARJO, J. She Had Some Horses . Londres: W. Norton & Company, 1983 (fragmento). Nesse poema, de uma autora de ascendência indígena, o eu lírico ressalta a', '["potência dos astros celestes.","origem das plantas e dos animais.","importância do apego à terra natal.","relação entre seres humanos e natureza.","conexão entre o tempo real e o tempo imaginário."]'::jsonb, '"relação entre seres humanos e natureza."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"8613764ed4d833225dc8dcfc61e1030eeb045347d040e508214f692d05adacc2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"a88ecd4176f0e9c79cf4ad94d5557e463c9f15abaa4a2a595d1028c13bb7ab2f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":3,"language":"ENGLISH","page":2,"storagePath":"2025-D1-CD1/question-3-ENGLISH/statement-page-2.png","sha256":"9a90a161d9a7814bb8ae68b8321eed9fd398783e1ffbc762ec76cf096b15967b","crop":{"left":0,"bottom":119.5829,"width":278.19109999999995,"height":224.7919}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":3,"language":"ENGLISH","source_page":2,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 3, subject_area = 'LINGUAGENS', statement = 'Remember the sky that you were born under, know each of the star’s stories. Remember the moon, know who she is. Remember the sun’s birth at dawn. [...] Remember your birth, how your mother struggled to give you form and breath [...] Remember the earth whose skin you are: red earth, black earth, yellow earth, white earth brown earth, we are earth. Remember the plants, trees, animal life who all have their tribes, their families, their histories, too [...] Remember you are all people and all people are you. Remember you are this universe and this universe is you. Remember all is in motion, is growing, is you. HARJO, J. She Had Some Horses . Londres: W. Norton & Company, 1983 (fragmento). Nesse poema, de uma autora de ascendência indígena, o eu lírico ressalta a', options = '["potência dos astros celestes.","origem das plantas e dos animais.","importância do apego à terra natal.","relação entre seres humanos e natureza.","conexão entre o tempo real e o tempo imaginário."]'::jsonb, correct_answer = '"relação entre seres humanos e natureza."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"8613764ed4d833225dc8dcfc61e1030eeb045347d040e508214f692d05adacc2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"a88ecd4176f0e9c79cf4ad94d5557e463c9f15abaa4a2a595d1028c13bb7ab2f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":3,"language":"ENGLISH","page":2,"storagePath":"2