  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 4, 'LINGUAGENS', 'It is true that all children are special, simply because they are children. But most adults are not special, and children end up as adults pretty quickly. Life then can be difficult and even disappointing. The shock of this may account for the emergence of the “snowflake generation” of university students, who are so delicate they can’t handle controversial ideas being put forward in their lectures. The roots of this fragility run deep in modern culture. So, an approach of the world that states: “Life is wonderful, you’re special and, if you are a good boy/girl, life will be amazing forever” is not a message designed to aid bouncing back from failure or confronting catastrophe. Resilience is not about feeding ego — telling your children how wonderful they are — but strengthening it. LOTT, T. Disponível em: www.theguardian.com. Acesso em: 10 dez. 2017 (adaptado). Nesse texto, a expressão “ snowflake generation ” é usada para', '["abordar obstáculos impostos a universitários.","destacar mensagens de incentivo a estudantes.","estimular ações proativas em situações de emergência.","retratar relações conflituosas em ambiente universitário.","apontar posturas de uma juventude avessa a contrariedades."]'::jsonb, '"apontar posturas de uma juventude avessa a contrariedades."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"4ada053f4df6b974c7df7676b5da95b26c0280f1a1a05da733d2adb0be5a0e67","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"5940463d88768576615961666894a43ee3963d5ce423af753173343b411bc5e0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":4,"language":"ENGLISH","page":3,"storagePath":"2025-D1-CD1/question-4-ENGLISH/statement-page-3.png","sha256":"f5b7c0158a8aaec47426fd5bc061e82b9ae3c3f6da70036daa0b3f850cb34a1a","crop":{"left":0,"bottom":602.4767,"width":297.3696079749999,"height":139.27329999999995}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":4,"language":"ENGLISH","source_page":3,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 4, subject_area = 'LINGUAGENS', statement = 'It is true that all children are special, simply because they are children. But most adults are not special, and children end up as adults pretty quickly. Life then can be difficult and even disappointing. The shock of this may account for the emergence of the “snowflake generation” of university students, who are so delicate they can’t handle controversial ideas being put forward in their lectures. The roots of this fragility run deep in modern culture. So, an approach of the world that states: “Life is wonderful, you’re special and, if you are a good boy/girl, life will be amazing forever” is not a message designed to aid bouncing back from failure or confronting catastrophe. Resilience is not about feeding ego — telling your children how wonderful they are — but strengthening it. LOTT, T. Disponível em: www.theguardian.com. Acesso em: 10 dez. 2017 (adaptado). Nesse texto, a expressão “ snowflake generation ” é usada para', options = '["abordar obstáculos impostos a universitários.","destacar mensagens de incentivo a estudantes.","estimular ações proativas em situações de emergência.","retratar relações conflituosas em ambiente universitário.","apontar posturas de uma juventude avessa a contrariedades."]'::jsonb, correct_answer = '"apontar posturas de uma juventude avessa a contrariedades."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"4ada053f4df6b974c7df7676b5da95b26c0280f1a1a05da733d2adb0be5a0e67","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL