  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 2, 'LINGUAGENS', 'O recurso que caracteriza essa letra de canção como um relato Guagua, las palabras también migran das memórias do eu poético é o uso de Pocas palabras del idioma castellano despiertan tanto', '["palavras no grau diminutivo. interés y asombro como guagua. En España su uso se reduce a las","adjetivos na descrição da paisagem. Islas Canarias, donde se registra a partir de los años 30 del pasado","vocábulos relacionados à fauna cubana. siglo. El origen de guagua resulta algo polémico. Todo parece","verbos no pretérito imperfeito do indicativo. indicar que la voz vino de Cuba. La trajeron de vuelta, junto con","marcas linguísticas de uma variedade caribenha."]'::jsonb, '"palavras no grau diminutivo. interés y asombro como guagua. En España su uso se reduce a las"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"9dc58c062969b32e6cf64a24e3c7c643fd0d666984f491e7bf91d660686e8a8e","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"ESPANHOL","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_SPANISH","classification_source_fingerprint":"d8357f0e12d5d746743bc88cac9d136cd782771f882a135df3b5a1baf1b24987","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":2,"language":"SPANISH","page":2,"storagePath":"2025-D1-CD1/question-2-SPANISH/statement-page-2.png","sha256":"94905a686fb6c96cb6d8320153c257ac9ebb00d8c0840b15832a3e9dd4a91216","crop":{"left":0,"bottom":393.3427,"width":278.19109999999995,"height":105.9334}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":2,"language":"SPANISH","source_page":4,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 2, subject_area = 'LINGUAGENS', statement = 'O recurso que caracteriza essa letra de canção como um relato Guagua, las palabras también migran das memórias do eu poético é o uso de Pocas palabras del idioma castellano despiertan tanto', options = '["palavras no grau diminutivo. interés y asombro como guagua. En España su uso se reduce a las","adjetivos na descrição da paisagem. Islas Canarias, donde se registra a partir de los años 30 del pasado","vocábulos relacionados à fauna cubana. siglo. El origen de guagua resulta algo polémico. Todo parece","verbos no pretérito imperfeito do indicativo. indicar que la voz vino de Cuba. La trajeron de vuelta, junto con","marcas linguísticas de uma variedade caribenha."]'::jsonb, correct_answer = '"palavras no grau diminutivo. interés y asombro como guagua. En España su uso se reduce a las"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"9dc58c062969b32e6cf64a24e3c7c643fd0d666984f491e7bf91d660686e8a8e","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"ESPANHOL","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_SPANISH","classification_source_fingerprint":"d8357f0e12d5d746743bc88cac9d136cd782771f882a135df3b5a1baf1b24987","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":2,"language":"SPANISH","page":2,"storagePath":"2025-D1-CD1/question-2-SPANISH/statement-page-2.png","sha256":"94905a686fb6c96cb6d8320153c257ac9ebb00d8c0840b15832a3e9dd4a91216","crop":{"left":0,"bottom":393.3427,"width":278.19109999999995,"height":105.9334}}],"enem_area":"LINGUAGENS","pedagogical_enrich