  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '5f4f480c68acd7e334ac606ca114d2fc288372a02cd16fdb0a86ac36c61a611f', 'STATEMENT_CROP', 11, '2025-D1-CD4/question-21-COMMON/statement-page-11.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"5f4f480c68acd7e334ac606ca114d2fc288372a02cd16fdb0a86ac36c61a611f","crop":{"left":0,"bottom":685.0406,"width":303.78965000000005,"height":56.70939999999996},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'de1c67506d89609810cc4f2c9fbeec0294fce996c5ebf4e5bd20f2cfa6536ce1' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 17, 'LINGUAGENS', 'Antes do inverno chegar. Ela tinha olhinhos brilhantes. Os mesmos de antes. Antes da fome. Antes das 17 mudanças de cidade. Dos sete filhos e dos muitos anos de trabalho dentro e fora de casa. Ela fazia ambrosia, bolo de fubá e pedacinhos de queijo. Antes do inverno, ela plantava flores novas e diferentes para nos esperar nas próximas férias de verão. Ela tinha o jeito de menina. Menina sapeca, correndo na grama seca do cerrado. O mesmo jeito de antes. Antes do marido (e mesmo com o marido). Antes do cansaço dos anos. Antes da dureza do trato com a terra. Ela tinha histórias. Compridas, curtas, divertidas e verdadeiras. Mas isso foi antes. Antes das lembranças se bagunçarem feito bolas coloridas de Natal esperando para serem montadas na árvore. Eu era sua neta. Antes do Alzheimer chegar, eu era sua neta. Mas ela é e sempre será minha avó. Disponível em: www.masp.org.br. Acesso em: 5 maio 2024 (adaptado). PERSON, C. R. Borboletas no estômago : porque às vezes o título precisa Ao dar protagonismo a Zeferina e a João de Deus Nascimento, ser adolescente e clichê, já que a vida exige sermos tão adultos. o artista Dalton Paula evidencia que a(s) São Paulo: Ed. das Autoras, 2021.', '["arte pode promover formas de afirmação de identidade social. A narradora, ao resgatar memórias da história de vida da avó,","comunidades periféricas passam a adquirir o gênero retrato. faz uso recorrente da locução “antes de”. Esse termo colabora para a progressão temática na medida em que","personagens retratadas simbolizam a sociedade brasileira.","pintura funciona como instrumento de ascensão social. A relaciona eventos ocorridos simultaneamente.","imagens tradicionais preservam memórias afetivas. B estabelece uma comparação entre as lembranças."]'::jsonb, '"personagens retratadas simbolizam a sociedade brasileira."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"de1c67506d89609810cc4f2c9fbeec0294fce996c5ebf4e5bd20f2cfa6536ce1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"930a51a66a948f33186720852cc7d4005235d7f4580eb4a15912f499f37c9914","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":17,"language":null,"page":9,"storagePath":"2025-D1-CD1/question-17-COMMON/statement-page-9.png","sha256":"41fbc1c0cc2f58aab16ed2e525852ad7a9bc0b8333cb7a7252c1c58e8f8f5d5e","crop":{"left":303.78965000000005,"bottom":318.7394,"width":263.13784999999996,"height":324.3874}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":17,"language":null,"source_page":9,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 17, subject_area = 'LINGUAGENS', statement = 'Antes do inverno chegar. Ela tinha olhinhos brilhantes. Os mesmos de antes. Antes da fome. Antes das 17 mudanças de cidade. Dos sete filhos e dos muitos anos de trabalho dentro e fora de casa. Ela fazia ambrosia, bolo de fubá e pedacinhos de queijo. Antes do inverno, ela plantava flores novas e diferentes para nos esperar nas próximas férias de verão. Ela tinha o jeito de menina. Menina sapeca, correndo na grama seca do cerrado. O mesmo jeito de antes. Antes do marido (e mesmo com o marido). Antes do cansaço dos anos. Antes da dureza do trato com a terra. Ela tinha histórias. Compridas, curtas, divertidas e verdadeiras. Mas isso foi antes. Antes das lembranças se bagunçarem feito bolas coloridas de Natal esperando para serem montadas na árvore. Eu era sua neta. Antes do Alzheimer chegar, eu era sua neta. Mas ela é e sempre será minha avó. Disponível em: www.masp.org.br. Acesso em: 5 maio 2024 (adaptado). PERSON, C. R. Borboletas no estômago : porque às vezes o título precisa Ao dar protagonismo a Zeferina e a João de Deus Nascimento, ser adolescente e clichê, já que a vida exige sermos tão adultos. o artista Dalton Paula evidencia que a(s) São Paulo: Ed. das Autoras, 2021.', options = '["arte pode promover formas de afirmação de identidade social. A narradora, ao resgatar memórias da história de vida da avó,","comunidades periféricas passam a adquirir o gênero retrato. faz uso recorrente da locução “antes de”. Esse termo colabora para a progressão temática na medida em que","personagens retratadas simbolizam a sociedade brasileira.","pintura funciona como instrumento de ascensão social. A relaciona eventos ocorridos simultaneamente.","imagens tradicionais preservam memórias afetivas. B estabelece uma comparação entre as lembranças."]'::jsonb, correct_answer = '"personagens retratadas simbolizam a sociedade brasileira."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"de1c67506d89609810cc4f2c9fbeec0294fce996c5ebf4e5bd20f2cfa6536ce1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"930a51a66a948f33186720852cc7d4005235d7f4580eb4a15912f499f37c9914","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":17,"language":null,"page":9,"storagePath":"2025-D1-CD1/question-17-COMMON/statement-page-9.png","sha256":"41fbc1c0cc2f58aab16ed2e525852ad7a9bc0b8333cb7a7252c1c58e8f8f5d5e","crop":{"left":303.78965000000005,"bottom":318.7394,"width":263.13784999999996,"height":324.3874}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":17,"language":null,"source_page":9,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
