o se dá pela', '["reutilização de materiais para redução do impacto ambiental.","ressignificação da matéria-prima atribuindo-lhe nova função.","reprodução em madeira de modelos artísticos canônicos. VAREJÃO, A. Azulejaria em carne viva . Óleo sobre tela, poliuretano,","representação de práticas corporais da comunidade. madeira e alumínio, 160 × 200 × 25 cm. 1999.","replicação seriada para distribuição em larga escala."]'::jsonb, '"reprodução em madeira de modelos artísticos canônicos. VAREJÃO, A. Azulejaria em carne viva . Óleo sobre tela, poliuretano,"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"f783bab404e51178177e9737e5705ca0d9cc304febef7099ae6e2b169bd9c1e5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"7a8c9ab6377dc206b4a95358c3f2dacb7b629911ae6e451265169ea9f082b795","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":23,"language":null,"source_page":11,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
