  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '678086d31e86a72718af9108ae73cc9e2d6dd1b1d9fb3fa4022266892f30e259' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 36, 'LINGUAGENS', 'I : o nome do filme é roupa suja ... eu assisti na minha casa ... com minha mãe ... tinha um ... o filme era sobre um homem que colocaram ... trocaram as bolsas ... daí o homem levou uma bolsa Disponível em: https://revistagalileu.globo.com. cheia de dinheiro sem ele saber que na mala dele ... pensando Acesso em: 18 jun. 2024 (adaptado). que era dele mas era errada ... quando ele chegou onde ele ia Com base na relação dos elementos não verbais com a frase trabalhar ... tinha uma moça tentando abrir a porta pra fazer “VOCÊ (NÃO) ESTÁ SOZINHO”, nessa capa de revista, a função entrevista com uns cantores lá que tinham ... daí ele perguntou poética fica evidente, pois ... “você tá tentando abrir a porta?”... daí ele ... “não ... não” ... daí ele disse ... “ah ... tá ... sim” ... daí ela ... “é ... e quero fazer', '["essa frase informa sobre os riscos de um determinado uma entrevista” ... daí ele disse ... “você quer entrar ... então comportamento social. pode entrar” ... daí entraram ... daí ficaram lá ... quando ela","o conteúdo da mensagem expressa a atitude do enunciador entrou e queria fazer a entrevista um homem num deixou ... daí a sobre o tema. mulher pegou ... subiu onde o homem tava trabalhando ... rapaz","a construção dessa frase possibilita mais de uma interpretação. né ... onde ele tava trabalhando e ficou lá e dando o show ...","essa frase estabelece um diálogo direto com o leitor. CUNHA, M. A. F. Corpus discurso & gramática : a língua falada e","a linguagem utilizada volta-se para si mesma."]'::jsonb, '"essa frase estabelece um diálogo direto com o leitor. CUNHA, M. A. F. Corpus discurso & gramática : a língua falada e"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"678086d31e86a72718af9108ae73cc9e2d6dd1b1d9fb3fa4022266892f30e259","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"b4f8e082375daae82259af005061c07a59e048696138c456ddfc0a6c2786b96c","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":36,"language":null,"page":15,"storagePath":"2025-D1-CD1/question-36-COMMON/statement-page-15.png","sha256":"3e6221b88a4d026c41fe54f7b168a7f8152fbe970f5c262daa60560fd4abd34f","crop":{"left":297.95445,"bottom":246.5376,"width":268.97305,"height":146.079}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":36,"language":null,"source_page":15,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
