  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'bf5f1f08a0c207fccad475320111595bbaaaaf722048a06f609bfccab708ed90', 'STATEMENT_CROP', 17, '2025-D1-CD4/question-40-COMMON/statement-page-17.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"bf5f1f08a0c207fccad475320111595bbaaaaf722048a06f609bfccab708ed90","crop":{"left":0,"bottom":174.4319,"width":265.38244999999995,"height":180.19050000000001},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '7c4813e8aa5bae08de43feb0ac3e056170c3dd6d668545ad6ae818791ebd0959' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 39, 'LINGUAGENS', 'Do rádio ao podcast Desde a disseminação do rádio no Brasil, entre as décadas de 1920 e 1930, principalmente no governo de Getúlio Vargas, as pessoas passaram a dedicar uma parte de seu dia para escutar notícias, novelas, músicas e eventos esportivos em aparelhos de som. O radiojornalismo, por sua vez, teve seu pontapé inicial durante a Revolução Constitucionalista (1932) e se desenvolveu durante a Segunda Guerra Mundial (1939-1945). Quando a TV surgiu, esperava-se que o rádio fosse totalmente substituído, porém ele se manteve em alta, pois o sinal de televisão não cobria todos os lugares, diferentemente do rádio. Com o surgimento da internet, dos smartphones e de outros dispositivos móveis, o rádio foi incorporado a essas novas tecnologias até o desenvolvimento da web rádio e do podcast, mostrando-se um meio de comunicação versátil e democrático na área jornalística. Para um pesquisador da Universidade Federal de Uberlândia (UFU), o rádio não se tornou obsoleto, visto que não deixou de ser consumido e se reinventou com o tempo. “O podcast é uma continuação, uma evolução natural do rádio”, opina. ALVES, A.; ALVES, C. Disponível em: https://comunica.ufu.br. Acesso em: 19 abr. 2024 (adaptado). Ao abordar a trajetória dos meios de comunicação, esse texto propõe uma reflexão sobre a', '["tecnologia digital e seus desdobramentos no desenvolvimento da televisão.","evolução da tecnologia digital com o predomínio do podcast sobre o rádio.","permanência do rádio e sua evolução por meio da tecnologia digital.","influência da televisão sobre os programas de radiojornalismo.","interferência da tecnologia digital nas interações humanas."]'::jsonb, '"permanência do rádio e sua evolução por meio da tecnologia digital."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"7c4813e8aa5bae08de43feb0ac3e056170c3dd6d668545ad6ae818791ebd0959","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"bddf59a1bf280ba1e2974f065cf5c02a4c637fdb8f3f27756c6c9f1b10416090","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":39,"language":null,"page":17,"storagePath":"2025-D1-CD1/question-39-COMMON/statement-page-17.png","sha256":"065c6fe881d5ad331a5aa7053e5e47a526b82bf915d0c81190193ead797c52d8","crop":{"left":0,"bottom":535.3901,"width":270.01249051749977,"height":206.35990000000004}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":39,"language":null,"source_page":17,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 39, subject_area = 'LINGUAGENS', statement = 'Do rádio ao podcast Desde a disseminação do rádio no Brasil, entre as décadas de 1920 e 1930, principalmente no governo de Getúlio Vargas, as pessoas passaram a dedicar uma parte de seu dia para escutar notícias, novelas, músicas e eventos esportivos em aparelhos de som. O radiojornalismo, por sua vez, teve seu pontapé inicial durante a Revolução Constitucionalista (1932) e se desenvolveu durante a Segunda Guerra Mundial (1939-1945). Quando a TV surgiu, esperava-se que o rádio fosse totalmente substituído, porém ele se manteve em alta, pois o sinal de televisão não cobria todos os lugares, diferentemente do rádio. Com o surgimento da internet, dos smartphones e de outros dispositivos móveis, o rádio foi incorporado a essas novas tecnologias até o desenvolvimento da web rádio e do podcast, mostrando-se um meio de comunicação versátil e democrático na área jornalística. Para um pesquisador da Universidade Federal de Uberlândia (UFU), o rádio não se tornou obsoleto, visto que não deixou de ser consumido e se reinventou com o tempo. “O podcast é uma continuação, uma evolução natural do rádio”, opina. ALVES, A.; ALVES, C. Disponível em: https://comunica.ufu.br. Acesso em: 19 abr. 2024 (adaptado). Ao abordar a trajetória dos meios de comunicação, esse texto propõe uma reflexão sobre a', options = '["tecnologia digital e seus desdobramentos no desenvolvimento da televisão.","evolução da tecnologia digital com o predomínio do podcast sobre o rádio.","permanência do rádio e sua evolução por meio da tecnologia digital.","influência da televisão sobre os programas de radiojornalismo.","interferência da tecnologia digital nas interações humanas."]'::jsonb, correct_answer = '"permanência do rádio e sua evolução por meio da tecnologia digital."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"7c4813e8aa5bae08de43feb0ac3e056170c3dd6d668545ad6ae818791ebd0959","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"bddf59a1bf280ba1e2974f065cf5c02a4c637fdb8f3f27756c6c9f1b10416090","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":39,"language":null,"page":17,"storagePath":"2025-D1-CD1/question-39-COMMON/statement-page-17.png","sha256":"065c6fe881d5ad331a5aa7053e5e47a526b82bf915d0c81190193ead797c52d8","crop":{"left":0,"bottom":535.3901,"width":270.01249051749977,"height":206.35990000000004}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":39,"language":null,"source_page":17,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
