  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'f2674328c4de8abbe9e141b59506f1025d28bd56b01b9f4bc3aa4fc227100a25', 'STATEMENT_CROP', 17, '2025-D1-CD1/question-40-COMMON/statement-page-17.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"f2674328c4de8abbe9e141b59506f1025d28bd56b01b9f4bc3aa4fc227100a25","crop":{"left":0,"bottom":171.4878,"width":270.01249051749977,"height":302.3598},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '39aa405e410093633d44c039b4bb02cbf9732e14a23e3fae5da5b4b8a68b49a5' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 41, 'LINGUAGENS', 'TEXTO I Origem, tradição e resistência Foi sentada em seu banco de quartzo que a avó do universo, moradora da Maloca do Céu, criou os homens, os animais, a terra e as águas. O banco foi entregue aos ancestrais dos atuais Tukano, que passaram a reproduzi-lo em madeira. O mito Tukano — povo do noroeste da Amazônia que ainda hoje fabrica os bancos em seu estilo tradicional — indica o lugar dos bancos entre os objetos sagrados, ao mesmo tempo parte do universo primitivo e fonte do poder de criação. A presença nos mitos de origem de alguns povos atesta a antiguidade da arte de talhar bancos: os primeiros registros do uso desses objetos entre ameríndios das terras baixas da América do Sul, do Caribe e da América Central datam de, pelo menos, 4 mil anos. ASSIS, R.; MENDES JR., L. Bancos indígenas do Brasil . São Paulo: BEI Comunicação, 2013. TEXTO II KAMAYURÁ, Y. Tatu Kamayurá 1 . Madeira, 61 × 24 × 20 cm. Xingu (MT), s.d. Disponível em: www.colecaobei.com.br. Acesso em: 15 out. 2024. Os textos I e ll demonstram, na confecção dos bancos, uma íntima relação de sacralidade entre o ser humano e a natureza, perceptível por meio da', '["representação realista de animais, mostrando o domínio do homem sobre a natureza.","manutenção da herança cultural, atribuindo nova função aos elementos da fauna.","anulação dos traços que permitem reconhecer o animal representado.","presença de grafismos na forma animal representada no banco.","criação de figuras fantásticas baseadas em formas animais."]'::jsonb, '"manutenção da herança cultural, atribuindo nova função aos elementos da fauna."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"39aa405e410093633d44c039b4bb02cbf9732e14a23e3fae5da5b4b8a68b49a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"44303455571d27164e53b3aee5237a9792eb598b442ddedb0180b93ee96fc1b0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":41,"language":null,"page":18,"storagePath":"2025-D1-CD1/question-41-COMMON/statement-page-18.png","sha256":"51a292c977b95e3395f71291de11c06129b29e0a9b3c59c33ba5e8af7e675726","crop":{"left":0,"bottom":403.9025,"width":288.11955,"height":337.8475}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":41,"language":null,"source_page":18,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 41, subject_area = 'LINGUAGENS', statement = 'TEXTO I Origem, tradição e resistência Foi sentada em seu banco de quartzo que a avó do universo, moradora da Maloca do Céu, criou os homens, os animais, a terra e as águas. O banco foi entregue aos ancestrais dos atuais Tukano, que passaram a reproduzi-lo em madeira. O mito Tukano — povo do noroeste da Amazônia que ainda hoje fabrica os bancos em seu estilo tradicional — indica o lugar dos bancos entre os objetos sagrados, ao mesmo tempo parte do universo primitivo e fonte do poder de criação. A presença nos mitos de origem de alguns povos atesta a antiguidade da arte de talhar bancos: os primeiros registros do uso desses objetos entre ameríndios das terras baixas da América do Sul, do Caribe e da América Central datam de, pelo menos, 4 mil anos. ASSIS, R.; MENDES JR., L. Bancos indígenas do Brasil . São Paulo: BEI Comunicação, 2013. TEXTO II KAMAYURÁ, Y. Tatu Kamayurá 1 . Madeira, 61 × 24 × 20 cm. Xingu (MT), s.d. Disponível em: www.colecaobei.com.br. Acesso em: 15 out. 2024. Os textos I e ll demonstram, na confecção dos bancos, uma íntima relação de sacralidade entre o ser humano e a natureza, perceptível por meio da', options = '["representação realista de animais, mostrando o domínio do homem sobre a natureza.","manutenção da herança cultural, atribuindo nova função aos elementos da fauna.","anulação dos traços que permitem reconhecer o animal representado.","presença de grafismos na forma animal representada no banco.","criação de figuras fantásticas baseadas em formas animais."]'::jsonb, correct_answer = '"manutenção da herança cultural, atribuindo nova função aos elementos da fauna."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"39aa405e410093633d44c039b4bb02cbf9732e14a23e3fae5da5b4b8a68b49a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"44303455571d27164e53b3aee5237a9792eb598b442ddedb0180b93ee96fc1b0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":41,"language":null,"page":18,"storagePath":"2025-D1-CD1/question-41-COMMON/statement-page-18.png","sha256":"51a292c977b95e3395f71291de11c06129b29e0a9b3c59c33ba5e8af7e675726","crop":{"left":0,"bottom":403.9025,"width":288.11955,"height":337.8475}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":41,"language":null,"source_page":18,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
