  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 42, 'LINGUAGENS', 'TRADUZINDO O JURIDIQUÊS “Denego a liminar pleiteada na exordial, inobstante Proposta de emenda à Constituição 269 de 2013. Aplica-se após a oitiva da parte adversa e da dilação probatória aos Governadores e Prefeitos o Regime Geral de Previdência possa lograr alcançar um outro epílogo para o deslinde Social, vedada a concessão graciosa, após o término do da quaestio sub examine .” mandato, de vantagem pecuniária, verba de representação, pensão ou subsídio. TRADUÇãO TRADUÇãO Não atendo, por ora, a liminar requerida na petição inicial, ainda que possa chegar a uma outra conclusão Torna-se proibido pagar benefícios vitalícios para após ouvir a outra parte e avaliar as provas produzidas. ex-prefeitos e ex-governadores. Superinteressante , n. 322, ago. 2013 (adaptado). Nesse texto, contribui para a construção da ironia a tradução das passagens escritas em “juridiquês” para uma variedade', '["padrão, que alcança o público em geral.","histórica, que registra a evolução das leis.","coloquial, que reproduz as relações sociais cotidianas.","erudita, que resgata a origem latina da língua portuguesa.","técnica, que facilita a circulação de informações no sistema judiciário."]'::jsonb, '"padrão, que alcança o público em geral."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"557fe327a3e748a35ed00b454148074ffe2ac589902333b9dc1e5b6e13be0adc","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fd101a27b4bee94cbba3728f9f3138faf0d2ffa60a8191642d7610b97e2187b7","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":42,"language":null,"page":18,"storagePath":"2025-D1-CD1/question-42-COMMON/statement-page-18.png","sha256":"9637965517d1a5b0455e627e5b66e97c611ff874fad40ab7982671d55dccadb9","crop":{"left":0,"bottom":129.4688,"width":288.11955,"height":209.3664}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":42,"language":null,"source_page":18,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
