  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '2dcff13938a9c63b07c9e66c1d7a823ccb9101d22755a6b4b6f3b9436f285453' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 46, 'CIENCIAS_HUMANAS', 'Macedônia do Norte Acordo entra em vigor e país muda oficialmente de nome Entrou em vigor, em 2019, o acordo que determina a mudança de nome da Macedônia para Macedônia do Norte. A troca põe fim — ao menos por enquanto — no impasse entre essa antiga república da Iugoslávia e a vizinha Grécia. O governo grego se opunha ao uso do nome Macedônia pelo novo país vizinho porque a Grécia tem uma província no norte com o mesmo nome. Por causa desse impasse, a Grécia bloqueou as negociações de adesão de seu vizinho à União Europeia. Depois de negociações, as duas partes chegaram a um acordo. Disponível em: https://g1.globo.com. Acesso em: 7 nov. 2021 (adaptado). Para o país originado da antiga Iugoslávia, a mudança de nome é uma estratégia política para', '["criar a moeda própria.","proteger a cultura local.","subjugar a minoria étnica.","expandir o território nacional.","intensificar a integração regional."]'::jsonb, '"intensificar a integração regional."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"2dcff13938a9c63b07c9e66c1d7a823ccb9101d22755a6b4b6f3b9436f285453","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"b6a540fe7ebbf82b23c34a44a2a1f5689d73a317193eb1ccfbb4a1e5093c89de","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":46,"language":null,"page":22,"storagePath":"2025-D1-CD1/question-46-COMMON/statement-page-22.png","sha256":"12589ffa87262cbba88d69ad6f191dd23e59ed5bd96f993aef91815ac0b024c8","crop":{"left":0,"bottom":556.3209,"width":275.0942499999999,"height":150.52609999999993}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":46,"language":null,"source_page":22,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 46, subject_area = 'CIENCIAS_HUMANAS', statement = 'Macedônia do Norte Acordo entra em vigor e país muda oficialmente de nome Entrou em vigor, em 2019, o acordo que determina a mudança de nome da Macedônia para Macedônia do Norte. A troca põe fim — ao menos por enquanto — no impasse entre essa antiga república da Iugoslávia e a vizinha Grécia. O governo grego se opunha ao uso do nome Macedônia pelo novo país vizinho porque a Grécia tem uma província no norte com o mesmo nome. Por causa desse impasse, a Grécia bloqueou as negociações de adesão de seu vizinho à União Europeia. Depois de negociações, as duas partes chegaram a um acordo. Disponível em: https://g1.globo.com. Acesso em: 7 nov. 2021 (adaptado). Para o país originado da antiga Iugoslávia, a mudança de nome é uma estratégia política para', options = '["criar a moeda própria.","proteger a cultura local.","subjugar a minoria étnica.","expandir o território nacional.","intensificar a integração regional."]'::jsonb, correct_answer = '"intensificar a integração regional."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"2dcff13938a9c63b07c9e66c1d7a823ccb9101d22755a6b4b6f3b9436f285453","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"b6a540fe7ebbf82b23c34a44a2a1f5689d73a317193eb1ccfbb4a1e5093c89de","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":46,"language":null,"page":22,"storagePath":"2025-D1-CD1/question-46-COMMON/statement-page-22.png","sha256":"