  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '96f8225127b057be22673a73e6436315d83b0cc58bbd799fa1e2194dfa7fe01c', 'STATEMENT_CROP', 25, '2025-D1-CD4/question-59-COMMON/statement-page-25.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"96f8225127b057be22673a73e6436315d83b0cc58bbd799fa1e2194dfa7fe01c","crop":{"left":0,"bottom":591.2198,"width":268.0076499999999,"height":150.53020000000004},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c386f8b482ce827846cd568f523daee58b42146259e8823fc5efb0a45a5cde02' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 48, 'CIENCIAS_HUMANAS', 'A credulidade dos ouvintes aumenta o descaramento do narrador, e o descaramento deste conquista-lhes a credulidade. A eloquência, quando levada a seu patamar mais alto, deixa pouco lugar à razão ou à reflexão, mas, dirigindo-se inteiramente à imaginação e aos afetos, cativa os ouvintes condescendentes e subjuga-lhes o entendimento. HUME, D. Uma investigação sobre o entendimento humano e sobre os princípios da moral . São Paulo: Edunesp, 2003. No contexto do século XVIII, o autor propõe uma reflexão radical acerca da arte da eloquência, restringindo-a ao', '["sistema de crenças, conforme a proposta kantiana de objetividade do conhecimento.","campo dos absolutos, semelhante ao entendimento medieval dos Universais.","domínio da lógica, consoante a compreensão aristotélica nos Analíticos.","paradigma da racionalidade, alinhado ao modelo cartesiano de método.","âmbito da persuasão, análogo às críticas platônicas aos sofistas."]'::jsonb, '"âmbito da persuasão, análogo às críticas platônicas aos sofistas."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"c386f8b482ce827846cd568f523daee58b42146259e8823fc5efb0a45a5cde02","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FILOSOFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FILOSOFIA","classification_source_fingerprint":"6afd30b46b191e52cffc9eb94a3959648f9212c38294ca72c190d2a463d10f7e","statement_assets":[{"asse