  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'd7d70267068dd70845351153dc86addf8d4afb810491324f527262ef7345abbb', 'STATEMENT_CROP', 24, '2025-D1-CD4/question-56-COMMON/statement-page-24.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"d7d70267068dd70845351153dc86addf8d4afb810491324f527262ef7345abbb","crop":{"left":0,"bottom":693.9694,"width":317.2666,"height":47.78060000000005},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'f8a691ed8b417daaae28167259fe8058071bbe26027313934b5a1070b1a1c2ba' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D1', 51, 'CIENCIAS_HUMANAS', 'Sinal fechado Olá, como vai? Eu vou indo e você, tudo bem? Tudo bem, eu vou indo, correndo Pegar meu lugar no futuro, e você? Tudo bem, eu vou indo em busca De um sono tranquilo, quem sabe? Quanto tempo... Pois é, quanto tempo... Me perdoe a pressa É a alma dos nossos negócios... Oh, não tem de que Eu também só ando a cem Quando é que você telefona? Precisamos nos ver por aí Pra semana, prometo, Talvez nos vejamos, quem sabe? Quanto tempo... CARLEVARIS, L. La piazetta (detalhe). Óleo sobre tela, 49 × 41 cm. Ashmolean Museum, Oxford, 1729. Pois é, quanto tempo... Disponível em: www.meinsterart.de. Acesso em: 13 dez. 2017. Tanta coisa que eu tinha a dizer TEXTO II Mas eu sumi na poeira das ruas Eu também tenho algo a dizer Antigo centro da economia mundo-europeia do século XV, Mas me foge a lembrança no final do século XVII e início do século XVIII, Veneza ainda era Por favor, telefone, eu preciso beber uma cidade cosmopolita onde orientais podiam sentir-se em casa. Alguma coisa rapidamente BRAUDEL, F. O tempo do mundo . São Paulo: Martins Fontes, 1979 (adaptado). Pra semana... O sinal... Qual elemento da condição cosmopolita de Veneza na Idade Eu procuro você... Moderna está explicitado nos textos? Vai abrir! Vai abrir!', '["Avanço do ensino laico. Prometo, não esqueço","Conquista das terras da América. Por favor, não esqueça","Integração do comércio mediterrâneo. Não esqueço, não esqueço Adeus...","Popularização do pensamento humanista. PAULINHO DA VIOLA. Foi um rio que passou em minha vida .","Desenvolvimento das corporações de ofício."]'::jsonb, '"Popularização do pensamento humanista. PAULINHO DA VIOLA. Foi um rio que passou em minha vida ."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"f8a691ed8b417daaae28167259fe8058071bbe26027313934b5a1070b1a1c2ba","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"74a50fb4ed229d3229b2eb75a050880ae08725ca0ff2d5bd4be2a50535c2bc24","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":51,"language":null,"page":23,"storagePath":"2025-D1-CD1/question-51-COMMON/statement-page-23.png","sha256":"21e2c288ad69e7d5239224ef952418bdfac301d0af94a1870c6d139d02b419dc","crop":{"left":310.18,"bottom":236.88930000000042,"width":256.7475,"height":401.5032999999996}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":51,"language":null,"source_page":23,"source_sha256":"a0f19f878d4ef3ba94c3e0f5ef9e57c13fb046d4bb362f72651898b473ddb7c8"}}'::jsonb, true) returning id into v_question_id; end if;
