  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'ce65eec28a2f42ffacd9f1554b086a07705aa1cedf2cf201d8ac27951cd170df', 'STATEMENT_CROP', 3, '2025-D2-CD5/question-96-COMMON/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"ce65eec28a2f42ffacd9f1554b086a07705aa1cedf2cf201d8ac27951cd170df","crop":{"left":0,"bottom":371.4499,"width":263.81866603249995,"height":126.8381},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'bb61eebad1d5852cc168664d781fc7300ee1bb6c58453f9d0f7b840d0548cf86' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D2', 107, 'CIENCIAS_NATUREZA', 'As usinas termonucleares são aquelas que produzem energia elétrica a partir da geração de energia térmica proveniente das reações nucleares. Normalmente, essas usinas funcionam por meio de dois circuitos, denominados circuito primário (vaso de pressão, pressurizador e bomba) e circuito secundário (gerador de vapor, turbina, condensador, tanque de alimentação e bombas), além de um sistema de água de refrigeração, formado por uma bomba ligada a uma fonte hídrica natural. Durante a operação da usina, se o sistema de água de refrigeração funcionar de forma ineficiente pode causar poluição térmica, comprometendo a vida no ecossistema aquático. Disponível em: www.eletronuclear.gov.br. Acesso em: 29 nov. 2021 (adaptado). Para o ecossistema aquático, a ineficiência do sistema de água de refrigeração tem como consequência a', '["diminuição do pH.","liberação de gases poluentes.","contaminação por combustíveis.","liberação de elementos radioativos.","diminuição da solubilidade do gás oxigênio."]'::jsonb, '"diminuição da solubilidade do gás oxigênio."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"bb61eebad1d5852cc168664d781fc7300ee1bb6c58453f9d0f7b840d0548cf86","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"e5728d7aa10c94ade64334206cc8239aca2f066c231a7ebf01e842f4ad34992b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":107,"language":null,"page":7,"storagePath":"2025-D2-CD5/question-107-COMMON/statement-page-7.png","sha256":"c6a1f6719c811efc9ee3d87ecc374b38f4afac4cf81fbef650e748b6564f779b","crop":{"left":0,"bottom":438.1155,"width":292.14060409499973,"height":303.6345}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":107,"language":null,"source_page":7,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, true) returning id into v_question_id; end if;
