  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'f3c31e74fdecc6b054ce17fa6d7f6424270acd644576ce25692dcd7e5a65bf1c' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D2', 111, 'CIENCIAS_NATUREZA', 'O fruto do cajueiro é um aquênio repleto de um líquido O esquema apresenta as etapas do processo de biodigestão, escuro, quase preto, cáustico e inflamável. Esse líquido da uma forma de dar um destino sustentável a excrementos animais casca da castanha do caju (LCC) representa aproximadamente e restos de comida produzidos em áreas de criação de gado e 25% da massa da castanha e é um subproduto de agronegócio porcos confinados. do caju. Quando submetido a altas temperaturas, o ácido anacárdico presente no LCC é convertido a cardanol, que recebe a denominação de LCC técnico, conforme o esquema: MAZZETTO, S. E.; LOMONACO, D.; MELE, G. Óleo da castanha de caju: oportunidades e desafios no contexto do desenvolvimento e sustentabilidade industrial. Química Nova , n. 3, 2009 (adaptado). O LCC técnico é produzido por meio de uma reação orgânica do tipo', '["hidrólise.","fenilação.","esterificação.","hidrogenação. Disponível em: www.engquimicasantossp.com.br.","descarboxilação."]'::jsonb, '"fenilação."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"f3c31e74fdecc6b054ce17fa6d7f6424270acd644576ce25692dcd7e5a65bf1c","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c53add3efe03545cdf2ea00968415dcc3e3e4f998889783b5dc238303b08025d","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":111,"language":null,"source_page":8,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 111, subject_area = 'CIENCIAS_NATUREZA', statement = 'O fruto do cajueiro é um aquênio repleto de um líquido O esquema apresenta as etapas do processo de biodigestão, escuro, quase preto, cáustico e inflamável. Esse líquido da uma forma de dar um destino sustentável a excrementos animais casca da castanha do caju (LCC) representa aproximadamente e restos de comida produzidos em áreas de criação de gado e 25% da massa da castanha e é um subproduto de agronegócio porcos confinados. do caju. Quando submetido a altas temperaturas, o ácido anacárdico presente no LCC é convertido a cardanol, que recebe a denominação de LCC técnico, conforme o esquema: MAZZETTO, S. E.; LOMONACO, D.; MELE, G. Óleo da castanha de caju: oportunidades e desafios no contexto do desenvolvimento e sustentabilidade industrial. Química Nova , n. 3, 2009 (adaptado). O LCC técnico é produzido por meio de uma reação orgânica do tipo', options = '["hidrólise.","fenilação.","esterificação.","hidrogenação. Disponível em: www.engquimicasantossp.com.br.","descarboxilação."]'::jsonb, correct_answer = '"fenilação."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"f3c31e74fdecc6b054ce17fa6d7f6424270acd644576ce25692dcd7e5a65bf1c","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c53add3efe03545cdf2ea00968415dcc3e3e4f998889783b5dc238303b08025d","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":111,"language":null,"source_page":8,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
