  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '3aa3fcd94e13ad0703a136b8aace5b497f143b970f79f7f4944cefec8e2b7cee' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D2', 123, 'CIENCIAS_NATUREZA', 'eletrotécnico é: Para a produção de titânio metálico ou dióxido de titânio puros, é necessário fazer a cloração do minério que contém dióxido de titânio, com o objetivo de separar esse óxido de A outras substâncias presentes no minério. A principal reação química de cloração é representada por: TiO2 (s) + 2 Cl2 (g) TiCl4 (g) + O2 (g) Δ H = + 175 kJ/mol Depois da cloração, o tetracloreto de titânio é condensado e convertido, novamente, a dióxido de titânio. Após o sistema atingir o equilíbrio químico, como a formação B do TiCl4 pode ser favorecida?', '["Aumentando a pressão total do sistema.","Diminuindo a temperatura do sistema.","Aumentando a pressão parcial de O2.","Aumentando a pressão parcial de Cl2. C","Variando a quantidade de TiO2."]'::jsonb, '"Aumentando a pressão parcial de Cl2. C"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"3aa3fcd94e13ad0703a136b8aace5b497f143b970f79f7f4944cefec8e2b7cee","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"4d44c5c6d29ae1d651804210ae6d88ffab3300d1d526b51808b433d25cc0738f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":123,"language":null,"page":12,"storagePath":"2025-D2-CD5/question-123-COMMON/statement-page-12.png","sha256":"5ced52f47435cf1c295b5715f17fdd62760c40432c904a2f373cc6b0d75d67d4","crop":{"left":0,"bottom":316.971,"width":301.00569999999993,"height":172.76330000000002}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":123,"language":null,"source_page":12,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, true) returning id into v_question_id; end if;
