  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '042b1407d4e5458c5dd38d8536b4df832070e16142af89541ef3ec287415706a' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D2', 173, 'MATEMATICA', 'Em um país, a primeira etapa para obtenção da carteira de motorista é a contratação de três produtos: • pacote com 20 aulas teóricas; • pacote com 10 aulas práticas; • aluguel do veículo para realização das aulas práticas. Uma pessoa que pretende obter a carteira de motorista pesquisou o valor do aluguel do veículo e os valores de cada aula teórica e de cada aula prática em três autoescolas. O quadro apresenta esses valores. Autoescola Valor de cada aula teórica (R$) Valor de cada aula prática (R$) Aluguel do veículo (R$) I 10 80 400 II 30 50 200 III 20 40 400 Ela contratará os três produtos numa mesma autoescola de modo que o custo total nessa primeira etapa seja o menor possível. A autoescola que será contratada é a', '["I, com o custo total de R$ 1 400,00.","II, com o custo total de R$ 280,00.","II, com o custo total de R$ 1 300,00.","III, com o custo total de R$ 460,00.","III, com o custo total de R$ 1 200,00."]'::jsonb, '"III, com o custo total de R$ 1 200,00."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"042b1407d4e5458c5dd38d8536b4df832070e16142af89541ef3ec287415706a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"2361c654222b3083506258476ecc44d2ed754526cad3514cf773e82974643456","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":173,"language":null,"page":29,"storagePath":"2025-D2-CD5/question-173-COMMON/statement-page-29.png","sha256":"e7c2f0690269e083fc0694a318f1e10e7de3c4e81b38772cf669f194fa012d59","crop":{"left":0,"bottom":129.6691,"width":299.7346,"height":224.8244}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":173,"language":null,"source_page":29,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, true) returning id into v_question_id; end if;
