  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'e7c2f0690269e083fc0694a318f1e10e7de3c4e81b38772cf669f194fa012d59', 'STATEMENT_CROP', 29, '2025-D2-CD5/question-173-COMMON/statement-page-29.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"e7c2f0690269e083fc0694a318f1e10e7de3c4e81b38772cf669f194fa012d59","crop":{"left":0,"bottom":129.6691,"width":299.7346,"height":224.8244},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8f2893c48c6dfbdc3f8f616354a61b9c698e314f6621262d7281e1e373b21636' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D2', 176, 'MATEMATICA', 'Um empresário utiliza máquinas cuja pressão interna P , em atmosfera, depende do tempo contínuo de utilização t , em hora, e de um parâmetro positivo K , que define o modelo da máquina, segundo a expressão: P = 4 ⋅ log[ − K ⋅ ( t + 1) ⋅ ( t − 19)] O fabricante dessas máquinas recomenda ao usuário que a pressão interna desse tipo de máquina não ultrapasse 10 atmosferas durante seu funcionamento. O empresário pretende comprar novas máquinas desse tipo que deverão funcionar, diariamente, por um período contínuo de 10 horas. Para isso, precisa definir o modelo de máquina a ser adquirida escolhendo o maior valor possível A cada acionamento da descarga, todo o volume de do parâmetro K , atendendo à recomendação do fabricante. água contida na caixa é despejado no vaso. Para reduzir o O maior valor a ser escolhido para K é volume de água despejado a cada acionamento, uma pessoa 0,5 colocará, no interior dessa caixa, garrafas de 300 mL, cheias A 10 de areia e tampadas, de modo a ficarem submersas quando 8 B 10 o abastecimento for interrompido. 2 5 , Para garantir o funcionamento eficiente, o mínimo de água 10 C despejada a cada acionamento deve ser de 5 L. 84 2 5 , A quantidade máxima de garrafas que serão colocadas nessa 10 D caixa, garantindo um funcionamento eficiente, é igual a 99 − 2 E 25 × 10', '["10.","8.","4.","3.","2."]'::jsonb, '"10."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"8f2893c48c6dfbdc3f8f616354a61b9c698e314f6621262d7281e1e373b21636","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"1eba3ff54dd2408af3649c033f851b9c059db5c355602393b22094b24244c724","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":176,"language":null,"page":30,"storagePath":"2025-D2-CD5/question-176-COMMON/statement-page-30.png","sha256":"f92540577bc756756850c0e36e847df536c2ef91b5bed851743bfba8e9bac0c3","crop":{"left":313.38323845,"bottom":120.34129999999999,"width":253.54426155,"height":337.0276}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":176,"language":null,"source_page":30,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 176, subject_area = 'MATEMATICA', statement = 'Um empresário utiliza máquinas cuja pressão interna P , em atmosfera, depende do tempo contínuo de utilização t , em hora, e de um parâmetro positivo K , que define o modelo da máquina, segundo a expressão: P = 4 ⋅ log[ − K ⋅ ( t + 1) ⋅ ( t − 19)] O fabricante dessas máquinas recomenda ao usuário que a pressão interna desse tipo de máquina não ultrapasse 10 atmosferas durante seu funcionamento. O empresário pretende comprar novas máquinas desse tipo que deverão funcionar, diariamente, por um período contínuo de 10 horas. Para isso, precisa definir o modelo de máquina a ser adquirida escolhendo o maior valor possível A cada acionamento da descarga, todo o volume de do parâmetro K , atendendo à recomendação do fabricante. água contida na caixa é despejado no vaso. Para reduzir o O maior valor a ser escolhido para K é volume de água despejado a cada acionamento, uma pessoa 0,5 colocará, no interior dessa caixa, garrafas de 300 mL, cheias A 10 de areia e tampadas, de modo a ficarem submersas quando 8 B 10 o abastecimento for interrompido. 2 5 , Para garantir o funcionamento eficiente, o mínimo de água 10 C despejada a cada acionamento deve ser de 5 L. 84 2 5 , A quantidade máxima de garrafas que serão colocadas nessa 10 D caixa, garantindo um funcionamento eficiente, é igual a 99 − 2 E 25 × 10', options = '["10.","8.","4.","3.","2."]'::jsonb, correct_answer = '"10."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"8f2893c48c6dfbdc3f8f616354a61b9c698e314f6621262d7281e1e373b21636","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"1eba3ff54dd2408af3649c033f851b9c059db5c355602393b22094b24244c724","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":176,"language":null,"page":30,"storagePath":"2025-D2-CD5/question-176-COMMON/statement-page-30.png","sha256":"f92540577bc756756850c0e36e847df536c2ef91b5bed851743bfba8e9bac0c3","crop":{"left":313.38323845,"bottom":120.34129999999999,"width":253.54426155,"height":337.0276}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":176,"language":null,"source_page":30,"source_sha256":"0a59697676989b55e6f3e40636fad164c1c26868ddba37d04e4fffc101168298"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
