  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '90a323a6e2cebe67ab530385ab1a04ca8bd78905c0a2af4119dae91153e170a5' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 1, 'LINGUAGENS', 'Still I Rise Out of the huts of history’s shame I rise Up from a past that’s rooted in pain I rise I’m a black ocean, leaping and wide, Welling and swelling I bear in the tide. Leaving behind nights of terror and fear I rise Into a daybreak that’s wondrously clear I rise Bringing the gifts that my ancestors gave, I am the dream and the hope of the slave. I rise I rise I rise. ANGELOU, M. Disponível em: www.famouspoetsandpoems.com. Acesso em: 30 jul. 2013 (fragmento). Maya Angelou, poeta afro-americana, escreveu diversos poemas sobre a opressão racial. Em Still I Rise , o recurso utilizado pela autora para sugerir a superação da opressão racial é a GLASBERGEN. Disponível em: www.glasbergen.com.', '["rima entre “ wide ” e “ tide” . Acesso em: 2 out. 2015 (adaptado).","repetição enfática de “ I rise” .","metáfora em “I’m a black ocean” . Esse cartum, que ilustra uma situação escolar, busca","hipérbole em “nights of terror and fear” .","ironia em “ the gifts that my ancestors gave ”. A revelar a imaturidade emocional dos estudantes."]'::jsonb, '"repetição enfática de “ I rise” ."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"90a323a6e2cebe67ab530385ab1a04ca8bd78905c0a2af4119dae91153e170a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"3a0d0d98a3ec170b43a65ab852ba558990d75f885bca201a62f1e00551983a74","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":1,"language":"ENGLISH","page":2,"storagePath":"2025-D3-CD1/question-1-ENGLISH/statement-page-2.png","sha256":"ac82b8fb02c23c780fa1b3dfaf6cc3d4e4c010684ba9befe2f28f8fe276c2884","crop":{"left":0,"bottom":419.5509,"width":311.8057125000009,"height":274.0301}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":1,"language":"ENGLISH","source_page":2,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D3', source_number = 1, subject_area = 'LINGUAGENS', statement = 'Still I Rise Out of the huts of history’s shame I rise Up from a past that’s rooted in pain I rise I’m a black ocean, leaping and wide, Welling and swelling I bear in the tide. Leaving behind nights of terror and fear I rise Into a daybreak that’s wondrously clear I rise Bringing the gifts that my ancestors gave, I am the dream and the hope of the slave. I rise I rise I rise. ANGELOU, M. Disponível em: www.famouspoetsandpoems.com. Acesso em: 30 jul. 2013 (fragmento). Maya Angelou, poeta afro-americana, escreveu diversos poemas sobre a opressão racial. Em Still I Rise , o recurso utilizado pela autora para sugerir a superação da opressão racial é a GLASBERGEN. Disponível em: www.glasbergen.com.', options = '["rima entre “ wide ” e “ tide” . Acesso em: 2 out. 2015 (adaptado).","repetição enfática de “ I rise” .","metáfora em “I’m a black ocean” . Esse cartum, que ilustra uma situação escolar, busca","hipérbole em “nights of terror and fear” .","ironia em “ the gifts that my ancestors gave ”. A revelar a imaturidade emocional dos estudantes."]'::jsonb, correct_answer = '"repetição enfática de “ I rise” ."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"90a323a6e2cebe67ab530385ab1a04ca8bd78905c0a2af4119dae91153e170a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"3a0d0d98a3ec170b43a65ab852ba558990d75f885bca201a62f1e00551983a74","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":1,"language":"ENGLISH","page":2,"storagePath":"2025-D3-CD1/question-1-ENGLISH/statement-page-2.png","sha256":"ac82b8fb02c23c780fa1b3dfaf6cc3d4e4c010684ba9befe2f28f8fe276c2884","crop":{"left":0,"bottom":419.5509,"width":311.8057125000009,"height":274.0301}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":1,"language":"ENGLISH","source_page":2,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
