  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'ac82b8fb02c23c780fa1b3dfaf6cc3d4e4c010684ba9befe2f28f8fe276c2884', 'STATEMENT_CROP', 2, '2025-D3-CD1/question-1-ENGLISH/statement-page-2.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"ac82b8fb02c23c780fa1b3dfaf6cc3d4e4c010684ba9befe2f28f8fe276c2884","crop":{"left":0,"bottom":419.5509,"width":311.8057125000009,"height":274.0301},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
