  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '23dd98dec991a999b83aa2868c6d5af12768c8594f9913dda947e14f99bb6b97' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 25, 'LINGUAGENS', 'voam. Sonho de Breno é voar, seja como piloto de avião ou jogador de futebol. Como borboleta, Breno nunca chegou a pensar, tem nove anos, mas sabe que é menino e não lagarta. A avó de Breno sempre diz: “Lagarta queima o dedinho e come planta, mas vira borboleta. Ninguém nasce borboleta”. Agora o menino pensa e olha a borboleta na janela. “De manhã vi um monte de buraquinhos nas folhas”; explicaram a ele: “É coisa de lagarta”. Os buracos nas acerolas e goiabas eram coisa dos passarinhos. Isso ninguém precisou explicar, porque ele sempre viu os passarinhos indo bicar as frutas, menos o beija-flor, que só ia bicar a água no copo de flor pendurado na goiabeira. “O que será que borboleta come? Será que beija-flor só bebe água?”. Pensou muito nisso e sentiu fome. Saiu em direção à cozinha. MARTINS, G. O sol na cabeça . São Paulo: Cia. das Letras, 2018. Nesse fragmento, a estratégia que constrói a narração sob a perspectiva do protagonista é a', '["recorrência de termos na forma diminutiva.","inserção de memórias no decorrer do enredo.","descrição pormenorizada do entorno do personagem.","incorporação da voz do personagem à voz do narrador.","mescla de planos narrativos nos tempos presente e passado."]'::jsonb, '"inserção de memórias no decorrer do enredo."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"23dd98dec991a999b83aa2868c6d5af12768c8594f9913dda947e14f99bb6b97","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"e1299d207488b1cf23cefb20bacb2abc43591cdfdcad5c97a526e01b514ce9f3","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":25,"language":null,"page":12,"storagePath":"2025-D3-CD1/question-25-COMMON/statement-page-12.png","sha256":"1a6b434a6d7d17a1972a476a4fd7377889d5b5782657284e0ebd4d37a3495417","crop":{"left":0,"bottom":406.2248,"width":290.30833676000003,"height":230.02129999999994}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":25,"language":null,"source_page":12,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, true) returning id into v_question_id; end if;
