  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'e67b07cbcd438524a38c2e37291e2bdd996e0e4a15e703d8e1826af9c45ef2e2', 'STATEMENT_CROP', 19, '2025-D3-CD4/question-44-COMMON/statement-page-19.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"e67b07cbcd438524a38c2e37291e2bdd996e0e4a15e703d8e1826af9c45ef2e2","crop":{"left":0,"bottom":710,"width":251.820725,"height":31.75},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd29c35a4792ac3ef71acbf06d1e61afe8f50b40136b62f9c5d13f4df7a51e42b' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 39, 'LINGUAGENS', '“Adjudicar?”: filme de Claudinho e Buchecha revela significado do termo em Nosso sonho O filme Nosso sonho , a cinebiografia de Claudinho e Buchecha, abordou uma dúvida carregada por muitos fãs da dupla. Afinal, o que significa a palavra “adjudicar”? O termo está presente na letra da canção Nosso sonho — que dá nome ao longa —, um dos maiores sucessos dos artistas. De acordo com o dicionário Aurélio , “adjudicar” é “conceder a posse de (algo), por decisão ou sentença judicial ou administrativa”. O termo também pode significar “considerar como autor, causa ou origem”. Uma das interpretações da música pode sugerir que “o sonho não vai acabar” se o “destino” conceder a posse do amor ao casal em questão. No filme, o assunto é abordado de uma forma muito bem-humorada. Ao levarem a letra de Nosso sonho para a gravadora, os produtores veem com estranheza o termo e afirmam que ele é “inventado”. Na sequência, Claudinho saca um dicionário gigantesco e lê o significado literal da palavra para provar sua existência. Disponível em: https://cultura.uol.com.br. Acesso em: 8 jan. 2024 (adaptado). De acordo com esse texto, o estranhamento em torno do vocábulo “adjudicar” se deve ao fato de a letra de canção', '["promover o uso de palavras rebuscadas na valorização da obra musical.","empregar um regionalismo típico carioca no gênero musical funk.","inserir um termo formal do meio jurídico em uma canção popular.","incorporar uma palavra em desuso no português brasileiro.","introduzir uma gíria comum ao público-alvo da canção."]'::jsonb, '"inserir um termo formal do meio jurídico em uma canção popular."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"d29c35a4792ac3ef71acbf06d1e61afe8f50b40136b62f9c5d13f4df7a51e42b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fd83fab795915e865bd0b8503eb023037626a36e1bd241cc515c489a0c57d214","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":39,"language":null,"page":17,"storagePath":"2025-D3-CD1/question-39-COMMON/statement-page-17.png","sha256":"bb2e04723d5f3be1e83e138a29b418f2d3d6449191ad25b127084dfc093822df","crop":{"left":249.896975,"bottom":277.4977,"width":317.030525,"height":323.9598}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":39,"language":null,"source_page":17,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D3', source_number = 39, subject_area = 'LINGUAGENS', statement = '“Adjudicar?”: filme de Claudinho e Buchecha revela significado do termo em Nosso sonho O filme Nosso sonho , a cinebiografia de Claudinho e Buchecha, abordou uma dúvida carregada por muitos fãs da dupla. Afinal, o que significa a palavra “adjudicar”? O termo está presente na letra da canção Nosso sonho — que dá nome ao longa —, um dos maiores sucessos dos artistas. De acordo com o dicionário Aurélio , “adjudicar” é “conceder a posse de (algo), por decisão ou sentença judicial ou administrativa”. O termo também pode significar “considerar como autor, causa ou origem”. Uma das interpretações da música pode sugerir que “o sonho não vai acabar” se o “destino” conceder a posse do amor ao casal em questão. No filme, o assunto é abordado de uma forma muito bem-humorada. Ao levarem a letra de Nosso sonho para a gravadora, os produtores veem com estranheza o termo e afirmam que ele é “inventado”. Na sequência, Claudinho saca um dicionário gigantesco e lê o significado literal da palavra para provar sua existência. Disponível em: https://cultura.uol.com.br. Acesso em: 8 jan. 2024 (adaptado). De acordo com esse texto, o estranhamento em torno do vocábulo “adjudicar” se deve ao fato de a letra de canção', options = '["promover o uso de palavras rebuscadas na valorização da obra musical.","empregar um regionalismo típico carioca no gênero musical funk.","inserir um termo formal do meio jurídico em uma canção popular.","incorporar uma palavra em desuso no português brasileiro.","introduzir uma gíria comum ao público-alvo da canção."]'::jsonb, correct_answer = '"inserir um termo formal do meio jurídico em uma canção popular."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"d29c35a4792ac3ef71acbf06d1e61afe8f50b40136b62f9c5d13f4df7a51e42b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fd83fab795915e865bd0b8503eb023037626a36e1bd241cc515c489a0c57d214","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":39,"language":null,"page":17,"storagePath":"2025-D3-CD1/question-39-COMMON/statement-page-17.png","sha256":"bb2e04723d5f3be1e83e138a29b418f2d3d6449191ad25b127084dfc093822df","crop":{"left":249.896975,"bottom":277.4977,"width":317.030525,"height":323.9598}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":39,"language":null,"source_page":17,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
