  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '6026ef370f1e4a02116c58119673540559018e1a5dc8f7890417e9c664bf5f10', 'STATEMENT_CROP', 16, '2025-D3-CD4/question-36-COMMON/statement-page-16.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"6026ef370f1e4a02116c58119673540559018e1a5dc8f7890417e9c664bf5f10","crop":{"left":0,"bottom":299.765,"width":311.05015000000094,"height":47.751900000000035},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '100e8c2ffe4a440db67914165f13bbf685dc60a20921a9269778c7b5d7299a3d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 43, 'LINGUAGENS', 'A multiplicidade das formas, presente em Carretéis 4 , de Iberê Camargo, sugere que Voldemort: um vilão fictício? A objeto, memória e lúdico são traduzidos como fonte criativa Imagine um personagem cuja simples menção nos provoque um em formas simplificadas. arrepio na espinha, nos cause ódio, medo, repulsa; um personagem B linhas, forma e infância são elementos criativos determinantes que nos faça questionar os limites da maldade e refletir: será que entre os artistas modernos. existe alguém assim no mundo real? Imagine um personagem que seja apresentado de forma superficial, sem que possamos C formas abstratas e geométricas são típicas da arte conhecer sua história e suas motivações; que seja apresentado contemporânea, com base na subjetividade do artista. como alguém puramente mau e que pareça existir apenas para D figuras na arte moderna são representadas com formas causar destruição e terror. Esse personagem é um vilão. simples e livres, como as pinturas realizadas por crianças. Muitos vilões da ficção são tão caricatos, têm características E memória, mãe e tecido são os elementos principais de tão exageradas e estão tão distantes daquilo que consideramos inspiração do filho artista, como reprodução do ofício “humano”, que visivelmente não possuem qualquer relação materno. com pessoas do mundo real. Mas há aqueles vilões que fazem você pensar: será que isso está tão distante da realidade assim?', '["objeto, memória e lúdico são traduzidos como fonte criativa","linhas, forma e infância são elementos criativos determinantes","formas abstratas e geométricas são típicas da arte","figuras na arte moderna são representadas com formas","memória, mãe e tecido são os elementos principais de"]'::jsonb, '"linhas, forma e infância são elementos criativos determinantes"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"100e8c2ffe4a440db67914165f13bbf685dc60a20921a9269778c7b5d7299a3d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"a6579baeb5e7a5ff0fb82bc5ed97d2200e464747d00888e1a6c0d8a1fdfbbf7b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":43,"language":null,"page":19,"storagePath":"2025-D3-CD1/question-43-COMMON/statement-page-19.png","sha256":"976965bfb880fdc818e8bf127b38ff5b9827287a682d652efde012bf0c8830ae","crop":{"left":0,"bottom":693.998,"width":295.254504260001,"height":47.75199999999995}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":43,"language":null,"source_page":19,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, true) returning id into v_question_id; end if;
