  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'fb6590c96543843f75096de6e516bbab5a39bef43d172b2cc66cbbde9a2a337e' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 67, 'CIENCIAS_HUMANAS', 'Brasil, China e Índia tiveram maiores O ano de 1492, segundo nossa tese central, é a data saltos em expectativa de vida do “nascimento da Modernidade”; embora sua gestação — Crescimento relativo da expectativa de vida, comparação como feto — leve um tempo de crescimento intrauterino. entre as 10 maiores economias do mundo, 1960-2020 A Modernidade originou-se nas cidades medievais europeias, livres centros de criatividades. Mas “nasceu” quando a Europa pôde se confrontar com o seu “outro” e controlá-lo, vencê-lo, violentá-lo: quando pôde se definir como um “ego” descobridor, colonizador da alteridade constitutiva da própria Modernidade. DUSSEL, E. 1492 — O encobrimento do outro : a origem do “Mito da Modernidade”. Petrópolis: Vozes, 1993 (adaptado). A tese do autor sobre o nascimento da Modernidade refere-se a um evento histórico conhecido como:', '["Iluminismo francês.","Reforma Protestante.","Conquista da América.","Expansão muçulmana.","Surgimento das universidades."]'::jsonb, '"Conquista da América."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"fb6590c96543843f75096de6e516bbab5a39bef43d172b2cc66cbbde9a2a337e","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fce48b6dbdee03f6cec0f16a825776a41c1f5609c2beb478daed29fc815287f4","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD1","question_number":67,"language":null,"source_page":26,"source_sha256":"5a79ada84a016c6d07841204bdeace2663c2f4e5278e8fbf611a496bc5307c66"}}'::jsonb, true) returning id into v_question_id; end if;
