  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'a4a1012f507151c30174f7b33704e768312aac1f96d30353fff62f11e819f6ce' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D3', 58, 'CIENCIAS_HUMANAS', 'B fragilidade do ecossistema. Quase 42% do rebanho brasileiro está nos estados do Acre, C indiferença dos cidadãos. Amapá, Amazonas, Mato Grosso, Pará, Rondônia, Roraima, D negligência dos magistrados. Tocantins e Maranhão, que formam a chamada Amazônia Legal. E redução do emprego. Segundo dados do IBGE, são 89 milhões de cabeças de gado na região. E o preço é pago pela floresta. De acordo com um levantamento da plataforma Mapbiomas, entre 1985 e 2019 o Brasil transformou 67,8 milhões de hectares de florestas em pastagens. Disponível em: https://istoe.com.br. Acesso em: 22 out. 2021 (adaptado). O processo econômico descrito traz a seguinte consequência ambiental para a região afetada:', '["Elevação do lençol freático.","Redução das médias térmicas.","Ampliação da fertilidade pedológica.","Intensificação das precipitações frontais.","Diminuição da evapotranspiração vegetal."]'::jsonb, '"Diminuição da evapotranspiração vegetal."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"a4a1012f507151c30174f7b33704e768312aac1f96d30353fff62f11e819f6ce","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"bf77fe851c06f49d7f021e6c62e7a24b68d977a249e38255c3388314c0e8292d","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":58,"language":null,"page":24,"storagePath":"2025-D3-CD4/question-58-COMMON/statement-page-24.png","sha256":"94e84ccfa6ee78cc9f0e6639f0600fb49f2409fa2d433f97b5a85ed3dd930c9f","crop":{"left":0,"bottom":132.2061,"width":305.62185050000096,"height":161.8666}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D3","booklet":"CD4","question_number":58,"language":null,"source_page":24,"source_sha256":"6b3c1a2377905316dc8048bff088be7d2902bceef44460a642fcdcf4810e87b5"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D3', source_number = 58, subject_area = 'CIENCIAS_HUMANAS', statement = 'B fragilidade do ecossistema. Quase 42% do rebanho brasileiro está nos estados do Acre, C indiferença dos cidadãos. Amapá, Amazonas, Mato Grosso, Pará, Rondônia, Roraima, D negligência dos magistrados. Tocantins e Maranhão, que formam a chamada Amazônia Legal. E redução do emprego. Segundo dados do IBGE, são 89 milhões de cabeças de gado na região. E o preço é pago pela floresta. De acordo com um levantamento da plataforma Mapbiomas, entre 1985 e 2019 o Brasil transformou 67,8 milhões de hectares de florestas em pastagens. Disponível em: https://istoe.com.br. Acesso em: 22 out. 2021 (adaptado). O processo econômico descrito traz a seguinte consequência ambiental para a região afetada:', options = '["Elevação do lençol freático.","Redução das médias térmicas.","Ampliação da fertilidade pedológica.","Intensificação das precipitações frontais.","Diminuição da evapotranspiração vegetal."]'::jsonb, correct_answer = '"Diminuição da evapotranspiração vegetal."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"a4a1012f507151c30174f7b33704e768312aac1f96d30353fff62f11e819f6ce","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"bf77fe851c06f49d7f021e6c62e7a24b68d977a249e38255c3388314c0e8292d","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":58,"language":null,"page":24,"storagePath":"2025-D3-CD4/question-58-COMMON/statement-page-24.png","sha256":"94e84ccfa6ee78cc9f0e6