  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '94e84ccfa6ee78cc9f0e6639f0600fb49f2409fa2d433f97b5a85ed3dd930c9f', 'STATEMENT_CROP', 24, '2025-D3-CD4/question-58-COMMON/statement-page-24.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"94e84ccfa6ee78cc9f0e6639f0600fb49f2409fa2d433f97b5a85ed3dd930c9f","crop":{"left":0,"bottom":132.2061,"width":305.62185050000096,"height":161.8666},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'ef4362c20ff953ebef8f4d66aa64bedf8a0d755db19f948382bc2d010fb908bb' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 92, 'CIENCIAS_NATUREZA', 'Em 2006, o Prêmio Nobel de medicina ou fisiologia foi dado pela descrição do mecanismo de interferência de RNA, ou simplesmente RNAi. O mecanismo RNAi é um processo biológico no qual pequenas moléculas de RNA interferem na expressão gênica, tipicamente pela destruição do RNA mensageiro de um gene específico no citoplasma. ESTEVES, B. Interferência de RNA dá prêmio a norte-americanos . Disponível em: http://cienciahoje.uol.br. Acesso em: 13 jul. 2015 (adaptado). Nesse mecanismo, a regulação da expressão gênica ocorre pela inibição da', '["síntese do RNA mensageiro.","saída do RNA mensageiro do núcleo.","tradução do RNA mensageiro em proteína.","síntese do ribossomo pelo RNA mensageiro.","captura de aminoácidos pelo RNA mensageiro."]'::jsonb, '"tradução do RNA mensageiro em proteína."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"ef4362c20ff953ebef8f4d66aa64bedf8a0d755db19f948382bc2d010fb908bb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"cfc9f6f3be8d32c87e3150d88b8cefba9e66022492c415beac41a43d354f0ad8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":92,"language":null,"page":2,"storagePath":"2025-D4-CD5/question-92-COMMON/statement-page-2.png","sha256":"8bd29f185bbc3cb097f207f5d6a438f696d707292c7124802662a5131a4e64ea","crop":{"left":0,"bottom":130.5695,"width":289.1142999999999,"height":101.4246}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":92,"language":null,"source_page":2,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 92, subject_area = 'CIENCIAS_NATUREZA', statement = 'Em 2006, o Prêmio Nobel de medicina ou fisiologia foi dado pela descrição do mecanismo de interferência de RNA, ou simplesmente RNAi. O mecanismo RNAi é um processo biológico no qual pequenas moléculas de RNA interferem na expressão gênica, tipicamente pela destruição do RNA mensageiro de um gene específico no citoplasma. ESTEVES, B. Interferência de RNA dá prêmio a norte-americanos . Disponível em: http://cienciahoje.uol.br. Acesso em: 13 jul. 2015 (adaptado). Nesse mecanismo, a regulação da expressão gênica ocorre pela inibição da', options = '["síntese do RNA mensageiro.","saída do RNA mensageiro do núcleo.","tradução do RNA mensageiro em proteína.","síntese do ribossomo pelo RNA mensageiro.","captura de aminoácidos pelo RNA mensageiro."]'::jsonb, correct_answer = '"tradução do RNA mensageiro em proteína."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"ef4362c20ff953ebef8f4d66aa64bedf8a0d755db19f948382bc2d010fb908bb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"cfc9f6f3be8d32c87e3150d88b8cefba9e66022492c415beac41a43d354f0ad8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":92,"language":null,"page":2,"storagePath":"2025-D4-CD5/question-92-COMMON/statement-page-2.png","sha256":"8bd29f185bbc3cb097f207f5d6a438f696d707292c7124802662a5131a4e64ea","crop":{"left":0,"bottom":130.5695,"width":289.1142999999999,"height":101.4246}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":92,"language":null,"source_page":2,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
