  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '90ad31a501e86aca19a0be0093633a4b774f7c0be4314cbe0f603978b857a12e' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 93, 'CIENCIAS_NATUREZA', 'Uma pessoa pretende avaliar qual é a potência real de uma placa fotovoltaica nas condições operacionais de instalação. Ela constata que a máxima temperatura atingida pela placa é de 65 ° ° C. O manual de instruções desse modelo de placa informa que, a 25 ° ° C, sua potência nominal é de 250 W. Já a potência real muda com a variação da temperatura da placa, a uma taxa de − 0,4% da potência nominal a cada grau Celsius. A menor potência real gerada, em watt, é', '["230 W.","210 W.","190 W.","150 W.","100 W."]'::jsonb, '"210 W."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"90ad31a501e86aca19a0be0093633a4b774f7c0be4314cbe0f603978b857a12e","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"0d49c0c13501dac386fb257542c5820d0b166a5302d52765377170c0d4d05aa0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":93,"language":null,"page":3,"storagePath":"2025-D4-CD5/question-93-COMMON/statement-page-3.png","sha256":"63ec4a41ec9abe5c87e9cce3480aa6e917b390d8d4522b158667281f58790cf6","crop":{"left":0,"bottom":638.908,"width":276.56794999999977,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":93,"language":null,"source_page":3,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 93, subject_area = 'CIENCIAS_NATUREZA', statement = 'Uma pessoa pretende avaliar qual é a potência real de uma placa fotovoltaica nas condições operacionais de instalação. Ela constata que a máxima temperatura atingida pela placa é de 65 ° ° C. O manual de instruções desse modelo de placa informa que, a 25 ° ° C, sua potência nominal é de 250 W. Já a potência real muda com a variação da temperatura da placa, a uma taxa de − 0,4% da potência nominal a cada grau Celsius. A menor potência real gerada, em watt, é', options = '["230 W.","210 W.","190 W.","150 W.","100 W."]'::jsonb, correct_answer = '"210 W."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"90ad31a501e86aca19a0be0093633a4b774f7c0be4314cbe0f603978b857a12e","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"0d49c0c13501dac386fb257542c5820d0b166a5302d52765377170c0d4d05aa0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":93,"language":null,"page":3,"storagePath":"2025-D4-CD5/question-93-COMMON/statement-page-3.png","sha256":"63ec4a41ec9abe5c87e9cce3480aa6e917b390d8d4522b158667281f58790cf6","crop":{"left":0,"bottom":638.908,"width":276.56794999999977,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":93,"language":null,"source_page":3,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
