  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '63ec4a41ec9abe5c87e9cce3480aa6e917b390d8d4522b158667281f58790cf6', 'STATEMENT_CROP', 3, '2025-D4-CD5/question-93-COMMON/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"63ec4a41ec9abe5c87e9cce3480aa6e917b390d8d4522b158667281f58790cf6","crop":{"left":0,"bottom":638.908,"width":276.56794999999977,"height":102.84199999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e91cdf81b0e5c3c6a565bd9f282c67746f04975a68cc2b9236d5d4756fd6a9d3' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 94, 'CIENCIAS_NATUREZA', 'Há um grande esforço científico no desenvolvimento de novos processos para o aproveitamento de resíduos lignocelulósicos, como o bagaço de cana-de-açúcar, para produção de etanol de segunda geração (2G). Apesar de já existirem tecnologias disponíveis, a maioria apresenta limitações técnicas ou econômicas. Nesse sentido, um dos principais desafios que envolvem a produção de etanol celulósico é disponibilizar monossacarídeos fermentáveis das moléculas poliméricas, conforme a ilustração. SANTOS, F. A. et al. Potencial da palha de cana-de-açúcar para produção de etanol. Química Nova , n. 5, 2012 (adaptado). Um pesquisador, para tentar otimizar a produção, poderia acrescentar ao processo de hidrólise enzimas extraídas de', '["células entéricas de gaviões.","suco pancreático de humanos.","bactérias do rúmen de bovinos.","glândulas salivares de roedores.","macerado do estômago de macacos."]'::jsonb, '"bactérias do rúmen de bovinos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"e91cdf81b0e5c3c6a565bd9f282c67746f04975a68cc2b9236d5d4756fd6a9d3","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"730a8effba876119ea106379df8bd3161b3430044dbce61115ca168ce98a94e6","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":94,"languag