  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '35390f390213c614d1c37976674bc271f419b0d3b4c6d56b8927bf03de69a7d3', 'STATEMENT_CROP', 3, '2025-D4-CD5/question-94-COMMON/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"35390f390213c614d1c37976674bc271f419b0d3b4c6d56b8927bf03de69a7d3","crop":{"left":0,"bottom":351.053,"width":276.56794999999977,"height":226.31590000000006},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '574d14ad67f0d0c76b247a448cff854acfa55cccbcc6efce4cadda9dfe3eee0a' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 95, 'CIENCIAS_NATUREZA', 'A industrialização, o crescimento populacional e a demanda por mais alimentos, bem como o aumento da frota veicular, entre outros, geram resíduos poluentes classificados como primários ou secundários. Os primários são aqueles lançados diretamente no ar, e muitos deles reagem com alguns componentes existentes na atmosfera (oxigênio, vapor de água, entre outros) originando os poluentes secundários. Disponível em: https://essentiaeditora.iff.edu.br. Acesso em: 9 dez. 2021 (adaptado). Qual poluente primário, em contato com o ar, origina um poluente secundário altamente corrosivo?', '["Metano.","Clorofluorcarbono.","Dióxido de enxofre.","Dióxido de carbono.","Monóxido de carbono."]'::jsonb, '"Dióxido de enxofre."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"574d14ad67f0d0c76b247a448cff854acfa55cccbcc6efce4cadda9dfe3eee0a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"8be795a379fc8af923817e1b9350fabb89bad250bfc8297e03b015e3e002fe6a","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":95,"language":null,"page":3,"storagePath":"2025-D4-CD5/question-95-COMMON/statement-page-3.png","sha256":"9b2d2ab3a684f0d2c5403322f1da770f83db3fb53403f470d7e90abb5ee3ce27","crop":{"left":0,"bottom":177.2372,"width":276.56794999999977,"height":115.27329999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":95,"language":null,"source_page":3,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 95, subject_area = 'CIENCIAS_NATUREZA', statement = 'A industrialização, o crescimento populacional e a demanda por mais alimentos, bem como o aumento da frota veicular, entre outros, geram resíduos poluentes classificados como primários ou secundários. Os primários são aqueles lançados diretamente no ar, e muitos deles reagem com alguns componentes existentes na atmosfera (oxigênio, vapor de água, entre outros) originando os poluentes secundários. Disponível em: https://essentiaeditora.iff.edu.br. Acesso em: 9 dez. 2021 (adaptado). Qual poluente primário, em contato com o ar, origina um poluente secundário altamente corrosivo?', options = '["Metano.","Clorofluorcarbono.","Dióxido de enxofre.","Dióxido de carbono.","Monóxido de carbono."]'::jsonb, correct_answer = '"Dióxido de enxofre."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"574d14ad67f0d0c76b247a448cff854acfa55cccbcc6efce4cadda9dfe3eee0a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"8be795a379fc8af923817e1b9350fabb89bad250bfc8297e03b015e3e002fe6a","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":95,"language":null,"page":3,"storagePath":"2025-D4-CD5/question-95-COMMON/statement-page-3.png","sha256":"9b2d2ab3a684f0d2c5403322f1da770f83db3fb53403f470d7e90abb5ee3ce27","crop":{"left":0,"bottom":177.2372,"width":276.56794999999977,"height":115.27329999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":95,"language":null,"source_page":3,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
