  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '9b2d2ab3a684f0d2c5403322f1da770f83db3fb53403f470d7e90abb5ee3ce27', 'STATEMENT_CROP', 3, '2025-D4-CD5/question-95-COMMON/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"9b2d2ab3a684f0d2c5403322f1da770f83db3fb53403f470d7e90abb5ee3ce27","crop":{"left":0,"bottom":177.2372,"width":276.56794999999977,"height":115.27329999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '183f1e99c3a14a08085a916f67900e04641778b23171d195f7c450f725e30c10' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 96, 'CIENCIAS_NATUREZA', 'As temperaturas nas regiões urbanas e rurais de uma mesma cidade podem diferir significativamente. Isso ocorre, principalmente, pela diferença entre os níveis de irradiação térmica das duas regiões. Considerando que o nível de irradiação térmica nas regiões urbanas pode até mesmo superar o valor percentual de 95%, uma opção viável para minimizar esse processo e melhorar o conforto térmico no interior das residências consiste em pintar o telhado com tinta branca. Essa opção é viável porque reduz a', '["capacidade térmica do material.","convecção térmica abaixo do telhado.","reflexão da radiação solar pelo telhado.","absorção de radiação solar pelo telhado.","condução térmica através da superfície do telhado."]'::jsonb, '"absorção de radiação solar pelo telhado."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"183f1e99c3a14a08085a916f67900e04641778b23171d195f7c450f725e30c10","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"664836fcc071b1d3ce82c30fa1ae209b0fb666356b90d6c1660e15606402e8de","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":96,"language":null,"page":4,"storagePath":"2025-D4-CD5/question-96-COMMON/statement-page-4.png","sha256":"6d2384169e87663c8ba9592ec05645749be534aa631de5797f6f18a4b9ca02c2","crop":{"left":0,"bottom":644.668,"width":295.75335499999994,"height":97.082}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":96,"language":null,"source_page":4,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 96, subject_area = 'CIENCIAS_NATUREZA', statement = 'As temperaturas nas regiões urbanas e rurais de uma mesma cidade podem diferir significativamente. Isso ocorre, principalmente, pela diferença entre os níveis de irradiação térmica das duas regiões. Considerando que o nível de irradiação térmica nas regiões urbanas pode até mesmo superar o valor percentual de 95%, uma opção viável para minimizar esse processo e melhorar o conforto térmico no interior das residências consiste em pintar o telhado com tinta branca. Essa opção é viável porque reduz a', options = '["capacidade térmica do material.","convecção térmica abaixo do telhado.","reflexão da radiação solar pelo telhado.","absorção de radiação solar pelo telhado.","condução térmica através da superfície do telhado."]'::jsonb, correct_answer = '"absorção de radiação solar pelo telhado."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"183f1e99c3a14a08085a916f67900e04641778b23171d195f7c450f725e30c10","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"664836fcc071b1d3ce82c30fa1ae209b0fb666356b90d6c1660e15606402e8de","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":96,"language":null,"page":4,"storagePath":"2025-D4-CD5/question-96-COMMON/statement-page-4.png","sha256":"6d2384169e87663c8ba9592ec05645749be534aa631de5797f6f18a4b9ca02c2","crop":{"left":0,"bottom":644.668,"width":295.75335499999994,"height":97.082}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_