  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e7cfa16070147050028104101c451757dd1afa0f8cd5273cc8518d0bc15e95d8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 98, 'CIENCIAS_NATUREZA', 'Energia solar fotovoltaica A energia solar fotovoltaica é renovável e limpa, associada à radiação emitida pelo Sol para gerar eletricidade. Baseia-se no denominado efeito fotoelétrico, por meio do qual determinados materiais são capazes de absorver fótons e liberar elétrons, gerando corrente elétrica. Para isso, utilizam-se placas com dispositivos semicondutores denominados células solares, ou fotovoltaicas, que podem ser feitos, por exemplo, de silício monocristalino, policristalino ou amorfo. Disponível em: www.ecycle.com.br. Acesso em: 2 dez. 2021 (adaptado). O principal impacto ambiental gerado pelo descarte desses dispositivos está associado ao(à)', '["contaminação do solo.","emissão de radioatividade.","emissão de radiação ultravioleta.","aumento da temperatura do solo.","produção de gases de efeito estufa."]'::jsonb, '"contaminação do solo."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"e7cfa16070147050028104101c451757dd1afa0f8cd5273cc8518d0bc15e95d8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"8e29645ff63d75d2dc18b950d3196ba8755464bbe4f7d11bd7043148e62a234c","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":98,"language":null,"page":4,"storagePath":"2025-D4-CD5/question-98-COMMON/statement-page-4.png","sha256":"d1b710a756fad8ef9b47fe3b250bf3212075238746618cda1b042ef995af2a3f","crop":{"left":0,"bottom":314.2531,"width":295.75335499999994,"height":123.67329999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":98,"language":null,"source_page":4,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
