  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'd1b710a756fad8ef9b47fe3b250bf3212075238746618cda1b042ef995af2a3f', 'STATEMENT_CROP', 4, '2025-D4-CD5/question-98-COMMON/statement-page-4.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"d1b710a756fad8ef9b47fe3b250bf3212075238746618cda1b042ef995af2a3f","crop":{"left":0,"bottom":314.2531,"width":295.75335499999994,"height":123.67329999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '93d9d9d76d596e281daee46a447fc8fd4ea0a8903e7a53ce167e1cc54f4332cd' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 99, 'CIENCIAS_NATUREZA', 'Nova vacina contra HIV utiliza DNA e proteínas recombinantes Uma equipe de pesquisadores desenvolveu uma nova vacina que consiste em DNA e proteínas recombinantes. Associando a biologia molecular e a bioinformática, rastrearam o genoma viral e obtiveram uma proteína que, quando ligada a anticorpos, resulta na destruição do vírus e das células infectadas por ele. Nos testes, a vacina se mostrou capaz de induzir anticorpos contra o HIV. Essa técnica de produção de vacinas é chamada de “vacinologia reversa”. Disponível em: https://sciam.com.br. Acesso em: 22 nov. 2021 (adaptado). Essa tecnologia pode ser vantajosa em relação aos métodos tradicionais de preparo de vacinas porque', '["necessita do agente causador da doença vivo e incapaz de fazer o ciclo infeccioso.","elimina a necessidade de os agentes infecciosos serem cultivados e modificados.","utiliza microrganismos modificados que são incapazes de causar a doença.","extingue o uso de partes de proteínas e açúcares dos agentes infecciosos.","aproveita uma toxina inativada do agente infeccioso em sua fabricação."]'::jsonb, '"elimina a necessidade de os agentes infecciosos serem cultivados e modificados."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"93d9d9d76d596e281daee46a447fc8fd4ea0a8903e7a53ce167e1cc54f4332cd","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"4dcd992fa7e7562824d475d1c25a1137516948d11f02a81570a73481cdd77d5b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":99,"language":null,"page":4,"storagePath":"2025-D4-CD5/question-99-COMMON/statement-page-4.png","sha256":"dbf02129fcf35eec4ad5fc3e38b6cd56111adf9a144dcf7d13cfb378ec038e4f","crop":{"left":0,"bottom":130.472,"width":295.75335499999994,"height":127.47329999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":99,"language":null,"source_page":4,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 99, subject_area = 'CIENCIAS_NATUREZA', statement = 'Nova vacina contra HIV utiliza DNA e proteínas recombinantes Uma equipe de pesquisadores desenvolveu uma nova vacina que consiste em DNA e proteínas recombinantes. Associando a biologia molecular e a bioinformática, rastrearam o genoma viral e obtiveram uma proteína que, quando ligada a anticorpos, resulta na destruição do vírus e das células infectadas por ele. Nos testes, a vacina se mostrou capaz de induzir anticorpos contra o HIV. Essa técnica de produção de vacinas é chamada de “vacinologia reversa”. Disponível em: https://sciam.com.br. Acesso em: 22 nov. 2021 (adaptado). Essa tecnologia pode ser vantajosa em relação aos métodos tradicionais de preparo de vacinas porque', options = '["necessita do agente causador da doença vivo e incapaz de fazer o ciclo infeccioso.","elimina a necessidade de os agentes infecciosos serem cultivados e modificados.","utiliza microrganismos modificados que são incapazes de causar a doença.","extingue o uso de partes de proteínas e açúcares dos agentes infecciosos.","aproveita uma toxina inativada do agente infeccioso em sua fabricação."]'::jsonb, correct_answer = '"elimina a necessidade de os agentes infecciosos serem cultivados e modificados."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"93d9d9d76d596e281daee46a447fc8fd4ea0a8903e7a53ce167e1cc54f4332cd","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"4dcd992fa7e7562824d475d1c25a1137516948d1