  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'f957dc5ad346e501fdcb442f0ddec3bf1d056e9f90b597f439b052528726fa3c', 'STATEMENT_CROP', 7, '2025-D4-CD5/question-113-COMMON/statement-page-7.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"f957dc5ad346e501fdcb442f0ddec3bf1d056e9f90b597f439b052528726fa3c","crop":{"left":244.41159969999987,"bottom":191.7742,"width":322.5159003000001,"height":164.2593},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0340acc9f4b9c26a8f1740a7356595600a467745fa5117409871ec82b1859d21' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 114, 'CIENCIAS_NATUREZA', 'O estudo da relação entre a estrutura e a atividade biológica de substâncias é de fundamental importância no desenvolvimento de drogas para o combate a doenças. Pesquisadores avaliaram o potencial antiviral de algumas moléculas frente ao vírus SARS-CoV-2, considerando a capacidade de inibição das enzimas responsáveis pela síntese de proteínas no vírus. A interação entre o composto e o sítio ativo da enzima depende de fatores eletrônicos e estéricos, permitindo estabelecer uma relação entre a estrutura e a atividade antiviral. A maior atividade foi correlacionada a substituintes pouco volumosos e moderadamente eletronegativos presentes no anel aromático da molécula do antiviral. Nesse estudo, foram modelados os cinco compostos hipotéticos apresentados a seguir. KNELLER, D. W. et al. Structural, Electronic and Electrostatic Determinants for lnhibitor Binding to Subsites S1 and S2 in SARS-CoV-2 Main Protease . Disponível em: https://doi.org/10.1021/acs.jmedchem.1c01475. Acesso em: 2 dez. 2021 (adaptado). Dentre os compostos modelados, qual deve apresentar a maior atividade antiviral?', '["I","II","III","IV","V"]'::jsonb, '"II"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"0340acc9f4b9c26a8f1740a7356595600a467745fa5117409871ec82b1859d21","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"03f7ee8cacf250989e673d306351885134a5052deb4b511e06b89ed7912ca83f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":114,"language":null,"page":8,"storagePath":"2025-D4-CD5/question-114-COMMON/statement-page-8.png","sha256":"159ecd6561455e52ad8ab5a25450a5ec336582eb1251d678ba8cb153678772a9","crop":{"left":0,"bottom":136.5904,"width":271.16419999999994,"height":605.1596}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":114,"language":null,"source_page":8,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 114, subject_area = 'CIENCIAS_NATUREZA', statement = 'O estudo da relação entre a estrutura e a atividade biológica de substâncias é de fundamental importância no desenvolvimento de drogas para o combate a doenças. Pesquisadores avaliaram o potencial antiviral de algumas moléculas frente ao vírus SARS-CoV-2, considerando a capacidade de inibição das enzimas responsáveis pela síntese de proteínas no vírus. A interação entre o composto e o sítio ativo da enzima depende de fatores eletrônicos e estéricos, permitindo estabelecer uma relação entre a estrutura e a atividade antiviral. A maior atividade foi correlacionada a substituintes pouco volumosos e moderadamente eletronegativos presentes no anel aromático da molécula do antiviral. Nesse estudo, foram modelados os cinco compostos hipotéticos apresentados a seguir. KNELLER, D. W. et al. Structural, Electronic and Electrostatic Determinants for lnhibitor Binding to Subsites S1 and S2 in SARS-CoV-2 Main Protease . Disponível em: https://doi.org/10.1021/acs.jmedchem.1c01475. Acesso em: 2 dez. 2021 (adaptado). Dentre os compostos modelados, qual deve apresentar a maior atividade antiviral?', options = '["I","II","III","IV","V"]'::jsonb, correct_answer = '"II"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"0340acc9f4b9c26a8f1740a7356595600a467745fa5117409871ec82b1859d21","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"03f7ee8cacf250989e673d306351885134a5052deb4b511e06b89ed7912ca83f","statement_assets