  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 119, subject_area = 'CIENCIAS_NATUREZA', statement = 'Um empresário sul-africano definiu o Hyperloop como a única opção para a viagem ultrarrápida. O Hyperloop é uma espécie de trem que se locomove sem atrito, levitando magneticamente sobre trilhos, em túneis com pressão reduzida. Durante o percurso, o ar vai sendo extraído do túnel, e a diferença de pressão gerada entre a parte traseira e a frontal faz com que a cápsula com passageiros seja colocada em movimento e siga deslocando-se praticamente sem atrito e sem resistência do ar. Em vez de trilhos convencionais, ela é levitada e guiada por campos eletromagnéticos. Disponível em: https://veja.abril.com.br. Acesso em: 21 nov. 2021 (adaptado). O Hyperloop se desloca de acordo com o mesmo princípio físico que explica o movimento de um', options = '["foguete subindo enquanto ejeta gases para baixo.","líquido sendo sugado pelo canudo do copo até a boca.","elétron abandonado entre as placas de um capacitor plano.","próton ganhando velocidade dentro de um acelerador de partículas.","submarino emergindo conforme a água é extraída de seus tubos de lastro."]'::jsonb, correct_answer = '"líquido sendo sugado pelo canudo do copo até a boca."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"96f6e83f77252eaa584a3dba4e747a4785bc18ceeceebf459ec5171efb997280","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"5ff9de4d7ff13d83f7fa3b728dc6c7633fa958a7255a2a7801c45eb13e86a0c7","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":119,"language":null,"page":10,"storagePath":"2025-D4-CD5/question-119-COMMON/statement-page-10.png","sha256":"c78457679c238424e9ed53bf445b38794e6b718bb56ac17103d168dafd662edb","crop":{"left":0,"bottom":614.4767,"width":284.1420499999998,"height":127.27329999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":119,"language":null,"source_page":10,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
