  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'c78457679c238424e9ed53bf445b38794e6b718bb56ac17103d168dafd662edb', 'STATEMENT_CROP', 10, '2025-D4-CD5/question-119-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"c78457679c238424e9ed53bf445b38794e6b718bb56ac17103d168dafd662edb","crop":{"left":0,"bottom":614.4767,"width":284.1420499999998,"height":127.27329999999995},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '2bac79b412a1cccba0125d638ff9d3851bc4eb06ede1cbb3eb9d944a8848aeca' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 120, 'CIENCIAS_NATUREZA', 'A seleção natural pode alterar a distribuição da frequência de caracteres herdáveis de várias maneiras. Essa alteração acontece a partir dos fenótipos e, consequentemente, genótipos, que devem ser favorecidos em uma dada população. Entre os tipos de seleção, há um tipo cujos critérios ambientais levam à redução dos organismos que apresentam os fenótipos extremos, preservando os fenótipos intermediários em casos de herança por dominância completa. O efeito dessa seleção nessa população implicará o(a)', '["permanência de fenótipos recessivos.","escolha de fenótipos aleatoriamente.","predominância de genótipos heterozigotos.","aumento de indivíduos com genótipos homozigotos dominantes.","crescimento da frequência de genótipos homozigotos recessivos."]'::jsonb, '"predominância de genótipos heterozigotos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"2bac79b412a1cccba0125d638ff9d3851bc4eb06ede1cbb3eb9d944a8848aeca","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"aa1799736822ee69aabdd482aa6f9ffe41241b4b55e6fdb921a090da3b0c0572","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":120,"language":null,"page":10,"storagePath":"2025-D4-CD5/question-120-COMMON/statement-page-10.png","sha256":"fb87a04ae582c004cf5636598baf818c8d59a4c6d2f1a5b39682f51101041c97","crop":{"left":0,"bottom":450.0923,"width":284.1420499999998,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":120,"language":null,"source_page":10,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 120, subject_area = 'CIENCIAS_NATUREZA', statement = 'A seleção natural pode alterar a distribuição da frequência de caracteres herdáveis de várias maneiras. Essa alteração acontece a partir dos fenótipos e, consequentemente, genótipos, que devem ser favorecidos em uma dada população. Entre os tipos de seleção, há um tipo cujos critérios ambientais levam à redução dos organismos que apresentam os fenótipos extremos, preservando os fenótipos intermediários em casos de herança por dominância completa. O efeito dessa seleção nessa população implicará o(a)', options = '["permanência de fenótipos recessivos.","escolha de fenótipos aleatoriamente.","predominância de genótipos heterozigotos.","aumento de indivíduos com genótipos homozigotos dominantes.","crescimento da frequência de genótipos homozigotos recessivos."]'::jsonb, correct_answer = '"predominância de genótipos heterozigotos."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"2bac79b412a1cccba0125d638ff9d3851bc4eb06ede1cbb3eb9d944a8848aeca","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"aa1799736822ee69aabdd482aa6f9ffe41241b4b55e6fdb921a090da3b0c0572","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":120,"language":null,"page":10,"storagePath":"2025-D4-CD5/question-120-COMMON/statement-page-10.png","sha256":"fb87a04ae582c004cf5636598baf818c8d59a4c6d2f1a5b39682f51101041c97","crop":{"left":0,"bottom":450.0923,"width":284.1420499999998,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":120,"language":null,"source_page":10,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
