  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'fb87a04ae582c004cf5636598baf818c8d59a4c6d2f1a5b39682f51101041c97', 'STATEMENT_CROP', 10, '2025-D4-CD5/question-120-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"fb87a04ae582c004cf5636598baf818c8d59a4c6d2f1a5b39682f51101041c97","crop":{"left":0,"bottom":450.0923,"width":284.1420499999998,"height":102.84199999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '92c15eab9f870a884b0fe701ebceafe37e9af45adeab64027e0adf5607542618' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 121, 'CIENCIAS_NATUREZA', 'Para a produção de insulina recombinante, é necessária a transformação do microrganismo com a inserção do gene da insulina. No processo de síntese da insulina, várias moléculas com função predefinida se orquestram para a produção da proteína completa e ativa. Erros nesse processo podem ocorrer, por exemplo, um RNAt que deveria estar ligado ao aminoácido serina pode se ligar erroneamente ao aminoácido valina. No caso do erro descrito, na produção da insulina ocorrerá a incorporação da', '["serina, em resposta a qualquer códon do RNAm.","valina, em resposta a qualquer códon do RNAm.","valina, somente em resposta ao códon de serina do RNAm.","valina, em resposta aos códons de serina e valina do RNAm.","serina, em resposta aos códons de serina e valina do RNAm."]'::jsonb, '"valina, em resposta aos códons de serina e valina do RNAm."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"92c15eab9f870a884b0fe701ebceafe37e9af45adeab64027e0adf5607542618","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"b8420c20fd1e7b4b53e75ccbd78a54ad29393cf149197fbde51f6aaddc5702eb","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":10,"storagePath":"2025-D4-CD5/question-121-COMMON/statement-page-10.png","sha256":"543a707d46e74481cf85968b3aded2db12cadd0f22af0ec9aa228b339037f6ac","crop":{"left":0,"bottom":285.7112,"width":284.1420499999998,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":121,"language":null,"source_page":10,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 121, subject_area = 'CIENCIAS_NATUREZA', statement = 'Para a produção de insulina recombinante, é necessária a transformação do microrganismo com a inserção do gene da insulina. No processo de síntese da insulina, várias moléculas com função predefinida se orquestram para a produção da proteína completa e ativa. Erros nesse processo podem ocorrer, por exemplo, um RNAt que deveria estar ligado ao aminoácido serina pode se ligar erroneamente ao aminoácido valina. No caso do erro descrito, na produção da insulina ocorrerá a incorporação da', options = '["serina, em resposta a qualquer códon do RNAm.","valina, em resposta a qualquer códon do RNAm.","valina, somente em resposta ao códon de serina do RNAm.","valina, em resposta aos códons de serina e valina do RNAm.","serina, em resposta aos códons de serina e valina do RNAm."]'::jsonb, correct_answer = '"valina, em resposta aos códons de serina e valina do RNAm."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"92c15eab9f870a884b0fe701ebceafe37e9af45adeab64027e0adf5607542618","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"b8420c20fd1e7b4b53e75ccbd78a54ad29393cf149197fbde51f6aaddc5702eb","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":10,"storagePath":"2025-D4-CD5/question-121-COMMON/statement-page-10.png","sha256":"543a707d46e74481cf85968b3aded2db12cadd0f22af0ec9aa228b339037f6ac","crop":{"left":0,"bottom":285.7112,"width":284.1420499999998,"height":102.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":121,"language":null,"source_page":10,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
