  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2025 and exam = 'ENEM' and application = 'REGULAR' and day = 'D4' and booklet = 'CD5' and question_number = 121 and coalesce(language, '') = '' limit 1;
  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '543a707d46e74481cf85968b3aded2db12cadd0f22af0ec9aa228b339037f6ac', 'STATEMENT_CROP', 10, '2025-D4-CD5/question-121-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"543a707d46e74481cf85968b3aded2db12cadd0f22af0ec9aa228b339037f6ac","crop":{"left":0,"bottom":285.7112,"width":284.1420499999998,"height":102.84199999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd02d0126f58b634991cfed8fceb3eb6fa746d3eb59c9ed6e06816e8f14bbfe06' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 122, 'CIENCIAS_NATUREZA', 'Um dos procedimentos mais rotineiros em análises químicas é a extração por solvente de materiais sólidos ou líquidos. No entanto, em pesquisas prospectivas, nas quais se pretende investigar a natureza química de determinado material, procede-se à extração por solventes em sequência, em ordem crescente de polaridade, conhecida como ordem eluotrópica. Em um processo de extração, foram utilizados os seguintes solventes: A sequência eluotrópica dos solventes utilizados é', '["água, etanol, metanol, n-hexano e clorofórmio.","etanol, metanol, água, clorofórmio e n-hexano.","clorofórmio, n-hexano, metanol, etanol e água.","n-hexano, clorofórmio, etanol, metanol e água.","n-hexano, metanol, etanol, água e clorofórmio."]'::jsonb, '"n-hexano, clorofórmio, etanol, metanol e água."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"d02d0126f58b634991cfed8fceb3eb6fa746d3eb59c9ed6e06816e8f14bbfe06","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"c248008ee995f58d1c6e25b0704b3d77907e45eca1c1b0a2df4e18e0a8faae2f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":122,"language":null,"page":11,"storagePath":"2025-D4-CD5/question-122-COMMON/statement-page-11.png","sha256":"b2e86ac37de3b413cf16249f8800ac57ca88278f7ff548a5c7802e872a4bcfe3","crop":{"left":0,"bottom":558.2141,"width":261.35445,"height":183.53589999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":122,"language":null,"source_page":11,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 122, subject_area = 'CIENCIAS_NATUREZA', statement = 'Um dos procedimentos mais rotineiros em análises químicas é a extração por solvente de materiais sólidos ou líquidos. No entanto, em pesquisas prospectivas, nas quais se pretende investigar a natureza química de determinado material, procede-se à extração por solventes em sequência, em ordem crescente de polaridade, conhecida como ordem eluotrópica. Em um processo de extração, foram utilizados os seguintes solventes: A sequência eluotrópica dos solventes utilizados é', options = '["água, etanol, metanol, n-hexano e clorofórmio.","etanol, metanol, água, clorofórmio e n-hexano.","clorofórmio, n-hexano, metanol, etanol e água.","n-hexano, clorofórmio, etanol, metanol e água.","n-hexano, metanol, etanol, água e clorofórmio."]'::jsonb, correct_answer = '"n-hexano, clorofórmio, etanol, metanol e água."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"d02d0126f58b634991cfed8fceb3eb6fa746d3eb59c9ed6e06816e8f14bbfe06","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"c248008ee995f58d1c6e25b0704b3d77907e45eca1c1b0a2df4e18e0a8faae2f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":122,"language":null,"page":11,"storagePath":"2025-D4-CD5/question-122-COMMON/statement-page-11.png","sha256":"b2e86ac37de3b413cf16249f8800ac57ca88278f7ff548a5c7802e872a4bcfe3","crop":{"left":0,"bottom":558.2141,"width":261.35445,"height":183.53589999999997}}],"enem_area":"CI