  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd79ada4ddf9a04bf462e8f6dd0450e80d3f73eb0247afc8b05063fa950205635' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 125, 'CIENCIAS_NATUREZA', 'O tipo predominante de excreta que um grupo animal produz está relacionado com o ambiente onde ele vive. Nesse contexto, os animais podem ser classificados em amoniotélicos, ureotélicos e uricotélicos, de acordo com o principal resíduo nitrogenado que produzem. Qual é o fator ambiental que determina o tipo de resíduo a ser eliminado?', '["Temperatura.","Fonte energética.","Quantidade de oxigênio.","Abundância de alimento.","Disponibilidade de água."]'::jsonb, '"Disponibilidade de água."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"d79ada4ddf9a04bf462e8f6dd0450e80d3f73eb0247afc8b05063fa950205635","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"50c1c9130f4b4b2c6ce9b3389a9b2612a23545ae4b942c046aa6c4abff4c5533","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":125,"language":null,"page":12,"storagePath":"2025-D4-CD5/question-125-COMMON/statement-page-12.png","sha256":"33091277ea3bbb28bbba685dfaffbb68f427999e7daed437c2cf78d7b30abb3b","crop":{"left":0,"bottom":377.3376,"width":246.21800000000002,"height":90.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":125,"language":null,"source_page":12,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 125, subject_area = 'CIENCIAS_NATUREZA', statement = 'O tipo predominante de excreta que um grupo animal produz está relacionado com o ambiente onde ele vive. Nesse contexto, os animais podem ser classificados em amoniotélicos, ureotélicos e uricotélicos, de acordo com o principal resíduo nitrogenado que produzem. Qual é o fator ambiental que determina o tipo de resíduo a ser eliminado?', options = '["Temperatura.","Fonte energética.","Quantidade de oxigênio.","Abundância de alimento.","Disponibilidade de água."]'::jsonb, correct_answer = '"Disponibilidade de água."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"d79ada4ddf9a04bf462e8f6dd0450e80d3f73eb0247afc8b05063fa950205635","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"50c1c9130f4b4b2c6ce9b3389a9b2612a23545ae4b942c046aa6c4abff4c5533","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":125,"language":null,"page":12,"storagePath":"2025-D4-CD5/question-125-COMMON/statement-page-12.png","sha256":"33091277ea3bbb28bbba685dfaffbb68f427999e7daed437c2cf78d7b30abb3b","crop":{"left":0,"bottom":377.3376,"width":246.21800000000002,"height":90.84199999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":125,"language":