  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '33091277ea3bbb28bbba685dfaffbb68f427999e7daed437c2cf78d7b30abb3b', 'STATEMENT_CROP', 12, '2025-D4-CD5/question-125-COMMON/statement-page-12.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"33091277ea3bbb28bbba685dfaffbb68f427999e7daed437c2cf78d7b30abb3b","crop":{"left":0,"bottom":377.3376,"width":246.21800000000002,"height":90.84199999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'a393fc5bbb62d052bbd952b9ec70f49360380c9107364dcfa5307659bbf04ccc' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 126, 'CIENCIAS_NATUREZA', 'Alguns aparelhos do nosso cotidiano, como TVs e drones, são operados a distância por controle remoto. A diferença no sistema de controle desses aparelhos se dá em relação à radiação emitida, pois, nas TVs, o acionamento do controle remoto deve ser realizado a uma curta distância e o sistema receptor de sinal não pode estar obstruído. Por outro lado, nos drones, o sistema de controle funciona a distâncias relativamente grandes, da ordem de alguns quilômetros. O acionamento dos equipamentos citados corresponde à emissão de ondas, respectivamente, nas regiões', '["visível e raios X.","rádio e ultravioleta.","ultravioleta e visível.","infravermelho e rádio.","raios X e infravermelho."]'::jsonb, '"infravermelho e rádio."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"a393fc5bbb62d052bbd952b9ec70f49360380c9107364dcfa5307659bbf04ccc","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"510523832262a7c781a4028369ea2ddc7b428950412cf6ae10cc8bf830c3a6ae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":126,"language":null,"page":12,"storagePath":"2025-D4-CD5/question-126-COMMON/statement-page-12.png","sha256":"eb155ac409e575a06266ed12e7db94c102e488763452ea4c0c5b717a03cdc458","crop":{"left":0,"bottom":212.95649999999998,"width":246.21800000000002,"height":102.84200000000001}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":126,"language":null,"source_page":12,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 126, subject_area = 'CIENCIAS_NATUREZA', statement = 'Alguns aparelhos do nosso cotidiano, como TVs e drones, são operados a distância por controle remoto. A diferença no sistema de controle desses aparelhos se dá em relação à radiação emitida, pois, nas TVs, o acionamento do controle remoto deve ser realizado a uma curta distância e o sistema receptor de sinal não pode estar obstruído. Por outro lado, nos drones, o sistema de controle funciona a distâncias relativamente grandes, da ordem de alguns quilômetros. O acionamento dos equipamentos citados corresponde à emissão de ondas, respectivamente, nas regiões', options = '["visível e raios X.","rádio e ultravioleta.","ultravioleta e visível.","infravermelho e rádio.","raios X e infravermelho."]'::jsonb, correct_answer = '"infravermelho e rádio."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"a393fc5bbb62d052bbd952b9ec70f49360380c9107364dcfa5307659bbf04ccc","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"510523832262a7c781a4028369ea2ddc7b428950412cf6ae10cc8bf830c3a6ae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":126,"language":null,"page":12,"storagePath":"2025-D4-CD5/question-126-COMMON/statement-page-12.png","sha256":"eb155ac409e575a06266ed12e7db94c102e488763452ea4c0c5b717a03cdc458","crop":{"left":0,"bottom":212.95649999999998,"width":246.21800000000002,"height":102.84200000000001}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":126,"language":null,"source_page":12,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
