  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2025 and exam = 'ENEM' and application = 'REGULAR' and day = 'D4' and booklet = 'CD5' and question_number = 129 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'b2711f2aa491364e998a37969a4a20556ab563cd19f6e99049c225ce6cbbbf64' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 128, 'CIENCIAS_NATUREZA', 'Técnicas de amaciamento envolvendo procedimentos de natureza físico-química vêm sendo substituídas por métodos Carros elétricos põem fim ao longo reinado da rádio AM biotecnológicos. Um exemplo é a utilização de celulases, As montadoras de automóveis estão em uma corrida produzidas por fungos do gênero Trichoderma , para digestão rumo a um futuro eletrificado, e rádios AM estão ficando pelo enzimática de parte da celulose do algodão. caminho. O problema, dizem os especialistas, é que os motores TORTORA, G. J.; FUNKE, B. R.; CASE, C. L. Microbiologia . dos veículos elétricos geram frequências eletromagnéticas do Porto Alegre: Artmed, 2016 (adaptado). mesmo comprimento de onda que os sinais das rádios AM. Esse método biotecnológico é considerado ambientalmente “Você tem dois sinais que colidem um com o outro e se seguro porque cancelam”, disse o diretor de inovação de motores e tecnologia de uma fabricante de autopeças. A utiliza catalisador inorgânico. Disponível em: www1.folha.uol.com.br. Acesso em: 20 nov. 2018 (adaptado). B torna a celulose mais resistente. C ocorre em diferentes temperaturas. O problema mencionado refere-se a qual fenômeno ondulatório? D é usado em diferentes valores de pH. A Difração. E minimiza a produção de resíduos tóxicos. B Reflexão. C Refração.', '["utiliza catalisador inorgânico.","torna a celulose mais resistente.","ocorre em diferentes temperaturas.","é usado em diferentes valores de pH.","minimiza a produção de resíduos tóxicos."]'::jsonb, '"minimiza a produção de resíduos tóxicos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"b2711f2aa491364e998a37969a4a20556ab563cd19f6e99049c225ce6cbbbf64","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"b6f6d4f7e1ec390a07a27e193f9bd65d6947b5c4f4b6fe57d82edef200defaf8","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":128,"language":null,"source_page":13,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 128, subject_area = 'CIENCIAS_NATUREZA', statement = 'Técnicas de amaciamento envolvendo procedimentos de natureza físico-química vêm sendo substituídas por métodos Carros elétricos põem fim ao longo reinado da rádio AM biotecnológicos. Um exemplo é a utilização de celulases, As montadoras de automóveis estão em uma corrida produzidas por fungos do gênero Trichoderma , para digestão rumo a um futuro eletrificado, e rádios AM estão ficando pelo enzimática de parte da celulose do algodão. caminho. O problema, dizem os especialistas, é que os motores TORTORA, G. J.; FUNKE, B. R.; CASE, C. L. Microbiologia . dos veículos elétricos geram frequências eletromagnéticas do Porto Alegre: Artmed, 2016 (adaptado). mesmo comprimento de onda que os sinais das rádios AM. Esse método biotecnológico é considerado ambientalmente “Você tem dois sinais que colidem um com o outro e se seguro porque cancelam”, disse o diretor de inovação de motores e tecnologia de uma fabricante de autopeças. A utiliza catalisador inorgânico. Disponível em: www1.folha.uol.com.br. Acesso em: 20 nov. 2018 (adaptado). B torna a celulose mais resistente. C ocorre em diferentes temperaturas. O problema mencionado refere-se a qual fenômeno ondulatório? D é usado em diferentes valores de pH. A Difração. E minimiza a produção de resíduos tóxicos. B Reflexão. C Refração.', options = '["utiliza catalisador inorgânico.","torna a celulose mais resistente.","ocorre em diferentes temperaturas.","é usado em diferentes valores de pH.","minimiza a produção de resíduos tóxicos."]'::jsonb, correct_answer = '"minimiza a produção de resíduos tóxicos."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"b2711f2aa491364e998a37969a4a20556ab563cd19f6e99049c225ce6cbbbf64","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"b6f6d4f7e1ec390a07a27e193f9bd65d6947b5c4f4b6fe57d82edef200defaf8","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":128,"language":null,"source_page":13,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
