  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '6e572ff0c1b22748f68fdf81bef14c744d678b9d5be2dbd5ac8f3faeca0b5d74', 'STATEMENT_CROP', 14, '2025-D4-CD5/question-132-COMMON/statement-page-14.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"6e572ff0c1b22748f68fdf81bef14c744d678b9d5be2dbd5ac8f3faeca0b5d74","crop":{"left":0,"bottom":492.9009,"width":295.34574999999995,"height":248.84910000000002},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '3b05e5446f3f2b3674a071245d57f062baa7f8fd35760aefd38a3461baab114b' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 135, 'CIENCIAS_NATUREZA', 'Os satélites artificiais e as sondas para exploração espacial são algumas das grandes realizações humanas desenvolvidas no último século. Para coletar e armazenar informações ao longo de anos, esses equipamentos precisam de energia. Como forma de fornecer energia limpa ao satélite, são acoplados diversos painéis de células solares, que, em fotografias, muitas vezes são confundidos com “asas”. Um satélite geoestacionário precisa armazenar a energia obtida pelos seus painéis solares em suas baterias. Como forma de otimizar o processo de absorção da energia solar, o ideal é que a superfície dos painéis mantenha-se perpendicular aos raios solares incidentes. Para isso, foi adaptado um sistema que rotaciona os painéis solares com velocidade angular constante. Qual é a velocidade de rotação dos painéis em comparação à velocidade de rotação da Terra (R )? T', '["0,25 RT","0,5 RT","RT","2 RT","4 RT"]'::jsonb, '"RT"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"3b05e5446f3f2b3674a071245d57f062baa7f8fd35760aefd38a3461baab114b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"74d5968e813cc15e12407f148bc90a94f3d8e8285a4eb4aa595a2d71716663e8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":135,"language":null,"page":15,"storagePath":"2025-D4-CD5/question-135-COMMON/statement-page-15.png","sha256":"2325cbbd82c7c464f909f60ed4d09d8f6e84a88e4bb16db929115967d05e4876","crop":{"left":0,"bottom":134.2881,"width":293.64315,"height":143.59020000000004}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":135,"language":null,"source_page":15,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 135, subject_area = 'CIENCIAS_NATUREZA', statement = 'Os satélites artificiais e as sondas para exploração espacial são algumas das grandes realizações humanas desenvolvidas no último século. Para coletar e armazenar informações ao longo de anos, esses equipamentos precisam de energia. Como forma de fornecer energia limpa ao satélite, são acoplados diversos painéis de células solares, que, em fotografias, muitas vezes são confundidos com “asas”. Um satélite geoestacionário precisa armazenar a energia obtida pelos seus painéis solares em suas baterias. Como forma de otimizar o processo de absorção da energia solar, o ideal é que a superfície dos painéis mantenha-se perpendicular aos raios solares incidentes. Para isso, foi adaptado um sistema que rotaciona os painéis solares com velocidade angular constante. Qual é a velocidade de rotação dos painéis em comparação à velocidade de rotação da Terra (R )? T', options = '["0,25 RT","0,5 RT","RT","2 RT","4 RT"]'::jsonb, correct_answer = '"RT"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"3b05e5446f3f2b3674a071245d57f062baa7f8fd35760aefd38a3461baab114b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"74d5968e813cc15e12407f148bc90a94f3d8e8285a4eb4aa595a2d71716663e8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":135,"language":null,"page":15,"storagePath":"2025-D4-CD5/question-135-COMMON/statement-page-15.png","sha256":"2325cbbd82c7c464f909f60ed4d