  select id into v_occurrence_id from public.learning_enem_official_occurrences where year = 2025 and exam = 'ENEM' and application = 'REGULAR' and day = 'D4' and booklet = 'CD5' and question_number = 150 and coalesce(language, '') = '' limit 1;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'a76768149b57a02793f84bba5a42ee149d8ec7abbacd36f9cd313e730fc803c0' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 149, 'MATEMATICA', 'Em uma empresa trabalham 50 funcionários, dos quais, inicialmente, 40 tomam café diariamente. Essa empresa tem uma máquina que produz, diariamente, 12 000 mililitros de café. A máquina está programada para liberar uma quantidade de mililitros de café a cada acionamento. Os 12 000 mL de café são suficientes, sem sobra, para que cada um desses 40 funcionários possa utilizar essa máquina 5 vezes por dia. Pretende-se reprogramar a máquina para que essa quantidade de café produzida seja suficiente para que cada um dos 50 funcionários possa utilizar essa máquina 3 vezes por dia. Na reprogramação, a quantidade de café, em mililitro, que deverá Quantas vezes, ao longo desse dia, o sistema de resfriamento ser liberada a cada uso é foi acionado?', '["48. A 0","80. B 1","100. C 3","150. D 4","240. E 5"]'::jsonb, '"80. B 1"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"a76768149b57a02793f84bba5a42ee149d8ec7abbacd36f9cd313e730fc803c0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"2788763a087a47a68d4b502a37ca9e517931da1f673150647105a679500846ba","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":149,"language":null,"page":21,"storagePath":"2025-D4-CD5/question-149-COMMON/statement-page-21.png","sha256":"6f99bd77e73c175ada9a4e30a93e6d7f6e8e4135c946967858ef24e65262282a","crop":{"left":0,"bottom":129.4412,"width":267.4843905225,"height":177.23850000000002}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":149,"language":null,"source_page":21,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 149, subject_area = 'MATEMATICA', statement = 'Em uma empresa trabalham 50 funcionários, dos quais, inicialmente, 40 tomam café diariamente. Essa empresa tem uma máquina que produz, diariamente, 12 000 mililitros de café. A máquina está programada para liberar uma quantidade de mililitros de café a cada acionamento. Os 12 000 mL de café são suficientes, sem sobra, para que cada um desses 40 funcionários possa utilizar essa máquina 5 vezes por dia. Pretende-se reprogramar a máquina para que essa quantidade de café produzida seja suficiente para que cada um dos 50 funcionários possa utilizar essa máquina 3 vezes por dia. Na reprogramação, a quantidade de café, em mililitro, que deverá Quantas vezes, ao longo desse dia, o sistema de resfriamento ser liberada a cada uso é foi acionado?', options = '["48. A 0","80. B 1","100. C 3","150. D 4","240. E 5"]'::jsonb, correct_answer = '"80. B 1"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"a76768149b57a02793f84bba5a42ee149d8ec7abbacd36f9cd313e730fc803c0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"2788763a087a47a68d4b502a37ca9e517931da1f673150647105a679500846ba","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":149,"language":null,"page":21,"storagePath":"2025-D4-CD5/question-149-COMMON/statement-page-21.png","sha256":"6f99bd77e73c175ada9a4e30a93e6d7f6e8e4135c946967858ef24e65262282a","crop":{"left":0,"bottom":129.4412,"width":267.4843905225,"heigh