  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c2a0034e2a6e0f9484d7f06ffd6cd131ad7992a5c8abf48e31f2734514fa0cf9' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 165, 'MATEMATICA', 'Em uma loja de informática, 5 dispositivos de armazenagem de dados contêm as seguintes capacidades, expressas em gigabytes (GB): 32, 64, 128, 256 e 512. Nessa loja, esses dispositivos têm os preços P1, P2, P3, P4 e P5, respectivamente, os quais são determinados considerando-se R$ 10,00 por GB. Qual é o termo geral da sequência desses preços? n + 4', '["2 n + 6","5 ⋅ 2 n + 4","10 ⋅ 2 n","10 ⋅ (2 + 4) n - 1","10 ⋅ (2 + 32)"]'::jsonb, '"10 ⋅ 2 n"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"c2a0034e2a6e0f9484d7f06ffd6cd131ad7992a5c8abf48e31f2734514fa0cf9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"7d247d599dcb9cc246e1f5c412b5ec330bdabeafe3f8d200422383da99da3e31","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":165,"language":null,"page":27,"storagePath":"2025-D4-CD5/question-165-COMMON/statement-page-27.png","sha256":"ffa87834cf6211453fa33a634fcca99e8b0d7a1c8f149b786df8110db703022f","crop":{"left":0,"bottom":632.5246,"width":305.74326173999987,"height":109.22540000000004}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":165,"language":null,"source_page":27,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D4', source_number = 165, subject_area = 'MATEMATICA', statement = 'Em uma loja de informática, 5 dispositivos de armazenagem de dados contêm as seguintes capacidades, expressas em gigabytes (GB): 32, 64, 128, 256 e 512. Nessa loja, esses dispositivos têm os preços P1, P2, P3, P4 e P5, respectivamente, os quais são determinados considerando-se R$ 10,00 por GB. Qual é o termo geral da sequência desses preços? n + 4', options = '["2 n + 6","5 ⋅ 2 n + 4","10 ⋅ 2 n","10 ⋅ (2 + 4) n - 1","10 ⋅ (2 + 32)"]'::jsonb, correct_answer = '"10 ⋅ 2 n"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"c2a0034e2a6e0f9484d7f06ffd6cd131ad7992a5c8abf48e31f2734514fa0cf9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"7d247d599dcb9cc246e1f5c412b5ec330bdabeafe3f8d200422383da99da3e31","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":165,"language":null,"page":27,"storagePath":"2025-D4-CD5/question-165-COMMON/statement-page-27.png","sha256":"ffa87834cf6211453fa33a634fcca99e8b0d7a1c8f149b786df8110db703022f","crop":{"left":0,"bottom":632.5246,"width":305.74326173999987,"height":109.22540000000004}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":165,"language":null,"source_page":27,"source_sha256":"d3b0828