  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '3cf824d24d61db6e3041188eef85d7ba839f270fb166e4476e0f6fa8583f99a2', 'STATEMENT_CROP', 27, '2025-D4-CD5/question-166-COMMON/statement-page-27.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"3cf824d24d61db6e3041188eef85d7ba839f270fb166e4476e0f6fa8583f99a2","crop":{"left":0,"bottom":443.0979,"width":305.74326173999987,"height":134.83590000000004},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '689d05aee786e56df472546de978bc01e8f44f837c2855920423a1000af9e241' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 167, 'MATEMATICA', 'Na avaliação de riscos em investimentos no setor financeiro, compreender o desvio padrão das taxas de retorno ao longo de um período permite analisar riscos potenciais associados a um investimento. Quanto maior o desvio padrão, maior a variação das taxas de retorno e, consequentemente, maior o risco associado ao investimento. Um desvio padrão mais baixo indica um investimento mais estável e previsível. Uma classificação de risco de investimento que adota o desvio padrão ( d ) como medida para avaliação é: p • muito baixo: dp < 5%; • baixo: 5% ≤ d < 10%; p • moderado: 10% ≤ d < 20%; p • alto: 20% ≤ d < 30%; p • muito alto: d ≥ 30%. p Um investidor analisou, ao longo de cinco meses, as taxas de retorno de um tipo de investimento na bolsa de valores e identificou, respectivamente, retornos mensais de 3%, 15%, 6%, 9% e 12%. Ele pretende aplicar um capital nesse tipo de investimento e adotará o desvio padrão como medida para avaliar a classificação do risco associado. A classificação do risco desse tipo de investimento é', '["muito baixo.","baixo.","moderado.","alto.","muito alto."]'::jsonb, '"muito baixo."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"689d05aee786e56df472546de978bc01e8f44f837c2855920423a1000af9e241","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"4721ed70be9c06ffc87edc32de6ada0509cb94eea066e4540303007bb9271081","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":167,"language":null,"page":27,"storagePath":"2025-D4-CD5/question-167-COMMON/statement-page-27.png","sha256":"54d5a6e2567535b55d5c87776b063eb42f994dcf71bf4d5f3e17eab9d5bb91e0","crop":{"left":0,"bottom":137.91840000000002,"width":305.74326173999987,"height":236.7688}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":167,"language":null,"source_page":27,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
