  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '54d5a6e2567535b55d5c87776b063eb42f994dcf71bf4d5f3e17eab9d5bb91e0', 'STATEMENT_CROP', 27, '2025-D4-CD5/question-167-COMMON/statement-page-27.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"54d5a6e2567535b55d5c87776b063eb42f994dcf71bf4d5f3e17eab9d5bb91e0","crop":{"left":0,"bottom":137.91840000000002,"width":305.74326173999987,"height":236.7688},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '6be66078a47679c64bc12bdb900ab23ce605b500f145c24a4e2d1424c34d205b' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D4', 170, 'MATEMATICA', 'Dois professores participam de um concurso público com três fases. A primeira fase avalia o desempenho teórico, a segunda fase refere-se às experiências e aos títulos obtidos A partir do mês de março, observa-se o crescimento das durante a vida acadêmica, e a última fase avalia o desempenho vendas até o mês de maio e uma queda no mês de junho, que se didático do participante, sendo as notas obtidas nessas fases explica pela falta de matéria-prima que ocorreu na primeira representadas por F1, F2 e F3, respectivamente. A nota final (NF) semana daquele mês. Caso essa falta de matéria-prima não dos participantes é calculada por: tivesse ocorrido, a estimativa feita pela gerência é de que as vendas mensais desse item continuariam a crescer linearmente, NF = 0,4 × F1 + 0,1 × F2 + 0,5 × F3 mantendo o padrão de crescimento observado no período de O candidato precisa apresentar nota mínima igual a 6,0 em março a maio nos demais meses do ano. cada uma das fases para não ser desclassificado. Em caso de A estimativa feita para as vendas desse item no mês de julho, empate nas notas finais, o candidato que obtiver a maior nota em milhar de unidades, antes da queda registrada no mês de na primeira fase será o primeiro colocado. junho, foi de O primeiro participante obteve nota 7,0 na primeira e na segunda fase e nota 10,0 na última fase. O segundo obteve nota', '["500. 8,0 em cada uma das duas primeiras fases e ainda participará","600. da terceira fase.","700.","800. Para alcançar a primeira colocação no concurso, qual é a nota","900. mínima que o segundo participante deverá obter na terceira fase?"]'::jsonb, '"800. Para alcançar a primeira colocação no concurso, qual é a nota"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"6be66078a47679c64bc12bdb900ab23ce605b500f145c24a4e2d1424c34d205b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"0459d858b8e174e3ac21013810312ccae3a89065718b0e4be744cee96e9034b8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":170,"language":null,"page":28,"storagePath":"2025-D4-CD5/question-170-COMMON/statement-page-28.png","sha256":"bf9a3e8a67b9fef6d1eec98966468a0ff315f052859720155abf8e6063d7c28b","crop":{"left":282.78870146500003,"bottom":391.2803,"width":284.138798535,"height":215.09050000000002}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D4","booklet":"CD5","question_number":170,"language":null,"source_page":28,"source_sha256":"d3b0828ef2a699c0136c19fdbef35876907c4821f5c9cda3a6c956a869f44edc"}}'::jsonb, true) returning id into v_question_id; end if;
