  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '303117f141e5e4db7117b2f7dd46da70535c652d5d5476971b3b0a4ab40caff1' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D5', 25, 'LINGUAGENS', 'Falar-se em preposição — É palavra invariável, A roda dos não ausentes Que sempre faz ligação A outras duas palavras O nada e o não, E exprime posição. ausência alguma, JOSÉ MARIA DE FORTALEZA. Disponível em: www.fiocruz.br. borda em mim o empecilho. Acesso em: 21 jan. 2024 (fragmento). Há tempos treino Nesse cordel, além da função poética, também está presente o equilíbrio sobre a função metalinguística, pois ocorre a esse alquebrado corpo,', '["prestação de informação. e, se inteira fui,","utilização da norma-padrão. cada pedaço que guardo de mim","produção de efeito estilístico. tem na memória o anelar","enunciação em primeira pessoa. de outros pedaços.","tematização da língua portuguesa."]'::jsonb, '"produção de efeito estilístico. tem na memória o anelar"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"303117f141e5e4db7117b2f7dd46da70535c652d5d5476971b3b0a4ab40caff1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"4ec181bb4c2841dee5abc32cccc958f23ee1ec854a0ca0b8e20e77937e2d588f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":25,"language":null,"page":11,"storagePath":"2025-D5-CD1/question-25-COMMON/statement-page-11.png","sha256":"a0f7414272f9ef048f7a7b19dc80534f1e272b480fd7869276ed6da542c2a8b8","crop":{"left":302.8502388699991,"bottom":397.3949999999999,"width":264.0772611300009,"height":135.1239000000001}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD1","question_number":25,"language":null,"source_page":11,"source_sha256":"0088e1b657b445b98ebfdcf14dc37dd0e453564f0064f1621b3663bf7a065001"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D5', source_number = 25, subject_area = 'LINGUAGENS', statement = 'Falar-se em preposição — É palavra invariável, A roda dos não ausentes Que sempre faz ligação A outras duas palavras O nada e o não, E exprime posição. ausência alguma, JOSÉ MARIA DE FORTALEZA. Disponível em: www.fiocruz.br. borda em mim o empecilho. Acesso em: 21 jan. 2024 (fragmento). Há tempos treino Nesse cordel, além da função poética, também está presente o equilíbrio sobre a função metalinguística, pois ocorre a esse alquebrado corpo,', options = '["prestação de informação. e, se inteira fui,","utilização da norma-padrão. cada pedaço que guardo de mim","produção de efeito estilístico. tem na memória o anelar","enunciação em primeira pessoa. de outros pedaços.","tematização da língua portuguesa."]'::jsonb, correct_answer = '"produção de efeito estilístico. tem na memória o anelar"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"303117f141e5e4db7117b2f7dd46da70535c652d5d5476971b3b0a4ab40caff1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"4ec181bb4c2841dee5abc32cccc958f23ee1ec854a0ca0b8e20e77937e2d588f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":25,"language":null,"page":11,"storagePath":"2025-D5-CD1/question-25-COMMON/statement-page-11.png","sha256":"a0f7414272f9ef048f7a7b19dc80534f1e272b480fd7869276ed6da542c2a8b8","crop":{"left":302.8502388699991,"bottom":397.3949999999999,"width":264.0772611300009,"height":135.1239000000001}}],"enem_area":"LI