  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '9a859b2872affc0e3857c805927e94b9c6a55cf06d8fabbf1e0825476b6e5418', 'STATEMENT_CROP', 10, '2025-D5-CD4/question-22-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"9a859b2872affc0e3857c805927e94b9c6a55cf06d8fabbf1e0825476b6e5418","crop":{"left":283.99474306250005,"bottom":429.571,"width":282.93275693749996,"height":195.88649999999996},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'a9b3dacb9b6d2b9dc253ff261946924df0bc4dd5838675d225eb67fbf7df16d9' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D5', 30, 'LINGUAGENS', 'Não posso ser professor se não percebo cada vez melhor que, por não poder ser neutra, minha prática exige de mim uma definição. Uma tomada de posição. Sou professor a favor da decência contra o despudor, a favor da liberdade contra o autoritarismo, da autoridade contra a licenciosidade, da democracia contra a ditadura de direita ou de esquerda. Sou professor a favor da luta constante contra qualquer forma de discriminação, contra a dominação econômica dos indivíduos ou das classes sociais. Sou professor contra a ordem capitalista vigente que inventou esta aberração: a misé ria na fartura . Sou professor a favor da esperança que me anima apesar de tudo. Sou professor contra o desengano que me consome e imobiliza. FREIRE, P. Pedagogia da autonomia : saberes necessários à prática educativa. Rio de Janeiro, São Paulo: Paz e Terra, 2015 (adaptado). Para reforçar o ponto de vista do autor, a progressão temática nesse texto é marcada pelo(a)', '["formulação de hipóteses.","emprego da primeira pessoa.","utilização de elementos coesivos.","repetição de estruturas sintáticas.","uso de palavras de sentido oposto."]'::jsonb, '"repetição de estruturas sintáticas."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"a9b3dacb9b6d2b9dc253ff261946924df0bc4dd5838675d225eb67fbf7df16d9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"3fcb0698129b1fc09fbd31279d66ea34827a6c51831854a78ea7902c55e4a03b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":30,"language":null,"page":13,"storagePath":"2025-D5-CD1/question-30-COMMON/statement-page-13.png","sha256":"ed958186b1fa774293737bb9a12a7f1aa675927a6f2cc508925ab5dd7d5f4366","crop":{"left":0,"bottom":346.6276,"width":262.00344999999993,"height":137.53470000000004}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD1","question_number":30,"language":null,"source_page":13,"source_sha256":"0088e1b657b445b98ebfdcf14dc37dd0e453564f0064f1621b3663bf7a065001"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D5', source_number = 30, subject_area = 'LINGUAGENS', statement = 'Não posso ser professor se não percebo cada vez melhor que, por não poder ser neutra, minha prática exige de mim uma definição. Uma tomada de posição. Sou professor a favor da decência contra o despudor, a favor da liberdade contra o autoritarismo, da autoridade contra a licenciosidade, da democracia contra a ditadura de direita ou de esquerda. Sou professor a favor da luta constante contra qualquer forma de discriminação, contra a dominação econômica dos indivíduos ou das classes sociais. Sou professor contra a ordem capitalista vigente que inventou esta aberração: a misé ria na fartura . Sou professor a favor da esperança que me anima apesar de tudo. Sou professor contra o desengano que me consome e imobiliza. FREIRE, P. Pedagogia da autonomia : saberes necessários à prática educativa. Rio de Janeiro, São Paulo: Paz e Terra, 2015 (adaptado). Para reforçar o ponto de vista do autor, a progressão temática nesse texto é marcada pelo(a)', options = '["formulação de hipóteses.","emprego da primeira pessoa.","utilização de elementos coesivos.","repetição de estruturas sintáticas.","uso de palavras de sentido oposto."]'::jsonb, correct_answer = '"repetição de estruturas sintáticas."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"a9b3dacb9b6d2b9dc253ff261946924df0bc4dd5838675d225eb67fbf7df16d9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"3fcb0698129b1fc09fbd31279d66ea34827a6c51831854a78ea7902c55e4a03b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":30,"language":null,"page":13,"storagePath":"2025-D5-CD1/question-30-COMMON/statement-page-13.png","sha256":"ed958186b1fa774293737bb9a12a7f1aa675927a6f2cc508925ab5dd7d5f4366","crop":{"left":0,"bottom":346.6276,"width":262.00344999999993,"height":137.53470000000004}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD1","question_number":30,"language":null,"source_page":13,"source_sha256":"0088e1b657b445b98ebfdcf14dc37dd0e453564f0064f1621b3663bf7a065001"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
