  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd7c9289bb901eaa04108984276f2c05f908ee0fe9eb7c35a0647a96ab3b7ea17' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D5', 33, 'LINGUAGENS', 'Esse exemplar do gênero carta de leitor, acerca de uma reportagem sobre o Dia da Amazônia, tem por finalidade Elvis , de Baz Luhrmann, e Priscilla , de Sofia Coppola, foram duas cinebiografias de Elvis Presley recentemente lançadas, A informar sobre o surgimento de novos focos de incêndio nos e somente uma delas era adequada para o rei. estados brasileiros. Elvis é uma cinebiografia musical que acompanha B conscientizar os leitores sobre a importância de atuar na a verdadeira história de Elvis Presley (Austin Butler) desde preservação ambiental. seus primeiros dias nos empobrecidos Mississippi e Memphis C denunciar os responsáveis pelos incêndios ocorridos em até sua glamorosa década final em Las Vegas. Atormentado ecossistemas brasileiros. pela dor causada pela morte de sua mãe, ele busca conforto D refletir sobre a urgência de enfrentamento dos problemas em seu casamento com Priscilla, mas no centro de seu mito está ambientais abordados na matéria. a controvérsia em torno do Coronel Tom Parker (Tom Hanks), E apresentar o posicionamento de um jornal sobre as ocorrências que transforma seu talento em uma mercadoria e deixa o rei intensas de fogo no país. em espiral, em uma crise existencial.', '["informar sobre o surgimento de novos focos de incêndio nos","conscientizar os leitores sobre a importância de atuar na","denunciar os responsáveis pelos incêndios ocorridos em","refletir sobre a urgência de enfrentamento dos problemas","somente uma delas era adequada para o rei. estados brasileiros."]'::jsonb, '"somente uma delas era adequada para o rei. estados brasileiros."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"d7c9289bb901eaa04108984276f2c05f908ee0fe9eb7c35a0647a96ab3b7ea17","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"b56f2fd6679d9367480ce272b01ade3820fe5187d2eeec5a415545a00eb1d6b7","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":33,"language":null,"page":15,"storagePath":"2025-D5-CD1/question-33-COMMON/statement-page-15.png","sha256":"2ef449cb24c17be453f4ee8dafa4bde153234b843e5068c95f0a92851a29ca0e","crop":{"left":0,"bottom":693.6151,"width":286.4443213474991,"height":48.134900000000016}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD1","question_number":33,"language":null,"source_page":15,"source_sha256":"0088e1b657b445b98ebfdcf14dc37dd0e453564f0064f1621b3663bf7a065001"}}'::jsonb, true) returning id into v_question_id; end if;
