ntação ontológica da ética proposta pelo autor encontra suporte na', '["afirmação da autoridade religiosa.","satisfação de interesses individuais.","formação do pragmatismo utilitarista.","compreensão da totalidade universal.","superação do modelo racionalista."]'::jsonb, '"afirmação da autoridade religiosa."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"abf658068b3fa4917aa6a77c77002a75c12f83ba46fc86637d6ffff49d9b95c2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"149572db12f4bf31e84f8f2bfabd626c1fbbc562f69bfe7a470520e84df0b9b1","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":71,"language":null,"page":27,"storagePath":"2025-D5-CD1/question-71-COMMON/statement-page-27.png","sha256":"0883ef54fe9ff4d268230512e3b62bd012e97cade9809cb98629e89b20cf5a92","crop":{"left":290.9007750000011,"bottom":327.5823,"width":276.0267249999989,"height":150.40390000000002}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD1","question_number":71,"language":null,"source_page":27,"source_sha256":"0088e1b657b445b98ebfdcf14dc37dd0e453564f0064f1621b3663bf7a065001"}}'::jsonb, true) returning id into v_question_id; end if;
