endência da atividade primária."]'::jsonb, '"dependência da atividade primária."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"bf7601d17ceb8feca0271137ee3cbee63e3cf10d7029261432d763b8ec0e7c6c","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"aa62344e16b77838908fb27076c9cb86a7207ac28850b9ccc572b66e239cc697","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D5","booklet":"CD4","question_number":72,"language":null,"source_page":27,"source_sha256":"68de4d9c0218df599f4a43848cb1c9c0b64e63ffa7e605b374ada5f15b883ac7"}}'::jsonb, true) returning id into v_question_id; end if;
