  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 92, subject_area = 'CIENCIAS_NATUREZA', statement = 'Várias plantas, como as bromélias, orquídeas e cactos, possuem uma adaptação metabólica que envolve o fechamento diurno de seus estômatos, levando à produção de ácidos orgânicos e à descarboxilação que permite a fixação do carbono à noite. Esse processo constitui uma adaptação fisiológica a condições de', options = '["alteração de pH.","falta de oxigênio.","escassez de água.","variação de temperatura.","mudança de luminosidade."]'::jsonb, correct_answer = '"escassez de água."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"b4757128e47227aa5c3126f79321ce1c0a7ec2aa845b6bf550fee5aefd44bc28","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"9855012539919844abaf3715e7adc2e5ee26aa862c697533c31752cd94773d97","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":92,"language":null,"page":2,"storagePath":"2025-D6-CD5/question-92-COMMON/statement-page-2.png","sha256":"23c9f008ea3b27cf87426ab41c7622edf4292fa4b7461c935d3b38e59658fee2","crop":{"left":0,"bottom":304.261,"width":295.184145115,"height":77.42129999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":92,"language":null,"source_page":2,"source_sha256":"