  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '23c9f008ea3b27cf87426ab41c7622edf4292fa4b7461c935d3b38e59658fee2', 'STATEMENT_CROP', 2, '2025-D6-CD5/question-92-COMMON/statement-page-2.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"23c9f008ea3b27cf87426ab41c7622edf4292fa4b7461c935d3b38e59658fee2","crop":{"left":0,"bottom":304.261,"width":295.184145115,"height":77.42129999999997},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'b1ab7feb90d8d5eeb81611a411eda2e873ce074592e7fe8626b3ec8c871f4ee6' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 93, 'CIENCIAS_NATUREZA', 'A destruição de florestas prejudica o equilíbrio climático e hídrico, podendo levar à extinção de espécies e causar outros efeitos imprevisíveis, como o reaparecimento de patógenos. Vírus que permaneciam latentes nas florestas podem aparecer e causar as viroses do tipo emergente. Ecologicamente, essa relação desarmônica entre os vírus e o homem pode causar enorme prejuízo para a saúde humana. GROSETH, A.; FELDMANN, H.; STRONG, J. E. Trends in Microbiology , v. 15, 2007 (adaptado). O enorme prejuízo ao hospedeiro nesse tipo de virose está associado com o(a)', '["baixa imunidade do hospedeiro.","alta capacidade de mutação dos vírus.","pouco tempo de relação entre o vírus e o hospedeiro.","acúmulo de substâncias tóxicas nos vírus emergentes.","grau elevado de especificidade dos vírus com o hospedeiro."]'::jsonb, '"pouco tempo de relação entre o vírus e o hospedeiro."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"b1ab7feb90d8d5eeb81611a411eda2e873ce074592e7fe8626b3ec8c871f4ee6","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"14e9a0326cb0edf8b065005075c78e1f7e16b1b32bff9b78a6c1eaba982d097c","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":93,"language":null,"page":2,"storagePath":"2025-D6-CD5/question-93-COMMON/