  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '61cecf408ba55796f070bba6f2d6eac4f5059da7017de054ded7e43be7f5994a', 'STATEMENT_CROP', 8, '2025-D6-CD5/question-114-COMMON/statement-page-8.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"61cecf408ba55796f070bba6f2d6eac4f5059da7017de054ded7e43be7f5994a","crop":{"left":295.150662500001,"bottom":222.8871,"width":271.77683749999903,"height":108.53450000000001},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5600952ae240fb8c4f37a42dbedb5e33a872e7fb4143195e99a924e79df818c8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 118, 'CIENCIAS_NATUREZA', 'O uso de terapias celulares no tratamento do diabetes O acelerador de partículas brasileiro Sirius é uma fonte mellitus tem crescido nos últimos anos, com destaque, inclusive, emissora de luz síncrotron. Fontes como esta são equipamentos para pesquisas brasileiras. Os critérios de inclusão para científicos de grande porte, que produzem radiação participação em uma dessas pesquisas exigem o diagnóstico eletromagnética de forma controlada. Essa radiação é usada precoce da doença em jovens com baixa produção de para investigar a composição e a estrutura da matéria em suas insulina. Os procedimentos terapêuticos envolvem a coleta mais variadas formas, com aplicações em praticamente todas de células-tronco do próprio paciente, imunossupressão com as áreas do conhecimento. quimioterapia e transplante das células. LOJUDICE, F. H.; SOGAYAR, M. C. Células-tronco no tratamento e cura do diabetes mellitus. Ciência & Saúde Coletiva , n. 1, 2008 (adaptado). Qual é o risco da utilização dessa nova biotecnologia?', '["O conflito ético na utilização de células-tronco.","A ocorrência de rejeição às novas células transplantadas.","A resistência dos receptores de insulina à ação hormonal.","A susceptibilidade maior do paciente a infecções oportunistas.","A necessidade de testes de compatibilidade genética para"]'::jsonb, '"A resistência dos receptores de insulina à ação hormonal."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"5600952ae240fb8c4f37a42dbedb5e33a872e7fb4143195e99a924e79df818c8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"50a12f0eac4cb8b810053565b0cdb563be7b3ef62c093dc8ac0de719fe11c8db","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":118,"language":null,"source_page":9,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
