  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '43b4973a7ea0c83ac2a68e258df208e45772bb70321d9ecc2ab24f8d6c2fd6c8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 116, 'CIENCIAS_NATUREZA', 'O feixe de elétrons do Sirius tem alta energia cinética O Aquífero Guarani é uma grande reserva de água 9 relativística (3,0 GeV = 3,0 × 10 eV) e percorre uma circunferência subterrânea potável cujas características físico-químicas de aproximadamente 520 metros em 1,7 microssegundos − 6 dependem de fatores como a geologia da região e a qualidade (1,7 × 10 s) no referencial do laboratório. Para fins de da água que o alimenta. Análises no aquífero realizadas em comparação, considere um carro com massa de 960 kg e mesma determinada região mostraram que a água estava com o energia cinética. Considere também que 1 eV é equivalente a − 19 valor do pH igual a 4. A água captada nessa região deverá ter 1,6 × 10 joule. + seu pH corrigido para que a concentração de íons H atinja Disponível em: https://lnls.cnpem.br. − 6 − 1 10 mol L , tornando-a apropriada para o consumo humano. Acesso em: 14 out. 2025 (adaptado). + Na correção do pH da água captada, a concentração de íons H Qual é a razão entre a velocidade do feixe eletrônico e a deverá ser do carro? 20', '["reduzida duas vezes. A 6 × 10 14","reduzida vinte vezes. B 3 2 10 × 14","reduzida cem vezes. C 3 × 10 14","aumentada duas vezes. D 12 × 10 3","aumentada duzentas vezes. E 3 1 6 10 , ×"]'::jsonb, '"reduzida cem vezes. C 3 × 10 14"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"43b4973a7ea0c83ac2a68e258df208e45772bb70321d9ecc2ab24f8d6c2fd6c8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"ec00fbbd8a91cfb713046c90986e5a4e5aabee71b14f3a4d7c9f3e499246d42f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":116,"language":null,"page":9,"storagePath":"2025-D6-CD5/question-116-COMMON/statement-page-9.png","sha256":"8394b650399a21190eecfabed30841cdfa9858fdc700f43fd36d8f5d766b3135","crop":{"left":0,"bottom":325.2428,"width":250.02477999999988,"height":165.42950000000002}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":116,"language":null,"source_page":9,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
