  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5b98c4ed8ffcd9844e33774a959ad2df1fad6896514b9414a04b844038db5327' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 117, 'CIENCIAS_NATUREZA', 'Em um experimento, camundongos inalaram resíduos de cádmio, um metal presente no cigarro. Posteriormente, foi verificada uma forte diminuição na fertilidade desses roedores, associada a uma alteração no funcionamento da cadeia respiratória mitocondrial dos espermatozoides. Qual consequência intracelular decorre do mau funcionamento dessa organela?', '["Diminuição nos níveis de ATP.","Aumento na concentração de CO2.","Aumento no consumo de oxigênio.","Diminuição na ocorrência da glicólise.","Aumento na quantidade de glicogênio."]'::jsonb, '"Diminuição nos níveis de ATP."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"5b98c4ed8ffcd9844e33774a959ad2df1fad6896514b9414a04b844038db5327","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"b8256bd450d0d89da095d9ecda9725d4da7e0203387c14a211415f6ee6bc6a56","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":117,"language":null,"page":9,"storagePath":"2025-D6-CD5/question-117-COMMON/statement-page-9.png","sha256":"f48a2974d4b44b86f813ab45234a48f200c001c51ac041b9e29dff5b16c274f7","crop":{"left":0,"bottom":133.4958,"width":250.02477999999988,"height":128.65149999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":117,"language":null,"source_page":9,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 117, subject_area = 'CIENCIAS_NATUREZA', statement = 'Em um experimento, camundongos inalaram resíduos de cádmio, um metal presente no cigarro. Posteriormente, foi verificada uma forte diminuição na fertilidade desses roedores, associada a uma alteração no funcionamento da cadeia respiratória mitocondrial dos espermatozoides. Qual consequência intracelular decorre do mau funcionamento dessa organela?', options = '["Diminuição nos níveis de ATP.","Aumento na concentração de CO2.","Aumento no consumo de oxigênio.","Diminuição na ocorrência da glicólise.","Aumento na quantidade de glicogênio."]'::jsonb, correct_answer = '"Diminuição nos níveis de ATP."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"5b98c4ed8ffcd9844e33774a959ad2df1fad6896514b9414a04b844038db5327","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"b8256bd450d0d89da095d9ecda9725d4da7e0203387c14a211415f6ee6bc6a56","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":117,"language":null,"page":9,"storagePath":"2025-D6-CD5/question-117-COMMON/statement-page-9.png","sha256":"f48a2974d4b44b86f813ab45234a48f200c001c51ac041b9e29dff5b16c274f7","crop":{"left":0,"bottom":133.4958,"width":250.02477999999988,"height":128.65149999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"e