  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 120, 'CIENCIAS_NATUREZA', 'Em 2011 foi aprovado, pela Comissão Técnica Nacional de Biossegurança, o primeiro organismo geneticamente modificado (OGM) produzido exclusivamente no Brasil. Esse OGM é uma variedade de feijão resistente ao mosaico dourado do feijoeiro, doença viral transmitida pela mosca-branca. Para desenvolver a resistência, foi introduzida no DNA da planta uma sequência gênica que codifica uma proteína não funcional, similar à proteína viral denominada Rep, fundamental para a replicação do vírus. Pesquisa Fapesp , n. 188, out. 2011 (adaptado). O processo descrito protege o feijão contra o referido vírus porque promove a', '["produção de proteínas de resistência contra o vírus.","inibição da síntese das proteínas Rep não funcionais.","produção de proteínas virais que repelem a mosca-branca.","indução de uma resposta de defesa da planta contra a mosca-branca.","síntese da proteína Rep não funcional, que impede a replicação viral."]'::jsonb, '"síntese da proteína Rep não funcional, que impede a replicação viral."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"e2369064a1abebf4ddf32dc3c217eafb6a4bdb7c249c568a570a6693b9b4fcb0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"6c34ec5514eba7514c7ae0adc2ea2ab7edd899c9ac4f82402e34375f908e2454","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":120,"language":null,"page":10,"storagePath":"2025-D6-CD5/question-120-COMMON/statement-page-10.png","sha256":"a8a367c97ae176f38f796fa3ae1511909711fb06d16830c80cd5a8e07c1729c6","crop":{"left":0,"bottom":291.1446,"width":249.7345499999999,"height":114.25449999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":120,"language":null,"source_page":10,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 120, subject_area = 'CIENCIAS_NATUREZA', statement = 'Em 2011 foi aprovado, pela Comissão Técnica Nacional de Biossegurança, o primeiro organismo geneticamente modificado (OGM) produzido exclusivamente no Brasil. Esse OGM é uma variedade de feijão resistente ao mosaico dourado do feijoeiro, doença viral transmitida pela mosca-branca. Para desenvolver a resistência, foi introduzida no DNA da planta uma sequência gênica que codifica uma proteína não funcional, similar à proteína viral denominada Rep, fundamental para a replicação do vírus. Pesquisa Fapesp , n. 188, out. 2011 (adaptado). O processo descrito protege o feijão contra o referido vírus porque promove a', options = '["produção de proteínas de resistência contra o vírus.","inibição da síntese das proteínas Rep não funcionais.","produção de proteínas virais que repelem a mosca-branca.","indução de uma resposta de defesa da planta contra a mosca-branca.","síntese da proteína Rep não funcional, que impede a replicação viral."]'::jsonb, correct_answer = '"síntese da proteína Rep não funcional, que impede a replicação viral."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"e2369064a1abebf4ddf32dc3c217eafb6a4bdb7c249c568a570a6693b9b4fcb0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"6c34ec5514eba7514c7ae0adc2ea2ab7edd899c9ac4f82402e34375f908e2454","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":120,"language":null,"page":10,"storagePath":"2025-D6-CD5/question-120-COMMON/statement-page-10.png","sha256":"a8a367c97ae176f38f796fa3ae1511909711fb06d16830c80cd5a8e07c1729c6","crop":{"left":0,"bottom":291.1446,"width":249.7345499999999,"height":114.25449999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":120,"language":null,"source_page":10,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
