  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'a8a367c97ae176f38f796fa3ae1511909711fb06d16830c80cd5a8e07c1729c6', 'STATEMENT_CROP', 10, '2025-D6-CD5/question-120-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"a8a367c97ae176f38f796fa3ae1511909711fb06d16830c80cd5a8e07c1729c6","crop":{"left":0,"bottom":291.1446,"width":249.7345499999999,"height":114.25449999999995},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c7acd299d61e9757f9e4e4bb141a9d1c7d0a9ea7b482f90eb8e8d2d15e765162' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 121, 'CIENCIAS_NATUREZA', 'Escorpiões podem se reproduzir de forma sexuada ou assexuada, dependendo da espécie. Algumas espécies, cuja reprodução ocorre sem a necessidade de um parceiro, podem se multiplicar rapidamente e apresentar ampla distribuição geográfica, inclusive adaptando-se a ambientes urbanos. Um exemplo muito comum é o escorpião-amarelo, que encontra nas cidades fartura de alimento, abrigo e ausência de predadores. Essa rápida multiplicação ocorre por meio de', '["fragmentação espontânea ou acidental.","desenvolvimento de embriões sem fecundação.","formação de esporos, que germinam formando indivíduos.","divisão de um indivíduo em duas partes de mesma dimensão.","divisão nuclear formando núcleos e, a partir desses, várias células."]'::jsonb, '"desenvolvimento de embriões sem fecundação."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"c7acd299d61e9757f9e4e4bb141a9d1c7d0a9ea7b482f90eb8e8d2d15e765162","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"805ce37fd5c2a7e09e50925b217ab04245366889f32c30d37dc01551be444d02","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":10,"storagePath":"2025-D6-CD5/question-121-COMMON/statement-page-10.png","sha256":"347a888bd3bbb4d435b7775766f8d9e8f9fc82ac1e6c984a20e892e7eb56a559","crop":{"left":0,"bottom":128.5359,"width":249.7345499999999,"height":103.1677}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":121,"language":null,"source_page":10,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 121, subject_area = 'CIENCIAS_NATUREZA', statement = 'Escorpiões podem se reproduzir de forma sexuada ou assexuada, dependendo da espécie. Algumas espécies, cuja reprodução ocorre sem a necessidade de um parceiro, podem se multiplicar rapidamente e apresentar ampla distribuição geográfica, inclusive adaptando-se a ambientes urbanos. Um exemplo muito comum é o escorpião-amarelo, que encontra nas cidades fartura de alimento, abrigo e ausência de predadores. Essa rápida multiplicação ocorre por meio de', options = '["fragmentação espontânea ou acidental.","desenvolvimento de embriões sem fecundação.","formação de esporos, que germinam formando indivíduos.","divisão de um indivíduo em duas partes de mesma dimensão.","divisão nuclear formando núcleos e, a partir desses, várias células."]'::jsonb, correct_answer = '"desenvolvimento de embriões sem fecundação."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"c7acd299d61e9757f9e4e4bb141a9d1c7d0a9ea7b482f90eb8e8d2d15e765162","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"805ce37fd5c2a7e09e50925b217ab04245366889f32c30d37dc01551be444d02","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":121,"language":null,"page":10,"storagePath":"2025-D6-CD5/question-121-COMMON/statement-page-10.png","sha256":"347a888bd3bbb4d435b7775766f8d9e8f9fc82ac1e6c984a20e892e7eb56a559","crop":{"left":0,"bottom":128.5359,"width":249.7345499999999,"height":103.1677}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":121,"language":null,"source_page":10,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
