  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '347a888bd3bbb4d435b7775766f8d9e8f9fc82ac1e6c984a20e892e7eb56a559', 'STATEMENT_CROP', 10, '2025-D6-CD5/question-121-COMMON/statement-page-10.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"347a888bd3bbb4d435b7775766f8d9e8f9fc82ac1e6c984a20e892e7eb56a559","crop":{"left":0,"bottom":128.5359,"width":249.7345499999999,"height":103.1677},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '868772729ae508af21cf25f9b9401f46fc7ef25fd6557a051923336e0ce53415' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 123, 'CIENCIAS_NATUREZA', 'Considere o esquema básico de funcionamento de uma usina nuclear responsável pelo fornecimento de energia elétrica a uma cidade próxima. No reator, ocorre a fissão nuclear, que gera energia suficiente para aquecer a água dentro do gerador de vapor. O vapor passa pelas pás da turbina gerando energia elétrica. Em seguida, ele é resfriado no condensador. A bomba l é responsável por fazer a água aquecida pela fissão nuclear circular e aquecer a água dentro da câmara geradora de vapor. A bomba ll leva a água do condensador para a câmara geradora de vapor. A bomba lll faz circular a água do ambiente aquático para resfriar/condensar o vapor que passou pelas turbinas. As setas cinza indicam o sentido do fluxo de água. Disponível em: https://energiainteligenteufjf.com.br. Acesso em: 5 mar. 2024 (adaptado). Se a bomba l parar de funcionar, o que ocorrerá na usina nuclear?', '["Aquecimento do reator da usina.","Aumento da atividade da turbina.","Resfriamento do ambiente aquático.","Inundação de água no condensador.","Aceleração do consumo de combustível."]'::jsonb, '"Aquecimento do reator da usina."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"868772729ae508af21cf25f9b9401f46fc7ef25fd6557a051923336e0ce53415","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c1d7f60ad8cc38ca63a8299bd07eae735fcfad0bb6324e9940167fa9e3524a44","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":123,"language":null,"page":11,"storagePath":"2025-D6-CD5/question-123-COMMON/statement-page-11.png","sha256":"ba64f50c25454e00c5434a0f82436c22e13aa8c5c80f288dc92e9fb1e4f74781","crop":{"left":0,"bottom":132.992,"width":288.86319999999995,"height":425.8969000000001}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":123,"language":null,"source_page":11,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 123, subject_area = 'CIENCIAS_NATUREZA', statement = 'Considere o esquema básico de funcionamento de uma usina nuclear responsável pelo fornecimento de energia elétrica a uma cidade próxima. No reator, ocorre a fissão nuclear, que gera energia suficiente para aquecer a água dentro do gerador de vapor. O vapor passa pelas pás da turbina gerando energia elétrica. Em seguida, ele é resfriado no condensador. A bomba l é responsável por fazer a água aquecida pela fissão nuclear circular e aquecer a água dentro da câmara geradora de vapor. A bomba ll leva a água do condensador para a câmara geradora de vapor. A bomba lll faz circular a água do ambiente aquático para resfriar/condensar o vapor que passou pelas turbinas. As setas cinza indicam o sentido do fluxo de água. Disponível em: https://energiainteligenteufjf.com.br. Acesso em: 5 mar. 2024 (adaptado). Se a bomba l parar de funcionar, o que ocorrerá na usina nuclear?', options = '["Aquecimento do reator da usina.","Aumento da atividade da turbina.","Resfriamento do ambiente aquático.","Inundação de água no condensador.","Aceleração do consumo de combustível."]'::jsonb, correct_answer = '"Aquecimento do reator da usina."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"868772729ae508af21cf25f9b9401f46fc7ef25fd6557a051923336e0ce53415","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c1d7f60ad8cc38ca63a8299bd07eae735fcfad0bb6324e9940167fa9e3524a44","statement_assets":[{"assetRole":"STATEMENT","mediaTy