  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 124, subject_area = 'CIENCIAS_NATUREZA', statement = 'Os cupins possuem em seu tubo digestório uma grande quantidade de microrganismos que fabricam celulase, enzima responsável por degradar a celulose, o que facilita a assimilação desse carboidrato pelos invertebrados. A relação ecológica existente entre esses seres vivos é conhecida como', options = '["mutualismo, pois tanto os cupins quanto os microrganismos se beneficiam.","cooperação, pois a associação entre o cupim e os microrganismos é facultativa.","competição, pois tanto os cupins quanto os microrganismos consomem a celulose.","comensalismo, pois somente os cupins se beneficiam com a fabricação da enzima pelo microrganismo.","parasitismo, pois os microrganismos absorvem a maioria dos nutrientes presentes no tubo digestório dos cupins."]'::jsonb, correct_answer = '"mutualismo, pois tanto os cupins quanto os microrganismos se beneficiam."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"3a2d6405da0c4b2f7ff6db62e0f47d76ff1fb2985b26a8840aaa19c6227d37a2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"b0a273fe0c8eb43585e6ca9a9f3d8fe1a3c60da757dae854e447b499c6d9d661","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":124,"language":null,"page":12,"storagePath":"2025-D6-CD5/question-124-COMMON/statement-page-12.png","sha256":"6292bb46d2fcb2f4eb4c69d706433e9f387abc94778b68e81da8a302f36df06b","crop":{"left":0,"bottom":662.908,"width":259.8485999999999,"heig