  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '6292bb46d2fcb2f4eb4c69d706433e9f387abc94778b68e81da8a302f36df06b', 'STATEMENT_CROP', 12, '2025-D6-CD5/question-124-COMMON/statement-page-12.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"6292bb46d2fcb2f4eb4c69d706433e9f387abc94778b68e81da8a302f36df06b","crop":{"left":0,"bottom":662.908,"width":259.8485999999999,"height":78.84199999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c13202fad356e6844d7aec605b6415831d6ca5f1a441977c9b72546e918e23d0' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 125, 'CIENCIAS_NATUREZA', 'Na produção do vinho pode ocorrer a contaminação por Aspergillus carbonarius e Aspergillus niger , fungos oportunistas que se desenvolvem, principalmente, nas bagas danificadas de uvas durante seu amadurecimento. Esses fungos produzem ocratoxina (OTA), um tipo de micotoxina, possivelmente cancerígena, que pode ser transferida para o vinho durante o processo de vinificação. WELKE, J. E.; HOELTZ, M.; NOLL, I. B. Aspectos relacionados à presença de fungos toxigênicos em uvas e ocratoxina A em vinhos. Ciência Rural , n. 8, out. 2009 (adaptado). Considerando os princípios dessa técnica de produção, que procedimento reduz o risco da presença de OTA no vinho?', '["Seleção dos cachos.","Utilização de inseticidas.","Maceração dos frutos.","Medição da infrutescência.","Escolha da variedade de uva."]'::jsonb, '"Seleção dos cachos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"c13202fad356e6844d7aec605b6415831d6ca5f1a441977c9b72546e918e23d0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"954fca936f373a5b3607cfc5e600f418da94315b2fdba65074c629735e9c227e","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":125,"language":null,"page":12,"storagePath":"2025-D6-CD5/question-125-COMMON/statement-page-12.png","sha256":"b88ed9e7b0733eb7e8cd0d8309d6980e8a1a2892a70028fc63aad36e3a24a3fa","crop":{"left":0,"bottom":488.4957,"width":259.8485999999999,"height":112.87320000000005}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":125,"language":null,"source_page":12,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 125, subject_area = 'CIENCIAS_NATUREZA', statement = 'Na produção do vinho pode ocorrer a contaminação por Aspergillus carbonarius e Aspergillus niger , fungos oportunistas que se desenvolvem, principalmente, nas bagas danificadas de uvas durante seu amadurecimento. Esses fungos produzem ocratoxina (OTA), um tipo de micotoxina, possivelmente cancerígena, que pode ser transferida para o vinho durante o processo de vinificação. WELKE, J. E.; HOELTZ, M.; NOLL, I. B. Aspectos relacionados à presença de fungos toxigênicos em uvas e ocratoxina A em vinhos. Ciência Rural , n. 8, out. 2009 (adaptado). Considerando os princípios dessa técnica de produção, que procedimento reduz o risco da presença de OTA no vinho?', options = '["Seleção dos cachos.","Utilização de inseticidas.","Maceração dos frutos.","Medição da infrutescência.","Escolha da variedade de uva."]'::jsonb, correct_answer = '"Seleção dos cachos."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"c13202fad356e6844d7aec605b6415831d6ca5f1a441977c9b72546e918e23d0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"954fca936f373a5b3607cfc5e600f418da94315b2fdba65074c629735e9c227e","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":125,"language":null,"page":12,"storagePath":"2025-D6-CD5/question-125-COMMON/statement-page-12.png","sha256":"b88ed9e7b0733eb7e8cd0d8309d6980e8a1a2892a70028fc63aad36e3a24a3fa","crop":{"left":0,"bottom":488.4957,"width":259.848599999999