  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 128, 'CIENCIAS_NATUREZA', 'Em 2008, o governo federal aprovou o Programa Nacional de Plantas Medicinais e Fitoterápicos, que apoia o desenvolvimento de projetos de qualidade que contemplam o cultivo e beneficiamento de plantas medicinais. Esse programa permite a expansão da oferta desses produtos para o Sistema Único de Saúde (SUS) e, consequentemente, o fortalecimento do desenvolvimento ambiental, social e econômico do país. RICARDO, L. M.; GOULART, E. M. A.; BRANDÃO, M. G. L. Plantas medicinais da Bacia do Rio das Velhas: avaliação das condições para produção e uso em saúde pública. Rev. Bras. Pl. Med. , n. 3, 2015 (adaptado). Esse programa tende a reduzir a', '["participação popular.","geração de emprego e renda.","adoção de opções terapêuticas.","utilização sustentável da biodiversidade.","dependência de grandes empresas farmacêuticas."]'::jsonb, '"dependência de grandes empresas farmacêuticas."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"be53c36b9dd91d52d82df80cfca7bd909059e8651321f09b9caa936681e27965","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"e5c7ca4961ac8d09b68f3dec0e3018f8c32ac7a4f99a857d470b7c9fd2c33978","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":128,"language":null,"page":13,"storagePath":"2025-D6-CD5/question-128-COMMON/statement-page-13.png","sha256":"342ad655fb4f7aaa2f24a370990cf654dd67c978cfb7e9c38c4cb100b04df6ca","crop":{"left":0,"bottom":133.4336,"width":240.87139999999988,"height":137.64569999999998}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":128,"language":null,"source_page":13,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 128, subject_area = 'CIENCIAS_NATUREZA', statement = 'Em 2008, o governo federal aprovou o Programa Nacional de Plantas Medicinais e Fitoterápicos, que apoia o desenvolvimento de projetos de qualidade que contemplam o cultivo e beneficiamento de plantas medicinais. Esse programa permite a expansão da oferta desses produtos para o Sistema Único de Saúde (SUS) e, consequentemente, o fortalecimento do desenvolvimento ambiental, social e econômico do país. RICARDO, L. M.; GOULART, E. M. A.; BRANDÃO, M. G. L. Plantas medicinais da Bacia do Rio das Velhas: avaliação das condições para produção e uso em saúde pública. Rev. Bras. Pl. Med. , n. 3, 2015 (adaptado). Esse programa tende a reduzir a', options = '["participação popular.","geração de emprego e renda.","adoção de opções terapêuticas.","utilização sustentável da biodiversidade.","dependência de grandes empresas farmacêuticas."]'::jsonb, correct_answer = '"dependência de grandes empresas farmacêuticas."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"be53c36b9dd91d52d82df80cfca7bd909059e8651321f09b9caa936681e27965","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"e5c7ca4961ac8d09b68f3dec0e3018f8c32ac7a4f99a857d470b7c9fd2c33978","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":128,"language":null,"page":13,"storagePath":"2025-D6-CD5/question-128-COMMON/statement-page-13.png","sha256":"342ad655fb4f7aaa2f24a370990cf654dd67c978cfb7e9c38c4cb100b04df6ca","crop"