  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c66da27f17153af39c75bf464ef95b8d229cf44e1528bb05876c17d7109ac1e5' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 133, 'CIENCIAS_NATUREZA', 'O complexo mecanismo da visão humana depende de uma reação de isomerização da molécula do retinal quando ligada à proteína opsina, estimulada pela incidência de luz, conforme o esquema. MARTINS, G. B. C.; SUCUPIRA, R. R.; SUAREZ, P. A. Z. A química e as cores. Revista Virtual de Química , n. 7, 2015 (adaptado). Portanto, o tipo de isomeria responsável pela visão humana é a', '["óptica.","de cadeia.","de posição.","geométrica.","de compensação."]'::jsonb, '"geométrica."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"c66da27f17153af39c75bf464ef95b8d229cf44e1528bb05876c17d7109ac1e5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fa5dfddf49df6157ec55081de4b469cd61f1760391ae5b628c9b3814b8e0bad9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":133,"language":null,"page":15,"storagePath":"2025-D6-CD5/question-133-COMMON/statement-page-15.png","sha256":"dfca5981f0e7bb46eb13dc93efaed0a3ad091b8f1e6ff8f86eeff63a272baccd","crop":{"left":0,"bottom":583.3182,"width":269.05364999999983,"height":158.43179999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":133,"language":null,"source_page":15,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 133, subject_area = 'CIENCIAS_NATUREZA', statement = 'O complexo mecanismo da visão humana depende de uma reação de isomerização da molécula do retinal quando ligada à proteína opsina, estimulada pela incidência de luz, conforme o esquema. MARTINS, G. B. C.; SUCUPIRA, R. R.; SUAREZ, P. A. Z. A química e as cores. Revista Virtual de Química , n. 7, 2015 (adaptado). Portanto, o tipo de isomeria responsável pela visão humana é a', options = '["óptica.","de cadeia.","de posição.","geométrica.","de compensação."]'::jsonb, correct_answer = '"geométrica."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"c66da27f17153af39c75bf464ef95b8d229cf44e1528bb05876c17d7109ac1e5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"fa5dfddf49df6157ec55081de4b469cd61f1760391ae5b628c9b3814b8e0bad9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":133,"language":null,"page":15,"storagePath":"2025-D6-CD5/question-133-COMMON/statement-page-15.png","sha256":"dfca5981f0e7bb46eb13dc93efaed0a3ad091b8f1e6ff8f86eeff63a272baccd","crop":{"left":0,"bottom":583.3182,"width":269.05364999999983,"height":158.43179999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":133,"language":null,"source_page