  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'dfca5981f0e7bb46eb13dc93efaed0a3ad091b8f1e6ff8f86eeff63a272baccd', 'STATEMENT_CROP', 15, '2025-D6-CD5/question-133-COMMON/statement-page-15.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"dfca5981f0e7bb46eb13dc93efaed0a3ad091b8f1e6ff8f86eeff63a272baccd","crop":{"left":0,"bottom":583.3182,"width":269.05364999999983,"height":158.43179999999995},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '657d5a21360a349ccd2c8763105b7761d7e2e644fa8690b92f76f5ecc6b54c0b' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 134, 'CIENCIAS_NATUREZA', 'As infecções parasitárias dos intestinos, de acordo com a sua prevalência, refletem com boa margem de segurança as condições de vida de diferentes comunidades. Por exemplo, em regiões onde a criação de gado corresponde à principal atividade econômica, uma das parasitoses mais comuns é a teníase, causada pela Taenia saginata . CHIEFFI, P. P.; AMATO NETO, V. Vermes, verminoses e saúde pública. Revista Ciência e Cultura , n. 1, 2003 (adaptado). Nesse sentido, para reduzir a incidência dessa verminose na comunidade, uma ação eficiente é', '["promover a vacinação do gado.","controlar a população de vetores.","tratar com hipoclorito de sódio a água consumida.","construir redes de saneamento básico.","evitar contato humano com solos contaminados."]'::jsonb, '"construir redes de saneamento básico."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"657d5a21360a349ccd2c8763105b7761d7e2e644fa8690b92f76f5ecc6b54c0b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"4984a22199ea0312a5fd943a6b1a892bd54a14608b8aebe5d5bdae638d7174c7","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":134,"language":null,"page":15,"storagePath":"2025-D6-CD5/question-134-COMMON/statement-page-15.png","sha256":"32a3a6dd49ab4cf0f9b63d7a13c30adbe644a0bf35f29f7