  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0e26b70db62f7c025beded06cdd34fb2292e57ab38e3aee7abe89a8736911e72' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 137, 'MATEMATICA', 'Uma empresa foi contratada para realizar a instalação de placas fotovoltaicas em um condomínio residencial no prazo de 14 dias. Essa empresa iniciou a instalação com 4 funcionários de mesmo rendimento, atuando em jornadas de trabalho de 8 horas 2 diárias. Ao finalizar o 10º dia de trabalho, apenas da instalação haviam sido concluídos. 5 Preocupado com o cumprimento do prazo estipulado, o gerente da empresa decidiu contratar mais funcionários com rendimento igual ao dos já contratados, e que todos deveriam atuar em jornadas de trabalho de 10 horas diárias. Para concluir a instalação no prazo estipulado, o número mínimo de funcionários a mais que o gerente irá contratar é', '["1.","2.","5.","8.","9."]'::jsonb, '"8."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"0e26b70db62f7c025beded06cdd34fb2292e57ab38e3aee7abe89a8736911e72","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"57bd57734143bd711cbc3fbb61146ed45cbd028532bc439b8da93d2a0548e0b0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":137,"language":null,"page":16,"storagePath":"2025-D6-CD5/question-137-COMMON/statement-page-16.png","sha256":"a3ac7627d3c572280542af3bc65ff8a75ff5c5b91b5e6bad3123d3adca2a2529","crop":{"left":0,"bottom":299.9357,"width":311.6357499999989,"height":123.76549999999997}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":137,"language":null,"source_page":16,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
