  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '47002fdf3874042392f246d2c434f8c8619b6d1b5cf151ebec57f1f6e7425e62' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 138, 'MATEMATICA', 'Uma loja de artigos esportivos fez a seguinte promoção: para cada compra com valor superior a R$ 500,00 realizada na loja, o cliente retira aleatoriamente uma única ficha de uma urna para receber um brinde. A urna contém 20 fichas brancas, 30 azuis e 50 vermelhas, todas com igual probabilidade de serem retiradas. O gerente dessa loja acrescentará algumas fichas brancas a essa urna, de modo que a probabilidade de a primeira ficha retirada ser branca seja superior a 50%. Qual é a quantidade mínima de fichas brancas que ele acrescentará à urna?', '["81","61","41","31","21"]'::jsonb, '"61"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"47002fdf3874042392f246d2c434f8c8619b6d1b5cf151ebec57f1f6e7425e62","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"925747f48509d116a78a07513c291908ae31999e9429ff312b20a545caa453f9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":138,"language":null,"page":16,"storagePath":"2025-D6-CD5/question-138-COMMON/statement-page-16.png","sha256":"0d06ed67471905b6fc5ab47fc794e0c3035d162a9d844c3991e0544a5cccef44","crop":{"left":0,"bottom":130.8432,"width":311.6357499999989,"height":113.21350000000001}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":138,"language":null,"source_page":16,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 138, subject_area = 'MATEMATICA', statement = 'Uma loja de artigos esportivos fez a seguinte promoção: para cada compra com valor superior a R$ 500,00 realizada na loja, o cliente retira aleatoriamente uma única ficha de uma urna para receber um brinde. A urna contém 20 fichas brancas, 30 azuis e 50 vermelhas, todas com igual probabilidade de serem retiradas. O gerente dessa loja acrescentará algumas fichas brancas a essa urna, de modo que a probabilidade de a primeira ficha retirada ser branca seja superior a 50%. Qual é a quantidade mínima de fichas brancas que ele acrescentará à urna?', options = '["81","61","41","31","21"]'::jsonb, correct_answer = '"61"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"47002fdf3874042392f246d2c434f8c8619b6d1b5cf151ebec57f1f6e7425e62","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"925747f48509d116a78a07513c291908ae31999e9429ff312b20a545caa453f9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":138,"language":null,"page":16,"storagePath":"2025-D6-CD5/question-138-COMMON/statement-page-16.png","sha256":"0d06ed67471905b6fc5ab47fc794e0c3035d162a9d844c3991e0544a5cccef44","crop":{"left":0,"bottom":130.8432,"width":311.6357499999989,"height":113.21350000000001}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,