  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '43787d7b2001dceed78dc674ce6d2a619f7af920c778d6e41b630fee29492f7a' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 145, 'MATEMATICA', 'Os egípcios utilizavam um dos sistemas de escrita numérica Uma fábrica de televisores de tela plana vende esse produto mais antigos, datado aproximadamente de 3500 a.C. Esse sistema a lojistas pelo valor unitário de R$ 1 200,00. Inicialmente, trabalhava com agrupamentos não posicionais. O quadro a gerência de uma loja planeja efetuar um pedido de 40 unidades apresenta alguns dos símbolos utilizados e seus respectivos de televisores para a fábrica. Uma transportadora cobra valores equivalentes. R$ 12 000,00 para o transporte de até 120 televisores. A gerência da loja decide aumentar a quantidade de televisores no pedido, de forma a reduzir em 60% o custo do frete por televisor em relação ao inicialmente planejado. O valor, em real, que a loja necessitará gastar a mais com a quantidade de televisores a serem adquiridos, em relação ao inicialmente planejado, é', '["19 200,00.","28 800,00.","32 400,00.","72 000,00.","96 000,00."]'::jsonb, '"72 000,00."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"43787d7b2001dceed78dc674ce6d2a619f7af920c778d6e41b630fee29492f7a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"e0d9998ea1ade639596a0a8bd9d4cd311e4c8b09d0f161bfbf9dcd5dbabe40d6","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":145,"language":null,"source_page":19,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 145, subject_area = 'MATEMATICA', statement = 'Os egípcios utilizavam um dos sistemas de escrita numérica Uma fábrica de televisores de tela plana vende esse produto mais antigos, datado aproximadamente de 3500 a.C. Esse sistema a lojistas pelo valor unitário de R$ 1 200,00. Inicialmente, trabalhava com agrupamentos não posicionais. O quadro a gerência de uma loja planeja efetuar um pedido de 40 unidades apresenta alguns dos símbolos utilizados e seus respectivos de televisores para a fábrica. Uma transportadora cobra valores equivalentes. R$ 12 000,00 para o transporte de até 120 televisores. A gerência da loja decide aumentar a quantidade de televisores no pedido, de forma a reduzir em 60% o custo do frete por televisor em relação ao inicialmente planejado. O valor, em real, que a loja necessitará gastar a mais com a quantidade de televisores a serem adquiridos, em relação ao inicialmente planejado, é', options = '["19 200,00.","28 800,00.","32 400,00.","72 000,00.","96 000,00."]'::jsonb, correct_answer = '"72 000,00."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"43787d7b2001dceed78dc674ce6d2a619f7af920c778d6e41b630fee29492f7a","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"e0d9998ea1ade639596a0a8bd9d4cd311e4c8b09d0f161bfbf9dcd5dbabe40d6","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":145,"language":null,"source_page":19,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
