  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0592bb02f7a3d1dd300c3a0f77f32ffe36da2909d45768b1b0492a6af6504d2d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 146, 'MATEMATICA', 'Assim, a representação do número 12 023, em símbolos Por causa da escassez de água, a companhia de egípcios, é: abastecimento de um município adotou uma medida de 4 3 12 023 = 1 ⋅ (10) + 2 ⋅ (10) + 2 ⋅ (10) + 3 = contenção de consumo. A medida consiste em calcular o acréscimo de consumo de água em um dos meses desse ano, Disponível em: www.matematica.br. Acesso em: 24 ago. 2014 (adaptado). em relação ao volume de água consumida no mesmo mês do No sistema egípcio, qual é a representação do número 2 030? ano anterior, para determinar o aumento a ser implementado na conta. Em função da faixa em que esse acréscimo de A consumo se enquadrar, aplicam-se diferentes percentuais de aumento ao valor mensal a ser pago, em real. Para acréscimos B de consumo de até 20%, o aumento no valor mensal da conta é de 50%, e para acréscimos de consumo superiores a 20%, C o aumento no valor mensal da conta é de 100%. Uma família, em determinado mês desse ano, consumiu 25% a mais de água em comparação ao consumo do mesmo D mês do ano anterior. Com isso, o valor da conta de água dessa família seria de R$ 120,00, caso a companhia não estivesse E adotando a medida de contenção de consumo. Qual é o valor a ser pago, em real, por essa família no referido mês com a aplicação de medida de contenção de consumo?', '["60,00","80,00","150,00","180,00","240,00"]'::jsonb, '"240,00"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"0592bb02f7a3d1dd300c3a0f77f32ffe36da2909d45768b1b0492a6af6504d2d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"68ea2b77ece6d772659f4dba857c8998023d24e16627318e8b48602c1a1d83c9","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":146,"language":null,"page":19,"storagePath":"2025-D6-CD5/question-146-COMMON/statement-page-19.png","sha256":"4c1e27aac1d54ee9b3e5ee4846425c93c5f617a1b25de487f09e5bcfe1631ac3","crop":{"left":272.0157499999991,"bottom":384.1996,"width":294.9117500000009,"height":119.75200000000001}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":146,"language":null,"source_page":19,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 146, subject_area = 'MATEMATICA', statement = 'Assim, a representação do número 12 023, em símbolos Por causa da escassez de água, a companhia de egípcios, é: abastecimento de um município adotou uma medida de 4 3 12 023 = 1 ⋅ (10) + 2 ⋅ (10) + 2 ⋅ (10) + 3 = contenção de consumo. A medida consiste em calcular o acréscimo de consumo de água em um dos meses desse ano, Disponível em: www.matematica.br. Acesso em: 24 ago. 2014 (adaptado). em relação ao volume de água consumida no mesmo mês do No sistema egípcio, qual é a representação do número 2 030? ano anterior, para determinar o aumento a ser implementado na conta. Em função da faixa em que esse acréscimo de A consumo se enquadrar, aplicam-se diferentes percentuais de aumento ao valor mensal a ser pago, em real. Para acréscimos B de consumo de até 20%, o aumento no valor mensal da conta é de 50%, e para acréscimos de consumo superiores a 20%, C o aumento no valor mensal da conta é de 100%. Uma família, em determinado mês desse ano, consumiu 25% a mais de água em comparação ao consumo do mesmo D mês do ano anterior. Com isso, o valor da conta de água dessa família seria de R$ 120,00, caso a companhia não estivesse E adotando a medida de contenção de consumo. Qual é o valor a ser pago, em real, por essa família no referido mês com a aplicação de medida de contenção de consumo?', options = '["60,00","80,00","150,00","180,00","240,00"]'::jsonb, correct_answer = '"240,00"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"0592bb02f7a3d1dd300c3a0f77f32ffe36da2909d45768b1b0492a6af6504d2d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"en