  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 163, 'MATEMATICA', 'Um país decidiu investir em programas de reeducação alimentar da população adulta de suas cidades. Foram cinco os níveis de investimento, distribuídos de acordo com a idade média da população obesa em cada cidade, conforme o quadro. Idade média da Nível de investimento população obesa ( M ) I M ≥ 50 II 42 < M < 50 III 37 < M ≤ 42 IV 30 < M ≤ 37 V M ≤ 30 Em uma cidade desse país, 70% da população obesa era composta por homens. A média de idade dos homens obesos era de 50 anos, e a média de idade das mulheres obesas era de 30 anos. O nível de investimento recebido por essa cidade foi o', '["I.","II.","III.","IV.","V."]'::jsonb, '"II."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"8a3047c941085137b50f428abf6d2d650d472dd11324231014856976d504c09b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"c3e63d657a099f2dab041e5b996aa188da460b73c7d6e73ff114736c8676632e","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":163,"language":null,"page":25,"storagePath":"2025-D6-CD5/question-163-COMMON/statement-page-25.png","sha256":"2100d686732b8818dd140155306c602906e3d111fa69d383f9d2db85be9a67d5","crop":{"left":0,"bottom":509.3426999999999,"width":265.46029999999996,"height":232.40730000000008}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":163,"language":null,"source_page":25,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 163, subject_area = 'MATEMATICA', statement = 'Um país decidiu investir em programas de reeducação alimentar da população adulta de suas cidades. Foram cinco os níveis de investimento, distribuídos de acordo com a idade média da população obesa em cada cidade, conforme o quadro. Idade média da Nível de investimento população obesa ( M ) I M ≥ 50 II 42 < M < 50 III 37 < M ≤ 42 IV 30 < M ≤ 37 V M ≤ 30 Em uma cidade desse país, 70% da população obesa era composta por homens. A média de idade dos homens obesos era de 50 anos, e a média de idade das mulheres obesas era de 30 anos. O nível de investimento recebido por essa cidade foi o', options = '["I.","II.","III.","IV.","V."]'::jsonb, correct_answer = '"II."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"8a3047c941085137b50f428abf6d2d650d472dd11324231014856976d504c09b","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"c3e63d657a099f2dab041e5b996aa188da460b73c7d6e73ff114736c8676632e","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":163,"language":null,"page":25,"storagePath":"2025-D6-CD5/question-163-COMMON/statement-page-25.png","sha256":"2100d686732b8818dd140155306c602906e3d111fa69d383f9d2db85be9a67d5","crop":{"left":0,"bottom":509.3426999999999,"width":265.46029999999996,"height":232.40730000000008}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_c