  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '618023b80315c5221849c6503b8fee09f8b7783be19b1ca89d1d7b31b7eae662', 'STATEMENT_CROP', 26, '2025-D6-CD5/question-165-COMMON/statement-page-26.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"618023b80315c5221849c6503b8fee09f8b7783be19b1ca89d1d7b31b7eae662","crop":{"left":0,"bottom":566.9868,"width":280.2781749999999,"height":174.76319999999998},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e714065cfe0610d69c1f3355e66824e72e61f8d42e13b04c8443b038add43fb6' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 168, 'MATEMATICA', 'Um mestre de obras coordena o andamento da construção de uma pequena ponte. Esse trabalho estava inicialmente sendo realizado por 24 profissionais, com um mesmo rendimento r , que completariam a obra em um determinado prazo. Entretanto, durante o andamento da obra, 18 deles abandonaram o serviço e os demais continuaram trabalhando com rendimento r . Para terminar a obra exatamente no prazo estabelecido, o mestre de obras solicitou ao setor de recursos humanos (RH) da empresa a contratação de novos profissionais. Para isso, o RH sugeriu que fossem contratados menos profissionais e ofereceu as seguintes opções de contratação, indicando o rendimento desses profissionais em relação ao rendimento dos que saíram. • Opção I: contratar 6 profissionais com rendimento igual a 2 r . • Opção II: contratar 8 profissionais com rendimento igual a 2,2 r . • Opção III: contratar 9 profissionais com rendimento igual a 1,5 r . • Opção IV: contratar 12 profissionais com rendimento igual a 1,5 r . • Opção V: contratar 15 profissionais com rendimento igual a 2 r . O mestre de obras deverá escolher a opção que permita terminar a obra dentro do prazo e com o menor número de profissionais. Nessas condições, a escolha do mestre de obras deverá ser a opção', '["I.","II.","III.","IV.","V."]'::jsonb, '"IV."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"e714065cfe0610d69c1f3355e66824e72e61f8d42e13b04c8443b038add43fb6","source_integrity":"VERIFIED","render_mode":"HYBRID","render_