  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 168, subject_area = 'MATEMATICA', statement = 'Um mestre de obras coordena o andamento da construção de uma pequena ponte. Esse trabalho estava inicialmente sendo realizado por 24 profissionais, com um mesmo rendimento r , que completariam a obra em um determinado prazo. Entretanto, durante o andamento da obra, 18 deles abandonaram o serviço e os demais continuaram trabalhando com rendimento r . Para terminar a obra exatamente no prazo estabelecido, o mestre de obras solicitou ao setor de recursos humanos (RH) da empresa a contratação de novos profissionais. Para isso, o RH sugeriu que fossem contratados menos profissionais e ofereceu as seguintes opções de contratação, indicando o rendimento desses profissionais em relação ao rendimento dos que saíram. • Opção I: contratar 6 profissionais com rendimento igual a 2 r . • Opção II: contratar 8 profissionais com rendimento igual a 2,2 r . • Opção III: contratar 9 profissionais com rendimento igual a 1,5 r . • Opção IV: contratar 12 profissionais com rendimento igual a 1,5 r . • Opção V: contratar 15 profissionais com rendimento igual a 2 r . O mestre de obras deverá escolher a opção que permita terminar a obra dentro do prazo e com o menor número de profissionais. Nessas condições, a escolha do mestre de obras deverá ser a opção', options = '["I.","II.","III.","IV.","V."]'::jsonb, correct_answer = '"IV."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"e714065cfe0610d69c1f3355e66824e72e61f8d42e13b04c8443b038add43fb6","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"ca1d58ee09f147606dac3dde7b7cd2470cc740e2694a3d6750bbb503b159cf77","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":168,"language":null,"page":27,"storagePath":"2025-D6-CD5/question-168-COMMON/statement-page-27.png","sha256":"0122b2573b7767a654201420effc28b8a0e1f223129a6a89c46c1bb540a32d7f","crop":{"left":0,"bottom":134.9698,"width":268.5599999999999,"height":219.3459}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":168,"language":null,"source_page":27,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
