  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '0122b2573b7767a654201420effc28b8a0e1f223129a6a89c46c1bb540a32d7f', 'STATEMENT_CROP', 27, '2025-D6-CD5/question-168-COMMON/statement-page-27.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"0122b2573b7767a654201420effc28b8a0e1f223129a6a89c46c1bb540a32d7f","crop":{"left":0,"bottom":134.9698,"width":268.5599999999999,"height":219.3459},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '5371857b7fd5a7850115ac8db53b5614753fd6920163c9976f0bd59abd61e223' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 169, 'MATEMATICA', 'Em um país, todos os produtos comercializados estão associados a uma única sequência numérica de 13 dígitos, e cada sequência numérica pode ser representada por um código de barras. Essas sequências são formadas de acordo com as seguintes regras: • os três primeiros dígitos são associados ao país que comercializa o produto. Esses dígitos são 7, 8 e 9 (nessa ordem); • dígitos nas posições quatro a nove identificam a empresa que comercializa o produto. Eles assumem os valores 4, 5, 6 ou 7; • dígitos nas posições dez a doze identificam o produto. Eles podem ser qualquer algarismo de 0 a 9. O último dígito, chamado de dígito verificador, é consequência dos doze primeiros, sendo obtido por meio de operações, previamente definidas, realizadas com os doze primeiros. Quantos diferentes códigos de barras podem estar associados a produtos comercializados nesse país? 6 3', '["4 × 9 6 3","4 × 10 6 3","10 × 10 6 3","3! × 4 × 10","(6 × 4) × (10 × 3)"]'::jsonb, '"4 × 10 6 3"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"5371857b7fd5a7850115ac8db53b5614753fd6920163c9976f0bd59abd61e223","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"7d382cdfecbf5b6ead82637cb02648ec3ccb8b8114d9d82feeb52fcaac99e669","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":169,"language":null,"page":28,"storagePath":"2025-D6-CD5/question-169-COMMON/statement-page-28.png","sha256":"3b21864fc44dc99ad73edc2610cde93029a92c190401d4358725aa009dbafc98","crop":{"left":0,"bottom":571.1555,"width":302.17474999999973,"height":170.59450000000004}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":169,"language":null,"source_page":28,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 169, subject_area = 'MATEMATICA', statement = 'Em um país, todos os produtos comercializados estão associados a uma única sequência numérica de 13 dígitos, e cada sequência numérica pode ser representada por um código de barras. Essas sequências são formadas de acordo com as seguintes regras: • os três primeiros dígitos são associados ao país que comercializa o produto. Esses dígitos são 7, 8 e 9 (nessa ordem); • dígitos nas posições quatro a nove identificam a empresa que comercializa o produto. Eles assumem os valores 4, 5, 6 ou 7; • dígitos nas posições dez a doze identificam o produto. Eles podem ser qualquer algarismo de 0 a 9. O último dígito, chamado de dígito verificador, é consequência dos doze primeiros, sendo obtido por meio de operações, previamente definidas, realizadas com os doze primeiros. Quantos diferentes códigos de barras podem estar associados a produtos comercializados nesse país? 6 3', options = '["4 × 9 6 3","4 × 10 6 3","10 × 10 6 3","3! × 4 × 10","(6 × 4) × (10 × 3)"]'::jsonb, correct_answer = '"4 × 10 6 3"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"5371857b7fd5a7850115ac8db53b5614753fd6920163c9976f0bd59abd61e223","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"7d382cdfecbf5b6ead82637cb02648ec3ccb8b8114d9d82feeb52fcaac99e669","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":169,"language":null,"page":28,"storagePath":"2025-D6-CD5/question-169-COMMON/statement-page-28.png","sha256":"3b21864fc44dc99ad73edc2610cde93029a92c190401d4358725aa009dbafc98","crop":{"left":0,"bottom":571.1555,"width":302.17474999999973,"height":170.59450000000004}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":169,"language":null,"source_page":28,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
