  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '3b21864fc44dc99ad73edc2610cde93029a92c190401d4358725aa009dbafc98', 'STATEMENT_CROP', 28, '2025-D6-CD5/question-169-COMMON/statement-page-28.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"3b21864fc44dc99ad73edc2610cde93029a92c190401d4358725aa009dbafc98","crop":{"left":0,"bottom":571.1555,"width":302.17474999999973,"height":170.59450000000004},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '57e3524565f63f329af51512ae42af95127aabb5a6e6e3502d0649c4ab562db8' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 170, 'MATEMATICA', 'Com o intuito de revestir o piso de uma sala retangular, com 8 m de largura por 4 m de comprimento, um construtor dirigiu-se a uma loja de revestimentos. Ao chegar à loja, constatou que dois tipos de porcelanato estavam com preços promocionais, caso fossem comprados em caixas fechadas, sem fracionamento. O quadro apresenta as características dos porcelanatos em promoção, como tamanho das peças, preço por caixa e quantidade de peças em cada caixa. Tipo Tamanho das peças (cm) Preço da caixa (R$) Quantidade de peças por caixa 1 40 × 40 6,00 2 2 80 × 80 70,00 5 O construtor pretende adquirir o tipo de porcelanato que apresente o menor custo para revestir todo o piso da sala. Para garantir o menor custo, o construtor deve comprar o porcelanato do tipo', '["1, pois apresenta valor unitário por peça menor do que o tipo 2.","2, pois utilizará 10 caixas, enquanto seriam necessárias 100 caixas do tipo 1.","1, pois gastará R$ 600,00, enquanto com as peças do tipo 2 gastaria R$ 700,00.","2, pois serão necessárias 50 peças, enquanto seriam necessárias 200 peças do tipo 1.","2, pois a quantidade de peças por caixa e o tamanho das peças são maiores do que as do tipo 1."]'::jsonb, '"1, pois gastará R$ 600,00, enquanto com as peças do tipo 2 gastaria R$ 700,00."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"57e3524565f63f329af51512ae42af95127aabb5a6e6e3502d0649c4ab562db8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"259bc176558ce9b94f16efd2e202098c19357b3dbfb1d48a15538432c249ae16","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":170,"language":null,"page":28,"storagePath":"2025-D6-CD5/question-170-COMMON/statement-page-28.png","sha256":"c0093e34d3ff976535bcada686113f0b4bb8565359ccf96ccaea925e9b9d106c","crop":{"left":0,"bottom":341.1889,"width":302.17474999999973,"height":181.0934000000001}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":170,"language":null,"source_page":28,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 170, subject_area = 'MATEMATICA', statement = 'Com o intuito de revestir o piso de uma sala retangular, com 8 m de largura por 4 m de comprimento, um construtor dirigiu-se a uma loja de revestimentos. Ao chegar à loja, constatou que dois tipos de porcelanato estavam com preços promocionais, caso fossem comprados em caixas fechadas, sem fracionamento. O quadro apresenta as características dos porcelanatos em promoção, como tamanho das peças, preço por caixa e quantidade de peças em cada caixa. Tipo Tamanho das peças (cm) Preço da caixa (R$) Quantidade de peças por caixa 1 40 × 40 6,00 2 2 80 × 80 70,00 5 O construtor pretende adquirir o tipo de porcelanato que apresente o menor custo para revestir todo o piso da sala. Para garantir o menor custo, o construtor deve comprar o porcelanato do tipo', options = '["1, pois apresenta valor unitário por peça menor do que o tipo 2.","2, pois utilizará 10 caixas, enquanto seriam necessárias 100 caixas do tipo 1.","1, pois gastará R$ 600,00, enquanto com as peças do tipo 2 gastaria R$ 700,00.","2, pois serão necessárias 50 peças, enquanto seriam necessárias 200 peças do tipo 1.","2, pois a quantidade de peças por caixa e o tamanho das peças são maiores do que as do tipo 1."]'::jsonb, correct_answer = '"1, pois gastará R$ 600,00, enquanto com as peças do tipo 2 gastaria R$ 700,00."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"57e3524565f63f329af51512ae42af95127aabb5a6e6e3502d0649c4ab562db8","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"259bc176558ce9b94f16efd2e202098c19357b3dbfb1d48a15538432c249ae16","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":170,"language":null,"page":28,"storagePath":"2025-D6-CD5/question-170-COMMON/statement-page-28.png","sha256":"c0093e34d3ff976535bcada686113f0b4bb8565359ccf96ccaea925e9b9d106c","crop":{"left":0,"bottom":341.1889,"width":302.17474999999973,"height":181.0934000000001}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":170,"language":null,"source_page":28,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
