  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'e305c22fda4bf87755214f4b6635e85104e43b708d73593089f4792162759aa4' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 172, 'MATEMATICA', 'Uma locadora de veículos possui uma frota distribuída em todas as cinco regiões brasileiras. Um levantamento indica que 18% dessa frota está no Nordeste, 12% encontra-se na região Centro-Oeste, e as regiões Sul e Norte, juntas, correspondem a 3 da frota. Objetivando concentrar um quantitativo maior de veículos no Sudeste, a região mais populosa do Brasil, a gerência 8 da locadora estabelece que nessa região deverão estar 40% da frota total de veículos, e que um percentual do total da frota das regiões Sul e Norte deverá para lá ser transferido. Qual percentual da frota total das regiões Sul e Norte deverá ser transferido?', '["4%","7,5%","14%","20%","23%"]'::jsonb, '"20%"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"e305c22fda4bf87755214f4b6635e85104e43b708d73593089f4792162759aa4","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"5828c4a658e48722c81cdabb3b04e13acd2d2edddecc721d47989ef88cfc5fae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":172,"language":null,"page":29,"storagePath":"2025-D6-CD5/question-172-COMMON/statement-page-29.png","sha256":"147e0f8f50aeddcbeb1f23bd3919ffab6f5a3e8324fcbdf821f38eeb5ef6337f","crop":{"left":0,"bottom":612.4080000000001,"width":242.57569999999993,"height":129.34199999999987}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":172,"language":null,"source_page":29,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2025, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D6', source_number = 172, subject_area = 'MATEMATICA', statement = 'Uma locadora de veículos possui uma frota distribuída em todas as cinco regiões brasileiras. Um levantamento indica que 18% dessa frota está no Nordeste, 12% encontra-se na região Centro-Oeste, e as regiões Sul e Norte, juntas, correspondem a 3 da frota. Objetivando concentrar um quantitativo maior de veículos no Sudeste, a região mais populosa do Brasil, a gerência 8 da locadora estabelece que nessa região deverão estar 40% da frota total de veículos, e que um percentual do total da frota das regiões Sul e Norte deverá para lá ser transferido. Qual percentual da frota total das regiões Sul e Norte deverá ser transferido?', options = '["4%","7,5%","14%","20%","23%"]'::jsonb, correct_answer = '"20%"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', metadata = '{"canonical_id":"e305c22fda4bf87755214f4b6635e85104e43b708d73593089f4792162759aa4","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"5828c4a658e48722c81cdabb3b04e13acd2d2edddecc721d47989ef88cfc5fae","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":172,"language":null,"page":29,"storagePath":"2025-D6-CD5/question-172-COMMON/statement-page-29.png","sha256":"147e0f8f50aeddcbeb1f23bd3919ffab6f5a3e8324fcbdf821f38eeb5ef6337f","crop":{"left":0,"bottom":612.4080000000001,"width":242.57569999999993,"height":129.34199999999987}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_a