  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '147e0f8f50aeddcbeb1f23bd3919ffab6f5a3e8324fcbdf821f38eeb5ef6337f', 'STATEMENT_CROP', 29, '2025-D6-CD5/question-172-COMMON/statement-page-29.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"147e0f8f50aeddcbeb1f23bd3919ffab6f5a3e8324fcbdf821f38eeb5ef6337f","crop":{"left":0,"bottom":612.4080000000001,"width":242.57569999999993,"height":129.34199999999987},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '892379035973104dc3457d28db528c4a0cb34e5c58e4fa5dd4b44f9e79496251' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 176, 'MATEMATICA', 'Uma fábrica produzia e vendia 200 000 garrafas de 2 litros Uma pessoa comprará uma tinta especial para pintar, de um suco. O administrador da fábrica decidiu aumentar com apenas uma demão, uma parede que tem medida de 2 2 a produção de suco em 20%, utilizando garrafas de menor 320 m de área. Para pintar uma área de 10 m , é necessário exatamente 1 L de tinta. Em uma loja, essa tinta está em capacidade. Com isso, precisou aumentar em 60% a quantidade promoção e é vendida em latas de diversas capacidades, mas só de garrafas utilizadas, em relação à quantidade inicial, de modo é possível comprar latas do mesmo tipo. A pessoa tem como a conseguir envazar todo o suco produzido. objetivo gastar o menor valor possível, em real, com a compra Qual é a quantidade máxima de suco, em litro, que deverá ser dessa tinta e observa os seguintes dados referentes aos tipos reduzida na nova embalagem, em relação à de 2 litros? de latas disponíveis:', '["0,4 • I: contém 0,6 L de tinta e custa R$ 18,00; • II: contém 0,8 L de tinta e custa R$ 23,00;","0,5 • III: contém 1,0 L de tinta e custa R$ 29,00;","0,6 • IV: contém 3,0 L de tinta e custa R$ 85,00;","0,8 • V: contém 5,0 L de tinta e custa R$ 150,00.","1,2"]'::jsonb, '"0,5 • III: contém 1,0 L de tinta e custa R$ 29,00;"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"892379035973104dc3457d28db528c4a0cb34e5c58e4fa5dd4b44f9e79496251","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"ad14737096bd5a9de27a456531fdd26ee2ca113097bfd11ff3bdef0883fbefda","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2025,"exam":"ENEM","application":"REGULAR","day":"D6","booklet":"CD5","question_number":176,"language":null,"source_page":30,"source_sha256":"851a99e7802fab47256f050e755b5b24389dfc35bea3fe20176ac10a47bf09f2"}}'::jsonb, true) returning id into v_question_id; end if;
