  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd36198273c53d5c91ced69a1942c1397569a7999f4aea065c991ccdbed4ced48' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2025, 'ENEM', 'REGULAR', 'D6', 177, 'MATEMATICA', 'sistema nesse período. O esquema apresenta dois postes de 6 metros de altura Investimentos no Sistema Nacional sobre um solo horizontal, com um fio elétrico passando pelos pontos A e B , distando 8 metros entre si, que representam os de Transplantes (2007-2012) extremos superiores de cada poste. Considerando o ponto A como origem do plano cartesiano Disponível em: http://portalsaude.saude.gov.br. e o segmento AB contido no eixo horizontal desse plano, admita Acesso em: 29 mar. 2014. que a curva que o fio elétrico forma entre A e B seja modelada 2 pela função quadrática y = 0,02 x – 0,16 x , com x e y em metro. Se esse aumento percentual tivesse ocorrido, o valor mais próximo ao do investimento, em real, nesse sistema em 2013 teria sido de A menor distância, em metro, dessa parte do fio até o solo é A 1 498,00.', '["5,36.","1 600,00. B 5,68.","1 680,00. C 5,84.","2 087,00. D 5,98.","2 744,00. E 5,99."]'::jsonb, '"1 600,00. B 5,68."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2025', '{"canonical_id":"d36198273c53d5c91ced69a1942c1397569a7999f4aea065c991ccdbed4ced48","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"ec76c7f2f2d791ce28348d2bc95b569691e9633496af57b8e38c60e291517710","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":177,"language":