  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '6d293341b7aaa0e55eb70090eed388439bc662b3e41af63e1b8f4c85bc15cc11' limit 1;
