  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '620d47724ab602436fb99e7774267c42767c888d8f672c8814b324ddf1900a93' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 11, 'LINGUAGENS', 'Esporte e cultura: análise acerca da esportivização de práticas corporais nos jogos indígenas Nos Jogos dos Povos Indígenas, observa-se que as práticas corporais realizadas envolvem elementos tradicionais (como as pinturas e adornos corporais) e modernos (como a regulamentação, a fiscalização e a padronização). O arco e flecha e a lança, por exemplo, são instrumentos tradicionalmente utilizados para a caça e a defesa da comunidade na aldeia. Na ocasião do evento, esses artefatos foram produzidos pela própria etnia, porém sua estruturação como “modalidade esportiva” promoveu uma semelhança entre as técnicas apresentadas, com o sentido único da competição. ALMEIDA, A. J. M.; SUASSUNA, D. M. F. A. Pensar a prática , n. 1, jan.-abr. 2010 (adaptado). A relação entre os elementos tradicionais e modernos nos Jogos dos Povos Indígenas desencadeou a', '["padronização de pinturas e adornos corporais.","sobreposição de elementos tradicionais sobre os modernos.","individuação das técnicas apresentadas em diferentes modalidades.","legitimação das práticas corporais indígenas como modalidade esportiva.","preservação dos significados próprios das práticas corporais em cada cultura."]'::jsonb, '"legitimação das práticas corporais indígenas como modalidade esportiva."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"620d47724ab602436fb99e7774267c42767c888d8f672c8814b324ddf1900a93","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"72886238a10d116fd4e6d4921de9ed95ef7a00808dfd7b67bebd90c0e1716978","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":11,"language":null,"page":7,"storagePath":"2019-D1-CD1/question-11-COMMON/statement-page-7.png","sha256":"280d54f32a6d0e99a40db21816551d855a5a26f0d423633dea5775a278ab09bc","crop":{"left":0,"bottom":109.1469,"width":342.2301899999999,"height":163.64639999999997}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":11,"language":null,"source_page":7,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 11, subject_area = 'LINGUAGENS', statement = 'Esporte e cultura: análise acerca da esportivização de práticas corporais nos jogos indígenas Nos Jogos dos Povos Indígenas, observa-se que as práticas corporais realizadas envolvem elementos tradicionais (como as pinturas e adornos corporais) e modernos (como a regulamentação, a fiscalização e a padronização). O arco e flecha e a lança, por exemplo, são instrumentos tradicionalmente utilizados para a caça e a defesa da comunidade na aldeia. Na ocasião do evento, esses artefatos foram produzidos pela própria etnia, porém sua estruturação como “modalidade esportiva” promoveu uma semelhança entre as técnicas apresentadas, com o sentido único da competição. ALMEIDA, A. J. M.; SUASSUNA, D. M. F. A. Pensar a prática , n. 1, jan.-abr. 2010 (adaptado). A relação entre os elementos tradicionais e modernos nos Jogos dos Povos Indígenas desencadeou a', options = '["padronização de pinturas e adornos corporais.","sobreposição de elementos tradicionais sobre os modernos.","individuação das técnicas apresentadas em diferentes modalidades.","legitimação das práticas corporais indígenas como modalidade esportiva.","preservação dos significados próprios das práticas corporais em cada cultura."]'::jsonb, correct_answer = '"legitimação das práticas corporais indígenas como modalidade esportiva."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"620d47724ab602436fb99e7774267c42767c888d8f672c8814b324ddf1900a93","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_S