ification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"196357c1de37223b2b3b832caa6beac70f3752595b4b44d2d637bedb09ca6239","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":12,"language":null,"page":8,"storagePath":"2019-D1-CD1/question-12-COMMON/statement-page-8.png","sha256":"f06e8b0f0e8ef9e75a0e294d52851ca096f7ef4c2736b49eefecb421c0437a82","crop":{"left":0,"bottom":636.2753,"width":260.93829,"height":70.87389999999994}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":12,"language":null,"source_page":8,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
