  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'c13825225246051cfb4f94bfaeef77f3b279ff2f91ef498efe1fe8999b48cfdf', 'STATEMENT_CROP', 8, '2019-D1-CD4/question-13-COMMON/statement-page-8.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"c13825225246051cfb4f94bfaeef77f3b279ff2f91ef498efe1fe8999b48cfdf","crop":{"left":0,"bottom":355.0344,"width":317.5335399999999,"height":352.11479999999995},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd4ab20c5e685bd759ddd85d7d62868243b3a6344e66909c2a71b1b86d62c6010' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 18, 'LINGUAGENS', 'O que é software livre Software livre é qualquer programa de computador construído de forma colaborativa, via internet, por uma comunidade internacional de desenvolvedores independentes. São centenas de milhares de hackers, que negam sua associação com os “violadores de segurança”. Esses desenvolvedores de software se recusam a reconhecer o significado pejorativo do termo e continuam usando a palavra hacker para indicar “alguém que ama programar e que gosta de ser hábil e engenhoso”. Além disso, esses programas são entregues à comunidade com o código fonte aberto e disponível, permitindo que a ideia original possa ser aperfeiçoada e devolvida novamente à comunidade. Nos programas convencionais, o código de programação é secreto e de propriedade da empresa que o desenvolveu, sendo quase impossível decifrar a programação. O que está em jogo é o controle da inovação tecnológica. Software livre é uma questão de liberdade de expressão e não apenas uma relação econômica. Hoje existem milhares de programas alternativos construídos dessa forma e uma comunidade de usuários com milhões de membros no mundo. BRANCO, M. Software livre e desenvolvimento social e económico. In: CASTELLS, M.; CARDOSO, G. (Org). A sociedade em rede : do conhecimento à acção política. Lisboa: Imprensa Nacional, 2005 (adaptado). A criação de softwares livres contribui para a produção do conhecimento na sociedade porque', '["democratiza o acesso a produtos construídos coletivamente.","complexifica os sistemas operacionais disponíveis no mercado.","qualifica um maior número de pessoas para o uso de tecnologias.","possibilita a coleta de dados confidenciais para seus desenvolvedores.","insere profissionalmente os hackers na área de in ov ação tecnológica."]'::jsonb, '"democratiza o acesso a produtos construídos coletivamente."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"d4ab20c5e685bd759ddd85d7d62868243b3a6344e66909c2a71b1b86d62c6010","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"1198879c77210ba5d52aed1919c0867f00c8efcf40bbf50c77094d50ea88f1ec","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":18,"language":null,"page":10,"storagePath":"2019-D1-CD1/question-18-COMMON/statement-page-10.png","sha256":"f27935128f35f8ec4d10787412107a9130e35b11ecd4c0130ccf47281a33b902","crop":{"left":0,"bottom":87.8879,"width":260.4787899999998,"height":216.07319999999999}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":18,"language":null,"source_page":10,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 18, subject_area = 'LINGUAGENS', statement = 'O que é software livre Software livre é qualquer programa de computador construído de forma colaborativa, via internet, por uma comunidade internacional de desenvolvedores independentes. São centenas de milhares de hackers, que negam sua associação com os “violadores de segurança”. Esses desenvolvedores de software se recusam a reconhecer o significado pejorativo do termo e continuam usando a palavra hacker para indicar “alguém que ama programar e que gosta de ser hábil e engenhoso”. Além disso, esses programas são entregues à comunidade com o código fonte aberto e disponível, permitindo que a ideia original possa ser aperfeiçoada e devolvida novamente à comunidade. Nos programas convencionais, o código de programação é secreto e de propriedade da empresa que o desenvolveu, sendo quase impossível decifrar a programação. O que está em jogo é o controle da inovação tecnológica. Software livre é uma questão de liberdade de expressão e não apenas uma relação econômica. Hoje existem milhares de programas alternativos construídos dessa forma e uma comunidade de usuários com milhões de membros no mundo. BRANCO, M. Software livre e desenvolvimento social e económico. In: CASTELLS, M.; CARDOSO, G. (Org). A sociedade em rede : do conhecimento à acção política. Lisboa: Imprensa Nacional, 2005 (adaptado). A criação de softwares livres contribui para a produção do conhecimento na sociedade porque', options = '["democratiza o acesso a produtos construídos coletivamente.","complexifica os sistemas operacionais disponíveis no mercado.","qualifica um maior número de pessoas para o uso de tecnologias.","possibilita a coleta de dados confidenciais para seus desenvolvedores.","insere profissionalmente os hackers na área de in ov ação tecnológica."]'::jsonb, correct_answer = '"democratiza o acesso a produtos construídos coletivamente."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"d4ab20c5e685bd759ddd85d7d62868243b3a6344e66909c2a71b1b86d62c6010","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"1198879c77210ba5d52aed1919c0867f00c8efcf40bbf50c77094d50ea88f1ec","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":18,"language":null,"page":10,"storagePath":"2019-D1-CD1/question-18-COMMON/statement-page-10.png","sha256":"f27935128f35f8ec4d10787412107a9130e35b11ecd4c0130ccf47281a33b902","crop":{"left":0,"bottom":87.8879,"width":260.4787899999998,"height":216.07319999999999}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":18,"language":null,"source_page":10,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
