  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c0726527bf8b2dcb06984eb8593e76e917e4c04a4dedae736264913bfc4c8676' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 27, 'LINGUAGENS', 'Educação para a saúde mediante programas de educação física escolar A educação para a saúde deverá ser alcançada mediante interação de ações que possam envolver o próprio homem mediante suas atitudes frente às exigências ambientais representadas pelos hábitos alimentares, estado de estresse, opções de lazer, atividade física, agressões climáticas etc. Dessa forma, parece evidente que o estado de ser saudável não é algo estático. Pelo contrário, torna-se necessário adquiri-lo e construí-lo de forma individualizada constantemente ao longo de toda a vida, apontando para o fato de que saúde é educável e, portanto, deve ser tratada não apenas com base em referenciais de natureza biológica e higienista, mas sobretudo em um contexto didático-pedagógico. GUEDES, D. P. Motriz , n. 1, 1999. A educação para a saúde pressupõe a adoção de comportamentos com base na interação de fatores relacionados à', '["adesão a programas de lazer.","opção por dietas balanceadas.","constituição de hábitos saudáveis.","evasão de ambientes estressores.","realização de ativ idades físicas regulares."]'::jsonb, '"constituição de hábitos saudáveis."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"c0726527bf8b2dcb06984eb8593e76e917e4c04a4dedae736264913bfc4c8676","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"294bd637f5b03a46bb69150bcb9893d5d782fad6958b0963043f06bc8f344c75","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":27,"language":null,"page":13,"storagePath":"2019-D1-CD1/question-27-COMMON/statement-page-13.png","sha256":"3e156d559714c8a90d77f74020b379af89aabcd4d1afa928809a64c0df972b0f","crop":{"left":0,"bottom":107.7138,"width":342.04243999999994,"height":172.61180000000002}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":27,"language":null,"source_page":13,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 27, subject_area = 'LINGUAGENS', statement = 'Educação para a saúde mediante programas de educação física escolar A educação para a saúde deverá ser alcançada mediante interação de ações que possam envolver o próprio homem mediante suas atitudes frente às exigências ambientais representadas pelos hábitos alimentares, estado de estresse, opções de lazer, atividade física, agressões climáticas etc. Dessa forma, parece evidente que o estado de ser saudável não é algo estático. Pelo contrário, torna-se necessário adquiri-lo e construí-lo de forma individualizada constantemente ao longo de toda a vida, apontando para o fato de que saúde é educável e, portanto, deve ser tratada não apenas com base em referenciais de natureza biológica e higienista, mas sobretudo em um contexto didático-pedagógico. GUEDES, D. P. Motriz , n. 1, 1999. A educação para a saúde pressupõe a adoção de comportamentos com base na interação de fatores relacionados à', options = '["adesão a programas de lazer.","opção por dietas balanceadas.","constituição de hábitos saudáveis.","evasão de ambientes estressores.","realização de ativ idades físicas regulares."]'::jsonb, correct_answer = '"constituição de hábitos saudáveis."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"c0726527bf8b2dcb06984eb8593e76e917e4c04a4dedae736264913bfc4c8676","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"294bd637f5b03a46bb69150bcb9893d5d782fad6958b0963043f06bc8f344c75","statement_assets":[{"asset