  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '404bc418bcbd70885f79162c4d2a65784f5ceef75289368e62b0ecf32d34717a', 'STATEMENT_CROP', 23, '2019-D1-CD1/question-58-COMMON/statement-page-23.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"404bc418bcbd70885f79162c4d2a65784f5ceef75289368e62b0ecf32d34717a","crop":{"left":284.45374000000004,"bottom":276.58799999999997,"width":282.47525999999993,"height":31.75},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8e67438f5247b365592b5c31d0613d20bd68a6e136231f5bdc4fbc9ace7dd424' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 60, 'CIENCIAS_HUMANAS', 'A cidade medieval é, antes de mais nada, uma sociedade da abundância, concentrada num pequeno espaço em meio a vastas regiões pouco povoadas. Em seguida, é um lugar de produção e de trocas, onde se articulam o artesanato e o comércio, sustentados por uma economia monetária. É também o centro de um sistema de valores particular, do qual emerge a prática laboriosa e criativa do trabalho, o gosto pelo negócio e pelo dinheiro, a inclinação para o luxo, o senso da beleza. É ainda um sistema de organização de um espaço fechado com muralhas, onde se penetra por portas e se caminha por ruas e praças e que é guarnecido por torres. LE GOFF, J.; SCHMITT, J.-C. Dicionário temático do Ocidente Medieval . Bauru: Edusc, 2006. No texto, o espaço descrito se caracteriza pela associação entre a ampliação das atividades urbanas e a', '["emancipação do poder hegemônico da realeza.","aceitação das práticas usurárias dos religiosos.","independência da produção alimentar dos campos.","superação do ordenamento corporativo dos ofícios.","permanência dos elementos arquitetônicos de proteção."]'::jsonb, '"permanência dos elementos arquitetônicos de proteção."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"8e67438f5247b365592b5c31d0613d20bd68a6e136231f5bdc4fbc9ace7dd424","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"266e21c1e30e950f4c9acae3e5951f5d2d5c1142f9837b20b477d3059629e265","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":60,"language":null,"page":24,"storagePath":"2019-D1-CD1/question-60-COMMON/statement-page-24.png","sha256":"9a0308cc147a63dc315e7c4955006d581add79d864335b23af39785d6c7b8b60","crop":{"left":0,"bottom":111.11299999999999,"width":336.86438999999984,"height":148.14249999999998}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":60,"language":null,"source_page":24,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
