o do espaço físico. B retomada do modelo criacionista.', '["promoção de atos ecumênicos.","fomento de orientações bíblicas. C recuperação do legado ancestral.","apropriação de cerimônias seculares. D infalibilidade do método científico.","retomada de ensinamentos apostólicos. E formação da cosmovisão holística.","ressignificação de rituais fundamentalistas."]'::jsonb, '"promoção de atos ecumênicos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"66197b461d1b92a583feea8d56c37987567f5675fb1e2e12b92599b97a878210","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"6ad0ff32afea3575ef8930cf486376c025cd93dd0d3ee71102391d09e2a7445e","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":75,"language":null,"source_page":28,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
