  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8b336c1bcec904c3848a830783afc927869cfa5d073d2d2bde1cdf1f38feeec2' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 79, 'CIENCIAS_HUMANAS', 'A soberania dos cidadãos dotados de plenos direitos era imprescindível para a existência da cidade-estado. Segundo os regimes políticos, a proporção desses cidadãos em relação à população total dos homens livres podia variar muito, sendo bastante pequena nas aristocracias e oligarquias e maior nas democracias. CARDOSO, C. F. A cidade-estado clássica . São Paulo: Ática, 1985. Nas cidades-estado da Antiguidade Clássica, a proporção de cidadãos descrita no texto é explicada pela adoção do seguinte critério para a participação política:', '["Controle da terra.","Liberdade de culto.","Igualdade de gênero.","Exclusão dos militares.","Exigência da alfabetização."]'::jsonb, '"Controle da terra."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"8b336c1bcec904c3848a830783afc927869cfa5d073d2d2bde1cdf1f38feeec2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"3143fad122a91e6a0141877777a9a59f9eae3749181552884e8d37440f86a0e7","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":79,"language":null,"source_page":29,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 79, subject_area = 'CIENCIAS_HUMANAS', statement = 'A soberania dos cidadãos dotados de plenos direitos era imprescindível para a existência da cidade-estado. Segundo os regimes políticos, a proporção desses cidadãos em relação à população total dos homens livres podia variar muito, sendo bastante pequena nas aristocracias e oligarquias e maior nas democracias. CARDOSO, C. F. A cidade-estado clássica . São Paulo: Ática, 1985. Nas cidades-estado da Antiguidade Clássica, a proporção de cidadãos descrita no texto é explicada pela adoção do seguinte critério para a participação política:', options = '["Controle da terra.","Liberdade de culto.","Igualdade de gênero.","Exclusão dos militares.","Exigência da alfabetização."]'::jsonb, correct_answer = '"Controle da terra."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"8b336c1bcec904c3848a830783afc927869cfa5d073d2d2bde1cdf1f38feeec2","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"3143fad122a91e6a0141877777a9a59f9eae3749181552884e8d37440f86a0e7","statement_assets":[],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":79,"language":null,"source_page":29,"source_sha256":"67d6ada3312f0964bf9fac60c28c550d96dc453f1352e4a59a06c4449a11fbc6"}}'::jsonb, act