  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '265da6781337be7401eb3cf26014dbd58634f315773e33ea913b7e0d77a46c90' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 3, 'LINGUAGENS', 'He was only twenty-three If children live with criticism, they learn to condemn. Gone before he had his time. If children live with fear, they learn to be apprehensive. It came without a warning If children live with pity, they learn to feel sorry for themselves. Didnꞌt want his friends to see him cry If children live with ridicule, they learn to feel shy. He knew the day was dawning If children live with tolerance, they learn patience. And I didnꞌt have a chance to say goodbye. If children live with praise, they learn appreciation. MADONNA. Erotica . Estados Unidos: Maverick, 1992. If children live with acceptance, they learn to love. A canção, muitas vezes, é uma forma de manifestar If children live with approval, they learn to like themselves. sentimentos e emoções da vida cotidiana. Por exemplo, If children live with recognition, they learn it is good to have a goal. o sofrimento retratado nessa canção foi causado If children live with sharing, they learn generosity.', '["pela morte precoce de um amigo jovem. If children live with fairness, they learn justice.","pelo término de um relacionamento amoroso. If children live with kindness and consideration, they","pela mudança de um amigo para outro país. learn respect.","pelo fim de uma amizade de mais de vinte anos. If children live with friendliness, they learn the world is a","pela traição por parte de pessoa próxima. nice place in which to live."]'::jsonb, '"pelo término de um relacionamento amoroso. If children live with kindness and consideration, they"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"265da6781337be7401eb3cf26014dbd58634f315773e33ea913b7e0d77a46c90","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"f4b58721efa803b99bbbcdaba653e82d96ce28145ddf3461a08e28822faaf8f4","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":3,"language":"ENGLISH","page":2,"storagePath":"2019-D1-CD4/question-3-ENGLISH/statement-page-2.png","sha256":"aa4737b6778164ace57e998dd358147a127b3403adad201518d414713c4761ee","crop":{"left":281.27793999999994,"bottom":427.76930000000016,"width":285.65106000000003,"height":159.73469999999986}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD4","question_number":3,"language":"ENGLISH","source_page":2,"source_sha256":"8c8e86a5507de97bebec1aefed09f8b57221734542a973ab64f7aed25afcd511"}}'::jsonb, true) returning id into v_question_id; end if;
