  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D1', 31, 'LINGUAGENS', 'tomas te u café com pão, tomas teu lugar no bote no cais do Capibaribe. Deixas chorando na esteira teu filho de mãe solteira. Levas ao lado a marmita, contendo a mesma ração do meio de todo o dia, a carne-seca e o feijão. De tudo quanto ele pede dás só bom-dia ao patrão, e recomeças a luta na engrenagem da fiação. MOTA, M. Canto ao meio . Rio de Janeiro: Civilização Brasileira, 1964. Nesse texto, a mobilização do uso padrão das formas verbais e pronominais', '["ajuda a localizar o enredo num ambiente estático.","auxilia na caracterização física do personagem principal.","acrescenta informações modificadoras às ações dos personagens.","alterna os tempos da narrativa, fazendo progredir as ideias do texto.","está a serviço do projeto poético, auxiliando na"]'::jsonb, '"acrescenta informações modificadoras às ações dos personagens."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"05ed251e0f80974d93e8f4f4e46c7942cc24eba3cf4bd3949952b82663570f25","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"ba44dcd498577ac79c1ab0ab2b058ecc50b6b79a91062b3c890ce13a205a41cd","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":31,"language":null,"page":15,"storagePath":"2019-D1-CD4/question-31-COMMON/statement-page-15.png","sha256":"92ce99ed0e7c09061e