  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'da7a747cec6fed396b7db3ff34968065115bf519047e990c12fc92918d0af126' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 91, 'CIENCIAS_NATUREZA', 'no qual continha os cinco postulados que serviam Uma casa tem um cabo elétrico mal dimensionado, como alicerce da primeira teoria atômica da matéria de resistência igual a 10 Ω, que a conecta à rede elétrica fundamentada no método científico. Esses postulados de 120 V. Nessa casa, cinco lâmpadas, de resistência são numerados a seguir: igual a 200 Ω, estão conectadas ao mesmo circuito que uma televisão de resistência igual a 50 Ω, conforme 1. A matéria é constituída de átomos indivisíveis. ilustrado no esquema. A televisão funciona apenas com tensão entre 90 V e 130 V. 2. Todos os átomos de um dado elemento químico são 10 Ω idênticos em massa e em todas as outras propriedades. 3. Diferentes elementos químicos têm diferentes tipos de átomos; em particular, seus átomos têm 120 V Ω diferentes massas. 50 Ω Ω Ω Ω Ω 4. Os átomos são indestrutíveis e nas reações químicas mantêm suas identidades. 200 200 200 200 200 5. Átomos de elementos combinam com átomos de outros elementos em proporções de números inteiros O número máximo de lâmpadas que podem ser ligadas pequenos para formar compostos. sem que a televisão pare de funcionar é: Após o modelo de Dalton, outros modelos baseados', '["1. em outros dados experimentais evidenciaram, entre","2. outras coisas, a natureza elétrica da matéria, a","3. composição e organização do átomo e a quantização da","4. energia no modelo atômico.","5."]'::jsonb, '"2. outras coisas, a natureza elétrica da matéria, a"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"da7a747cec6fed396b7db3ff34968065115bf519047e990c12fc92918d0af126","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"8587e643bdd3a5fa64414702dab601c3eebabbe2358f1674ad323e1759933e1b","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":91,"language":null,"page":2,"storagePath":"2019-D2-CD5/question-91-COMMON/statement-page-2.png","sha256":"880689526910b49ceee952fa981c1933e377b849d539f2fcd1a6d9f86095dc68","crop":{"left":0,"bottom":419.4554,"width":285.13214,"height":236.55789999999996}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":91,"language":null,"source_page":2,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 91, subject_area = 'CIENCIAS_NATUREZA', statement = 'no qual continha os cinco postulados que serviam Uma casa tem um cabo elétrico mal dimensionado, como alicerce da primeira teoria atômica da matéria de resistência igual a 10 Ω, que a conecta à rede elétrica fundamentada no método científico. Esses postulados de 120 V. Nessa casa, cinco lâmpadas, de resistência são numerados a seguir: igual a 200 Ω, estão conectadas ao mesmo circuito que uma televisão de resistência igual a 50 Ω, conforme 1. A matéria é constituída de átomos indivisíveis. ilustrado no esquema. A televisão funciona apenas com tensão entre 90 V e 130 V. 2. Todos os átomos de um dado elemento químico são 10 Ω idênticos em massa e em todas as outras propriedades. 3. Diferentes elementos químicos têm diferentes tipos de átomos; em particular, seus átomos têm 120 V Ω diferentes massas. 50 Ω Ω Ω Ω Ω 4. Os átomos são indestrutíveis e nas reações químicas mantêm suas identidades. 200 200 200 200 200 5. Átomos de elementos combinam com átomos de outros elementos em proporções de números inteiros O número máximo de lâmpadas que podem ser ligadas pequenos para formar compostos. sem que a televisão pare de funcionar é: Após o modelo de Dalton, outros modelos baseados', options = '["1. em outros dados experimentais evidenciaram, entre","2. outras coisas, a natureza elétrica da matéria, a","3. composição e organização do átomo e a quantização da","4. energia no modelo atômico.","5."]'::jsonb, correct_answer = '"2. outras coisas, a natureza elétrica da matéria, a"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"da7a747cec6fed396b7db3ff34968065115bf519047e990c12fc92918d0af1