  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 100, 'CIENCIAS_NATUREZA', 'Dois amigos se encontram em um posto de gasolina para calibrar os pneus de suas bicicletas. Uma das bicicletas é de corrida (bicicleta A ) e a outra, de passeio (bicicleta B ). Os pneus de ambas as bicicletas têm as mesmas características, exceto que a largura dos pneus de A é menor que a largura dos pneus de B . Ao calibrarem os pneus das bicicletas A e B , respectivamente com pressões de calibração p e p , os amigos A B observam que o pneu da bicicleta A deforma, sob mesmos esforços, muito menos que o pneu da bicicleta B . Pode-se considerar que as massas de ar comprimido no pneu da bicicleta A , m , e no pneu da bicicleta B , m , são A B diretamente proporcionais aos seus volumes. Comparando as pressões e massas de ar comprimido nos pneus das bicicletas, temos: A p < p e m < m A B A B B p > p e m < m A B A B C p > p e m = m A B A B D p < p e m = m A B A B E p > p e m > m A B A B', '[") e a outra, de passeio (bicicleta B ). Os pneus de ambas as bicicletas","p > p e m < m","p > p e m = m","p < p e m = m","p > p e m > m"]'::jsonb, '"p > p e m < m"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"f7b57e560d149411a046247b64a3a7daefbed97b1ad135c3769ffde9280c2810","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"d9793507e045dbb889a6977e2e6f83230f67c5cd507d997b53036def31783bdc","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":100,"language":null,"source_page":5,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 100, subject_area = 'CIENCIAS_NATUREZA', statement = 'Dois amigos se encontram em um posto de gasolina para calibrar os pneus de suas bicicletas. Uma das bicicletas é de corrida (bicicleta A ) e a outra, de passeio (bicicleta B ). Os pneus de ambas as bicicletas têm as mesmas características, exceto que a largura dos pneus de A é menor que a largura dos pneus de B . Ao calibrarem os pneus das bicicletas A e B , respectivamente com pressões de calibração p e p , os amigos A B observam que o pneu da bicicleta A deforma, sob mesmos esforços, muito menos que o pneu da bicicleta B . Pode-se considerar que as massas de ar comprimido no pneu da bicicleta A , m , e no pneu da bicicleta B , m , são A B diretamente proporcionais aos seus volumes. Comparando as pressões e massas de ar comprimido nos pneus das bicicletas, temos: A p < p e m < m A B A B B p > p e m < m A B A B C p > p e m = m A B A B D p < p e m = m A B A B E p > p e m > m A B A B', options = '[") e a outra, de passeio (bicicleta B ). Os pneus de ambas as bicicletas","p > p e m < m","p > p e m = m","p < p e m = m","p > p e m > m"]'::jsonb, correct_answer = '"p > p e m < m"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"f7b57e560d149411a046247b64a3a7daefbed97b1ad135c3769ffde9280c2810","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"d9793507e045dbb889a6977e2e6f83230f67c5cd507d997b53036def31783bdc","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adap