  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'ee726b64a298ca032ce3a0e7d8ae76e43a7784deb83825850346e5a6a4a48f3f' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 106, 'CIENCIAS_NATUREZA', 'Com base nos experim entos de plantas de Mendel, foram estabelecidos três princípios básicos, que são conhecidos como leis da uniformidade, segregação e distribuição independente. A lei da distribuição independente refere-se ao fato de que os membros de pares diferentes de genes segregam-se independentemente, uns dos outros, para a prole. TURNPENNY, P. D. Genética médica . Rio de Janeiro: Elsevier, 2009 (adaptado). Hoje, sabe-se que isso nem sempre é verdade. Por quê?', '["A distribuição depende do caráter de dominância ou recessividade do gene.","Os organismos nem sempre herdam cada um dos genes de cada um dos genitores.","As alterações cromossômicas podem levar a falhas na segregação durante a meiose.","Os genes localizados fisicamente próximos no mesmo cromossomo tendem a ser herdados juntos.","O cromossomo que contém dois determinados genes pode não sofrer a disjunção na primeira fase da meiose."]'::jsonb, '"Os genes localizados fisicamente próximos no mesmo cromossomo tendem a ser herdados juntos."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"ee726b64a298ca032ce3a0e7d8ae76e43a7784deb83825850346e5a6a4a48f3f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"903c0c8522cbf69522b9889f38ab9c31e5183412a584036c17ea502f1f5c0bde","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":106,"language":null,"page":7,"storagePath":"2019-D2-CD5/question-106-COMMON/statement-page-7.png","sha256":"45031cd0f8a8551245783a49d36f1af881ba5fe27a278e477736304042c63420","crop":{"left":0,"bottom":593.1106,"width":313.17778999999985,"height":114.03859999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":106,"language":null,"source_page":7,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 106, subject_area = 'CIENCIAS_NATUREZA', statement = 'Com base nos experim entos de plantas de Mendel, foram estabelecidos três princípios básicos, que são conhecidos como leis da uniformidade, segregação e distribuição independente. A lei da distribuição independente refere-se ao fato de que os membros de pares diferentes de genes segregam-se independentemente, uns dos outros, para a prole. TURNPENNY, P. D. Genética médica . Rio de Janeiro: Elsevier, 2009 (adaptado). Hoje, sabe-se que isso nem sempre é verdade. Por quê?', options = '["A distribuição depende do caráter de dominância ou recessividade do gene.","Os organismos nem sempre herdam cada um dos genes de cada um dos genitores.","As alterações cromossômicas podem levar a falhas na segregação durante a meiose.","Os genes localizados fisicamente próximos no mesmo cromossomo tendem a ser herdados juntos.","O cromossomo que contém dois determinados genes pode não sofrer a disjunção na primeira fase da meiose."]'::jsonb, correct_answer = '"Os genes localizados fisicamente próximos no mesmo cromossomo tendem a ser herdados juntos."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"ee726b64a298ca032ce3a0e7d8ae76e43a7784deb83825850346e5a6a4a48f3f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"903c0c8522cbf69522b9889f38ab9c31e5183412a584036c17ea502f1f5c0bde","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":106,"language":null,"page":7,"storagePath":"2019-