  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 107, 'CIENCIAS_NATUREZA', 'Em qualquer obra de construção civil é fundamental a utilização de equipamentos de proteção individual, tal como capacetes. Por exemplo, a queda livre de um tijolo de massa 2,5 kg de uma altura de 5 m, cujo impacto contra um capacete pode durar até 0,5 s, resulta em uma força impulsiva média maior do que o peso do tijolo. −2 Suponha que a aceleração grav itacional seja 10 m s e que o efeito de resistência do ar seja desprezível. A força impulsiva média gerada por esse impacto equivale ao peso de quantos tijolos iguais?', '["2","5","10","20","50"]'::jsonb, '"2"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"f0cb471f0d0419b59396339745060e75d6c2df7b6ca6fd13d0f5c37dddbf2f0f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"31074d97082ed4d24a5fb8323249dcc4fc75aaf80cf23662585eb5b4d56496e1","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":107,"language":null,"page":7,"storagePath":"2019-D2-CD5/question-107-COMMON/statement-page-7.png","sha256":"caf4f0149ab2d600476ea3161b6e78df93077e6670dee9fdbcb453b9c874e761","crop":{"left":0,"bottom":418.2256,"width":313.17778999999985,"height":104.43859999999995}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_le