  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'caf4f0149ab2d600476ea3161b6e78df93077e6670dee9fdbcb453b9c874e761', 'STATEMENT_CROP', 7, '2019-D2-CD5/question-107-COMMON/statement-page-7.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"caf4f0149ab2d600476ea3161b6e78df93077e6670dee9fdbcb453b9c874e761","crop":{"left":0,"bottom":418.2256,"width":313.17778999999985,"height":104.43859999999995},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'd32503358855de188a0e168adafc3901a2e791647285435e02c62262e073414f' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 111, 'CIENCIAS_NATUREZA', 'x O concreto utilizado na construção civil é um A massa do íon medida por esse dispositivo será material formado por cimento misturado a areia, a brita e a água. A areia é normalmente extraída de leitos qBt A de rios e a brita, oriunda da fragmentação de rochas. N 2  Impactos ambientais gerados no uso do concreto qBt estão associados à extração de recursos minerais e ao B N  descarte indiscriminado desse material. Na tentativa de reverter esse quadro, foi proposta a utilização de 2 qBt C concreto reciclado moído em substituição ao particulado N  rochoso graúdo na fabricação de novo concreto, qBt obtendo um material com as mesmas propriedades que D N o anterior. 2 qBt O benefício ambiental gerado nessa proposta é a E N redução do(a)', '["extração da brita.","extração de areia.","consumo de água.","consumo de concreto.","fabricação de cimento."]'::jsonb, '"extração da brita."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"d32503358855de188a0e168adafc3901a2e791647285435e02c62262e073414f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"43dc5cd86f98a23b1637a467152333290d06bda8e4914fbba1600ba1430b3018","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":111,"language":null,"page":8,"storagePath":"2019-D2-CD5/question-111-COMMON/statement-page-8.png","sha256":"54a0727f3c0b7cb6d71a7ddae6211aa7c3c44ec91bb31fbc8c63c36d119ef812","crop":{"left":240.84704415,"bottom":299.4256,"width":326.08195585,"height":76.00389999999999}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":111,"language":null,"source_page":8,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
