  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '8a98e9b49f58a44cd06310beb823cbb28f4ad8536d491304f15a5572ad7a23bb' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 116, 'CIENCIAS_NATUREZA', 'Um teste de laboratório permite identificar alguns cátions metálicos ao introduzir uma pequena quantidade do material de interesse em uma chama de bico de Bunsen para, em seguida, observar a cor da luz emitida. A cor observada é proveniente da emissão de radiação eletromagnética ao ocorrer a', '["mudança da fase sólida para a fase líquida do elemento metálico.","combustão dos cátions metálicos provocada pelas moléculas de oxigênio da atmosfera.","diminuição da energia cinética dos elétrons em uma mesma órbita na eletrosfera atômica.","transição eletrônica de um nível mais externo para outro mais interno na eletrosfera atômica.","promoção dos elétrons que se encontram no"]'::jsonb, '"transição eletrônica de um nível mais externo para outro mais interno na eletrosfera atômica."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"8a98e9b49f58a44cd06310beb823cbb28f4ad8536d491304f15a5572ad7a23bb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"4a1acdc27e97f7cde62b5662aa1c285e3d375551f4ea97d6c5a05d4a75b22684","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":116,"language":null,"page":10,"storagePath":"2019-D2-CD5/question-116-COMMON/statement-page-10.png","sha256":"17fd7ce4b12f7c6771c477cbd14477e4bbf7432bbbb835c13f0c966a6be42a96","crop":{"left":0,"bottom":188.48700000000002,"width":305.13939000000005,"height":121.27319999999997}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":116,"language":null,"source_page":10,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 116, subject_area = 'CIENCIAS_NATUREZA', statement = 'Um teste de laboratório permite identificar alguns cátions metálicos ao introduzir uma pequena quantidade do material de interesse em uma chama de bico de Bunsen para, em seguida, observar a cor da luz emitida. A cor observada é proveniente da emissão de radiação eletromagnética ao ocorrer a', options = '["mudança da fase sólida para a fase líquida do elemento metálico.","combustão dos cátions metálicos provocada pelas moléculas de oxigênio da atmosfera.","diminuição da energia cinética dos elétrons em uma mesma órbita na eletrosfera atômica.","transição eletrônica de um nível mais externo para outro mais interno na eletrosfera atômica.","promoção dos elétrons que se encontram no"]'::jsonb, correct_answer = '"transição eletrônica de um nível mais externo para outro mais interno na eletrosfera atômica."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"8a98e9b49f58a44cd06310beb823cbb28f4ad8536d491304f15a5572ad7a23bb","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"4a1acdc27e97f7cde62b5662aa1c285e3d375551f4ea97d6c5a05d4a75b22684","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":116,"language":null,"page":10,"storagePath":"2019-D2-CD5/question-116-COMMON/statement-page-10.png","sha256":"17fd7ce4b12f7c6771c477cbd14477e4bbf7432bbbb835c13f0c966a6be42a96","crop":{"left":0,"bottom":188.48700000000002,"width":305.13939000000005,"height":121.27319999999997}}],"e