  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'f488e909c15877df9110a893c7e17e3517c2fe33043d6d345d97698b3a388c10' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 143, 'MATEMATICA', 'Um casal planejou uma viagem e definiu como teto para o gasto diário um valor de até R$ 1 000,00. Antes de decidir o destino da viagem, fizeram uma pesquisa sobre a taxa de câmbio vigente para as moedas de cinco países que desejavam visitar e também sobre as estimativas de gasto diário em cada um, com o objetivo de escolher o destino que apresentasse o menor custo diário em real. O quadro mostra os resultados obtidos com a pesquisa realizada. País de destino Moeda local Taxa de câmbio Gasto diário França Euro (€) R$ 3,14 315,00 € EUA Dólar (US$) R$ 2,78 US$ 390,00 Austrália Dólar australiano (A$) R$ 2,14 A$ 400,00 Canadá Dólar canadense (C$) R$ 2,10 C$ 410,00 Reino Unido Libra esterlina (£) R$ 4,24 £ 290,00 Nessas condições, qual será o destino escolhido para a viagem?', '["Austrália.","Canadá.","EUA.","França.","Reino Unido ."]'::jsonb, '"Austrália."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"f488e909c15877df9110a893c7e17e3517c2fe33043d6d345d97698b3a388c10","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"a2107abb752f3a225ebedf5e818a21bb43165f74982dec39f7f6a2a36fe546c6","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":143,"language":null,"page":19,"storagePath":"2019-D2-CD5/question-143-COMMON/statement-page-19.p