  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '1d32b432f7be201fe7f019c10fb1b7243caa0456446c2d80173275fb7e0d0a19' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 176, 'MATEMATICA', 'Em um determinado ano, os computadores da receita federal de um país identificaram como inconsistentes 20% das declarações de imposto de renda que lhe foram encaminhadas. Uma declaração é classificada como inconsistente quando apresenta algum tipo de erro ou conflito nas informações prestadas. Essas declarações consideradas inconsistentes foram analisadas pelos auditores, que constataram que 25% delas eram fraudulentas. Constatou-se ainda que, dentre as declarações que não apresentaram inconsistências, 6,25% eram fraudulentas. Qual é a probabilidade de, nesse ano, a declaração de um contribuinte ser considerada inconsistente, dado que ela era fraudulenta?', '["0,0500","0,1000","0,1125","0,3125","0,5000"]'::jsonb, '"0,5000"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"1d32b432f7be201fe7f019c10fb1b7243caa0456446c2d80173275fb7e0d0a19","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"9914f53fca1e175631a712fca264d1470194b88cce75ea65f029b043a57da491","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":176,"language":null,"page":30,"storagePath":"2019-D2-CD5/question-176-COMMON/statement-page-30.png","sha256":"9dcf91113981222ea26ffc19234424326bb96f6937e752ece4f05eaa3807a030","crop":{"left":0,"bottom":573.276,"width":269.2754842000002,"height":133.8732}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":176,"language":null,"source_page":30,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2019, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 176, subject_area = 'MATEMATICA', statement = 'Em um determinado ano, os computadores da receita federal de um país identificaram como inconsistentes 20% das declarações de imposto de renda que lhe foram encaminhadas. Uma declaração é classificada como inconsistente quando apresenta algum tipo de erro ou conflito nas informações prestadas. Essas declarações consideradas inconsistentes foram analisadas pelos auditores, que constataram que 25% delas eram fraudulentas. Constatou-se ainda que, dentre as declarações que não apresentaram inconsistências, 6,25% eram fraudulentas. Qual é a probabilidade de, nesse ano, a declaração de um contribuinte ser considerada inconsistente, dado que ela era fraudulenta?', options = '["0,0500","0,1000","0,1125","0,3125","0,5000"]'::jsonb, correct_answer = '"0,5000"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', metadata = '{"canonical_id":"1d32b432f7be201fe7f019c10fb1b7243caa0456446c2d80173275fb7e0d0a19","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"9914f53fca1e175631a712fca264d1470194b88cce75ea65f029b043a57da491","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":176,"language":null,"page":30,"storagePath":"2019-D2-CD5/question-176-COMMON/statement-page-30.png","sha256":"9dcf91113981222ea26ffc19234424326bb96f6937e752ece4f05eaa3807a030","crop":{"left":0,"bottom":573.276,"width":269.2754842000002,"height":133.8732}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":176,"language":null,"source_page":30,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
