  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '6818fc680468fcfe4a12aa062ff6303fe3e67ab4ad0c11d3d7f7cb5d120ccbf1' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2019, 'ENEM', 'REGULAR', 'D2', 177, 'MATEMATICA', 'A taxa de urbanização de um município é dada pela razão entre a população urbana e a população total do município (isto é, a soma das populações rural e urbana). Os gráficos apresentam, respectivamente, a população urbana e a população rural de cinco municípios (I, II, III, IV, V) de uma mesma região estadual. Em reunião entre o governo do estado e os prefeitos desses municípios, ficou acordado que o município com maior taxa de urbanização receberá um investimento extra em infraestrutura. População urbana População rural 14 000 20 000 18 000 17 000 12 000 18 000 12 000 16 000 10 000 10 000 14 000 8 000 11 000 12 000 8 000 10 000 10 000 6 000 5 000 8 000 8 000 4 000 4 000 6 000 4 000 2 000 2 000 0 0 I II III IV V I II III IV V Segundo o acordo, qual município receberá o investimento extra?', '["I","II","III","IV","V"]'::jsonb, '"III"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2019', '{"canonical_id":"6818fc680468fcfe4a12aa062ff6303fe3e67ab4ad0c11d3d7f7cb5d120ccbf1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"57a9b99d15787646ae10ee5b9fe7ea7bf1baa328bd470ca58dc1b5c1900c5acc","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":177,"language":null,"page":30,"storagePath":"2019-D2-CD5/question-177-COMMON/statement-page-30.png","sha256":"13542f0003957fc6859be39c755234bfa0795e4e47f0545a2127902deb2dd24c","crop":{"left":0,"bottom":225.2854,"width":269.2754842000002,"height":274.3441}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2019,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":177,"language":null,"source_page":30,"source_sha256":"83727df7025a435404fe1c98ee323ad6501b9d37262bdfcfccc77c193d278621"}}'::jsonb, true) returning id into v_question_id; end if;
