e que a explosão de matéria"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', metadata = '{"canonical_id":"d571bb9adfa1490b8bca707f37bfbef5842f7367478b5944892fb2c0ae5f4047","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"NO_REPRODUCIBLE_SUBJECT_SIGNAL","classification_source_fingerprint":"52b0a8bcde1af9c5275b5b75e5810f34037899c8a13bd04d4a6350ed3a1a6fc8","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":26,"language":null,"page":12,"storagePath":"2018-D1-CD1/question-26-COMMON/statement-page-12.png","sha256":"29df98c0cee61dd5bb9d833f35aea696c0c68a3ced53656e70ac5b34eb105340","crop":{"left":0,"bottom":659.2554500000001,"width":312.6323749999999,"height":68.55374999999992}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":26,"language":null,"source_page":12,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
