  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'f9aa64499727d4a8d23426df8f318dba694e8e22381ed31104929d4e54e8dddb', 'STATEMENT_CROP', 12, '2018-D1-CD1/question-28-COMMON/statement-page-12.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"f9aa64499727d4a8d23426df8f318dba694e8e22381ed31104929d4e54e8dddb","crop":{"left":312.6323749999999,"bottom":520.0059499999999,"width":268.4699250000001,"height":30.1875},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '0c7ddbe41137a132bdf1ee5a089aea57a8552727b7d8881d3016ec95f39b2a90' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 33, 'LINGUAGENS', 'A trajetória de Liesel Meminger é contada por uma narradora mórbida, surpreendentemente simpática. Ao perceber que a pequena ladra de livros lhe escapa, a Morte afeiçoa-se à menina e rastreia suas pegadas de 1939 a 1943. Traços de uma sobrevivente: a mãe comunista, perseguida pelo nazismo, envia Liesel e o irmão para o subúrbio pobre de uma cidade alemã, onde um casal se dispõe a adotá-los por dinheiro. O garoto morre no trajeto e é enterrado por um coveiro que deixa cair um livro na neve. É o primeiro de uma série que a menina vai surrupiar ao longo dos anos. O único vínculo com a família é esta obra, que ela ainda não sabe ler. A vida ao redor é a pseudorrealidade criada em torno do culto a Hitler na Segunda Guerra. Ela assiste à eufórica celebração do aniversário do Führer pela vizinhança. A Morte, perplexa diante da violência humana, dá um tom leve e divertido à narrativa deste duro confronto entre a infância perdida e a crueldade do mundo adulto, um sucesso absoluto – e raro – de crítica e público. Disponível em: www.odevoradordelivros.com. Acesso em: 24 jun. 2014. Os gêneros textuais podem ser caracterizados, dentre outros fatores, por seus objetivos. Esse fragmento é um(a)', '["reportagem, pois busca convencer o interlocutor da tese defendida ao longo do texto.","resumo, pois promove o contato rápido do leitor com uma informação desconhecida.","sinopse, pois sintetiza as informações relevantes de uma obra de modo impessoal.","instrução, pois ensina algo por meio de explicações Fotografia: LUCAS HALLEL. Disponível em: www.flickr.com. Acesso em: 16 abr. 2018 (adaptado). sobre uma obra específica.","resenha, pois apresenta uma produção intelectual de"]'::jsonb, '"resenha, pois apresenta uma produção intelectual de"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"0c7ddbe41137a132bdf1ee5a089aea57a8552727b7d8881d3016ec95f39b2a90","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c862895ae5546f5aa6524c7ac8a762a0a3f7d454a4e5b0cc2548a47148180935","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":33,"language":null,"source_page":14,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2018, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 33, subject_area = 'LINGUAGENS', statement = 'A trajetória de Liesel Meminger é contada por uma narradora mórbida, surpreendentemente simpática. Ao perceber que a pequena ladra de livros lhe escapa, a Morte afeiçoa-se à menina e rastreia suas pegadas de 1939 a 1943. Traços de uma sobrevivente: a mãe comunista, perseguida pelo nazismo, envia Liesel e o irmão para o subúrbio pobre de uma cidade alemã, onde um casal se dispõe a adotá-los por dinheiro. O garoto morre no trajeto e é enterrado por um coveiro que deixa cair um livro na neve. É o primeiro de uma série que a menina vai surrupiar ao longo dos anos. O único vínculo com a família é esta obra, que ela ainda não sabe ler. A vida ao redor é a pseudorrealidade criada em torno do culto a Hitler na Segunda Guerra. Ela assiste à eufórica celebração do aniversário do Führer pela vizinhança. A Morte, perplexa diante da violência humana, dá um tom leve e divertido à narrativa deste duro confronto entre a infância perdida e a crueldade do mundo adulto, um sucesso absoluto – e raro – de crítica e público. Disponível em: www.odevoradordelivros.com. Acesso em: 24 jun. 2014. Os gêneros textuais podem ser caracterizados, dentre outros fatores, por seus objetivos. Esse fragmento é um(a)', options = '["reportagem, pois busca convencer o interlocutor da tese defendida ao longo do texto.","resumo, pois promove o contato rápido do leitor com uma informação desconhecida.","sinopse, pois sintetiza as informações relevantes de uma obra de modo impessoal.","instrução, pois ensina algo por meio de explicações Fotografia: LUCAS HALLEL. Disponível em: www.flickr.com. Acesso em: 16 abr. 2018 (adaptado). sobre uma obra específica.","resenha, pois apresenta uma produção intelectual de"]'::jsonb, correct_answer = '"resenha, pois apresenta uma produção intelectual de"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', metadata = '{"canonical_id":"0c7ddbe41137a132bdf1ee5a089aea57a8552727b7d8881d3016ec95f39b2a90","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"c862895ae5546f5aa6524c7ac8a762a0a3f7d454a4e5b0cc2548a47148180935","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":33,"language":null,"source_page":14,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
