  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 41, 'LINGUAGENS', 'Houve protestos. Proibiram os protestos. E no lugar dos protestos nasceu o ódio. Então surgiu a Casa de Vidro, para acabar com aquele ódio. ÂNGELO, I. A casa de vidro . São Paulo: Círculo do Livro, 1985. Publicado em 1979, o texto compartilha com outras obras da literatura brasileira escritas no período as marcas do contexto em que foi produzido, como a A referência à censura e à opressão para alegorizar', '["falta de liberdade de expressão característica da época.","valorização de situações do cotidiano para atenuar os sentimentos de revolta em relação ao governo instituído.","utilização de metáforas e ironias para expressar um olhar crítico em relação à situação social e política do país.","tendência realista para documentar com verossimilhança o drama da população brasileira durante o Regime Militar.","sobreposição das manifestações populares pelo"]'::jsonb, '"sobreposição das manifestações populares pelo"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"410e0e2edc9697864c8142f28fa424133fcda80f79eb1ef6c33600b92231ebd3","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"70dca91c1a4428ecae331e513b910cd4702a3c8e5e73addef57ac1bde03470de","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":41,"language":null,"page":17,"storagePath":"2018-