  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '78d061e136ce8afcb01d10b262b5f35d83ca5112cfe4ff00ff27618ebd9b63be', 'STATEMENT_CROP', 28, '2018-D1-CD1/question-79-COMMON/statement-page-28.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"78d061e136ce8afcb01d10b262b5f35d83ca5112cfe4ff00ff27618ebd9b63be","crop":{"left":0,"bottom":133.57865,"width":311.53062499999993,"height":91.09294999999992},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'c2134a48655f5a829b96f2f550ce6b11227a3cd15c34a916d52a1cc87ffef45f' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 82, 'CIENCIAS_HUMANAS', 'TEXTO I Há mais de duas décadas, os cientistas e ambientalistas têm alertado para o fato de a água doce ser um recurso escasso em nosso planeta. Desde o começo de 2014, o Sudeste do Brasil adquiriu uma clara percepção dessa realidade em função da seca. TEXTO II Dinâmicas atmosféricas no Brasil Elementos relevantes ao transporte de umidade na América do Sul a leste dos Andes pelos Jatos de Baixos Níveis (JBN), Frentes Frias (FF) e transporte de umidade do Atlântico Sul, assim como a presença da Zona de Convergência do Atlântico Sul (ZCAS), para um verão normal e para o verão seco de 2014. “A” representa o centro da anomalia de alta pressão atmosférica. Amazônia Verão normal Verão de 2014 Amazônia JBN JBN 0° 0° Fluxo do Fluxo do Oceano Atlântico Oceano Atlântico ZCAS Solo 20° S A Solo úmido 20° S seco FF FF 40° S 40° S 60° W 60° W MARENGO, J. A. et al. A seca e a crise hídrica de 2014-2015 em São Paulo. Revista USP , n. 106, 2015 (adaptado). De acordo com as informações apresentadas, a seca de 2014, no Sudeste, teve como causa natural o(a)', '["constituição de frentes quentes barrando as chuvas convectivas.","formação de anticiclone impedindo a entrada de umidade.","presença de nebulosidade na região de cordilheira.","avanço de massas polares para o continente.","baixa pressão atmosférica no litoral."]'::jsonb, '"formação de anticiclone impedindo a entrada de umidade."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"c2134a48655f5a829b96f2f550ce6b11227a3cd15c34a916d52a1cc87ffef45f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"HISTORIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_HISTORIA","classification_source_fingerprint":"b12bc602ec44f088e8806ff0a11816a8a3bf35a07923195d9dffcf0734e16313","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":82,"language":null,"page":29,"storagePath":"2018-D1-CD1/question-82-COMMON/statement-page-29.png","sha256":"b8bcf6750f5ca59b78f21e83063f5e407b02c5f0f6cd997339998eb487ede0a3","crop":{"left":0,"bottom":324.6113,"width":301.182371,"height":403.1979}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":82,"language":null,"source_page":29,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2018, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 82, subject_area = 'CIENCIAS_HUMANAS', statement = 'TEXTO I Há mais de duas décadas, os cientistas e ambientalistas têm alertado para o fato de a água doce ser um recurso escasso em nosso planeta. Desde o começo de 2014, o Sudeste do Brasil adquiriu uma clara percepção dessa realidade em função da seca. TEXTO II Dinâmicas atmosféricas no Brasil Elementos relevantes ao transporte de umidade na América do Sul a leste dos Andes pelos Jatos de Baixos Níveis (JBN), Frentes Frias (FF) e transporte de umidade do Atlântico Sul, assim como a presença da Zona de Convergência do Atlântico Sul (ZCAS), para um verão normal e para o verão seco de 2014. “A” representa o centro da anomalia de alta pressão atmosférica. Amazônia Verão normal Verão de 2014 Amazônia JBN JBN 0° 0° Fluxo do Fluxo do Oceano Atlântico Oceano Atlântico ZCAS Solo 20° S A Solo úmido 20° S seco FF FF 40° S 40° S 60° W 60° W MARENGO, J. A. et al. A seca e a crise hídrica de 2014-2015 em São Paulo. Revista USP , n. 106, 2015 (adaptado). De acordo com as informações apresentadas, a seca de 2014, no Sudeste, teve como causa natural o(a)', options = '["constituição de frentes quentes barrando as chuvas convectivas.","formação de anticiclone impedindo a entrada de umidade.","presença de nebulosidade na região de cordilheira.","avanço de massas polares para o continente.","baixa pressão atmosférica no litoral."]'::jsonb, correct_answer = '"formação de anticiclone impedindo a entrada de umidade."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', metadata = '{"canonical_id":"c2134a48655f5a829b96f2f550ce6b11227a3cd15c34a916d52a1cc87ffef45f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":tr