  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '5175fc90eceb0cbead32d50d8aae8aa51a6cb906a55cfd8b1aa7ae49763804c5', 'STATEMENT_CROP', 29, '2018-D1-CD1/question-83-COMMON/statement-page-29.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"5175fc90eceb0cbead32d50d8aae8aa51a6cb906a55cfd8b1aa7ae49763804c5","crop":{"left":0,"bottom":129.3262,"width":301.182371,"height":129.75685000000007},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'f4d66b7289a07ae34609b2d8d6d3d3dccf45a673c3b17d1bcc39486a65942fdd' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 85, 'CIENCIAS_HUMANAS', 'Então disse: “Este é o local onde construirei. Tudo pode chegar aqui pelo Eufrates, o Tigre e uma rede de canais. Só um lugar como este sustentará o exército e a população geral”. Assim ele traçou e destinou as verbas para a sua construção, e deitou o primeiro tijolo com sua própria mão, dizendo: “Em nome de Deus, e em louvor a Ele. Construí, e que Deus vos abençoe”. AL-TABARI, M. Uma história dos povos árabes . São Paulo: Cia. das Letras, 1995 (adaptado). A decisão do califa Al-Mansur (754-775) de construir Bagdá nesse local orientou-se pela', '["disponibilidade de rotas e terras férteis como base da dominação política.","proximidade de áreas populosas como afirmação da superioridade bélica.","submissão à hierarquia e à lei islâmica como controle do poder real.","fuga da península arábica como afastamento dos conflitos sucessórios.","ocupação de região fronteiriça como contenção do"]'::jsonb, '"disponibilidade de rotas e terras férteis como base da dominação política."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"f4d66b7289a07ae34609b2d8d6d3d3dccf45a673c3b17d1bcc39486a65942fdd","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"GEOGRAFIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_GEOGRAFIA","classification_source_fingerprint":"c7c86f3562672b07f1cede4efdaeb470046d169edd6c84d9a8dfbcf0485a7f7c","statement_assets":[{"assetRole":"STATEMENT","mediaType"