  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '2b07327c21927a5d53245bd0c86856e86efb6eee29f6c35318f45ec1ae8f3c6e', 'STATEMENT_CROP', 21, '2018-D1-CD4/question-50-COMMON/statement-page-21.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"2b07327c21927a5d53245bd0c86856e86efb6eee29f6c35318f45ec1ae8f3c6e","crop":{"left":0,"bottom":279.6982,"width":316.07620000000003,"height":164.05155000000002},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'cb81c4b26f079a4b37fa667d030ec0700410f134c891010b78b42c7ab71d1b8d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 89, 'CIENCIAS_HUMANAS', 'No início da década de 1990, dois biólogos importantes, Redford e Robinson, produziram um modelo largamente aceito de “produção sustentável” que previa quantos indivíduos de cada espécie poderiam ser caçados de forma sustentável baseado nas suas taxas de reprodução. Os seringueiros do Alto Juruá tinham um modelo diferente: a quem lhes afirmava que estavam caçando acima do sustentável (dentro do modelo), eles diziam que não, que o nível da caça dependia da existência de áreas de refúgio em que ninguém caçava. Ora, esse acabou sendo o modelo batizado de “fonte-ralo” proposto dez anos após o primeiro por Novaro, Bodmer e o próprio Redford e que suplantou o modelo anterior. CUNHA, M. C. Revista USP , n. 75, set.-nov. 2007. No contexto da produção científica, a necessidade de reconstrução desse modelo, conforme exposto no texto, foi determinada pelo confronto com um(a)', '["conclusão operacional obtida por lógica dedutiva.","visão de mundo marcada por preconceitos morais.","hábito social condicionado pela religiosidade popular.","conhecimento empírico apropriado pelo senso comum.","padrão de preservação construído por experimentação dirigida."]'::jsonb, '"conhecimento empírico apropriado pelo senso comum."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"cb81c4b26f079a4b37fa667d030ec0700410f134c891010b78b42c7ab71d1b8d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"SOCIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_SOCIOLOGIA","classification_source_fingerprint":"d1702db85c9377a8cde2e4bf9d639abe93baff37e27445018201e7ae86964971","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":89,"language":null,"page":31,"storagePath":"2018-D1-CD1/question-89-COMMON/statement-page-31.png","sha256":"13ad9fa3a8409d1d0d7046fdf4b2dbe8d2ab2b1f74030bbf4118896616f126c5","crop":{"left":0,"bottom":292.6757,"width":285.6117554,"height":137.99705}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":89,"language":null,"source_page":31,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, true) returning id into v_question_id; end if;
