  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'da73eaf85082b54023b8d694e4db2949f98f31d8eee9d90a21f7451a1bcdd4e5', 'STATEMENT_CROP', 20, '2018-D1-CD4/question-47-COMMON/statement-page-20.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"da73eaf85082b54023b8d694e4db2949f98f31d8eee9d90a21f7451a1bcdd4e5","crop":{"left":0,"bottom":277.33805,"width":253.1997666,"height":127.9738000000001},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '79a8a22f95d3b2b3cbdf3d07a291b24033b72caceac469fbb791a964681cf34d' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D1', 90, 'CIENCIAS_HUMANAS', 'Um dos teóricos da democracia moderna, Hans Kelsen, considera elemento essencial da democracia real (não da democracia ideal, que não existe em lugar algum) o método da seleção dos líderes, ou seja, a eleição. Exemplar, neste sentido, é a afirmação de um juiz da Corte Suprema dos Estados Unidos, por ocasião de uma eleição de 1902: “A cabine eleitoral é o templo das instituições americanas, onde cada um de nós é um sacerdote, ao qual é confiada a guarda da arca da aliança e cada um oficia do seu próprio altar”. BOBBIO, N. Teoria geral da política . Rio de Janeiro: Elsevier, 2000 (adaptado). As metáforas utilizadas no texto referem-se a uma concepção de democracia fundamentada no(a)', '["justificação teísta do direito.","rigidez da hierarquia de classe.","ênfase formalista na administração.","protagonismo do Executivo no poder.","centralidade do indivíduo na sociedade."]'::jsonb, '"centralidade do indivíduo na sociedade."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"79a8a22f95d3b2b3cbdf3d07a291b24033b72caceac469fbb791a964681cf34d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"SOCIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_SOCIOLOGIA","classification_source_fingerprint":"631cf8f1b121fa30d0ea23428e16a1312de266e70ca36e54c66b7d70414fc78a","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":90,"language":null,"page":31,"storagePath":"2018-D1-CD1/question-90-COMMON/statement-page-31.png","sha256":"d78915ce63287147cfe6145e02711c37704b35dbce524d0ca74f5e6ecf8e1ec4","crop":{"left":0,"bottom":121.0264,"width":285.6117554,"height":114.7108}}],"enem_area":"CIENCIAS_HUMANAS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":90,"language":null,"source_page":31,"source_sha256":"ec8c73472ad5d64e69224abd20cd837c4ca4b58b607a3804dcac47ff4ffbe3a8"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2018, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D1', source_number = 90, subject_area = 'CIENCIAS_HUMANAS', statement = 'Um dos teóricos da democracia moderna, Hans Kelsen, considera elemento essencial da democracia real (não da democracia ideal, que não existe em lugar algum) o método da seleção dos líderes, ou seja, a eleição. Exemplar, neste sentido, é a afirmação de um juiz da Corte Suprema dos Estados Unidos, por ocasião de uma eleição de 1902: “A cabine eleitoral é o templo das instituições americanas, onde cada um de nós é um sacerdote, ao qual é confiada a guarda da arca da aliança e cada um oficia do seu próprio altar”. BOBBIO, N. Teoria geral da política . Rio de Janeiro: Elsevier, 2000 (adaptado). As metáforas utilizadas no texto referem-se a uma concepção de democracia fundamentada no(a)', options = '["justificação teísta do direito.","rigidez da hierarquia de classe.","ênfase formalista na administração.","protagonismo do Executivo no poder.","centralidade do indivíduo na sociedade."]'::jsonb, correct_answer = '"centralidade do indivíduo na sociedade."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', metadata = '{"canonical_id":"79a8a22f95d3b2b3cbdf3d07a291b24033b72caceac469fbb791a964681cf34d","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"SOCIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_SOCIOLOGIA","classification_source_fingerprint":"631cf8f1b121fa30d0ea23428e16a1312de266e70ca36e54c66b7d70414fc78a","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":90,"language":null,"page":31,"storagePath":"2018-D1-CD1/question-90-COMMON/statement-page-31.png","sha256":"d78915ce63