te.', '["reverência de um povo a seu país. REBELO, M. A estrela sobe . Rio de Janeiro: José Olympio, 2009.","gênero solene de característica protocolar. O romance, de 1939, traz à cena tipos e situações que","canção concebida sem interferência da oralidade. espelham o Rio de Janeiro daquela década. No fragmento,","escrita de uma fase mais antiga da língua portuguesa. o narrador delineia esse contexto centrado no","artefato cultural respeitado por todo o povo brasileiro."]'::jsonb, '"artefato cultural respeitado por todo o povo brasileiro."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"32ef79533eeee63e7c172b411dee5b453d840d70c74a040892d4c39882919f62","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"b69daf759975cb9297b2592e73d0ed191ce8aae749cad6587252e737ce9af2c5","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD4","question_number":13,"language":null,"source_page":7,"source_sha256":"a2f3d95e6363cdb1efaba1cee324a7ab5252eba997522584d0bd7b0872ed28f1"}}'::jsonb, true) returning id into v_question_id; end if;
