  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D2', 104, 'CIENCIAS_NATUREZA', 'O cruzamento de duas espécies da família das Anonáceas, a cherimoia ( Annona cherimola ) com a fruta-pinha ( Annona squamosa ), resultou em uma planta híbrida denominada de atemoia. Recomenda-se que o seu plantio seja por meio de enxertia. Um dos benefícios dessa forma de plantio é a', '["ampliação da variabilidade genética.","produção de frutos das duas espécies.","manutenção do genótipo da planta híbrida.","reprodução de clones das plantas parentais.","modificação do genoma decorrente da transgenia."]'::jsonb, '"reprodução de clones das plantas parentais."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"d2fbdb565aee70383395557a545c799a9befbf671b85a21fbeb010f9ac914cd0","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"BIOLOGIA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_BIOLOGIA","classification_source_fingerprint":"5ebc3f9aebe1b99c0c2b0a283b9f6944936eb497ff554d65aa61a605574d605f","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":104,"language":null,"page":6,"storagePath":"2018-D2-CD6/question-104-COMMON/statement-page-6.png","sha256":"60e2927b9f210cd1459d55f3b7057668bb81253b1442f2582dddf48767c46c4f","crop":{"left":0,"bottom":130.81209999999996,"width":263.62978749999996,"height":84.68025}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_