  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2018, 'ENEM', 'REGULAR', 'D2', 106, 'CIENCIAS_NATUREZA', 'O sulfeto de mercúrio(II) foi usado como pigmento vermelho para pinturas de quadros e murais. Esse pigmento, conhecido como vermilion , escurece com o passar dos anos, fenômeno cuja origem é alvo de pesquisas. Aventou-se a hipótese de que o vermilion Em qual dos objetos a força potente é maior que a força seja decomposto sob a ação da luz, produzindo uma fina resistente? camada de mercúrio metálico na superfície. Essa reação A Pinça. seria catalisada por íon cloreto presente na umidade do ar. WOGAN, T. Mercury''s Dark Influence on Art . Disponível em: www.chemistryworld.com. B Alicate. Acesso em: 26 abr. 2018 (adaptado). C Quebra-nozes. Segundo a hipótese proposta, o íon cloreto atua na decomposição fotoquímica do vermilion D Carrinho de mão. A reagindo como agente oxidante. E Abridor de garrafa. B deslocando o equilíbrio químico.', '["Pinça.","Alicate.","Quebra-nozes.","Carrinho de mão.","murais. Esse"]'::jsonb, '"Quebra-nozes."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', '{"canonical_id":"27ec4c3c109ccb017ba25ad4e457c48f016a5649f1cb54d9616f66972cb28c88","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"1c09a42bfcfeeff723953121009d9edee09c0bb645e83499c4bac583a2dd08ca","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":106,"language":null,"page":7,"storagePath":"2018-D2-CD6/question-106-COMMON/statement-page-7.png","sha256":"043a5b54b66ecc42c16065961dd12bdafab46bf4da5725811c831911b58fad3d","crop":{"left":0,"bottom":388.9402,"width":313.7761999999999,"height":168.48600000000022}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2018,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD6","question_number":106,"language":null,"source_page":7,"source_sha256":"c943ad2355a8b3eb844b81043ead17f497b2f19b3ddc5a2e442dc34417a729d5"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2018, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 106, subject_area = 'CIENCIAS_NATUREZA', statement = 'O sulfeto de mercúrio(II) foi usado como pigmento vermelho para pinturas de quadros e murais. Esse pigmento, conhecido como vermilion , escurece com o passar dos anos, fenômeno cuja origem é alvo de pesquisas. Aventou-se a hipótese de que o vermilion Em qual dos objetos a força potente é maior que a força seja decomposto sob a ação da luz, produzindo uma fina resistente? camada de mercúrio metálico na superfície. Essa reação A Pinça. seria catalisada por íon cloreto presente na umidade do ar. WOGAN, T. Mercury''s Dark Influence on Art . Disponível em: www.chemistryworld.com. B Alicate. Acesso em: 26 abr. 2018 (adaptado). C Quebra-nozes. Segundo a hipótese proposta, o íon cloreto atua na decomposição fotoquímica do vermilion D Carrinho de mão. A reagindo como agente oxidante. E Abridor de garrafa. B deslocando o equilíbrio químico.', options = '["Pinça.","Alicate.","Quebra-nozes.","Carrinho de mão.","murais. Esse"]'::jsonb, correct_answer = '"Quebra-nozes."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2018', metadata = '{"canonical_id":"27ec4c3c109ccb017ba25ad4e457c48f016a5649f1cb54d9616f66972cb28c88","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"1c09a42bfcfeeff723953121009d9edee09c0bb645e83499c4bac583a2dd08ca","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":106,"language":null,"page":7,"storagePath":"2018-D2-CD6/question-106-COMMON/statement-page-7.png","sha256":"043a5b54b66ecc42