  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '12183b774a422546cccdc4b74b3d20d987edd1f1e245283dedd796fd06f31cfb' limit 1;
