s de sua vida.', options = '["indignação face à suspeita do adultério da esposa. Disponível em: http://provsjose.blogspot.com.br. Acesso em: 5 dez. 2012.","tristeza compartilhada pela perda da mulher amada. O comentário do Texto II sobre o Texto I evoca a","espanto diante da demonstração de afeto de Garcia. mobilização da língua oral que, em determinados","prazer da personagem em relação ao sofrimento contextos, alheio. A assegura a existência de pensamentos contrários à","superação do ciúme pela comoção decorrente da ordem vigente."]'::jsonb, correct_answer = '"superação do ciúme pela comoção decorrente da ordem vigente."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', metadata = '{"canonical_id":"dc4fa8d68c48cbc217679460266dfa9dac224a0c5a3663c8fd12291b1075b64f","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":null,"subject_verified":false,"classification_reason_code":"AMBIGUOUS_SUBJECT_SIGNALS","classification_source_fingerprint":"f98d5d029b2900d9411404ced3b6fe805e029e417446d95fe031e986582fcd0c","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"E","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":9,"language":null,"source_page":6,"source_sha256":"c7e130925e3d9dddd2a6370cbfaacd5edbbc20c2b789f55522721954447038e6"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
