  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'b3019413660b450331e4163a923a6a9563ac88a54fb96e62b176b0d0f2151d9b', 'STATEMENT_CROP', 14, '2017-D1-CD4/question-33-COMMON/statement-page-14.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"b3019413660b450331e4163a923a6a9563ac88a54fb96e62b176b0d0f2151d9b","crop":{"left":313.9126749999999,"bottom":491.0727,"width":267.1901250000001,"height":30.499999999999943},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'bf6a5202ed2a735de3b4f333d582dc7f98d96b8a3b8510b75395ee9389ec04de' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D1', 39, 'LINGUAGENS', 'Zé Araújo começou a cantar num tom triste, dizendo aos curiosos que começaram a chegar que uma mulher tinha se ajoelhado aos pés da santa cruz e jurado em nome de Jesus um grande amor, mas jurou e não cumpriu, fi ngiu e me enganou, pra mim você mentiu, pra Deus você pecou, o coração tem razões que a própria razão desconhece, faz promessas e juras, depois esquece. O caboclo estava triste e inspirado. Depois dessa canção que arrepiou os cabelos da Neusa, emendou com uma valsa mais arretada ainda, cheia de palavras difíceis, mas bonita que só a gota serena. Era a história de uma boneca encantadora vista numa vitrine de cristal sobre o soberbo pedestal. Zé Araújo fechava os olhos e soltava a voz: Seus cabelos tinham a cor/ Do sol a irradiar/ Fulvos raios de amor./ Seus olhos eram circúnvagos/ Do romantismo azul dos lagos/ Mãos liriais, uns ERNESTO NETO. Dengo . 2010. MAM-SP, 2010. braços divinais,/ Um corpo alvo sem par/ E os pés Disponível em: http://espacohumus.com. Acesso em: 25 abr. 2017. muito pequenos./ Enfim eu vi nesta boneca/ Uma perfeita A instalação Dengo transformou a sala do MAM-SP Vênus. CASTRO, N. L. As pelejas de Ojuara : o homem que desa fi ou o diabo. em um ambiente singular, explorando como principal São Paulo: Arx, 2006 (adaptado). característica artística a O comentário do narrador do romance “[...] emendou com', '["participação do público na interação lúdica com a obra. uma valsa mais arretada ainda, cheia de palavras difíceis, mas bonita que só a gota serena” relaciona-se ao fato","distribuição de obstáculos no espaço da exposição. de que essa valsa é representativa de uma variedade","representação simbólica de objetos oníricos. linguística","interpretação subjetiva da lei da gravidade.","valorização de técnicas de artesanato. A detentora de grande prestígio social."]'::jsonb, '"participação do público na interação lúdica com a obra. uma valsa mais arretada ainda, cheia de palavras difíceis, mas bonita que só a gota serena” relaciona-se ao fato"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"bf6a5202ed2a735de3b4f333d582dc7f98d96b8a3b8510b75395ee9389ec04de","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"d74e8aba3a0a25120a95c939a7714d22bde285f2b7b0d8db0bf77291881becbd","statement_assets":[],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":39,"language":null,"source_page":16,"source_sha256":"c7e130925e3d9dddd2a6370cbfaacd5edbbc20c2b789f55522721954447038e6"}}'::jsonb, true) returning id into v_question_id; end if;
