  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, '5affc741bc6caec64d38f6c93cb4000e054eb9b701c1fa72bb75f729cb746596', 'STATEMENT_CROP', 7, '2017-D1-CD4/question-12-COMMON/statement-page-7.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"5affc741bc6caec64d38f6c93cb4000e054eb9b701c1fa72bb75f729cb746596","crop":{"left":0,"bottom":699.8812,"width":257.6812,"height":30.5},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '08e2f94b9adc20fb47ade9d7df98396ac02d0d0b704f1d2ffbb657bccf0baba5' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D1', 44, 'LINGUAGENS', 'O homem disse, Está a chover, e depois, Quem é você, Não sou daqui, Anda à procura de comida, Sim, há quatro dias que não comemos, E como sabe que são quatro dias, É um cálculo, Está sozinha, Estou com o meu marido e uns companheiros, Quantos são, Ao todo, sete, Se estão a pensar em fi car conosco, tirem daí o sentido, já somos muitos, Só estamos de passagem, Donde vêm, Estivemos internados desde que a cegueira começou, Ah, sim, a quarentena, não serviu de nada, Por que diz isso, Deixaram-nos sair, Houve um incêndio e nesse momento percebemos que os soldados que nos vigiavam tinham desaparecido, E saíram, Sim, Os vossos soldados devem ter sido dos últimos a cegar, toda a gente está cega, Toda a gente, a cidade toda, o país, SARAMAGO, J. Ensaio sobre a cegueira . São Paulo: Cia. das Letras, 1995. A cena retrata as experiências das personagens em um país atingido por uma epidemia. No diálogo, a violação de determinadas regras de pontuação', '["revela uma incompatibilidade entre o sistema de pontuação convencional e a produção do gênero romance.","provoca uma leitura equivocada das frases interrogativas e prejudica a verossimilhança.","singulariza o estilo do autor e auxilia na representação do ambiente caótico.","representa uma exceção às regras do sistema de pontuação canônica.","colabora para a construção da identidade do narrador pouco escolarizado."]'::jsonb, '"singulariza o estilo do autor e auxilia na representação do ambiente caótico."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"08e2f94b9adc20fb47ade9d7df98396ac02d0d0b704f1d2ffbb657bccf0baba5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"d4ecda207b541b6ec6f1f548d8eec0e455ba4efb71795d56637e5f03f8723191","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":44,"language":null,"page":18,"storagePath":"2017-D1-CD1/question-44-COMMON/statement-page-18.png","sha256":"20f3eaff115857ba302d625e4e14dd0b1947a7d4f6d6d705370041d8044e9e74","crop":{"left":0,"bottom":594.2709,"width":292.22158750000006,"height":136.11030000000005}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":44,"language":null,"source_page":18,"source_sha256":"c7e130925e3d9dddd2a6370cbfaacd5edbbc20c2b789f55522721954447038e6"}}'::jsonb, true) returning id into v_question_id; end if;
