  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'aab21cae2604bd090bad66adce332ea5afafa2125c263f56f7b028f7db605f8d', 'STATEMENT_CROP', 8, '2017-D1-CD4/question-15-COMMON/statement-page-8.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"aab21cae2604bd090bad66adce332ea5afafa2125c263f56f7b028f7db605f8d","crop":{"left":0,"bottom":594.2709,"width":292.22158750000006,"height":136.11030000000005},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '22f78eaa65a80168776e1d742c508bfb8973c1db789be58ac823c80553f274d1' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D1', 45, 'LINGUAGENS', 'TEXTO I TEXTO II No verão de 1954, o artista Robert Rauschenberg (n.1925) criou o termo combine para se referir a suas novas obras que possuíam aspectos tanto da pintura como da escultura. Em 1958, Cama foi selecionada para ser incluída em uma exposição de jovens artistas americanos e italianos no Festival dos Dois Mundos em Spoleto, na Itália. Os responsáveis pelo festival, entretanto, se recusaram a expor a obra e a removeram para um depósito. Embora o mundo da arte debatesse a inovação de se pendurar uma cama numa parede, Rauschenberg considerava sua obra “um dos quadros mais acolhedores que já pintei, mas sempre tive medo de que alguém quisesse se en fi ar nela”. RAUSCHENBERG, R. Cama . Óleo e lápis em travesseiro, colcha e folha em suporte de madeira. DEMPSEY, A. Estilos, escolas e movimentos : guia enciclopédico da arte moderna. 191,1 x 80 x 20,3 cm. Museu de Arte Moderna de Nova York, 1995. São Paulo: Cosac & Naify, 2003. Disponível em: www.moma.org. Acesso em: 8 jun. 2017. A obra de Rauschenberg chocou o público na época em que foi feita, e recebeu forte influência de um movimento artístico que se caracterizava pela', '["dissolução das tonalidades e dos contornos, revelando uma produção rápida.","exploração insólita de elementos do cotidiano, dialogando com os ready-mades .","repetição exaustiva de elementos visuais, levando à simpli fi cação máxima da composição.","incorporação das transformações tecnológicas, valorizando o dinamismo da vida moderna.","geometrização das formas, diluindo os detalhes sem se preocupar com a fi delidade ao real."]'::jsonb, '"exploração insólita de elementos do cotidiano, dialogando com os ready-mades ."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"22f78eaa65a80168776e1d742c508bfb8973c1db789be58ac823c80553f274d1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"45221e6903813c4cef154408ce0d7bb3ea38e6adb034b377bf931d3afae80234","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":45,"language":null,"page":18,"storagePath":"2017-D1-CD1/question-45-COMMON/statement-page-18.png","sha256":"b2dde04efb8178e7a954a6c19cbc84044cec0e9d14ca9c761a0c1f9e6e5912a4","crop":{"left":0,"bottom":191.7457,"width":292.22158750000006,"height":362.46229999999997}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":45,"language":null,"source_page":18,"source_sha256":"c7e130925e3d9dddd2a6370cbfaacd5edbbc20c2b789f55522721954447038e6"}}'::jsonb, true) returning id into v_question_id; end if;
