ttps://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', metadata = '{"canonical_id":"22f78eaa65a80168776e1d742c508bfb8973c1db789be58ac823c80553f274d1","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"LINGUA_PORTUGUESA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_LINGUA_PORTUGUESA","classification_source_fingerprint":"45221e6903813c4cef154408ce0d7bb3ea38e6adb034b377bf931d3afae80234","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":45,"language":null,"page":18,"storagePath":"2017-D1-CD1/question-45-COMMON/statement-page-18.png","sha256":"b2dde04efb8178e7a954a6c19cbc84044cec0e9d14ca9c761a0c1f9e6e5912a4","crop":{"left":0,"bottom":191.7457,"width":292.22158750000006,"height":362.46229999999997}}],"enem_area":"LINGUAGENS","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D1","booklet":"CD1","question_number":45,"language":null,"source_page":18,"source_sha256":"c7e130925e3d9dddd2a6370cbfaacd5edbbc20c2b789f55522721954447038e6"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
