  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '51147bd7b4aa3c18edf8c14b2fb866813ee35d2e06d8af5be807954d68c4e515' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D1', 4, 'LINGUAGENS', 'Segundo informações veiculadas pela NBC News , a geração digital já tem seu espaço conquistado nas agências britânicas de inteligência. O governo britânico decidiu que', '["enfrentará a guerra vigente e deliberada contra a propriedade intelectual no Reino Unido.","abandonará a política de contratação de universitários como agentes secretos.","recrutará jovens jogadores de Xbox como ciberespiões das agências de inteligência.","implantará um esquema de capacitação de adolescentes para atuarem como agentes secretos.","anunciará os nomes dos jovens a serem contratados"]'::jsonb, '"recrutará jovens jogadores de Xbox como ciberespiões das agências de inteligência."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"51147bd7b4aa3c18edf8c14b2fb866813ee35d2e06d8af5be807954d68c4e515","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"INGLES","subject_verified":true,"classification_reason_code":"OFFICIAL_LANGUAGE_ENGLISH","classification_source_fingerprint":"82ef1057a96561797a176c60128b4b33402b22008e0ccf6a4afe52353163cfc0","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":4,"language":"ENGLISH","page":3,"storagePath":"2017-D1-CD4/question-4-ENGLISH/statement-page-3.png","sha256":"ede31b439d5ce24ad04bede0190b331398943c8febc4ea1c0e29f9bbd6a1c3a5","crop":{"left":0,"bottom":699.8812,"width":315.13687500000003,"height":30.5}}],"enem_area":"LINGUAGENS","pedagogical_enrichmen