gem do ipê com maior e fi ciência?"]'::jsonb, '"dominância incompleta do alelo mutante em relação ao alelo normal."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"5b537992556e4ccb816eaa93d943ccedf638d42ca1827750229d9231ebb867ab","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"99c3687739f83658ccc477d91ffd7d3e1762adf0bef2854700d614c03ff9aae5","statement_assets":[],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":120,"language":null,"source_page":11,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, true) returning id into v_question_id; end if;
