  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'fa7549976afd568e711ec2d753c9bb5bbf8c58c440622cd2bda248fd0cfd19e9' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D2', 130, 'CIENCIAS_NATUREZA', 'Em algumas residências, cercas eletri fi cadas são utilizadas com o objetivo de afastar possíveis invasores. Uma cerca eletri fi cada funciona com uma diferença de potencial elétrico de aproximadamente 10 000 V. Para que não seja letal, a corrente que pode ser transmitida através de uma pessoa não deve ser maior do que 0,01 A. Já a resistência elétrica corporal entre as mãos e os pés de uma pessoa é da ordem de 1 000 Ω . Para que a corrente não seja letal a uma pessoa que toca a cerca eletri fi cada, o gerador de tensão deve possuir uma resistência interna que, em relação à do corpo humano, é', '["praticamente nula.","aproximadamente igual.","milhares de vezes maior.","da ordem de 10 vezes maior.","da ordem de 10 vezes menor."]'::jsonb, '"milhares de vezes maior."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"fa7549976afd568e711ec2d753c9bb5bbf8c58c440622cd2bda248fd0cfd19e9","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"FISICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_FISICA","classification_source_fingerprint":"c8b8c74a3327d7c3840ac15eee7e281c492ef881200a0205b0224ad50f16a2db","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":130,"language":null,"page":14,"storagePath":"2017-D2-CD5/question-130-COMMON/statement-page-14.png","sha256":"cacc78925530a3dc1bd5846d6a6b08ad1bda2f277d0558ad1f0284c5aa527788","crop":{"left":0,"bottom":601.0959499999999,"width":292.8967,"height":128.91325000000006}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"C","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":130,"language":null,"source_page":14,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, true) returning id into v_question_id; end if;
