  insert into public.learning_enem_media_assets(occurrence_id, media_fingerprint, media_type, source_page, storage_path, quality_state, metadata) values (v_occurrence_id, 'ea50a62a73668ae56d9aba333ce3f1a54b9afda55c77998f2ad3afc95d0cc7ee', 'STATEMENT_CROP', 3, '2017-D2-CD6/question-95-COMMON/statement-page-3.png', 'VALIDATED', '{"asset_role":"STATEMENT","official_pdf_crop":true,"render_ready":true,"sha256":"ea50a62a73668ae56d9aba333ce3f1a54b9afda55c77998f2ad3afc95d0cc7ee","crop":{"left":0,"bottom":601.46805,"width":292.8967,"height":128.9131500000001},"excluded_option_labels":["A","B","C","D","E"]}'::jsonb) on conflict do nothing;
  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'f289b3cffe6271ceeb67755fe1e9a5933d32bbffe8b9e5fa90cdd24f562ce435' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D2', 131, 'CIENCIAS_NATUREZA', 'A cromatogra fi a em papel é um método de separação que se baseia na migração diferencial dos componentes de uma mistura entre duas fases imiscíveis. Os componentes da amostra são separados entre a fase estacionária e a fase móvel em movimento no papel. A fase estacionária consiste de celulose praticamente pura, que pode absorver até 22% de água. É a água absorvida que funciona como fase estacionária líquida e que interage com a fase móvel, também líquida (partição líquido-líquido). Os componentes capazes de formar interações intermoleculares mais fortes com a fase estacionária migram mais lentamente. Uma mistura de hexano com 5% (v/v) de acetona foi utilizada como fase móvel na separação dos componentes de um extrato vegetal obtido a partir de pimentões. Considere que esse extrato contém as substâncias representadas. HO Licopeno O O Capsorubina OH α -caroteno OH α -criptoxantina γ -caroteno RIBEIRO, N. M.; NUNES, C. R. Análise de pigmentos de pimentões por cromatogra fi a em papel. Química Nova na Escola , n. 29, ago. 2008 (adaptado). A substância presente na mistura que migra mais lentamente é o(a)', '["licopeno.","α -caroteno.","γ -caroteno.","capsorubina.","α -criptoxantina."]'::jsonb, '"capsorubina."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"f289b3cffe6271ceeb67755fe1e9a5933d32bbffe8b9e5fa90cdd24f562ce435","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"QUIMICA","subject_verified":false,"classification_reason_code":"CLASSIFICATION_CANDIDATE_QUIMICA","classification_source_fingerprint":"02746a560b4f371bd2d03f42464ba4a20ef8d11615d754fae83a33fb487dd6b5","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":131,"language":null,"page":14,"storagePath":"2017-D2-CD5/question-131-COMMON/statement-page-14.png","sha256":"7ae6bbbc5fcec2d7f4d9a5f69d404293c837e2329628f5008139cae713884f98","crop":{"left":0,"bottom":143.2375,"width":292.8967,"height":376.252}}],"enem_area":"CIENCIAS_NATUREZA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":131,"language":null,"source_page":14,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, true) returning id into v_question_id; end if;
