  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = 'eb951c1ef651a03a86de7ee54a543b65bf9af8c13b03467fef875cbeaaaed6a5' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D2', 155, 'MATEMATICA', 'Num dia de tempestade, a alteração na profundidade A fi gura ilustra uma partida de Campo Minado, o jogo de um rio, num determinado local, foi registrada durante presente em praticamente todo computador pessoal. um período de 4 horas. Os resultados estão indicados no Quatro quadrados em um tabuleiro 16 × 16 foram abertos, grá fi co de linhas. Nele, a profundidade h , registrada às e os números em suas faces indicam quantos dos seus 13 horas, não foi anotada e, a partir de h , cada unidade 8 vizinhos contêm minas (a serem evitadas). O número sobre o eixo vertical representa um metro. 40 no canto inferior direito é o número total de minas no Registro de profundidade tabuleiro, cujas posições foram escolhidas ao acaso, de forma uniforme, antes de se abrir qualquer quadrado. Profundidade (m) 0 13 14 15 16 17 Hora Foi informado que entre 15 horas e 16 horas, a profundidade do rio diminuiu em 10%. Às 16 horas, qual é a profundidade do rio, em metro, no local onde foram feitos os registros?', '["18","20","24","36","40"]'::jsonb, '"20"'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"eb951c1ef651a03a86de7ee54a543b65bf9af8c13b03467fef875cbeaaaed6a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"4476852a19807e9e3350a234bd27c1bf15eb9a22515f2232a4d57bec1709a2de","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":155,"language":null,"source_page":21,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, true) returning id into v_question_id; end if;
  update public.learning_question_bank set package_type = 'ENEM', source_name = 'INEP', source_year = 2017, source_exam = 'ENEM', source_application = 'REGULAR', source_day = 'D2', source_number = 155, subject_area = 'MATEMATICA', statement = 'Num dia de tempestade, a alteração na profundidade A fi gura ilustra uma partida de Campo Minado, o jogo de um rio, num determinado local, foi registrada durante presente em praticamente todo computador pessoal. um período de 4 horas. Os resultados estão indicados no Quatro quadrados em um tabuleiro 16 × 16 foram abertos, grá fi co de linhas. Nele, a profundidade h , registrada às e os números em suas faces indicam quantos dos seus 13 horas, não foi anotada e, a partir de h , cada unidade 8 vizinhos contêm minas (a serem evitadas). O número sobre o eixo vertical representa um metro. 40 no canto inferior direito é o número total de minas no Registro de profundidade tabuleiro, cujas posições foram escolhidas ao acaso, de forma uniforme, antes de se abrir qualquer quadrado. Profundidade (m) 0 13 14 15 16 17 Hora Foi informado que entre 15 horas e 16 horas, a profundidade do rio diminuiu em 10%. Às 16 horas, qual é a profundidade do rio, em metro, no local onde foram feitos os registros?', options = '["18","20","24","36","40"]'::jsonb, correct_answer = '"20"'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', metadata = '{"canonical_id":"eb951c1ef651a03a86de7ee54a543b65bf9af8c13b03467fef875cbeaaaed6a5","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"4476852a19807e9e3350a234bd27c1bf15eb9a22515f2232a4d57bec1709a2de","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"B","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":155,"language":null,"source_page":21,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
