tura máxima mais aproximada registrada 1 2 e T devem ser, em metro por hora, de nesse termômetro? 3', options = '["5 °C A 12 , 24 e 36.","7 °C B 6 , 12 e 18.","13 °C C 2 , 4 e 6.","15 °C D 300 , 1 200 e 2 700.","19 °C E 600 , 2 400 e 5 400."]'::jsonb, correct_answer = '"5 °C A 12 , 24 e 36."'::jsonb, provenance = 'INEP_OFFICIAL', source_reference = 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', metadata = '{"canonical_id":"20a1b5291ee2fb4e89db1a82b07ae41b075024431cb6255e4c5d9ed55fcc6afe","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":false,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"7a24b0ce2db224395f5e3dab2d0240410662e3d700673faba15e317d92b7f9f0","statement_assets":[],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"A","official_occurrence_count":2,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD5","question_number":175,"language":null,"source_page":29,"source_sha256":"456cc94ca81dea02cc89a15d2e8a253f70e5b049e99d875025dd8dba5c2460eb"}}'::jsonb, active = true, updated_at = now() where id = v_question_id;
