  select id into v_question_id from public.learning_question_bank where source_type = 'ENEM_OFFICIAL' and metadata->>'canonical_id' = '51640a3fb774c8a45018f1b8c914c0ec4b1a85e3f9e08b85c0056d991804a5be' limit 1;
  if v_question_id is null then insert into public.learning_question_bank(package_type, source_type, source_name, source_year, source_exam, source_application, source_day, source_number, subject_area, statement, options, correct_answer, explanation, estimated_minutes, provenance, source_reference, metadata, active) values ('ENEM', 'ENEM_OFFICIAL', 'INEP', 2017, 'ENEM', 'REGULAR', 'D2', 165, 'MATEMATICA', 'da catraca. Durante um passeio em uma bicicleta desse tipo, Viveiros de lagostas são construídos, por deseja-se fazer um percurso o mais devagar possível, cooperativas locais de pescadores, em formato de escolhendo, para isso, uma das seguintes combinações prismas reto-retangulares, fi xados ao solo e com telas de engrenagens (coroa x catraca): flexíveis de mesma altura, capazes de suportar a corrosão marinha. Para cada viveiro a ser construído, I II III IV V a cooperativa utiliza integralmente 100 metros lineares dessa tela, que é usada apenas nas laterais. 1ª × 1ª 1ª × 6ª 2ª × 4ª 3ª × 1ª 3ª × 6ª A combinação escolhida para realizar esse passeio da Nível do mar forma desejada é', '["I.","II.","III. Y","IV.","V. X"]'::jsonb, '"IV."'::jsonb, null, 4, 'INEP_OFFICIAL', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/2017', '{"canonical_id":"51640a3fb774c8a45018f1b8c914c0ec4b1a85e3f9e08b85c0056d991804a5be","source_integrity":"VERIFIED","render_mode":"HYBRID","render_ready":true,"area_verified":true,"enem_subject":"MATEMATICA","subject_verified":true,"classification_reason_code":"OFFICIAL_MATH_AREA_EQUIVALENT","classification_source_fingerprint":"c75a9c9e7c493e418a3c586b08965ad032679dffeb7d5c9672f7df0257d52583","statement_assets":[{"assetRole":"STATEMENT","mediaType":"STATEMENT_CROP","questionNumber":165,"language":null,"page":25,"storagePath":"2017-D2-CD6/question-165-COMMON/statement-page-25.png","sha256":"bd6823466a92384e7ac56d6aab477b78ee93e69d59f8a1117e64a77c9f529467","crop":{"left":310.78229999999996,"bottom":241.14102499999998,"width":270.32050000000004,"height":144.83327500000004}}],"enem_area":"MATEMATICA","pedagogical_enrichment":"PENDING","adaptive_evidence_enabled":false,"official_answer_letter":"D","official_occurrence_count":1,"annulled":false,"source_provenance":{"year":2017,"exam":"ENEM","application":"REGULAR","day":"D2","booklet":"CD6","question_number":165,"language":null,"source_page":25,"source_sha256":"c42adbc2d4abaa162cab00e7f41cefb2b37ed17d9ca35ccbafdbd07454b59190"}}'::jsonb, true) returning id into v_question_id; end if;
